class InspectionAnalysis(BaseModel):
    model_config = ConfigDict(extra="ignore")
    critical_damages_count: int = 0
    total_damages_count: int = 0
    new_damages_count: int = 0
    severity: str = "sin_danos"
    dirt_level: Optional[float] = None  # 0 impecable — 10 cubierta de barro
    urgency: str = "puede_esperar"
    risk: str = "bajo"
    circulation_safe: bool = True
    detected_plate: str = ""
    fraud_warnings: List[str] = []
    hidden_damage_probability: float = 0.0
    total_estimated_cost: float = 0.0
    confidence: float = 0.0
    executive_summary: str = ""
    image_quality_warnings: List[str] = []
    # Zonas que la IA declara que NO puede juzgar. Ni daño ni limpio: "hace
    # falta otra foto". Es la tercera salida que le faltaba y que la empujaba
    # a inventarse daños ante una foto mala.
    zonas_no_evaluables: List[dict] = []
    affected_parts: List[str] = []
    critical_damages: list = []
    new_damages: List[Damage] = []
    damages: List[Damage] = []

    @model_validator(mode="after")
    def _severidad_coherente(self):
        """Sin daños en la lista no hay severidad de daño.

        La IA devuelve `severity` y `damages` por separado y a veces dice
        "leve" con la lista vacia (suciedad, una duda descartada): 128 de
        3.964 inspecciones en produccion el 02-09-2026, que en la lista salian
        como "Leve · 0 daños" y en el dashboard contaban como daño. Una
        pantalla que reparte en cajones tiene que cuadrar (gotcha 30).
        """
        if not self.damages and not self.new_damages and \
                self.severity in ("leve", "moderado", "grave", "critico"):
            self.severity = "sin_danos"
        return self


