OWNER_ORG_ID = "owner"


async def get_org(org_id):
    if not org_id:
        return None
    return await global_db.organizations.find_one({"id": org_id}, {"_id": 0})


# Módulos OCULTOS por tipo de cuenta (para los candados del frontend).
# El dueño (tú) lo ve todo; los DSP comerciales NO ven IA Peritaje ni Scorecard.
HIDDEN_MODULES_DSP = ["ia-peritaje", "scorecard", "turnos"]


def org_hidden_modules(org):
    if not org or org.get("account_type") == "owner":
        return []
    return org.get("hidden_modules") or HIDDEN_MODULES_DSP


async def ensure_owner_org():
    o = await global_db.organizations.find_one({"id": OWNER_ORG_ID})
    if not o:
        await global_db.organizations.insert_one({
            "id": OWNER_ORG_ID,
            "name": os.environ.get("ADMIN_NAME", "FlotaDSP"),
            "account_type": "owner",
            "db_name": _DEFAULT_DB_NAME,
            "slug": "admin",
            "status": "active",
            "centers": ["OGA5", "DGA1", "DGA2"],
            "max_centers": 999,
            "created_at": datetime.now(timezone.utc).isoformat(),
        })
        logger.info("Organización 'owner' creada (BD: %s)", _DEFAULT_DB_NAME)
    else:
        patch = {}
        if not o.get("slug"):
            patch["slug"] = "admin"
        if not o.get("centers"):
            patch["centers"] = ["OGA5", "DGA1", "DGA2"]
            patch["max_centers"] = 999
        if patch:
            await global_db.organizations.update_one({"id": OWNER_ORG_ID}, {"$set": patch})
    return OWNER_ORG_ID


# =========================
# STARTUP — seed admin inicial (en global_db) + migración
# =========================

@app.on_event("startup")
async def _init_segmentation():
    import asyncio
    loop = asyncio.get_event_loop()
    await loop.run_in_executor(None, preload_sam)

@app.on_event("startup")
async def seed_initial_admin():
    await ensure_owner_org()

    # Migración: pasa los admins existentes de la BD por defecto a global_db.
    # Corre UNA sola vez de verdad (flag en app_meta): antes corría en cada
    # arranque y resucitaba usuarios borrados a propósito.
    if not await global_db.app_meta.find_one({"_id": "legacy_admins_migrated"}):
        legacy = client[_DEFAULT_DB_NAME].admin_users
        async for u in legacy.find({}):
            if await global_db.admin_tombstones.find_one({"username": u["username"]}):
                continue  # borrado a propósito: no resucitar
            if not await global_db.admin_users.find_one({"username": u["username"]}):
                u.pop("_id", None)
                u["org_id"] = OWNER_ORG_ID
                await global_db.admin_users.insert_one(u)
                logger.info("Admin '%s' migrado a global_db", u.get("username"))
        await global_db.app_meta.update_one(
            {"_id": "legacy_admins_migrated"},
            {"$set": {"at": datetime.now(timezone.utc).isoformat()}}, upsert=True)

    # Admin inicial desde env: SOLO en el primer arranque (BD sin admins).
    # Antes se re-creaba en cada deploy si no existía → un admin borrado volvía solo.
    username = os.environ.get("ADMIN_USERNAME", "")
    password = os.environ.get("ADMIN_PASSWORD", "")
    if not username or not password:
        logger.info("ADMIN_USERNAME/ADMIN_PASSWORD no configurados — omitiendo seed")
    elif await global_db.admin_users.count_documents({}) == 0:
        await global_db.admin_users.insert_one({
            "id": str(uuid.uuid4()), "username": username,
            "hashed_password": hash_password(password),
            "name": os.environ.get("ADMIN_NAME", username),
            "role": "admin", "org_id": OWNER_ORG_ID,
            "created_at": datetime.now(timezone.utc).isoformat(),
        })
        logger.info(f"Admin inicial '{username}' creado (primer arranque)")

    # ── Admin fijo: Mery ── (idempotente)
    # Contraseña inicial: variable de entorno MERY_PASSWORD (obligatoria en producción).
    mery_password = os.environ.get("MERY_PASSWORD", "")
    mery_existing = await global_db.admin_users.find_one({"username": "Mery"})
    if not mery_existing:
        if not mery_password:
            logger.warning("MERY_PASSWORD no configurada — admin 'Mery' NO creado. Configura: fly secrets set MERY_PASSWORD=<contraseña>")
        else:
            await global_db.admin_users.insert_one({
                "id": str(uuid.uuid4()), "username": "Mery",
                "hashed_password": hash_password(mery_password), "name": "Mery",
                "role": "admin", "theme": "pastel", "org_id": OWNER_ORG_ID,
                "created_at": datetime.now(timezone.utc).isoformat(),
            })
            logger.info("Admin 'Mery' creado")
    elif not mery_existing.get("theme"):
        await global_db.admin_users.update_one(
            {"username": "Mery"}, {"$set": {"theme": "pastel"}})

    # ── Super-admin: dani (dueño del negocio, ÚNICO con panel super-admin) ── (idempotente)
    # Contraseña inicial: variable de entorno DANI_PASSWORD (obligatoria en producción).
    dani_password = os.environ.get("DANI_PASSWORD", "")
    dani = await global_db.admin_users.find_one({"username": "dani"})
    if not dani:
        if not dani_password:
            logger.warning("DANI_PASSWORD no configurada — super-admin 'dani' NO creado. Configura: fly secrets set DANI_PASSWORD=<contraseña>")
        else:
            await global_db.admin_users.insert_one({
                "id": str(uuid.uuid4()), "username": "dani",
                "hashed_password": hash_password(dani_password), "name": "Dani",
                "role": "admin", "org_id": OWNER_ORG_ID, "super_admin": True,
                "created_at": datetime.now(timezone.utc).isoformat(),
            })
            logger.info("Super-admin 'dani' creado")
    elif not dani.get("super_admin"):
        await global_db.admin_users.update_one(
            {"username": "dani"}, {"$set": {"super_admin": True}})

    # Informar si R2 está configurado
    r2 = get_r2()
    if r2:
        logger.info(f"Cloudflare R2 configurado: bucket={R2_BUCKET}, public_url={R2_PUBLIC_URL}")
    else:
        logger.warning("R2 NO configurado — usando almacenamiento local (no recomendado en producción)")


async def _dedupe_cortex_stations(tdb):
    """Deja UN solo documento por service_area_id en cortex_stations.

    De dónde salían los duplicados: la ingesta de la extensión escribe el mapeo
    con `update_one(..., upsert=True)` y llega en rafagas (miles de paquetes en
    cola). Dos upserts a la vez que no encuentran documento INSERTAN los dos, y
    el índice de service_area_id no era único, así que nadie lo impedía.

    Lo que provocaba, y costó encontrar porque todo respondía 200:
      · La asignación manual del panel hace `update_one`: tocaba UNO de los
        duplicados. La lectura arma `{sid: doc}` recorriendo todos, así que se
        quedaba con el ÚLTIMO — a veces el otro. Resultado: pulsabas el centro,
        el backend devolvía 200 y en pantalla no cambiaba nada.
      · Peor: como el duplicado que ganaba no tenía `manual`, la extensión lo
        volvía a pisar en cada captura, y la resincronización propagaba ese
        centro a decenas de miles de paquetes. El mapeo oscilaba solo.

    Se conserva el documento MANUAL si lo hay: es el único que decidió una
    persona, y es justo el que la extensión no puede tocar.
    """
    try:
        vistos: dict = {}
        sobran: list = []
        async for d in tdb.cortex_stations.find({}):
            sid = (d.get("service_area_id") or "").strip()
            if not sid:
                continue
            previo = vistos.get(sid)
            if previo is None:
                vistos[sid] = d
                continue
            # Gana el manual; a igualdad, el que ya estaba.
            if d.get("manual") and not previo.get("manual"):
                sobran.append(previo["_id"])
                vistos[sid] = d
            else:
                sobran.append(d["_id"])
        if sobran:
            await tdb.cortex_stations.delete_many({"_id": {"$in": sobran}})
            logger.warning(f"cortex_stations: {len(sobran)} duplicados eliminados")
    except Exception as e:
        logger.error(f"dedupe cortex_stations: {e}")


async def _idx_unico(coleccion, campo: str):
    """Índice ÚNICO sobre un campo, aunque ya exista uno normal con ese nombre.

    `create_index(..., unique=True)` sobre una colección que ya tiene el índice
    NO único con el mismo nombre no lo convierte: falla con el código 86
    (IndexKeySpecsConflict) y se queda todo como estaba. Pasó aquí: el índice
    seguía sin ser único y los duplicados podían volver a aparecer en cuanto la
    extensión mandara otra ráfaga.

    Así que hay que tirar el viejo y crearlo de nuevo. Se hace DESPUÉS de haber
    limpiado los duplicados; si aún quedara alguno, la creación falla y se
    queda sin índice único, que es como estaba: nunca peor.
    """
    nombre = f"{campo}_1"
    try:
        await coleccion.create_index(campo, unique=True)
        return
    except Exception as e:
        if getattr(e, "code", None) not in (85, 86):
            logger.error(f"Indice unico {coleccion.name}.{campo}: {e}")
            return
    try:
        await coleccion.drop_index(nombre)
        await coleccion.create_index(campo, unique=True)
        logger.warning(f"Indice {coleccion.name}.{campo} recreado como UNICO")
    except Exception as e:
        logger.error(f"Indice unico {coleccion.name}.{campo} (recrear): {e}")


async def _idx(coleccion, *args, **kwargs):
    """Crea un indice sin que un fallo tumbe a los demas.

    Casos reales que hay que tolerar:
      · el indice ya existe con OTRO nombre (Atlas los auto-crea) -> error 85
      · falta permiso o la coleccion aun no existe
    Cualquiera de ellos deja de ser mortal: se anota y se sigue.
    """
    try:
        await coleccion.create_index(*args, **kwargs)
    except Exception as e:
        codigo = getattr(e, "code", None)
        if codigo == 85:      # ya existe con otro nombre: es equivalente
            return
        logger.warning(f"Indice {coleccion.name} {args}: {e}")


async def _ensure_tenant_indexes(db_name: str):
    """Crea índices en la BD de un tenant. Idempotente. Llamar al registrar un DSP nuevo."""
    tdb = client[db_name]
    await _idx(tdb.vehicles, "id")
    await _idx(tdb.vehicles, "license_plate")
    # UNA MATRICULA VIVA, UNA FICHA. `create_vehicle` ya comparaba en Python,
    # pero cinco altas a la vez de la misma matricula pasaban las cinco la
    # comprobacion antes de que ninguna insertara: 3 fichas (medido el
    # 02-09-2026 en una empresa de prueba). Solo la base puede impedirlo, y
    # solo entre las vivas: una devuelta (`deleted`) y dada de alta otra vez es
    # legitima. En produccion no habia repetidas vivas, asi que se crea limpio;
    # si en alguna empresa las hubiera, `_idx` lo anota y se queda como estaba.
    await _idx(tdb.vehicles, [("license_plate", 1)], unique=True, name="matricula_unica_viva",
               partialFilterExpression={"status": {"$in": ["active", "taller", "baja"]}})
    await _idx(tdb.vehicles, "center")
    await _idx(tdb.vehicles, "current_driver_id")
    await _idx(tdb.vehicles, "status")
    await _idx(tdb.drivers, "id")
    await _idx(tdb.drivers, "driver_id")
    # EL CORREO ES LA LLAVE DEL PORTAL y no tenia indice ninguno: cada vez que
    # un conductor entra, Mongo recorria las 202 fichas enteras. Medido el
    # 22-08-2026 con la auditoria de datos.
    #
    # Va SIN unique a proposito. Hay 12 correos compartidos por varias fichas
    # (los duplicados de conductores, gotcha 15) y crear el unico con
    # duplicados dentro FALLA y se queda sin indice — o sea, peor que ahora.
    # El unico se pone cuando se fusionen las fichas, con _idx_unico().
    await _idx(tdb.drivers, "email")
    # ...y mientras tanto, unico SOLO ENTRE LOS ACTIVOS y sin distinguir
    # mayusculas: las 13 parejas repetidas que quedan en produccion tienen al
    # menos una ficha dada de baja, asi que este si se puede crear. Sin el,
    # `POST /drivers` cinco veces a la vez con el mismo correo daba cinco
    # fichas (02-09-2026), que es justo el gotcha 15: el login cae en la que no
    # toca. Un `active` que no sea `true` queda fuera del indice a proposito.
    await _idx(tdb.drivers, [("email", 1)], unique=True, name="email_unico_activo",
               partialFilterExpression={"active": True, "email": {"$type": "string", "$gt": ""}},
               collation={"locale": "en", "strength": 2})
    # ── Empleo: ofertas y candidatos ───────────────────────────────────────
    await _idx(tdb.ofertas_empleo, "id")
    # El slug es la URL publica: dos ofertas con el mismo dejarian una
    # inalcanzable. `_empleo_slug_libre` ya lo evita, pero dos creaciones a la
    # vez pasan las dos la comprobacion y solo la base puede pararlas (gotcha 46).
    await _idx(tdb.ofertas_empleo, [("slug", 1)], unique=True, name="slug_oferta_unico")
    await _idx(tdb.candidatos, "id")
    await _idx(tdb.candidatos, [("oferta_id", 1), ("fase", 1)])
    await _idx(tdb.candidatos, "centro")
    # UNA CANDIDATURA POR PERSONA Y OFERTA. Sin esto, dar dos veces a enviar
    # con mala cobertura deja dos candidatos iguales y alguien llama dos veces.
    await _idx(tdb.candidatos, [("oferta_id", 1), ("tel_clave", 1)], unique=True,
               name="candidato_unico_por_oferta",
               partialFilterExpression={"tel_clave": {"$type": "string", "$gt": ""}})
    # Datos personales con fecha de caducidad: Mongo los borra solo a los 12
    # meses. Es la unica forma de que el plazo se cumpla sin que nadie se acuerde.
    await _idx(tdb.candidatos, "expira_en", expireAfterSeconds=0)
    # Bloqueos de dias: se consultan en CADA peticion del conductor.
    await _idx(tdb.shift_blocks, [("hasta", 1), ("desde", 1)])
    await _idx(tdb.shift_blocks, "driver_id")
    # ── Cortex: son las colecciones que mas crecen con diferencia ──────────
    # Medido en produccion: cortex_packages 90.876 docs / 68 MB y
    # cortex_events 133.528 docs / 30 MB SIN NINGUN INDICE.
    # Estos son los campos por los que filtra de verdad _cortex_scope().
    # 'tba' y 'updated_at' ya los auto-creo Atlas (con sufijo _autocreated):
    # volver a pedirlos daba error 85 y abortaba el resto.
    await _idx(tdb.cortex_packages, [("service_day", -1)])
    # Compuesto para la calidad por conductor: sin el, cada consulta del
    # scorecard en vivo recorre los ~100.000 paquetes del mes enteros.
    await _idx(tdb.cortex_packages, [("driver_id", 1), ("service_day", -1)])
    await _idx(tdb.cortex_packages, [("service_day", -1), ("state", 1)])
    # El nombre del conductor se resuelve por estos dos: ambos van con $in.
    await _idx(tdb.drivers, "driver_id")
    await _idx(tdb.route_history, "transporter_id")
    # Diarios de Cortex. `tracking_id` unico: pegar dos veces el mismo reporte
    # tiene que ACTUALIZAR la fila (la columna DSC se rellena tarde), no
    # duplicarla; sin el indice se acumularian copias con distinto DSC y el
    # recuento de defectos saldria multiplicado.
    await _idx(tdb.dnr_rows, "tracking_id", unique=True)
    await _idx(tdb.dnr_rows, [("center", 1), ("fecha_concesion", 1)])
    await _idx(tdb.dnr_rows, "transporter_id")
    await _idx(tdb.daily_reports, [("center", 1), ("fecha", 1), ("transporter_id", 1)])
    await _idx(tdb.daily_reports, [("center", 1), ("fecha_dnr", 1)])
    # Ordenes de trabajo
    await _idx(tdb.ordenes_trabajo, "id", unique=True)
    await _idx(tdb.ordenes_trabajo, [("center", 1), ("estado", 1), ("creada_en", -1)])
    await _idx(tdb.ordenes_trabajo, [("vehicle_id", 1), ("creada_en", -1)])
    await _idx(tdb.ordenes_trabajo, [("workshop_id", 1), ("creada_en", -1)])
    # Las otras tres tablas del diario. La clave es (tracking, fecha del
    # reporte): 763 trackings de RTS salen en mas de un dia, asi que el tracking
    # solo perderia filas.
    for _col in (tdb.rts_rows, tdb.pod_rows, tdb.cc_rows):
        await _idx(_col, [("tracking_id", 1), ("fecha_reporte", 1)], unique=True)
        await _idx(_col, [("center", 1), ("fecha_reporte", -1)])
        await _idx(_col, "transporter_id")
    await _idx(tdb.drivers, "transporter_id")
    # Errores de navegador: se consultan por fecha y se purgan solos a los 30
    # dias. Un buzon de errores que crece sin techo acaba siendo otro problema.
    await _idx(tdb.client_errors, [("ts", -1)])
    try:
        await tdb.client_errors.create_index("ts", expireAfterSeconds=30 * 24 * 3600,
                                             name="ts_ttl")
    except Exception:
        pass
    await _idx(tdb.portales, "celda")
    await _idx(tdb.cortex_packages, "center")
    await _idx(tdb.cortex_packages, "service_area_id")
    await _idx(tdb.cortex_packages, "state")
    # OJO: primero se limpian los duplicados y LUEGO se pone el índice único.
    # Al revés, la creación falla (ya hay duplicados) y todo se queda igual.
    await _dedupe_cortex_stations(tdb)
    await _idx_unico(tdb.cortex_stations, "service_area_id")
    # La foto diaria: se consulta por dia y por centro.
    # Un unico parcial: dos analisis a la vez del mismo vehiculo creaban dos
    # entradas del mismo golpe (gotcha 9). Solo sobre los ABIERTOS, porque el
    # historico SI puede tener varias del mismo panel en distintas epocas.
    try:
        await tdb.vehicle_damage_ledger.create_index(
            [("vehicle_id", 1), ("panel", 1)], unique=True,
            partialFilterExpression={"status": "open"}, name="uniq_veh_panel_open")
    except Exception as e:                                       # noqa: BLE001
        logger.warning("indice unico del ledger: %s", e)
    await _idx(tdb.cortex_day_snapshots, "service_day")
    await _idx(tdb.cortex_day_snapshots, "center")
    # cortex_events es un registro que SOLO se escribe (0 lecturas en todo el
    # codigo). Se le pone caducidad de 90 dias para que no crezca sin fin en un
    # Atlas de 512 MB: conserva la traza reciente y libera el resto solo.
    try:
        await _idx(tdb.cortex_events, "expira_en", expireAfterSeconds=0)
        # cortex_packages crecia SIN LIMITE mientras su coleccion hermana ya
        # caducaba. Medido: 3.309 docs/dia, 812 bytes/doc = 77 MB/mes con UN
        # cliente. Un Atlas de 512 MB se llena en 2,8 meses; con tres DSP, en
        # menos de uno. Misma retencion que los eventos: 90 dias.
        await _idx(tdb.cortex_packages, "expira_en", expireAfterSeconds=0)
        # El diagnostico de esquema es una foto, no un historico: caduca a 30
        # dias y son unos pocos documentos (uno por tipo, con upsert).
        await _idx(tdb.cortex_diagnostico, "expira_en", expireAfterSeconds=0)
        # El registro de WhatsApp caduca solo a los 90 dias: es operacion, no
        # historico, y una coleccion de avisos sin techo crece hasta que alguien
        # la descubre. Y se consulta por fecha desde el panel.
        await _idx(tdb.whatsapp_envios, "expira_en", expireAfterSeconds=0)
        await _idx(tdb.whatsapp_envios, [("at", -1)])
    except Exception as _e:
        logger.warning(f"Indice TTL de cortex: {_e}")
    await _idx(tdb.inspections, "id")
    await _idx(tdb.inspections, "vehicle_id")
    await _idx(tdb.inspections, [("created_at", -1)])
    await _idx(tdb.inspections, "driver_id")
    await _idx(tdb.inspections, "reviewed")
    await _idx(tdb.inspections, "analysis_status")
    await _idx(tdb.inspections, "forensic_signed")
    await _idx(tdb.inspections, "forensic_hash")
    await _idx(tdb.inspections, "first_phash")
    await _idx(tdb.inspections, "fraud_score")
    await _idx(tdb.daily_assignments, [("date", -1), ("center", 1)])
    await _idx(tdb.vehicle_damage_ledger, [("vehicle_id", 1), ("status", 1)])
    await _idx(tdb.alerts, [("created_at", -1)])
    await _idx(tdb.alerts, "read")
    # Turnos: un conductor tiene UN turno por dia. Los cuatro sitios que los
    # guardan hacen upsert por (driver_id, date), y sin unico dos peticiones a
    # la vez dejan dos documentos (gotcha 9). Medido 0 repetidos el 02-09-2026
    # antes de crearlo; los upserts pasan por _upsert_turno/_bulk_turnos.
    await _idx(tdb.shifts, [("driver_id", 1), ("date", 1)], unique=True, name="turno_unico")
    await _idx(tdb.shifts, [("center", 1), ("date", 1)])
    # Apoyo en ruta (un conductor le quita paradas a otro, con mapa por WhatsApp).
    await _idx(tdb.apoyos, "id", unique=True, name="apoyo_id_unico")
    await _idx(tdb.apoyos, [("dia", 1), ("center", 1)])
    # Un apoyo ABIERTO por pareja y dia, dicho por la base: dos clics a la vez en
    # «Crear apoyo» no pueden dejar dos (gotcha 46). El find_one previo solo
    # sirve para dar un mensaje bonito; el que manda es este unico parcial.
    await _idx(tdb.apoyos, [("dia", 1), ("de.driver_id", 1), ("a.driver_id", 1)], unique=True,
               partialFilterExpression={"fase": "enviado"}, name="apoyo_pareja_abierta")
    await _idx(tdb.ai_feedback, [("created_at", -1)])
    await _idx(tdb.ai_feedback, [("damage.part", 1)])
    await _idx(tdb.ai_feedback, [("damage.location_hint", 1)])
    await _idx(tdb.ai_feedback, [("verdict", 1)])
    # UN VEREDICTO POR DAÑO Y ALCANCE. El unico de antes era sobre
    # (inspection_id, damage_index) y NUNCA llego a existir en produccion: los
    # avisos de "daño no visto" van con `damage_index: null` y hay varios por
    # inspeccion (legitimo), y el upsert de Revision Rapida va por
    # (inspection_id, scope, damage_index), asi que la misma pareja convivia
    # con dos `scope`. La creacion fallaba en cada arranque con un WARNING que
    # nadie leia (medido el 02-09-2026: 10 parejas repetidas, 0 con el scope).
    # Este si se crea: la clave del upsert, y solo para daños numerados.
    await _idx(tdb.ai_feedback,
        [("inspection_id", 1), ("scope", 1), ("damage_index", 1)], unique=True,
        name="feedback_unico", partialFilterExpression={"damage_index": {"$type": "number"}}
    )
    await _idx(tdb.incidents, "vehicle_id")
    await _idx(tdb.incidents, "status")
    await _idx(tdb.forensic_signatures, [("inspection_id", 1), ("revision", 1)], unique=True)
    await _idx(tdb.forensic_signatures, "content_hash", unique=True)
    await _idx(tdb.forensic_signatures, [("signed_at", -1)])
    await _idx(tdb.daily_checklists, 
        [("center", 1), ("date", 1), ("shift", 1)], unique=True
    )
    await _idx(tdb.chat_messages, [("center", 1), ("created_at", -1)])
    await _idx(tdb.driver_accounts, "username")
    # `generar_accesos_conductores` capturaba DuplicateKeyError "por si dos
    # pestañas a la vez"... sobre una coleccion SIN indice unico, asi que nunca
    # saltaba: cinco pulsaciones a la vez dejaron 21 cuentas para un mismo
    # conductor, cada una con una contraseña distinta (02-09-2026). Un except
    # de duplicado sin indice unico es papel mojado; `check_unicos.py` lo vigila.
    await _idx(tdb.driver_accounts, [("driver_id", 1)], unique=True, name="driver_id_unico",
               partialFilterExpression={"driver_id": {"$type": "string"}})
    await _idx(tdb.inspection_ai_results,
        [("inspection_id", 1), ("photo_index", 1)], unique=True
    )
    await _idx(tdb.workshops, "id")
    await _idx(tdb.workshops, "center")
    await _idx(tdb.workshops, "convenios")
    await _idx(tdb.workshops, "categories")
    await _idx(tdb.plantillas_diarias, "id")
    await _idx(tdb.plantillas_diarias, [("center", 1), ("uploaded_at", -1)])
    await _idx(tdb.plantillas_compartidas, "id", unique=True)
    await _idx(tdb.plantillas_compartidas, [("center", 1), ("updated_at", -1)])
    # Citas de taller del calendario de flota. El único PARCIAL es la regla de
    # negocio en sí: una furgoneta no puede tener dos citas ABIERTAS del mismo
    # tipo. Sin él, dos clics a la vez dejarían dos citas y el calendario
    # pintaría el mismo cambio dos días distintos (gotcha 9 del CLAUDE.md).
    await _idx(tdb.fleet_appointments, "id", unique=True)
    await _idx(tdb.fleet_appointments, [("vehicle_id", 1), ("tipo", 1)], unique=True,
               partialFilterExpression={"estado": "pendiente"})
    await _idx(tdb.fleet_appointments, [("fecha", 1)])
    await _idx(tdb.maintenance_log, "id", unique=True)
    await _idx(tdb.maintenance_log, [("vehicle_id", 1), ("fecha", -1)])


@app.on_event("startup")
async def create_indexes():
    """Crea índices en la BD owner y en todas las BDs de DSPs existentes. Idempotente."""
    try:
        # Índices del owner (BD por defecto)
        await _ensure_tenant_indexes(_DEFAULT_DB_NAME)
        # Índices globales (compartidos entre tenants)
        await _idx(global_db.admin_users, "username")
        await _idx(global_db.inbox_messages, [("created_at", -1)])
        await _idx(global_db.ls_webhook_events, "event_uid", unique=True)
        await _idx(global_db.forensic_index, "content_hash", unique=True)
        await _idx(global_db.forensic_index, [("signed_at", -1)])
        # Enlaces del portal de talleres. El token es la unica llave que hay:
        # unico, y indexado por orden para poder revocarlos de golpe.
        await _idx(global_db.taller_enlaces, "token", unique=True)
        await _idx(global_db.taller_enlaces, [("orden_id", 1), ("revocado", 1)])
        await _idx(global_db.taller_enlaces, [("workshop_id", 1), ("db_name", 1)])
        # Registro de escrituras (quien hizo que): 30 dias y fuera.
        await _idx(global_db.audit_requests, "at", expireAfterSeconds=30 * 24 * 3600)
        await _idx(global_db.audit_requests, [("path", 1), ("at", -1)])
        await _idx(global_db.audit_requests, [("sub", 1), ("at", -1)])
        # Crear índices en BDs de DSPs ya existentes (por si arrancamos con DSPs sin índices)
        orgs = await global_db.organizations.find(
            {"account_type": "dsp", "db_name": {"$exists": True}}, {"db_name": 1}
        ).to_list(500)
        for org in orgs:
            try:
                await _ensure_tenant_indexes(org["db_name"])
            except Exception as _ie:
                logger.warning(f"Error creando índices para DSP {org.get('db_name')}: {_ie}")
        logger.info("Índices MongoDB creados/verificados correctamente")
    except Exception as e:
        logger.warning(f"Error creando índices: {e}")


