def _org_billing(org):
    """Estado de suscripción de una organización (para el trial y el bloqueo)."""
    if not org or org.get("account_type") == "owner":
        limits = PLAN_LIMITS["owner"]
        return {"status": "owner", "required": False, "days_left": None, "plan": "owner", "limits": limits}
    _raw = (org.get("plan") or "").lower().strip()
    for _c, _r in [("á","a"),("é","e"),("í","i"),("ó","o"),("ú","u")]:
        _raw = _raw.replace(_c, _r)
    plan_key = _raw
    limits = PLAN_LIMITS.get(plan_key, PLAN_DEFAULT)
    status = org.get("status", "trial")
    if status == "active":
        return {"status": "active", "required": False, "days_left": None, "plan": plan_key or "pro", "limits": limits}
    if status == "trial":
        days = None
        te = org.get("trial_ends")
        if te:
            try:
                te_dt = datetime.fromisoformat(te)
                # Normalizar a aware si es naive (cuentas antiguas sin tz)
                if te_dt.tzinfo is None:
                    te_dt = te_dt.replace(tzinfo=timezone.utc)
                delta = te_dt - datetime.now(timezone.utc)
                # Redondear hacia arriba: si quedan 13d 23h mostramos 14
                days = max(0, -(-delta.total_seconds() // 86400))  # ceil division
                days = int(days)
            except Exception:
                days = None
        trial_limits = PLAN_LIMITS.get(plan_key, PLAN_DEFAULT)
        return {"status": "trial", "required": (days is not None and days < 0), "days_left": days,
                "plan": plan_key or "pro", "limits": trial_limits}
    # past_due / canceled / unpaid → bloqueado
    return {"status": status, "required": True, "days_left": None, "plan": plan_key or "basico", "limits": PLAN_LIMITS.get(plan_key, PLAN_LIMITS["basico"])}


@api_router.get("/org/billing")
async def org_billing(user: dict = Depends(get_current_user)):
    """Estado de la suscripción de TU organización (trial, días restantes, si toca pagar)."""
    org = await get_org(user.get("org_id"))
    b = _org_billing(org)
    b["account_type"] = (org or {}).get("account_type")
    b["org_name"] = (org or {}).get("name")
    return b


# ===== UPGRADE PRORRATEADO =====

# Precio POR FURGONETA y mes, con un minimo facturable. El minimo evita que una
# flota de 5 furgonetas salga a 40 EUR: por debajo de cierto tamaño el soporte
# cuesta lo mismo que en una grande.
PLAN_TARIFAS = {
    "operacion": {"por_vehiculo": 5, "minimo_vehiculos": 20, "rango": 1},
    "completo":  {"por_vehiculo": 8, "minimo_vehiculos": 20, "rango": 2},
    "holding":   {"por_vehiculo": 0, "minimo_vehiculos": 0,  "rango": 3},  # a medida
}
# Claves antiguas -> nuevas. Sin esto, una organizacion con plan "pro" se
# quedaria sin tarifa y sin limites.
_PLAN_ALIAS = {"basico": "operacion", "pro": "completo", "flota": "completo",
               "enterprise": "holding"}


# El catalogo vive en BD para poder cambiarlo sin desplegar. Cache de 60 s: se
# consulta en cada pagina de precios y no hace falta ir a Mongo cada vez.
_CATALOGO_CACHE = {"ts": 0.0, "datos": None}
_CATALOGO_TTL = 60.0


def _catalogo_por_defecto():
    """Los valores del codigo. Respaldo si la BD no tiene nada."""
    return {
        "moneda": "EUR",
        "descuento_anual_meses": 2,
        "iva_pct": 21,
        "planes": [
            {"clave": "operacion", "nombre": "Operación", "para": "Un centro",
             "por_vehiculo": PLAN_TARIFAS["operacion"]["por_vehiculo"],
             "minimo_vehiculos": PLAN_TARIFAS["operacion"]["minimo_vehiculos"],
             "recomendado": False},
            {"clave": "completo", "nombre": "Completo", "para": "Varios centros",
             "por_vehiculo": PLAN_TARIFAS["completo"]["por_vehiculo"],
             "minimo_vehiculos": PLAN_TARIFAS["completo"]["minimo_vehiculos"],
             "recomendado": True},
            {"clave": "holding", "nombre": "Holding", "para": "Cinco estaciones o más",
             "por_vehiculo": 0, "minimo_vehiculos": 0, "recomendado": False},
        ],
    }


async def _catalogo_planes(forzar: bool = False):
    """Catalogo vigente: BD si existe, codigo si no. Nunca lanza."""
    ahora = time.time()
    if not forzar and _CATALOGO_CACHE["datos"] and ahora - _CATALOGO_CACHE["ts"] < _CATALOGO_TTL:
        return _CATALOGO_CACHE["datos"]
    datos = _catalogo_por_defecto()
    try:
        doc = await global_db.plan_catalog.find_one({"_id": "vigente"}, {"_id": 0})
        if doc and isinstance(doc.get("planes"), list) and doc["planes"]:
            datos = {**datos, **doc}
    except Exception as e:
        logger.warning(f"Catalogo de planes: uso los valores del codigo ({e})")
    _CATALOGO_CACHE.update({"ts": ahora, "datos": datos})
    return datos


def _tarifa_de(catalogo, plan):
    """Tarifa de un plan dentro de un catalogo ya cargado."""
    canon = _plan_canon(plan)
    for p in catalogo.get("planes") or []:
        if p.get("clave") == canon:
            return p
    return None


def _plan_canon(plan) -> str:
    """Nombre canonico del plan, aceptando las claves antiguas."""
    p = (plan or "").lower().strip()
    for a, b in (("á", "a"), ("é", "e"), ("í", "i"), ("ó", "o"), ("ú", "u")):
        p = p.replace(a, b)
    return _PLAN_ALIAS.get(p, p)


def _precio_mensual(plan, n_vehiculos: int) -> int:
    """Lo que paga al mes una flota de ese tamaño, segun el CODIGO.

    Para el precio real usa _precio_vigente: respeta lo que se haya editado
    desde el panel. Esta se queda para los sitios sincronos.
    """
    t = PLAN_TARIFAS.get(_plan_canon(plan))
    if not t or not t.get("por_vehiculo"):
        return 0
    return int(t["por_vehiculo"] * max(int(n_vehiculos or 0), t["minimo_vehiculos"]))


async def _precio_vigente(plan, n_vehiculos: int) -> int:
    """Precio con la tarifa que este puesta AHORA (editable desde el panel)."""
    t = _tarifa_de(await _catalogo_planes(), plan)
    if not t or not t.get("por_vehiculo"):
        return 0
    return int(float(t["por_vehiculo"]) * max(int(n_vehiculos or 0),
                                              int(t.get("minimo_vehiculos") or 0)))


# Compatibilidad: precio de referencia de una flota tipo (30 furgonetas), para
# el codigo viejo que aun compara planes por precio.
PLAN_PRICES = {k: _precio_mensual(k, 30) for k in
               ("operacion", "completo", "holding", "basico", "pro", "flota")}
PLAN_PRICES["enterprise"] = 0
PLAN_PRICES["owner"] = 0
# Orden por lo que DESBLOQUEA cada plan, no por lo que cuesta: holding se
# factura a medida (0 €) pero lo incluye todo, así que por precio pasaría por
# "bajada de plan". "owner" es interno: fuera del mapa a propósito, nadie
# puede pedirlo (solo super-admin).
_PLAN_RANGO = {k: v["rango"] for k, v in PLAN_TARIFAS.items()}
_PLAN_RANGO.update({viejo: PLAN_TARIFAS[nuevo]["rango"]
                    for viejo, nuevo in _PLAN_ALIAS.items()})

@api_router.get("/org/upgrade-preview")
async def upgrade_preview(new_plan: str, user: dict = Depends(require_admin)):
    """Calcula el coste real de subir de plan a mitad de ciclo.
    Devuelve: credit (días ya pagados del plan actual), charge (a pagar ahora), total_new (precio completo del nuevo plan)."""
    org = await get_org(user.get("org_id"))
    billing = _org_billing(org)
    current_plan = billing.get("plan", "basico")
    new_plan = new_plan.lower().strip()

    if new_plan not in PLAN_LIMITS:
        raise HTTPException(400, "Plan no válido")
    if _plan_canon(new_plan) == _plan_canon(current_plan):
        raise HTTPException(400, "Ya estás en ese plan")

    # El precio depende del tamaño de la flota, no es plano.
    n_vehiculos = await db.vehicles.count_documents({"status": {"$nin": ["deleted", "baja"]}})
    current_price = _precio_mensual(current_plan, n_vehiculos)
    new_price = _precio_mensual(new_plan, n_vehiculos)

    if new_price <= current_price:
        return {"type": "downgrade", "current_plan": current_plan, "new_plan": new_plan,
                "message": "El cambio a un plan inferior se aplica al siguiente ciclo de facturación.",
                "charge": 0, "credit": 0, "total_new": new_price}

    # Calcular días restantes del mes actual
    today = datetime.now(timezone.utc)
    import calendar as _cal
    days_in_month = _cal.monthrange(today.year, today.month)[1]
    days_used = today.day - 1
    days_remaining = days_in_month - days_used
    credit = round(current_price * days_remaining / days_in_month, 2)
    prorated_new = round(new_price * days_remaining / days_in_month, 2)
    charge = max(0, round(prorated_new - credit, 2))

    return {
        "type": "upgrade",
        "current_plan": current_plan, "new_plan": new_plan,
        "current_price": current_price, "new_price": new_price,
        "days_remaining": days_remaining, "days_in_month": days_in_month,
        "credit": credit,
        "prorated_new": prorated_new,
        "charge": charge,
        "message": f"Pagas {charge}€ ahora ({days_remaining} días del nuevo plan menos {credit}€ de crédito del plan actual).",
    }


@api_router.post("/org/change-plan")
async def change_plan(data: dict = Body(...), user: dict = Depends(require_admin)):
    """Cambia el plan de la organización.

    Bajar de plan es self-service. SUBIR no: lo aplica el webhook de Lemon
    Squeezy cuando el pago entra de verdad. Antes esta ruta escribía el plan
    que le pidieras, así que cualquier admin podía ponerse en el plan más caro
    gratis — no se notaba porque ninguna pantalla la llamaba, pero es HTTP
    público. El super-admin sí puede forzarlo (soporte) y queda auditado.
    """
    new_plan = (data.get("plan") or "").lower().strip()
    if new_plan not in PLAN_LIMITS:
        raise HTTPException(400, "Plan no válido")
    org = await get_org(user.get("org_id"))
    if not org:
        raise HTTPException(404, "Organización no encontrada")

    plan_actual = _org_billing(org).get("plan", "basico")
    if new_plan == plan_actual:
        raise HTTPException(400, "Ya estás en ese plan")

    # El super-admin se marca con el flag "sa", NO con role=="sa" (asi lo
    # comprueban require_superadmin y el resto del fichero). Con la version
    # anterior la via de soporte no funcionaba nunca.
    es_superadmin = bool(user.get("sa"))
    # Sin rango conocido (p. ej. "owner") no es self-service jamás.
    rango_nuevo = _PLAN_RANGO.get(new_plan)
    sube = rango_nuevo is None or rango_nuevo > _PLAN_RANGO.get(plan_actual, 0)
    if sube and not es_superadmin:
        raise HTTPException(
            status_code=402,
            detail="Para subir de plan hay que completar el pago. "
                   "El plan se activa solo cuando el pago se confirma.")

    await global_db.organizations.update_one(
        {"id": org["id"]},
        {"$set": {"plan": new_plan, "plan_changed_at": datetime.now(timezone.utc).isoformat()}}
    )
    await _audit(user, "cambio_de_plan", {
        "org_id": org["id"], "org": org.get("name") or org.get("slug"),
        "de": plan_actual, "a": new_plan,
        "forzado_por_superadmin": bool(es_superadmin and sube),
    })
    return {"success": True, "plan": new_plan, "anterior": plan_actual}


