@api_router.get("/scoring/drivers")
async def get_driver_scoring(month: int = None, year: int = None, _=Depends(require_admin)):
    """Scoring competitivo de conductores (0-100), 5 pilares:

      📋 Cumplimiento   30 — inspecciones hechas vs días con asignación en el cuadrante
                              (si no hay cuadrantes, días naturales transcurridos)
      ⏰ Puntualidad    15 — hora de subida: 100% antes de las 20:45 (vuelta de ruta),
                              decae hasta 0 a las 23:00
      📸 Evidencia      15 — fotos completas + análisis OK; cada aviso de calidad
                              de la IA (borrosa, zona equivocada) resta
      🔍 Honestidad     15 — si la IA ve daños, ¿los declaró en sus notas?
      🛡️ Conservación   25 — daños NUEVOS en su turno, con TRES garantías de
                              justicia: (1) el veredicto humano de Revisión
                              Rápida manda (✗ nunca penaliza, ✓ cuenta siempre);
                              (2) rate-based: penaliza la TASA de daños, no el
                              volumen — trabajar más días no castiga;
                              (3) suavizado bayesiano con muestras pequeñas.

    🏆 Premio del mes: solo son ELEGIBLES los conductores con ≥35% de los días
    transcurridos asignados en cuadrante (mín. 3) — nadie gana con 3 días buenos.
    Desempate: racha limpia, luego nº de inspecciones. Puntualidad en hora
    Europe/Madrid real (con cambio de hora). Mínimo 3 inspecciones para puntuar.
    """
    import calendar as _cal
    now = datetime.now(timezone.utc)
    y = year or now.year
    m = month or now.month
    days_in_month = _cal.monthrange(y, m)[1]
    month_start = datetime(y, m, 1, tzinfo=timezone.utc)
    month_end = datetime(y, m, days_in_month, 23, 59, 59, tzinfo=timezone.utc)
    days_elapsed = now.day if (y == now.year and m == now.month) else days_in_month

    inspections_month = await db.inspections.find(
        {"deleted": {"$ne": True}, "created_at": {"$gte": month_start.isoformat(), "$lte": month_end.isoformat()}},
        {"_id": 0}
    ).to_list(length=5000)

    drivers = await db.drivers.find({"status": {"$ne": "deleted"}, "active": {"$ne": False}}, {"_id": 0}).to_list(500)

    # Días asignados por conductor según los cuadrantes del mes
    assignments = await db.daily_assignments.find(
        {"date": {"$gte": month_start.strftime("%Y-%m-%d"), "$lte": month_end.strftime("%Y-%m-%d")}},
        {"_id": 0, "date": 1, "slots.driver_id": 1}
    ).to_list(200)
    assigned_days = {}
    for a in assignments:
        for slot in a.get("slots", []):
            did = slot.get("driver_id")
            if did:
                assigned_days.setdefault(did, set()).add(a.get("date"))

    # Historial por vehículo SOLO con análisis válidos (para el delta) — acotado a 6 meses atrás
    _history_start = datetime(y, m, 1, tzinfo=timezone.utc) - __import__('datetime').timedelta(days=180)
    all_inspections = await db.inspections.find(
        {"deleted": {"$ne": True}, "analysis_status": "ok", "analysis": {"$ne": None},
         "created_at": {"$gte": _history_start.isoformat()}},
        {"_id": 0, "id": 1, "vehicle_id": 1, "driver_id": 1, "created_at": 1, "analysis": 1}
    ).sort("created_at", 1).to_list(length=2000)
    vehicle_history = {}
    for insp in all_inspections:
        vid = insp.get("vehicle_id")
        if vid:
            vehicle_history.setdefault(vid, []).append(insp)

    SEV = {"sin_danos": 0, "sin_daños": 0, "": 0, "leve": 1, "moderado": 1, "grave": 2, "critico": 3, "crítico": 3}

    def get_sev(insp):
        a = insp.get("analysis") or {}
        return SEV.get((a.get("severity") or "").lower().strip(), 0)

    def hour_of(iso):
        """Hora local española REAL (Europe/Madrid, con horario de verano/invierno)."""
        try:
            from zoneinfo import ZoneInfo
            dt = datetime.fromisoformat(iso.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            local = dt.astimezone(ZoneInfo("Europe/Madrid"))
            return local.hour + local.minute / 60.0
        except Exception:
            return None

    # ── Veredictos humanos de Revisión Rápida ──
    # Un daño marcado ✗ (falso positivo) por un inspector NO puede penalizar al
    # conductor; uno marcado ✓ cuenta aunque la IA dudara. El humano manda.
    _fb_docs = await db.ai_feedback.find(
        {"verdict": {"$in": ["wrong", "correct"]}},
        {"_id": 0, "inspection_id": 1, "verdict": 1, "damage.part": 1, "damage.zone": 1, "damage.location": 1}
    ).to_list(5000)
    wrong_panels: dict = {}   # inspection_id → set(panels rechazados por humano)
    correct_panels: dict = {}  # inspection_id → set(panels confirmados por humano)
    for _f in _fb_docs:
        _dmg = _f.get("damage") or {}
        _p = _canon_panel(_dmg.get("part") or _dmg.get("zone") or _dmg.get("location"))
        if not _p:
            continue
        _target = wrong_panels if _f["verdict"] == "wrong" else correct_panels
        _target.setdefault(_f.get("inspection_id"), set()).add(_p)

    results = []
    for driver in drivers:
        driver_id = driver.get("id")
        name = driver.get("name", "—")
        center = driver.get("center", "—")
        driver_insps = [i for i in inspections_month if i.get("driver_id") == driver_id]
        n = len(driver_insps)

        if n < 3:
            results.append({
                "driver_id": driver_id, "name": name, "center": center,
                "photo_url": driver.get("photo_url"),
                "total": None, "inspections_count": n, "insufficient": True,
            })
            continue

        # ── 📋 Cumplimiento (30) ──
        days_assigned = len(assigned_days.get(driver_id, set()))
        denom = days_assigned if days_assigned >= 3 else max(days_elapsed, 1)
        compliance = round(min(30, (n / denom) * 30))

        # ── ⏰ Puntualidad (15) ──
        punct_scores = []
        for insp in driver_insps:
            hr = hour_of(insp.get("created_at", ""))
            if hr is None:
                continue
            # Operación DSP real: inspección al volver de ruta. Puntual = antes
            # de las 20:45; decae hasta 0 a las 23:00. Las de mañana (pre-ruta,
            # antes de las 12:00) también puntúan completo.
            if hr <= 12.0 or hr <= 20.75:
                punct_scores.append(15)
            elif hr >= 23.0:
                punct_scores.append(0)
            else:
                punct_scores.append(15 * (23.0 - hr) / 2.25)
        punctuality = round(sum(punct_scores) / len(punct_scores)) if punct_scores else 8

        # ── 📸 Evidencia (15) ──
        ev_scores = []
        for insp in driver_insps:
            photos = len(insp.get("photo_urls") or insp.get("photos") or [])
            ok = insp.get("analysis_status") == "ok"
            base = 15 if (photos >= 5 and ok) else 11 if photos >= 4 else 6 if photos >= 2 else 0
            warns = len(((insp.get("analysis") or {}).get("image_quality_warnings")) or [])
            ev_scores.append(max(0, base - 3 * warns))
        evidence = round(sum(ev_scores) / len(ev_scores)) if ev_scores else 0

        # ── 🔍 Honestidad (15) ──
        # JUSTO: solo se examina la honestidad cuando hay daño NUEVO serio
        # (abolladura/grave/crítico) en esa inspección. No se pide declarar lo
        # preexistente (el sistema ya lo conoce del historial) ni los rayones
        # leves — así no es una carga y no penaliza por daño que ya estaba.
        h_scores = []
        for insp in driver_insps:
            a = insp.get("analysis") or {}
            serious_new = any(
                _norm_sev(d.get("severity")) in ("moderado", "grave", "critico")
                for d in (a.get("new_damages") or []) if isinstance(d, dict))
            if insp.get("analysis_status") == "ok" and serious_new:
                notes = (insp.get("notes") or "").lower()
                kws = ["daño", "dano", "golpe", "rasguño", "rasguno", "rayad", "abollad",
                       "roto", "rota", "crack", "grieta", "araña", "arana", "choc", "malo", "danado",
                       "raya", "marca", "toque", "incidente"]
                # Declararlo = 15 (transparente). No declararlo NO es prueba de
                # ocultación (quizá no lo vio o no sabía que debía) → suelo de 10,
                # no un cero que hunda el score antes de educar el hábito.
                h_scores.append(15 if any(k in notes for k in kws) else 10)
        honesty = round(sum(h_scores) / len(h_scores)) if h_scores else 15

        # ── 🛡️ Conservación (25) — rate-based, confirmed-only, Bayesian-smoothed ──
        #
        #  Tres garantías de justicia:
        #  1) Solo daños CONFIRMADOS (confidence ≥ 0.65). Los "sugeridos" no penalizan
        #     aunque aparezcan en la foto anotada para revisión del admin.
        #  2) Rate-based: se pondera por nº de inspecciones del mes, así quien trabaja
        #     más días con la misma tasa de incidencias puntúa igual que quien trabaja
        #     menos — la exposición mayor no castiga.
        #  3) Bayesian smoothing (k=5): con pocas inspecciones el score se acerca a la
        #     media perfecta (25 pts), evitando premiar/castigar con muestras pequeñas.
        #     Con ≥15 inspecciones el peso propio del conductor es ya >75%.
        #
        #  Pesos de severidad (escala cuadrática: grave duele 3×, crítico 6×):
        #    leve=0  moderado=1  grave=3  crítico=6
        #  Conservación = 25 × exp(−rate × 1.2),  Bayesian → (raw×n + 25×5)/(n+5)
        import math as _math
        SEV_W = {"leve": 0, "moderado": 1, "grave": 3, "critico": 6}
        delta_events = []
        for insp in driver_insps:
            vid = insp.get("vehicle_id")
            if not vid or vid not in vehicle_history:
                continue
            if insp.get("analysis_status") != "ok" or not insp.get("analysis"):
                continue
            insp_time = insp.get("created_at", "")
            prior = [h for h in vehicle_history[vid] if h.get("created_at", "") < insp_time]
            if not prior:
                continue  # sin baseline → no se puede saber qué es nuevo
            base_panels = set()
            for h in prior:
                for d in ((h.get("analysis") or {}).get("damages") or []):
                    if isinstance(d, dict):
                        p = _canon_panel(d.get("part") or d.get("zone") or d.get("location"))
                        if p:
                            base_panels.add(p)
            photos = insp.get("photo_urls") or insp.get("photos") or []
            curr = {}
            _iid = insp.get("id")
            _wrong = wrong_panels.get(_iid, set())
            _correct = correct_panels.get(_iid, set())
            for d in ((insp.get("analysis") or {}).get("damages") or []):
                if not isinstance(d, dict):
                    continue
                p = _canon_panel(d.get("part") or d.get("zone") or d.get("location"))
                if not p:
                    continue
                # Veredicto humano manda: ✗ nunca penaliza; ✓ cuenta aunque la IA dudara
                if p in _wrong:
                    continue
                if d.get("confirmed") is False and p not in _correct:
                    continue  # sugerido sin confirmación humana → no penaliza
                sev = _norm_sev(d.get("severity"))
                rank = _SEV_RANK[sev]
                if rank > curr.get(p, {}).get("rank", 0):
                    curr[p] = {"rank": rank, "sev": sev, "dmg": d}
            for p, info in curr.items():
                sev = info["sev"]
                w = SEV_W.get(sev, 0)
                if p not in base_panels and w > 0:
                    d = info["dmg"]
                    pidx = d.get("photo_index")
                    photo_url = (photos[pidx - 1] if isinstance(pidx, int) and 1 <= pidx <= len(photos)
                                 else (photos[0] if photos else None))
                    # penalty_display: equivalencia visual con el sistema anterior
                    _PEN_DISP = {"moderado": -6, "grave": -12, "critico": -20}
                    delta_events.append({
                        "vehicle_id": vid,
                        "panel": p,
                        "part": d.get("part") or p,
                        "to_sev": sev,
                        "weight": w,
                        "penalty": _PEN_DISP.get(sev, 0),  # solo display
                        "date": insp_time[:10] if len(insp_time) >= 10 else insp_time,
                        "inspection_id": insp.get("id"),
                        "photo_url": photo_url,
                        "box_2d": d.get("box_2d"),
                        "description": d.get("description"),
                        "confirmed": d.get("confirmed", True),
                    })

        # Rate: peso total / nº inspecciones → independiente del volumen de trabajo
        total_dmg_weight = sum(e["weight"] for e in delta_events)
        damage_rate = total_dmg_weight / max(n, 1)
        # Curva exponencial: rate=0 → 25 pts; rate=1 (1 grave/insp) → ~8 pts; rate=2 → ~2 pts
        raw_conservation = round(25 * _math.exp(-damage_rate * 1.2))
        # Bayesian prior k=5: mezcla el resultado propio con la media perfecta (25)
        # para que los conductores con pocas inspecciones no distorsionen el ranking
        _k = 5
        conservation = round((raw_conservation * n + 25 * _k) / (n + _k))

        # ── 📈 Tendencia del mes (no suma en total — informa al admin) ──
        # Compara la tasa de daño de la primera mitad del mes vs la segunda.
        insps_sorted = sorted(driver_insps, key=lambda x: x.get("created_at", ""))
        half = max(len(insps_sorted) // 2, 1)

        def _half_rate(subset):
            w = sum(
                SEV_W.get(_norm_sev(d.get("severity")), 0)
                for i in subset
                for d in ((i.get("analysis") or {}).get("damages") or [])
                if isinstance(d, dict) and d.get("confirmed") is not False
            )
            return w / max(len(subset), 1)

        if len(insps_sorted) >= 4:
            r1 = _half_rate(insps_sorted[:half])
            r2 = _half_rate(insps_sorted[half:])
            if r2 < r1 * 0.7:
                trend = "mejorando"
            elif r2 > r1 * 1.4:
                trend = "empeorando"
            else:
                trend = "estable"
        else:
            trend = "sin_datos"

        # ── 🔥 Racha limpia (no suma en total — tiebreaker + badge) ──
        # Inspecciones consecutivas más recientes sin daño confirmado ≥ moderado.
        clean_streak = 0
        for insp in reversed(insps_sorted):
            if insp.get("analysis_status") != "ok":
                continue
            new_dmgs = ((insp.get("analysis") or {}).get("new_damages") or
                        (insp.get("analysis") or {}).get("damages") or [])
            has_new_confirmed = any(
                d.get("confirmed") is not False and
                _norm_sev(d.get("severity")) in ("moderado", "grave", "critico")
                for d in new_dmgs if isinstance(d, dict)
            )
            if not has_new_confirmed:
                clean_streak += 1
            else:
                break

        total = min(100, compliance + punctuality + evidence + honesty + conservation)

        # ── 🏆 Elegibilidad para el premio del mes ──
        # Regla explicable: al menos el 35% de los días transcurridos con
        # asignación en el cuadrante (mínimo 3). Sin cuadrantes, cuentan las
        # inspecciones hechas. Evita que una muestra pequeña gane el premio.
        _prize_min = max(3, round(days_elapsed * 0.35))
        _base_days = days_assigned if days_assigned > 0 else n
        prize_eligible = _base_days >= _prize_min

        results.append({
            "driver_id": driver_id, "name": name, "center": center,
            "photo_url": driver.get("photo_url"),
            "total": total,
            "prize_eligible": prize_eligible,
            "compliance": compliance, "punctuality": punctuality,
            "evidence": evidence, "honesty": honesty, "conservation": conservation,
            "damage_rate": round(damage_rate, 3),       # rate crudo (debug / gráficas)
            "trend": trend,                             # mejorando / empeorando / estable
            "clean_streak": clean_streak,               # racha de inspecciones limpias
            "delta_events": delta_events,
            "inspections_count": n,
            "days_assigned": days_assigned,
            "days_elapsed": days_elapsed,
            "insufficient": False,
        })

    # Orden: puntuación desc; desempate por racha limpia; los 'sin datos' al final
    results.sort(key=lambda x: (
        x["total"] is None,
        -(x["total"] or 0),
        -(x.get("clean_streak") or 0),
        -x["inspections_count"],
    ))
    return {"scores": results, "month": m, "year": y, "days_elapsed": days_elapsed,
            "min_inspections": 3, "prize_min_days": max(3, round(days_elapsed * 0.35))}


@api_router.get("/scoring/leaderboard")
async def get_scoring_leaderboard(month: int = None, year: int = None, _=Depends(require_admin)):
    """Top-3 conductores por centro según el scoring mensual.

    Devuelve para cada centro los tres mejores conductores con su puntuación,
    racha limpia, tendencia y una medalla (oro/plata/bronce).
    Solo conductores con al menos 3 inspecciones en el mes.
    """
    import calendar as _cal
    now = datetime.now(timezone.utc)
    y = year or now.year
    m = month or now.month
    days_in_month = _cal.monthrange(y, m)[1]
    month_start = datetime(y, m, 1, tzinfo=timezone.utc)
    month_end = datetime(y, m, days_in_month, 23, 59, 59, tzinfo=timezone.utc)

    # Reusar el endpoint de scoring completo para obtener todos los datos.
    # El PODIO solo admite conductores elegibles para el premio (≥35% de días
    # asignados): nadie gana el mes con una muestra pequeña.
    full = await get_driver_scoring(month=m, year=y)
    scores = [s for s in full["scores"] if not s.get("insufficient") and s.get("prize_eligible")]

    MEDALS = ["🥇", "🥈", "🥉"]
    BADGE_LABELS = {
        "🥇": "oro", "🥈": "plata", "🥉": "bronce",
    }

    leaderboard = {}
    centers_seen = set()
    for s in scores:
        c = s["center"]
        centers_seen.add(c)
        if c not in leaderboard:
            leaderboard[c] = []
        if len(leaderboard[c]) < 3:
            pos = len(leaderboard[c])
            leaderboard[c].append({
                "position": pos + 1,
                "medal": MEDALS[pos],
                "badge": BADGE_LABELS[MEDALS[pos]],
                "driver_id": s["driver_id"],
                "name": s["name"],
                "photo_url": s.get("photo_url"),
                "total": s["total"],
                "trend": s.get("trend", "sin_datos"),
                "clean_streak": s.get("clean_streak", 0),
                "inspections_count": s["inspections_count"],
                "compliance": s.get("compliance"),
                "conservation": s.get("conservation"),
                "damage_rate": s.get("damage_rate"),
                "prize_eligible": True,
            })

    # Estadísticas por centro (para comparativas)
    center_stats = {}
    for c in centers_seen:
        center_scores = [s["total"] for s in scores if s["center"] == c]
        if center_scores:
            center_stats[c] = {
                "drivers_ranked": len(center_scores),
                "avg_score": round(sum(center_scores) / len(center_scores), 1),
                "top_score": max(center_scores),
            }

    return {
        "month": m, "year": y,
        "leaderboard": leaderboard,
        "center_stats": center_stats,
        "prize_min_days": full.get("prize_min_days"),
    }


@api_router.patch("/vehicles/{vehicle_id}")
async def update_vehicle(vehicle_id: str, data: dict, _=Depends(require_admin)):
    _VEHICLE_ALLOWED = {
        "license_plate","brand","model","year","color","fuel_type","status",
        "center","notes","current_driver_id","mileage","last_itv","next_itv",
        "last_service","next_service","photo_url","vin","seats","load_capacity",
        "acquisition_date","insurance_expiry","leasing","owner","gps_id","tags",
        # Campos que edita la ficha del panel (antes se filtraban y el guardado
        # fallaba en silencio): tipo, ITV, renting, proveedor y motivo de taller.
        "vehicle_type","itv_date","renting_end_date","renting_baja_date",
        "provider","workshop_status","workshop_reason",
        # El candado de la plantilla diaria: la furgoneta sigue activa para todo
        # lo demas, pero no se ofrece para asignar ese dia (lo pidio Mery el
        # 03-09-2026: «una que no esta en taller pero no quieres que salga»).
        "bloqueada", "bloqueada_motivo",
    }
    data = {k: v for k, v in data.items() if k in _VEHICLE_ALLOWED}
    # EL CENTRO SE GUARDA LIMPIO. Aqui entraba 'AMZL OGA5 SANTIAGO XPT' y
    # convivia con 'OGA5', asi que cualquier recuento que agrupe por centro
    # partia OGA5 en dos mitades (gotcha 6). Solo se toca si el codigo ya existe
    # limpio en la base: un centro nuevo se queda tal cual.
    if "center" in data:
        data["center"] = _centro_norm(data["center"], await _centros_conocidos())
    prev = await db.vehicles.find_one({"id": vehicle_id}, {"_id": 0, "status": 1})
    try:
        result = await db.vehicles.update_one({"id": vehicle_id}, {"$set": data})
    except DuplicateKeyError:
        # Cambiarle la matricula a una que ya lleva otra furgoneta viva, o
        # resucitar una `deleted` con matricula ya ocupada: el indice lo para.
        raise HTTPException(409, "Esa matrícula ya la lleva otra furgoneta dada de alta.")
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Vehículo no encontrado")
    if "status" in data:
        try:
            await _auto_incident_on_workshop(vehicle_id, (prev or {}).get("status"), data.get("status"))
        except Exception as _ai:
            logger.warning(f"Auto-incidencia taller: {_ai}")
    return {"success": True}


# =========================
# DRIVERS — solo admin
# =========================

@api_router.post("/drivers", response_model=Driver)
async def create_driver(data: DriverCreate, admin: dict = Depends(require_admin)):
    driver_data = data.model_dump()
    password = driver_data.pop("password", None)

    driver = Driver(**driver_data)
    # UNA PERSONA, UNA FICHA ACTIVA. Esta ruta no comprobaba nada: dos altas
    # con el mismo correo, seguidas o a la vez, daban dos fichas, y el login
    # del portal cae en la que Mongo tenga primero (gotcha 15). Se compara sin
    # distinguir mayusculas y solo contra las activas: una persona que vuelve
    # tras una baja se da de alta otra vez con normalidad.
    email = (driver.email or "").strip()
    if email:
        otra = await db.drivers.find_one(
            {"email": {"$regex": "^%s$" % re.escape(email), "$options": "i"},
             "active": {"$ne": False}}, {"_id": 0, "id": 1, "name": 1})
        if otra:
            raise HTTPException(
                409, "Ya hay un conductor activo con el correo %s (%s). Edita esa "
                     "ficha o cambia el correo." % (email, otra.get("name") or otra.get("id")))
    doc = serialize_doc(driver.model_dump())
    try:
        await db.drivers.insert_one(doc)
    except DuplicateKeyError:
        # Dos altas A LA VEZ: la comprobacion de arriba las deja pasar a las
        # dos y solo el indice `email_unico_activo` para a la segunda.
        raise HTTPException(409, "Ya hay un conductor activo con el correo %s." % email)

    if password and driver.email:
        await db.driver_accounts.insert_one({
            "id": str(uuid.uuid4()),
            "driver_id": driver.id,
            "email": driver.email,
            "hashed_password": hash_password(password),
            "active": True,
            "created_at": datetime.now(timezone.utc).isoformat()
        })
        logger.info(f"Conductor y cuenta creados: {driver.email}")

    return driver


_CENTRO_RE = re.compile(r"\b([A-Z]{2,4}\d{1,2})\b")


def _centro_norm(valor, conocidos=None) -> str:
    """Deja el centro en su codigo: 'AMZL OGA5 SANTIAGO XPT' -> 'OGA5'.

    El mismo centro esta guardado de siete formas en `vehicles`: 'OGA5' (76),
    'AMZL OGA5 SANTIAGO XPT' (37), 'oga5' (5), 'OGA5 ' (2)... El gotcha 6 lo
    documenta y por eso los filtros van por `$regex`, pero eso arregla la
    LECTURA, no el dato: cualquier recuento nuevo que agrupe por centro parte
    OGA5 en dos mitades sin avisar. Paso el 28-08-2026 contando la flota.

    NO ADIVINA. Solo reescribe cuando dentro del texto aparece EXACTAMENTE UN
    codigo que ya existe limpio en la base. Un centro nuevo que nadie haya
    escrito bien todavia se queda como esta, que es mejor que renombrarlo a algo
    que no es. Devuelve el original —solo recortado y en mayusculas— si no lo
    tiene claro.
    """
    t = str(valor or "").strip().upper()
    if not t:
        return ""
    if conocidos and t in conocidos:
        return t
    hallados = {c for c in _CENTRO_RE.findall(t) if not conocidos or c in conocidos}
    return hallados.pop() if len(hallados) == 1 else t


async def _centro_por_defecto() -> str:
    """El centro que se usa cuando no viene ninguno.

    Tres sitios lo tenian escrito como "OGA5" —importar cuadrante y las dos
    rutas del plan de reparto—, o sea el centro de la empresa principal. En
    cualquier otra, esos datos se guardaban en un centro que no existe en su
    flota y no volvian a aparecer en ninguna pantalla, sin ningun error.

    Se usa el PRIMERO de `organizations.centers`, que es el principal: el que
    la empresa escribio al darse de alta. Ordenar alfabeticamente parecia mas
    limpio y era peor — a la empresa principal le habria cambiado el centro por
    defecto de OGA5 a DGA1 en silencio, que es exactamente el tipo de cambio
    que nadie nota hasta que faltan datos en una pantalla.

    Si la organizacion no se encuentra, se cae a los centros que ya existen en
    los datos; y si tampoco hay, cadena vacia: mejor que decida quien llama,
    antes que inventarse el centro de otro.
    """
    try:
        org = await global_db.organizations.find_one(
            {"db_name": _current_db_name.get()}, {"_id": 0, "centers": 1})
        if not org and _current_db_name.get() == _DEFAULT_DB_NAME:
            # La organizacion principal no guarda `db_name`: se resuelve por
            # `account_type == "owner"` (ver `_tenant_db_name`).
            org = await global_db.organizations.find_one(
                {"account_type": "owner"}, {"_id": 0, "centers": 1})
        cs = [str(c).strip().upper() for c in ((org or {}).get("centers") or []) if str(c).strip()]
        if cs:
            return cs[0]
        conocidos = sorted(c for c in await _centros_conocidos() if c)
        return conocidos[0] if conocidos else ""
    except Exception:
        return ""


async def _centros_conocidos() -> set:
    """Los codigos de centro que ya existen escritos limpios.

    Se sacan de `drivers`, que es la coleccion que los tiene bien (medido: 4
    formas y todas limpias), y no de `vehicles`, que es justo la sucia. Sin esta
    lista, `_centro_norm` no puede distinguir un codigo de verdad de tres letras
    y un numero que aparezcan por casualidad en un texto libre.
    """
    fuera = set()
    for col in ("drivers", "cortex_stations", "workshops"):
        for v in await db[col].distinct("center"):
            t = str(v or "").strip().upper()
            if t and _CENTRO_RE.fullmatch(t):
                fuera.add(t)
    return fuera


@api_router.get("/drivers/duplicados")
async def drivers_duplicados(_=Depends(require_admin)):
    """La misma persona dada de alta dos veces, emparejada por CORREO.

    Por correo y nunca por nombre: dos tocayos distintos acabarian fusionados y
    uno auditando la furgoneta del otro. El correo lo pone la empresa y es unico
    por persona (gotcha 15).

    Esto ya costo un dia de operacion. El 19-08-2026 hubo cinco conductores en
    ruta viendo "no tienes furgoneta asignada": el cuadrante apuntaba a una
    ficha y el login del portal resuelve por correo con `find_one`, que devuelve
    la que Mongo tenga primero — normalmente la otra. Medido el 28-08-2026
    seguian 13 correos con dos fichas, 14 fichas de mas.

    De cada ficha se cuenta lo que cuelga de ella para poder decidir cual se
    queda: la que tiene el historial, no la que se creo antes.

    OJO AL ORDEN: declarado ANTES de /drivers/{driver_id}/... o 'duplicados'
    entraria como si fuera un id.
    """
    porcorreo: dict = {}
    async for d in db.drivers.find({}, {"_id": 0}):
        e = (d.get("email") or "").strip().lower()
        if not e or d.get("merged_into"):
            continue
        porcorreo.setdefault(e, []).append(d)
    grupos = {e: v for e, v in porcorreo.items() if len(v) > 1}
    if not grupos:
        return {"grupos": [], "total": 0, "fichas_de_mas": 0}

    ids = [d["id"] for v in grupos.values() for d in v if d.get("id")]
    async def _cuenta(col, campo):
        out: dict = {}
        async for r in db[col].aggregate([
            {"$match": {campo: {"$in": ids}}},
            {"$group": {"_id": "$" + campo, "n": {"$sum": 1}}},
        ]):
            out[r["_id"]] = r["n"]
        return out
    insp = await _cuenta("inspections", "driver_id")
    turnos = await _cuenta("shifts", "driver_id")
    pets = await _cuenta("shift_requests", "driver_id")
    asig: dict = {}
    async for a_doc in db.daily_assignments.find({}, {"_id": 0, "slots": 1}):
        for sl in (a_doc.get("slots") or []):
            if sl.get("driver_id") in ids:
                asig[sl["driver_id"]] = asig.get(sl["driver_id"], 0) + 1

    fuera = []
    for e, fichas in sorted(grupos.items()):
        filas = []
        for d in fichas:
            i = d["id"]
            filas.append({
                "id": i, "nombre": d.get("name"), "center": d.get("center"),
                "creada": str(d.get("created_at") or "")[:10],
                "transporter_id": d.get("transporter_id"),
                "telefono": d.get("phone") or d.get("telefono"),
                "inspecciones": insp.get(i, 0), "turnos": turnos.get(i, 0),
                "peticiones": pets.get(i, 0), "asignaciones": asig.get(i, 0),
            })
            filas[-1]["total"] = sum(filas[-1][k] for k in
                                     ("inspecciones", "turnos", "peticiones", "asignaciones"))
        # La que mas historial tiene primero: es la que conviene conservar.
        filas.sort(key=lambda x: -x["total"])
        fuera.append({"email": e, "fichas": filas, "sugerida": filas[0]["id"]})
    return {"grupos": fuera, "total": len(fuera),
            "fichas_de_mas": sum(len(g["fichas"]) - 1 for g in fuera)}


# ── IMPORTAR CONDUCTORES DE GOLPE ───────────────────────────────────────────
# Una empresa que empieza tiene la plantilla en un Excel, y darla de alta a mano
# —cincuenta fichas, una a una— es el motivo por el que la mayoría de las
# aplicaciones de flota se abandonan la primera semana.
#
# Dos decisiones que hacen que esto funcione de verdad:
#
#   1. NO SE PIDE UNA PLANTILLA. Se lee el Excel que ya tienen, con las columnas
#      que ya usan. Pedir un formato concreto es trasladarles el trabajo:
#      reconocer «Nombre», «NOMBRE Y APELLIDOS» o «Driver name» lo hacemos aquí
#      una vez, y ellos no hacen nada.
#   2. SE ENSEÑA ANTES DE GUARDAR. Primero se dice qué se ha entendido, cuántos
#      se darían de alta y qué filas se van a saltar y por qué. Importar a ciegas
#      y descubrir que han entrado 50 fichas mal es peor que no importar.
#
# El teléfono y el correo se normalizan al entrar, porque el gotcha 15 nació
# justo de aquí: nombres con espacios de más y correos en mayúsculas crearon
# 17 personas duplicadas y cinco conductores acabaron viendo la furgoneta de
# otro.

# Cómo se llama cada cosa en los Excel que se ven de verdad. El orden importa:
# gana la primera que case.
_IMP_COLS = {
    "name": ("nombre y apellidos", "nombre completo", "nombre", "conductor",
             "driver name", "empleado", "trabajador", "apellidos y nombre"),
    "dni": ("dni", "nif", "documento", "dni/nie", "nie", "id documento"),
    "phone": ("telefono", "teléfono", "movil", "móvil", "tlf", "phone", "contacto"),
    "email": ("email", "correo", "correo electronico", "correo electrónico",
              "e-mail", "mail"),
    "driver_id": ("driver id", "id amazon", "amazon id", "id conductor",
                  "transporter", "transporter id"),
    "center": ("centro", "estacion", "estación", "nave", "station", "site"),
    "license_number": ("carnet", "licencia", "permiso", "license"),
    "contrato": ("contrato", "tipo contrato", "empresa/ett", "modalidad"),
}


def _imp_norm(s) -> str:
    """Texto de cabecera comparable: sin tildes, sin dobles espacios, en bajas."""
    t = unicodedata.normalize("NFKD", str(s or "")).encode("ascii", "ignore").decode()
    return re.sub(r"\s+", " ", t).strip().lower()


def _imp_mapea(cabecera: list) -> dict:
    """{indice de columna: campo}. Solo la PRIMERA columna que case cada campo.

    Sin ese «solo la primera», un Excel con «Teléfono» y «Teléfono 2» mapearía
    las dos al mismo campo y la segunda pisaría a la primera.
    """
    mapa, usados = {}, set()
    limpio = [_imp_norm(c) for c in cabecera]
    for campo, nombres in _IMP_COLS.items():
        for n in nombres:
            for i, c in enumerate(limpio):
                if i in mapa or campo in usados:
                    continue
                if c == n or (len(n) > 4 and n in c):
                    mapa[i] = campo
                    usados.add(campo)
                    break
            if campo in usados:
                break
    return mapa


def _imp_cabecera(filas: list) -> int:
    """En qué fila está la cabecera.

    No siempre es la primera: los Excel de gestoría traen el logo, el mes y un
    par de filas vacías antes. Se busca la que más columnas reconocidas tenga.
    """
    mejor, mejor_n = 0, 0
    for i, f in enumerate(filas[:15]):
        n = len(_imp_mapea(f))
        if n > mejor_n:
            mejor, mejor_n = i, n
    return mejor if mejor_n >= 1 else 0


_IMP_RESUMEN = ("total", "totales", "suma", "subtotal", "recuento", "n conductores",
                "num conductores", "plantilla", "resumen")


def _imp_es_resumen(nombre: str) -> bool:
    """Si esa «persona» es en realidad la fila de totales del final.

    Se compara contra el nombre ENTERO o su primera palabra, no por «contiene»:
    hay apellidos que empiezan por Suma y no queremos tirar a nadie de verdad.
    """
    t = _imp_norm(nombre)
    if t in _IMP_RESUMEN:
        return True
    # «TOTAL: 47», «TOTAL 47», «Total conductores»
    primera = t.split(":")[0].split()[0] if t.split() else ""
    return primera in _IMP_RESUMEN and len(t.split()) <= 3


def _imp_lee(filas: list) -> dict:
    """Convierte las filas del Excel en fichas, diciendo qué se salta y por qué."""
    if not filas:
        return {"cabecera": [], "mapa": {}, "personas": [], "saltadas": []}
    ic = _imp_cabecera(filas)
    mapa = _imp_mapea(filas[ic])
    personas, saltadas, vistos = [], [], set()

    for n, fila in enumerate(filas[ic + 1:], start=ic + 2):
        d = {}
        for i, campo in mapa.items():
            if i < len(fila):
                d[campo] = str(fila[i] or "").strip()
        nombre = re.sub(r"\s+", " ", (d.get("name") or "")).strip()
        if not nombre:
            # Una fila sin nombre no es un error: son los totales y las filas en
            # blanco del final. Se cuentan aparte para no asustar con «40 filas
            # con problemas» cuando son cuarenta líneas vacías.
            if any(v for v in d.values()):
                saltadas.append({"fila": n, "motivo": "no tiene nombre"})
            continue
        if len(nombre) < 3:
            saltadas.append({"fila": n, "motivo": "el nombre es demasiado corto: %r" % nombre})
            continue
        # Las filas de resumen del final. Casi todos los Excel de plantilla
        # llevan una, y sin esto se daba de alta un conductor llamado
        # «TOTAL: 47» — basura que luego sale en el cuadrante y en las listas.
        if _imp_es_resumen(nombre):
            saltadas.append({"fila": n, "motivo": "parece una fila de totales: %r" % nombre})
            continue

        correo = (d.get("email") or "").strip().lower()
        if correo and not _EMAIL_RE.match(correo):
            correo = ""
        clave = correo or _imp_norm(nombre)
        if clave in vistos:
            saltadas.append({"fila": n, "motivo": "repetido en el propio fichero: %s" % nombre})
            continue
        vistos.add(clave)

        personas.append({
            "name": nombre.upper(),          # como el resto de la base
            "dni": (d.get("dni") or "").strip().upper() or None,
            "phone": whatsapp.normaliza_telefono(d.get("phone")) or None,
            "email": correo or None,
            "driver_id": (d.get("driver_id") or "").strip() or None,
            "center": (d.get("center") or "").strip() or None,
            "license_number": (d.get("license_number") or "").strip() or None,
            "fila": n,
        })
    return {"cabecera": [str(c) for c in filas[ic]], "fila_cabecera": ic + 1,
            "mapa": {str(k): v for k, v in mapa.items()},
            "personas": personas, "saltadas": saltadas}


@api_router.post("/drivers/importar/previsualizar")
async def drivers_importar_prev(file: UploadFile = File(...), center: str = Form(""),
                                _=Depends(require_admin)):
    """Qué se importaría, SIN guardar nada."""
    contenido = await file.read()
    try:
        filas = _read_table_any(contenido, file.filename or "")
    except Exception as e:                                       # noqa: BLE001
        raise HTTPException(400, "No se pudo leer el fichero: %s" % str(e)[:120])
    r = _imp_lee(filas)
    if not r["personas"]:
        raise HTTPException(
            400, "No se ha encontrado ninguna persona. Hace falta una columna con "
                 "el nombre — puede llamarse «Nombre», «Conductor», «Nombre y "
                 "apellidos» o «Driver name».")

    # Quién ya está. Por correo, nunca por nombre: dos tocayos son dos personas
    # (gotcha 15), y fusionarlos haría que uno viera la furgoneta del otro.
    correos = [p["email"] for p in r["personas"] if p["email"]]
    ya = {}
    async for d in db.drivers.find({"email": {"$in": correos}},
                                   {"_id": 0, "email": 1, "name": 1}):
        ya[str(d.get("email") or "").lower()] = d.get("name")
    nombres_bd = {_imp_norm(d["name"]) async for d in db.drivers.find(
        {}, {"_id": 0, "name": 1}) if d.get("name")}

    nuevos = repetidos = 0
    for p in r["personas"]:
        p["ya_existe"] = bool(p["email"] and p["email"] in ya) or \
            (not p["email"] and _imp_norm(p["name"]) in nombres_bd)
        if p["ya_existe"]:
            repetidos += 1
        else:
            nuevos += 1

    return {
        "columnas_reconocidas": r["mapa"],
        "cabecera": r["cabecera"], "fila_cabecera": r["fila_cabecera"],
        "total_leidas": len(r["personas"]),
        "nuevas": nuevos, "ya_estaban": repetidos,
        "saltadas": r["saltadas"][:40], "n_saltadas": len(r["saltadas"]),
        # Las primeras, para que se vea que se ha entendido bien antes de tocar
        # nada. Es la diferencia entre importar y importar a ciegas.
        "muestra": r["personas"][:12],
        "centro_por_defecto": center,
        "sin_correo": sum(1 for p in r["personas"] if not p["email"]),
    }


@api_router.post("/drivers/importar")
async def drivers_importar(file: UploadFile = File(...), center: str = Form(""),
                           user: dict = Depends(require_admin)):
    """Da de alta lo que no esté ya. Nunca pisa una ficha existente."""
    contenido = await file.read()
    try:
        filas = _read_table_any(contenido, file.filename or "")
    except Exception as e:                                       # noqa: BLE001
        raise HTTPException(400, "No se pudo leer el fichero: %s" % str(e)[:120])
    r = _imp_lee(filas)
    if not r["personas"]:
        raise HTTPException(400, "No se ha encontrado ninguna persona en el fichero.")

    correos = [p["email"] for p in r["personas"] if p["email"]]
    ya = set()
    async for d in db.drivers.find({"email": {"$in": correos}}, {"_id": 0, "email": 1}):
        ya.add(str(d.get("email") or "").lower())
    nombres_bd = {_imp_norm(d["name"]) async for d in db.drivers.find(
        {}, {"_id": 0, "name": 1}) if d.get("name")}

    ahora = datetime.now(timezone.utc).isoformat()
    quien = user.get("name") or user.get("username") or "importación"
    # El centro de la empresa, si solo tiene uno. Se saca de la organizacion y
    # no de los conductores que ya haya: en una empresa nueva no hay ninguno.
    unico_centro = ""
    try:
        org = await get_org(user.get("org_id"))
        centros = [c for c in ((org or {}).get("centers") or []) if c]
        if len(centros) == 1:
            unico_centro = centros[0]
    except Exception:                                            # noqa: BLE001
        pass
    nuevos, saltados = [], []
    for p in r["personas"]:
        existe = (p["email"] and p["email"] in ya) or \
            (not p["email"] and _imp_norm(p["name"]) in nombres_bd)
        if existe:
            # NO se actualiza la ficha que ya está. Importar es dar de alta lo
            # que falta; pisar datos buenos con los de un Excel viejo es la
            # forma más rápida de que se deje de confiar en la aplicación.
            saltados.append({"nombre": p["name"], "motivo": "ya estaba dado de alta"})
            continue
        d = {k: v for k, v in p.items() if k != "fila" and v is not None}
        d.update({"id": str(uuid.uuid4()), "active": True,
                  "created_at": ahora, "updated_at": ahora,
                  "importado_por": quien, "importado_en": ahora})
        if not d.get("center"):
            # El centro que venga del formulario; y si no hay ninguno, el unico
            # de la empresa. Casi todos los DSP empiezan con una sola nave, y
            # sin centro los conductores NO SALEN en ninguna lista filtrada:
            # importas cincuenta y parece que no ha funcionado nada.
            d["center"] = (center if center and center not in ("Todos", "todos")
                           else (unico_centro or None))
        nuevos.append(d)
        if p["email"]:
            ya.add(p["email"])
        else:
            nombres_bd.add(_imp_norm(p["name"]))

    metidos = len(nuevos)
    if nuevos:
        try:
            await db.drivers.insert_many(nuevos, ordered=False)
        except BulkWriteError as e:
            # Dos importaciones a la vez del mismo fichero: los correos que ya
            # entraron por la otra los para el indice `email_unico_activo`, el
            # resto entra igual (`ordered=False`). Se cuenta lo que entro.
            metidos = int((e.details or {}).get("nInserted") or 0)
            saltados = saltados + [None] * (len(nuevos) - metidos)
    logger.info("Conductores importados: %d nuevos, %d ya estaban", metidos, len(saltados))
    return {"importados": metidos, "ya_estaban": len(saltados),
            "no_leidas": len(r["saltadas"]),
            "nombres": [d["name"] for d in nuevos][:50]}


@api_router.post("/drivers/fusionar")
async def drivers_fusionar(data: dict = Body(...), user: dict = Depends(require_admin)):
    """Une dos fichas de la misma persona en una.

    NO BORRA NADA. La ficha absorbida se marca `merged_into` y se desactiva,
    asi que si el emparejamiento estuviera mal se puede deshacer mirando el
    campo. Borrarla dejaria huerfano cualquier documento que se nos hubiera
    escapado, y eso no se ve hasta que alguien lo echa en falta.

    Se repuntan los CUATRO sitios que apuntan a un conductor, contados sobre la
    base de produccion: inspections, shifts, shift_requests y los slots de
    daily_assignments. Se comprueban en un test, no de memoria.
    """
    conservar = str(data.get("conservar") or "").strip()
    absorber = [str(x).strip() for x in (data.get("absorber") or []) if str(x).strip()]
    if not conservar or not absorber:
        raise HTTPException(400, "Hace falta cual se conserva y cual se absorbe")
    if conservar in absorber:
        raise HTTPException(400, "Una ficha no se puede absorber a si misma")

    buena = await db.drivers.find_one({"id": conservar}, {"_id": 0})
    if not buena:
        raise HTTPException(404, "La ficha que se conserva no existe")
    otras = await db.drivers.find({"id": {"$in": absorber}}, {"_id": 0}).to_list(20)
    if len(otras) != len(absorber):
        raise HTTPException(404, "Alguna de las fichas a absorber no existe")
    # Mismo correo o no se toca: es la unica prueba de que son la misma persona.
    correo = (buena.get("email") or "").strip().lower()
    for o in otras:
        if (o.get("email") or "").strip().lower() != correo or not correo:
            raise HTTPException(400,
                                "Solo se fusionan fichas con el MISMO correo. "
                                "Por nombre no: dos tocayos acabarian mezclados.")

    movidos = {}
    for col, campo in (("inspections", "driver_id"), ("shifts", "driver_id"),
                       ("shift_requests", "driver_id")):
        r = await db[col].update_many({campo: {"$in": absorber}},
                                      {"$set": {campo: conservar}})
        movidos[col] = r.modified_count
    r = await db.daily_assignments.update_many(
        {"slots.driver_id": {"$in": absorber}},
        {"$set": {"slots.$[s].driver_id": conservar,
                  "slots.$[s].driver_name": buena.get("name")}},
        array_filters=[{"s.driver_id": {"$in": absorber}}])
    movidos["daily_assignments"] = r.modified_count

    # Lo que le falte a la buena se lo queda de las otras: telefono, transporter
    # id, foto... Nunca al reves — la buena manda.
    def _vacio(v):
        return v is None or (isinstance(v, str) and not v.strip())

    relleno = {}
    for campo in ("transporter_id", "phone", "telefono", "photo_url", "dni", "center"):
        if not _vacio(buena.get(campo)):
            continue                      # la buena ya lo tiene: manda ella
        for o in otras:
            v = o.get(campo)
            if isinstance(v, str) and v.strip():
                relleno[campo] = v.strip()
                break
    ahora = datetime.now(timezone.utc).isoformat()
    if relleno:
        await db.drivers.update_one({"id": conservar}, {"$set": relleno})
    await db.drivers.update_many({"id": {"$in": absorber}}, {"$set": {
        "merged_into": conservar, "active": False, "status": "fusionada",
        "merged_at": ahora, "merged_by": user.get("name") or "oficina"}})
    logger.info("Fichas fusionadas en %s: %s (movidos %s)", conservar, absorber, movidos)
    return {"ok": True, "conservada": conservar, "absorbidas": absorber,
            "movidos": movidos, "rellenado": relleno}


@api_router.get("/drivers", response_model=List[Driver])
async def get_drivers(center: Optional[str] = None, user: dict = Depends(require_admin)):
    query = {"active": {"$ne": False}}
    query.update(_filtro_centro(user, center))
    drivers = await db.drivers.find(query, {"_id": 0}).to_list(1000)
    return drivers


@api_router.patch("/drivers/{driver_id}")
async def update_driver(driver_id: str, data: dict, _=Depends(require_admin)):
    _DRIVER_ALLOWED = {
        "name","email","phone","center","notes","photo_url","active","dni",
        "license_number","license_expiry","address","emergency_contact",
        "contract_type","hire_date","tags","score_override",
        # Campos del formulario del panel (antes se filtraban y el guardado
        # fallaba en silencio): contrato/nivel/zona + ficha extendida.
        "contrato","nivel","zona","driver_id","alojamiento","notas","login",
        "transporter_id",
        # Poder apagar el WhatsApp de UNA persona sin apagarlo para todos.
        # Sin esto en la whitelist, el campo se descartaria en silencio al
        # guardar y la casilla del panel no haria nada (gotcha 1).
        "whatsapp_opt_in",
    }
    data = {k: v for k, v in data.items() if k in _DRIVER_ALLOWED}

    # EL TRANSPORTER ID NO ES UN CAMPO DE TEXTO CUALQUIERA.
    # Es la llave con la que se reparten los DNR, asi que:
    #  · se guarda en MAYUSCULAS (en los reportes viene asi y la busqueda es
    #    exacta: 'a2h4...' en minusculas no encontraria nada y el conductor
    #    apareceria a cero teniendo defectos),
    #  · se valida el formato, para que un dedazo no cree un id fantasma,
    #  · y se quita de cualquier otra ficha. Si dos personas tuvieran el mismo,
    #    el nombre que saliera en el contador dependeria del orden en que Mongo
    #    los tuviera guardados: los DNR de uno apareceriean bajo el otro.
    quitar = {}
    if "transporter_id" in data:
        tid = str(data["transporter_id"] or "").strip().upper()
        if not tid:
            data.pop("transporter_id")
            quitar["transporter_id"] = ""
        elif not _DIA_TID.match(tid):
            raise HTTPException(400, "Ese no parece un Transporter ID de Cortex "
                                     "(empieza por A, sin espacios)")
        else:
            data["transporter_id"] = tid
            await db.drivers.update_many(
                {"transporter_id": tid, "id": {"$ne": driver_id}},
                {"$unset": {"transporter_id": ""}})
            # Y si estaba como etiqueta suelta, sobra: manda la ficha.
            await db.app_meta.update_one({"_id": "transporter_alias"},
                                         {"$unset": {f"mapa.{tid}": ""}})

    cambio = {}
    if data:
        cambio["$set"] = data
    if quitar:
        cambio["$unset"] = quitar
    if not cambio:
        return {"success": True, "sin_cambios": True}
    try:
        result = await db.drivers.update_one({"id": driver_id}, cambio)
    except DuplicateKeyError:
        raise HTTPException(409, "Ese correo ya lo tiene otro conductor activo.")
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Conductor no encontrado")
    return {"success": True}


