@api_router.post("/telegram/test")
async def test_telegram(_=Depends(require_admin)):
    config = await db.telegram_config.find_one({}, {"_id": 0})
    if not config or not config.get("bot_token"):
        raise HTTPException(status_code=400, detail="Telegram no configurado")

    token = config["bot_token"]
    chat_ids = config.get("chat_ids", [])

    results = []
    async with _aiohttp.ClientSession() as session:
        for chat_id in chat_ids:
            if not chat_id.strip():
                continue
            url = f"https://api.telegram.org/bot{token}/sendMessage"
            payload = {"chat_id": chat_id, "text": "✅ FlotaDSP — Test de conexión exitoso", "parse_mode": "HTML"}
            try:
                async with session.post(url, json=payload, timeout=_aiohttp.ClientTimeout(total=10)) as resp:
                    data = await resp.json()
                    results.append({"chat_id": chat_id, "ok": data.get("ok", False)})
            except Exception as e:
                results.append({"chat_id": chat_id, "ok": False, "error": str(e)})

    all_ok = all(r["ok"] for r in results)
    return {"success": all_ok, "results": results}


async def send_telegram_alert(title: str, message: str, severity: str = "critico"):
    """Envía alerta a Telegram. Llamar cuando hay daños graves."""
    try:
        config = await db.telegram_config.find_one({}, {"_id": 0})
        if not config or not config.get("enabled") or not config.get("bot_token"):
            return
        if severity in ["critico", "grave"] and not config.get("notify_critical"):
            return

        token = config["bot_token"]
        emoji = "🚨" if severity == "critico" else "⚠️"
        text = f"{emoji} <b>{title}</b>\n\n{message}"

        async with _aiohttp.ClientSession() as session:
            for chat_id in config.get("chat_ids", []):
                if not chat_id.strip():
                    continue
                url = f"https://api.telegram.org/bot{token}/sendMessage"
                await session.post(url, json={"chat_id": chat_id, "text": text, "parse_mode": "HTML"},
                                   timeout=_aiohttp.ClientTimeout(total=5))
    except Exception as e:
        logger.warning(f"Error enviando Telegram: {e}")


# =========================
# MONITORIZACIÓN DE ERRORES — el panel/portal reporta errores JS y el backend
# avisa por Telegram de los 500 no controlados. Dedupe 1h por mensaje.
# =========================

_err_alerted: dict = {}          # hash del error → timestamp del último aviso
_ERR_ALERT_WINDOW_S = 3600       # backend: máx 1 aviso por error único y hora
_ERR_ALERT_WINDOW_FRONT_S = 6 * 3600  # frontend: máx 1 aviso por error único cada 6h

# Ruido que NO merece Telegram (se loguea y ya): chunks viejos tras un deploy,
# cortes de red de móvil, errores opacos de extensiones, desconexiones de cliente…
_ERR_NOISE_PATTERNS = (
    "dynamically imported module", "importing a module script failed", "chunkloaderror",
    "failed to fetch", "networkerror", "load failed", "network error",
    "script error", "resizeobserver",
    # backend: desconexiones y cancelaciones normales, no son fallos reales
    "clientdisconnect", "connection reset", "broken pipe", "cancellederror",
    "connectionreset", "peer closed", "response ended prematurely",
)

# Los avisos de "error backend" por Telegram eran ruido inútil ("no sé ni a qué
# se refiere"): se apagan por defecto (todo queda en el log). Para reactivarlos:
# fly secrets set BACKEND_ERROR_ALERTS=1
def _backend_alerts_on() -> bool:
    return os.environ.get("BACKEND_ERROR_ALERTS", "0").lower() in ("1", "true", "yes")


async def _notify_error_once(kind: str, message: str, extra: str = ""):
    """Log + Telegram con dedupe. kind: 'frontend' | 'backend'."""
    import hashlib as _hl
    logger.error(f"[{kind}] {message} {extra}"[:2000])
    # Ruido conocido (cualquier origen): queda en el log, no molesta por Telegram.
    if any(p in (message or "").lower() for p in _ERR_NOISE_PATTERNS):
        return
    # Errores de backend: silenciados por defecto (solo log). Reactivables por env.
    if kind == "backend" and not _backend_alerts_on():
        return
    key = _hl.sha256(f"{kind}:{message[:300]}".encode()).hexdigest()
    now_ts = datetime.now(timezone.utc).timestamp()
    window = _ERR_ALERT_WINDOW_FRONT_S if kind == "frontend" else _ERR_ALERT_WINDOW_S
    if now_ts - _err_alerted.get(key, 0) < window:
        return
    _err_alerted[key] = now_ts
    # Limpieza para que el dict no crezca sin límite
    if len(_err_alerted) > 500:
        cutoff = now_ts - _ERR_ALERT_WINDOW_S
        for k in [k for k, t in _err_alerted.items() if t < cutoff]:
            _err_alerted.pop(k, None)
    emoji = "🖥️" if kind == "frontend" else "🔥"
    await send_telegram_alert(
        f"{emoji} Error en {'el panel/portal' if kind == 'frontend' else 'el backend'}",
        f"{message[:500]}\n{extra[:400]}".strip(),
        severity="critico",
    )


@api_router.post("/client-error")
async def report_client_error(data: dict, request: Request):
    """Recibe errores JS del frontend (window.onerror). Público pero rate-limited."""
    _rl_public_action(f"ce:{_rl_key_ip(request)}", max_count=10, window_s=600,
                      detail="Demasiados reportes")
    message = str(data.get("message") or "")[:500]
    if not message:
        return {"success": True}
    stack = str(data.get("stack") or "")[:800]
    url = str(data.get("url") or "")[:200]
    ua = (request.headers.get("user-agent") or "")[:120]

    # LO QUE NO ES NUESTRO NO SE GUARDA NI DESPIERTA A NADIE.
    #
    # `window.onerror` recoge TODO lo que pasa en la pestaña, incluidas las
    # extensiones que el usuario tenga puestas. De los 14 errores guardados el
    # 31-08-2026, CINCO venian de una extension de Chrome ajena
    # (`chrome-extension://.../executors/200.js`, siempre el mismo 'M_ID') y
    # uno de un traductor automatico moviendo nodos del DOM. Nada de eso lo
    # podemos arreglar, y cada uno mandaba su aviso a Telegram.
    #
    # El problema no es el espacio: es que con el registro lleno de ruido, los
    # de verdad —tres del chunk envenenado, uno de React— no se ven. Es lo
    # mismo que pasaba con el checker de fechas: 15 avisos en falso por cada
    # uno bueno y los buenos llevaban meses escondidos.
    _AJENO = ("chrome-extension://", "moz-extension://", "safari-extension://",
              "safari-web-extension://", "webkit-masked-url")
    if any(x in stack for x in _AJENO) or any(x in url for x in _AJENO):
        logger.info("Error de una extension del navegador, no nuestro: %s", message[:120])
        return {"success": True, "ignorado": "extension del navegador"}
    # El traductor de Chrome reescribe el DOM por debajo de React y provoca
    # esto sin que nada nuestro falle. Se reconoce por el mensaje exacto.
    if "insertBefore" in message and "not a child of this node" in message:
        logger.info("Error del traductor del navegador, no nuestro")
        return {"success": True, "ignorado": "traductor del navegador"}

    # SE GUARDA, no solo se avisa.
    #
    # Hasta ahora un error del navegador iba a Telegram y a una linea de log.
    # El aviso se puede perder y el log de Fly dura minutos, asi que cuando
    # alguien dice "se me queda la pantalla en negro" no queda ni rastro de
    # QUE error fue: hay que reproducirlo a ciegas. Pasó el 23-08-2026 con la
    # pantalla de Inspecciones y no habia nada que leer.
    #
    # Se guarda tambien QUIEN lo sufrio si viene sesion. El endpoint es publico
    # a proposito —un error puede ocurrir antes de tener token— asi que el
    # usuario se saca del Bearer si lo hay, sin exigirlo.
    quien = None
    try:
        auth = request.headers.get("authorization") or ""
        if auth.lower().startswith("bearer "):
            _tok = decode_token(auth[7:]) or {}
            quien = _tok.get("name")
            # Y su EMPRESA. Sin esto el error se guardaba en la base principal
            # viniera de donde viniera (gotcha 26): la empresa que lo sufre no
            # lo ve en su pantalla de errores, y en la principal aparecen
            # mezclados los de todo el mundo sin saber de quien son. Justo lo
            # contrario de para lo que se guardan.
            if _tok.get("db_name"):
                set_current_org_db(_tok["db_name"])
    except Exception:
        pass          # un token caducado no puede impedir guardar el error

    try:
        await db.client_errors.insert_one({
            "id": str(uuid.uuid4()), "message": message, "stack": stack,
            "url": url, "ua": ua, "usuario": quien,
            "ts": datetime.now(timezone.utc).isoformat(),
        })
    except Exception as e:
        logger.warning("No se pudo guardar el error de cliente: %s", e)

    await _notify_error_once("frontend", message, f"URL: {url}\nStack: {stack[:300]}\nUA: {ua}")
    return {"success": True}


@api_router.get("/client-errors")
async def listar_client_errors(limit: int = 100, _=Depends(require_admin)):
    """Los errores de navegador guardados, del mas reciente al mas viejo.

    Existe para no tener que preguntar "¿y que ponia exactamente?": el mensaje,
    la pantalla donde paso, quien lo sufrio y con que navegador.
    """
    docs = await db.client_errors.find({}, {"_id": 0}).sort("ts", -1).to_list(
        max(1, min(int(limit or 100), 500)))
    return {"errores": docs, "total": len(docs)}


@app.exception_handler(Exception)
async def unhandled_exception_handler(request: Request, exc: Exception):
    """Los 500 no controlados se loguean con traza y avisan por Telegram (dedupe 1h)."""
    import traceback as _tb
    trace = "".join(_tb.format_exception(type(exc), exc, exc.__traceback__))[-1500:]
    try:
        await _notify_error_once("backend", f"{type(exc).__name__}: {exc}",
                                 f"{request.method} {request.url.path}\n{trace[-600:]}")
    except Exception:
        logger.error(f"Error notificando excepción: {exc}")
    return JSONResponse(status_code=500, content={"detail": "Error interno del servidor"})


def _severity_emoji(sev: str) -> str:
    return {"critico": "🔴", "grave": "🟠", "moderado": "🟡", "leve": "🟢"}.get(sev, "⚪")


async def send_telegram_damage_alert(plate, driver_name, analysis, photo_urls, inspection_id, center=None):
    """Envía a Telegram una alerta de daños con formato detallado: matrícula, conductor,
    daños NUEVOS y enlaces a las fotos. Además dispara push a los coordinadores del centro."""
    # Push al móvil (independiente de Telegram: aunque Telegram no esté configurado)
    try:
        _sev = (getattr(analysis, "severity", None)
                or (analysis.get("severity") if isinstance(analysis, dict) else "") or "")
        await push_center_event(
            center or "", f"🚨 Daño {_sev} · {center or ''}".strip(),
            f"{plate}: nueva inspección con daño, revísala", url="/panel/revision")
    except Exception as _pe:
        logger.debug(f"push daño: {_pe}")
    try:
        config = await db.telegram_config.find_one({}, {"_id": 0})
        if not config or not config.get("enabled") or not config.get("bot_token"):
            return
        if not config.get("notify_critical", True):
            return

        token = config["bot_token"]
        sev = analysis.severity
        head_emoji = "🚨" if sev == "critico" else "⚠️"

        # Daños nuevos (si la IA los distingue); si no, usar todos
        nuevos = analysis.new_damages if analysis.new_damages else analysis.damages

        # Extraer código de centro corto (ej: "AMZL OGA5 SANTIAGO XPT" → "OGA5")
        center_display = ""
        if center:
            import re as _re_tg
            m = _re_tg.search(r'\b(OGA\d|DGA\d|[A-Z]{2,4}\d)\b', center.upper())
            center_display = m.group(1) if m else center[:6]

        lines = []
        center_tag = f" [{center_display}]" if center_display else ""
        lines.append(f"{head_emoji} <b>PERITAJE — DAÑOS DETECTADOS{center_tag}</b>")
        lines.append("")
        if center_display:
            lines.append(f"🏢 <b>Centro:</b> {center_display}")
        lines.append(f"🚗 <b>Matrícula:</b> {plate}")
        lines.append(f"👤 <b>Conductor:</b> {driver_name}")
        lines.append(f"{_severity_emoji(sev)} <b>Severidad:</b> {sev.upper()}")
        lines.append(f"💶 <b>Coste estimado:</b> {analysis.total_estimated_cost:.0f} €")

        # Aviso anti-fraude si la matrícula leída no coincide
        detected = (analysis.detected_plate or "").replace(" ", "").upper()
        plate_norm = (plate or "").replace(" ", "").upper()
        if detected and plate_norm and detected != plate_norm:
            lines.append("")
            lines.append(f"⛔ <b>ALERTA FRAUDE:</b> la matrícula leída en la foto ({analysis.detected_plate}) NO coincide con la del vehículo ({plate}).")
        if analysis.fraud_warnings:
            lines.append("")
            for fw in analysis.fraud_warnings[:3]:
                lines.append(f"⛔ {fw}")

        # Daños nuevos
        lines.append("")
        if nuevos:
            lines.append(f"<b>🆕 DAÑOS NUEVOS ({len(nuevos)}):</b>")
            for i, d in enumerate(nuevos[:10], 1):
                loc = f" [{d.location_hint}]" if getattr(d, "location_hint", "") else ""
                lines.append(f"{i}. <b>{d.part}</b>{loc} — {d.severity}")
                if d.description:
                    lines.append(f"   {d.description}")
        else:
            lines.append("Sin daños nuevos respecto al peritaje anterior.")

        # Enlaces a las fotos — etiquetadas por zona (orden del portal conductor)
        zonas = ["Frontal", "Trasera", "Lateral izquierdo", "Lateral derecho",
                 "Foto 5", "Foto 6", "Foto 7", "Foto 8"]
        if photo_urls:
            lines.append("")
            lines.append("<b>📸 Fotos por zona:</b>")
            for i, u in enumerate(photo_urls[:8]):
                etiqueta = zonas[i] if i < len(zonas) else f"Foto {i+1}"
                lines.append(f"• {etiqueta}: <a href=\"{u}\">ver</a>")

        text = "\n".join(lines)

        async with _aiohttp.ClientSession() as session:
            for chat_id in config.get("chat_ids", []):
                if not chat_id.strip():
                    continue
                url = f"https://api.telegram.org/bot{token}/sendMessage"
                await session.post(
                    url,
                    json={"chat_id": chat_id, "text": text, "parse_mode": "HTML",
                          "disable_web_page_preview": True},
                    timeout=_aiohttp.ClientTimeout(total=8)
                )
    except Exception as e:
        logger.warning(f"Error enviando alerta detallada Telegram: {e}")


async def _cierre_entrega(center: str, dia: str) -> Optional[dict]:
    """DCR del día para un centro, con el MISMO motor que la pantalla de calidad
    en vivo (_cx_bruto / _cx_dias / _cx_tasas). No se reimplementa nada: si el
    mensaje de las 22:00 calculara el DCR por su cuenta, acabaría diciendo un
    número distinto al del panel y no habría forma de saber cuál miente.

    Devuelve None si no hay ni un paquete de ese día: sin datos no hay tasa, y
    un 100 % de un centro sin actividad sería el peor falso positivo posible.
    """
    try:
        bruto = await _cx_bruto(dia, dia, center)
        if not bruto:
            return None
        ok = sum(r["ok"] for r in bruto)
        fallo = sum(r["fallo"] for r in bruto)
        rts = sum(r["rts"] for r in bruto)
        estado_dia = _cx_dias(bruto).get(dia) or {}
        t = _cx_tasas(ok, fallo, rts)
        t["cerrado"] = bool(estado_dia.get("cerrado"))
        t["en_vuelo"] = estado_dia.get("vuelo", 0)
        t["en_vuelo_pct"] = estado_dia.get("en_vuelo_pct", 0.0)
        t["nodesp"] = sum(r["nodesp"] for r in bruto)
        return t
    except Exception as e:
        logger.warning(f"Cierre 22:00 — DCR de {center}: {e}")
        return None


async def _cierre_recordatorios(center: str) -> list:
    """Lo que hay que mirar mañana en ese centro. Todo sale de datos ya
    guardados: ITV de la ficha, mantenimiento del mismo cálculo que usa la cola
    de flota, y la última declaración de rueda de repuesto del conductor.

    Nada de esto es una predicción. Son cosas que YA están vencidas o
    declaradas, y por eso se pueden decir sin matizar.
    """
    avisos = []
    try:
        # center está sucio en la BD ('OGA5', 'OGA5 ', 'AMZL OGA5 …'): regex.
        q = {"status": {"$ne": "baja"}}
        if center and center != "—":
            q["center"] = {"$regex": re.escape(center.strip()[:4]), "$options": "i"}
        vehs = await db.vehicles.find(q, {"_id": 0}).to_list(500)
        if not vehs:
            return avisos

        hoy = datetime.now(timezone.utc).date()
        itv = []
        for v in vehs:
            f = v.get("itv_date") or v.get("next_itv")
            if not f:
                continue
            try:
                d = (datetime.fromisoformat(str(f)[:10]).date() - hoy).days
            except Exception:
                continue
            if d <= 30:
                itv.append((d, v.get("license_plate") or "—"))
        if itv:
            itv.sort()
            venc = [p for d, p in itv if d < 0]
            prox = [f"{p} ({d}d)" for d, p in itv if d >= 0]
            if venc:
                avisos.append(f"🔴 ITV VENCIDA: {', '.join(venc[:6])}")
            if prox:
                avisos.append(f"🟠 ITV en 30 días: {', '.join(prox[:6])}")

        vencidos = []
        for v in vehs:
            for kind, i, w, label in [("oil", 15000, 2500, "aceite"),
                                      ("ruedas", 40000, 3000, "ruedas"),
                                      ("pastillas", 30000, 3000, "pastillas")]:
                for pos in _ejes_de(v, kind):
                    it = _build_maint_item(v, kind, i, w, pos)
                    if it and it["overdue"]:
                        que = f"{label} {pos}" if pos else label
                        vencidos.append(f"{v.get('license_plate') or '—'} ({que})")
        if vencidos:
            avisos.append(f"🔧 Mantenimiento pasado: {', '.join(vencidos[:6])}"
                          + (f" y {len(vencidos) - 6} más" if len(vencidos) > 6 else ""))

        # Rueda de repuesto: SOLO las declaradas ausentes. Las que nunca se
        # preguntaron no se mencionan: no saberlo no es un problema que reportar.
        ids = {v["id"] for v in vehs if v.get("id")}
        sin_rueda = []
        if ids:
            cur = db.inspections.aggregate([
                {"$match": {"deleted": {"$ne": True}, "vehicle_id": {"$in": list(ids)},
                            "notes": {"$regex": "rueda_repuesto"}}},
                {"$sort": {"created_at": -1}},
                {"$group": {"_id": "$vehicle_id", "notes": {"$first": "$notes"}}},
            ])
            placas = {v["id"]: (v.get("license_plate") or "—") for v in vehs if v.get("id")}
            async for row in cur:
                vid = row.get("_id")           # $group omite la clave si no existe
                if not vid:
                    continue
                try:
                    n = json.loads(row.get("notes") or "")
                except Exception:
                    continue
                if isinstance(n, dict) and n.get("rueda_repuesto") == "no":
                    sin_rueda.append(placas.get(vid, "—"))
        if sin_rueda:
            avisos.append(f"🛞 Sin rueda de repuesto (declarado): {', '.join(sorted(sin_rueda)[:6])}")
    except Exception as e:
        logger.warning(f"Cierre 22:00 — recordatorios de {center}: {e}")
    return avisos


async def send_daily_inspection_summary():
    """Cierre nocturno por centro a las 22:00.

    Antes era solo el recuento de auditorías. Ahora es el cierre del día:
      · Entrega — DCR real de Cortex, con el motor de calidad en vivo.
      · Auditorías — quién la hizo y quién no (lo de siempre).
      · Daños nuevos de hoy, con quién conducía.
      · Recordatorios para mañana: ITV, mantenimiento vencido, rueda ausente.

    Lo que NO lleva, y es a propósito: descontar del DCR las anulaciones hechas
    en la propia nave antes de salir. Cortex no tiene estado de anulación, así
    que detectarlas exige comparar la dirección de la parada con la dirección
    de la estación, y esas direcciones NO están guardadas en ninguna parte
    (`cortex_stations` solo mapea serviceAreaId → centro). Con las direcciones
    a ojo, el mensaje de cada noche estaría regalando o quitando décimas de DCR
    sin que nadie pudiera comprobarlo. Se queda fuera hasta que existan.

    Cuándo se dispara no cambia: sigue habiendo un mensaje por centro con
    cuadrante, y sin cuadrante no se manda nada.
    """
    try:
        config = await db.telegram_config.find_one({}, {"_id": 0})
        if not config or not config.get("enabled") or not config.get("bot_token"):
            logger.info("Resumen diario: Telegram no configurado — omitido")
            return
        token = config["bot_token"]
        chat_ids = [c for c in config.get("chat_ids", []) if c.strip()]
        if not chat_ids:
            return

        today = _dia_negocio()
        assignments = await db.daily_assignments.find({"date": today}, {"_id": 0}).to_list(20)
        if not assignments:
            logger.info("Resumen diario: sin cuadrante hoy — nada que enviar")
            return

        # Fecha bonita en español
        dias = ["Lunes", "Martes", "Miércoles", "Jueves", "Viernes", "Sábado", "Domingo"]
        now_dt = datetime.now(timezone.utc)
        fecha_str = f"{dias[now_dt.weekday()]} {now_dt.strftime('%d/%m/%Y')}"

        # Inspecciones de hoy (una consulta, agrupadas por vehículo)
        insps_today = await db.inspections.find(
            {"deleted": {"$ne": True}, "created_at": {"$regex": f"^{today}"}},
            {"_id": 0, "vehicle_id": 1, "analysis": 1, "driver_id": 1, "notes": 1}
        ).to_list(1000)
        insp_by_vehicle = {}
        for i in insps_today:
            vid = i.get("vehicle_id")
            if vid:
                insp_by_vehicle[vid] = i

        for assignment in assignments:
            center = assignment.get("center", "—")
            slots = [s for s in assignment.get("slots", []) if s.get("vehicle_id")]
            if not slots:
                continue

            total = len(slots)
            done = []
            missing = []
            sev_counts = {"sin": 0, "leve": 0, "grave": 0}
            for slot in slots:
                vid = slot["vehicle_id"]
                insp = insp_by_vehicle.get(vid)
                if insp:
                    done.append(slot)
                    sev = ((insp.get("analysis") or {}).get("severity") or "").lower()
                    if sev in ("grave", "critico", "crítico"):
                        sev_counts["grave"] += 1
                    elif sev in ("leve", "moderado"):
                        sev_counts["leve"] += 1
                    else:
                        sev_counts["sin"] += 1
                else:
                    missing.append(slot)

            pct = round(len(done) / total * 100) if total else 0

            # ── 1 · ENTREGA ─────────────────────────────────────────────────
            ent = await _cierre_entrega(center, today)

            # ── 2 · DAÑOS NUEVOS DE HOY, con quién conducía ─────────────────
            # Se cruza por el cuadrante: el conductor que llevaba ESA furgoneta
            # hoy. Si el hueco no dice quién, no se pone un nombre a dedo.
            cond_por_veh = {s["vehicle_id"]: (s.get("driver_name") or "")
                            for s in slots if s.get("vehicle_id")}
            danos = []
            for slot in done:
                insp = insp_by_vehicle.get(slot["vehicle_id"]) or {}
                nuevos = ((insp.get("analysis") or {}).get("new_damages") or [])
                for d in nuevos:
                    if not isinstance(d, dict):
                        continue
                    quien = cond_por_veh.get(slot["vehicle_id"]) or ""
                    danos.append((slot.get("vehicle_plate") or "—",
                                  d.get("part") or "—",
                                  (d.get("severity") or "").lower(),
                                  quien))

            cabecera = "✅" if not missing else "⚠️"
            lines = [f"{cabecera} <b>CIERRE DEL DÍA — {center}</b>", f"📅 {fecha_str}", ""]

            # ENTREGA
            if ent and ent.get("dcr") is not None:
                if ent["cerrado"]:
                    lines.append(f"📦 <b>DCR {ent['dcr']}%</b> — {ent['entregados']}/{ent['despachados']} entregados")
                else:
                    # Jornada sin cerrar: dar el DCR como definitivo sería mentir,
                    # porque los paquetes en vuelo aún pueden entregarse.
                    lines.append(f"📦 Jornada sin cerrar ({ent['en_vuelo']} paquetes aún en vuelo)")
                    lines.append(f"   Provisional: {ent['dcr']}% — {ent['entregados']}/{ent['despachados']}")
                if ent.get("fallos"):
                    lines.append(f"   ❌ {ent['fallos']} fallos · ↩️ {ent['rts']} RTS")
                if ent.get("nodesp"):
                    lines.append(f"   ⏸ {ent['nodesp']} no despachados (fuera del DCR)")
            else:
                lines.append("📦 Sin datos de Cortex hoy")
            lines.append("")

            # AUDITORÍAS
            if not missing:
                lines.append(f"📸 <b>Auditorías {len(done)}/{total}</b> — todas hechas")
            else:
                lines.append(f"📸 <b>Auditorías {len(done)}/{total}</b> ({pct}%) — faltan {len(missing)}:")
                for slot in missing[:15]:
                    drv = slot.get("driver_name") or "Sin conductor asignado"
                    lines.append(f"• {drv} — {slot.get('vehicle_plate', '—')}")
                if len(missing) > 15:
                    lines.append(f"• …y {len(missing) - 15} más")
            lines.append(f"   🟢 {sev_counts['sin']} sin daños · 🟡 {sev_counts['leve']} leves · 🔴 {sev_counts['grave']} graves")
            lines.append("")

            # DAÑOS NUEVOS
            if danos:
                lines.append(f"🔨 <b>{len(danos)} daño(s) nuevo(s) hoy</b>")
                for plate, part, sev, quien in danos[:8]:
                    ico = "🔴" if sev in ("grave", "critico", "crítico") else "🟡"
                    lines.append(f"{ico} {plate} — {part}" + (f" · {quien}" if quien else ""))
                if len(danos) > 8:
                    lines.append(f"• …y {len(danos) - 8} más")
                lines.append("")

            # RECORDATORIOS PARA MAÑANA
            avisos = await _cierre_recordatorios(center)
            if avisos:
                lines.append("<b>Para mañana</b>")
                lines.extend(avisos)

            text = "\n".join(lines).rstrip()
            # Telegram corta en 4096 caracteres y devuelve error: con un centro
            # grande y muchos avisos se llega. Mejor recortar nosotros y decirlo
            # que perder el mensaje entero.
            if len(text) > 3900:
                text = text[:3880].rsplit("\n", 1)[0] + "\n…(recortado)"
            async with _aiohttp.ClientSession() as session:
                for chat_id in chat_ids:
                    try:
                        await session.post(
                            f"https://api.telegram.org/bot{token}/sendMessage",
                            json={"chat_id": chat_id, "text": text, "parse_mode": "HTML",
                                  "disable_web_page_preview": True},
                            timeout=_aiohttp.ClientTimeout(total=8)
                        )
                    except Exception as _se:
                        logger.warning(f"Resumen diario: error enviando a {chat_id}: {_se}")
            logger.info(f"Resumen diario enviado: {center} — {len(done)}/{total} inspecciones")
    except Exception as e:
        logger.error(f"Error en resumen diario: {e}", exc_info=True)


async def backup_database_to_r2() -> dict:
    """Copia TODAS las bases (global + cada inquilino) a un JSONL.gz en R2.

    El cluster Atlas es M0: no tiene copias nativas. Esto es la unica red de
    seguridad contra un borrado o una corrupcion, asi que tiene que funcionar
    de verdad y tiene que gritar cuando no.

    Se escribe en streaming a un fichero temporal: la memoria NO crece con el
    tamano de la base. La version anterior montaba el volcado entero en RAM y
    luego hacia otras tres copias (json.dumps, encode, gzip); con 149 MB de
    datos en una maquina de 1 GB, moria y dejaba ficheros de 0 bytes.
    """
    import gzip as _gzip
    import tempfile
    r2 = get_r2()
    if not r2:
        return {"success": False, "error": "R2 no configurado"}

    ruta = None
    try:
        bases = [n for n in await client.list_database_names()
                 if n not in ("admin", "local", "config", "sample_mflix")]
        total_docs = 0
        total_cols = 0
        por_base = {}

        fd, ruta = tempfile.mkstemp(suffix=".jsonl.gz")
        os.close(fd)
        with _gzip.open(ruta, "wt", encoding="utf-8", compresslevel=6) as f:
            for base in bases:
                bdb = client[base]
                n_base = 0
                for cname in await bdb.list_collection_names():
                    total_cols += 1
                    # Cursor por lotes: NUNCA to_list con tope. El anterior
                    # cortaba en 100.000 y perdia 59.189 eventos por copia.
                    cur = bdb[cname].find({}, {"_id": 0}).batch_size(500)
                    async for doc in cur:
                        f.write(json.dumps({"_db": base, "_col": cname, "d": doc},
                                           default=str, ensure_ascii=False))
                        f.write("\n")
                        n_base += 1
                        total_docs += 1
                por_base[base] = n_base

        tam = os.path.getsize(ruta)
        # Una copia sana ronda los 100 bytes comprimidos por documento. Muy por
        # debajo de eso significa que se trunco o que fallo a mitad: eso NO se
        # sube como si nada, se reporta como fallo para que salte el aviso.
        minimo = max(1024, total_docs * 8)
        if total_docs == 0 or tam < minimo:
            return {"success": False,
                    "error": f"Copia sospechosa: {tam} bytes para {total_docs} documentos"}

        stamp = datetime.now(timezone.utc).strftime("%Y-%m-%d_%H%M")
        key = f"backups/flotadsp_{stamp}.jsonl.gz"
        loop = asyncio.get_running_loop()

        def _subir():
            with open(ruta, "rb") as fh:
                r2.put_object(Bucket=R2_BUCKET, Key=key, Body=fh,
                              ContentType="application/gzip")
            # Releer el tamano en R2: si lo subido no coincide con lo escrito,
            # la copia no vale. Es justo el fallo que dejo un fichero de 0 MB
            # pasando por bueno durante ocho dias.
            return r2.head_object(Bucket=R2_BUCKET, Key=key).get("ContentLength", 0)

        subido = await loop.run_in_executor(_executor, _subir)
        if subido != tam:
            return {"success": False,
                    "error": f"Subida incompleta: {subido} de {tam} bytes"}

        # Rotacion: conservar las 14 mas recientes.
        borrados = 0
        try:
            listing = await loop.run_in_executor(_executor, lambda: r2.list_objects_v2(
                Bucket=R2_BUCKET, Prefix="backups/"))
            keys = sorted([o["Key"] for o in listing.get("Contents", [])], reverse=True)
            for old_key in keys[14:]:
                await loop.run_in_executor(_executor, lambda k=old_key: r2.delete_object(
                    Bucket=R2_BUCKET, Key=k))
                borrados += 1
        except Exception as _rot:
            logger.warning(f"Rotacion de copias fallo (no critico): {_rot}")

        size_mb = round(tam / 1024 / 1024, 2)
        logger.info(f"Backup OK: {key} - {total_docs} docs, {total_cols} colecciones, "
                    f"{len(bases)} bases, {size_mb}MB, {borrados} antiguas borradas")
        return {"success": True, "key": key, "bases": len(bases),
                "collections": total_cols, "documents": total_docs,
                "size_mb": size_mb, "por_base": por_base}
    except Exception as e:
        logger.error(f"Backup FALLO: {e}", exc_info=True)
        return {"success": False, "error": str(e)}
    finally:
        if ruta:
            try:
                os.remove(ruta)
            except OSError:
                pass


@api_router.post("/admin/backup-now")
async def trigger_backup(_=Depends(require_admin)):
    """Lanza un backup manual de la base de datos a R2."""
    return await backup_database_to_r2()


@app.on_event("startup")
async def start_backup_scheduler():
    """Backup automático diario a las 04:00 hora española."""
    async def _backup_loop():
        from zoneinfo import ZoneInfo
        madrid = ZoneInfo("Europe/Madrid")
        while True:
            try:
                now = datetime.now(madrid)
                target = now.replace(hour=4, minute=0, second=0, microsecond=0)
                if now >= target:
                    target = target + timedelta(days=1)
                await asyncio.sleep((target - now).total_seconds())
                result = await backup_database_to_r2()
                if not result.get("success"):
                    # Avisar por Telegram si el backup falla — esto SÍ es crítico
                    try:
                        config = await db.telegram_config.find_one({}, {"_id": 0})
                        if config and config.get("enabled") and config.get("bot_token"):
                            async with _aiohttp.ClientSession() as session:
                                for chat_id in config.get("chat_ids", []):
                                    if chat_id.strip():
                                        await session.post(
                                            f"https://api.telegram.org/bot{config['bot_token']}/sendMessage",
                                            json={"chat_id": chat_id,
                                                  "text": f"🚨 EL BACKUP DIARIO DE LA BASE DE DATOS HA FALLADO: {result.get('error')}"},
                                            timeout=_aiohttp.ClientTimeout(total=8))
                    except Exception:
                        pass
                await asyncio.sleep(70)
            except Exception as e:
                logger.error(f"Backup scheduler: {e}")
                await asyncio.sleep(600)
    asyncio.create_task(_backup_loop())


async def send_weekly_summary():
    """Informe de gerencia de la semana (lunes 08:00): cumplimiento por centro,
    € de daños nuevos, top 3 del scoring y furgonetas con más daños nuevos."""
    try:
        config = await db.telegram_config.find_one({}, {"_id": 0})
        if not config or not config.get("enabled") or not config.get("bot_token"):
            return {"success": False, "error": "Telegram no configurado"}
        token = config["bot_token"]
        chat_ids = [c for c in config.get("chat_ids", []) if c.strip()]
        if not chat_ids:
            return {"success": False, "error": "sin chats"}

        now = datetime.now(timezone.utc)
        week_ago = (now - timedelta(days=7)).isoformat()
        week_start_d = (now - timedelta(days=7)).strftime("%d/%m")
        week_end_d = now.strftime("%d/%m")

        # Inspecciones de la semana
        insps = await db.inspections.find(
            {"deleted": {"$ne": True}, "created_at": {"$gte": week_ago}},
            {"_id": 0, "vehicle_id": 1, "analysis": 1, "analysis_status": 1, "reference_photos": 1}
        ).to_list(3000)

        # Cumplimiento: slots asignados vs inspecciones, por los cuadrantes de la semana
        assignments = await db.daily_assignments.find(
            {"date": {"$gte": (now - timedelta(days=7)).strftime("%Y-%m-%d")}},
            {"_id": 0, "center": 1, "slots": 1, "date": 1}
        ).to_list(100)
        total_slots = sum(len([sl for sl in a.get("slots", []) if sl.get("driver_id")]) for a in assignments)

        # € de daños nuevos de la semana + furgonetas con más daños nuevos
        total_eur = 0.0
        dam_by_vehicle = {}
        for i in insps:
            a = i.get("analysis") or {}
            if i.get("analysis_status") != "ok":
                continue
            if i.get("reference_photos"):
                nds = [nd for nd in (a.get("new_damages") or []) if isinstance(nd, dict)]
                total_eur += sum((nd.get("estimated_cost") or 0) for nd in nds)
                if nds:
                    dam_by_vehicle[i.get("vehicle_id")] = dam_by_vehicle.get(i.get("vehicle_id"), 0) + len(nds)

        # Matrículas de las furgonetas problemáticas
        worst = sorted(dam_by_vehicle.items(), key=lambda x: -x[1])[:3]
        plates = {}
        if worst:
            vids = [w[0] for w in worst]
            async for v in db.vehicles.find({"id": {"$in": vids}}, {"_id": 0, "id": 1, "license_plate": 1}):
                plates[v["id"]] = v.get("license_plate", "?")

        # Top 3 del scoring del mes en curso
        top3_txt = ""
        try:
            sc = await get_driver_scoring(month=now.month, year=now.year, _=None)
            ranked = [x for x in sc.get("scores", []) if not x.get("insufficient")][:3]
            medals = ["🥇", "🥈", "🥉"]
            top3_txt = "\n".join(f"{medals[i]} {r['name']} — {r['total']} pts" for i, r in enumerate(ranked))
        except Exception as _se:
            logger.warning(f"Weekly: scoring falló: {_se}")

        lines = [
            f"📊 <b>RESUMEN SEMANAL</b> ({week_start_d} – {week_end_d})",
            "",
            f"📸 Inspecciones: <b>{len(insps)}</b>" + (f" de {total_slots} asignaciones ({round(len(insps)/total_slots*100)}%)" if total_slots else ""),
            f"💶 Daños nuevos detectados: <b>{round(total_eur):,} €</b>".replace(",", "."),
        ]
        if worst:
            lines.append("")
            lines.append("🚨 <b>Furgonetas con más daños nuevos:</b>")
            for vid, cnt in worst:
                lines.append(f"  • {plates.get(vid, '?')} — {cnt} daño(s)")
        if top3_txt:
            lines.append("")
            lines.append("🏆 <b>Top scoring del mes:</b>")
            lines.append(top3_txt)
        lines.append("")
        lines.append("¡Buena semana! 💪")

        text = "\n".join(lines)
        async with _aiohttp.ClientSession() as session:
            for cid in chat_ids:
                await session.post(
                    f"https://api.telegram.org/bot{token}/sendMessage",
                    json={"chat_id": cid, "text": text, "parse_mode": "HTML"},
                    timeout=_aiohttp.ClientTimeout(total=8))
        logger.info("Resumen semanal enviado")
        return {"success": True}
    except Exception as e:
        logger.error(f"Resumen semanal: {e}", exc_info=True)
        return {"success": False, "error": str(e)}


