# INCIDENCIAS
# =========================

class Incident(BaseModel):
    model_config = ConfigDict(extra="ignore")
    id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    vehicle_id: str
    driver_id: Optional[str] = None
    created_by_name: Optional[str] = None   # nombre del admin/conductor que abrió la incidencia
    title: str = ""
    description: str
    severity: str = "leve"
    status: str = "open"
    photos: List[str] = []
    notes: str = ""
    created_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))
    resolved_at: Optional[datetime] = None


class IncidentCreate(BaseModel):
    vehicle_id: str
    driver_id: Optional[str] = None
    title: str = ""
    description: str
    severity: str = "leve"
    photos: List[str] = []
    notes: str = ""


async def _auto_incident_on_workshop(vehicle_id: str, prev_status, new_status):
    """Al marcar un vehículo 'en taller', crea (o reabre) su incidencia automáticamente
    para que siempre quede en el histórico. Y le pone el reloj en marcha."""
    # ── EL RELOJ DEL TALLER ──────────────────────────────────────────────────
    # `status: "taller"` era una etiqueta sin fecha: nadie sabia desde cuando
    # estaba parada una furgoneta. Medido el 28-08-2026: 14 paradas, tres de
    # ellas desde hacia 52 dias, 319 dias-furgoneta acumulados y ni un solo
    # sitio donde se viera. Una furgoneta parada no cuesta menos por no mirarla.
    # Se escribe aqui porque esta funcion es el paso obligado de las tres rutas
    # que meten una furgoneta en taller (PATCH de vehiculos, el de super-admin y
    # la creacion de una orden), asi que no hay forma de entrar sin reloj.
    if new_status == "taller" and prev_status != "taller":
        await db.vehicles.update_one(
            {"id": vehicle_id},
            {"$set": {"taller_desde": datetime.now(timezone.utc).isoformat()}})
    elif prev_status == "taller" and new_status != "taller":
        # Al salir se borra: si se quedara, la proxima entrada heredaria la
        # fecha vieja y la furgoneta apareceria parada desde hace meses.
        await db.vehicles.update_one({"id": vehicle_id}, {"$unset": {"taller_desde": ""}})
        # Y LA INCIDENCIA AUTOMATICA SE CIERRA SOLA. Nadie la cerraba: el
        # 02-09-2026 habia 7 "Vehiculo en taller" abiertas de furgonetas
        # activas desde julio, contando en las "40 incidencias abiertas" del
        # dashboard. Solo las automaticas: una escrita a mano ("ADBLUE",
        # "EMBRAGUE") la cierra quien sepa si esta arreglado.
        ahora = datetime.now(timezone.utc).isoformat()
        r = await db.incidents.update_many(
            {"vehicle_id": vehicle_id, "auto_created": True, "status": "open"},
            {"$set": {"status": "resolved", "resolved_at": ahora,
                      "resolucion": "Cerrada sola: la furgoneta salió del taller"},
             "$push": {"history": {"date": ahora, "event": "Cerrada: salió del taller"}}})
        if r.modified_count:
            logger.info("Incidencia de taller cerrada sola al salir (%s)", vehicle_id)

    if new_status != "taller" or prev_status == "taller":
        return
    v = await db.vehicles.find_one({"id": vehicle_id}, {"_id": 0, "license_plate": 1})
    plate = (v or {}).get("license_plate", vehicle_id)
    titulo = f"Vehículo en taller — {plate}"
    now_iso = datetime.now(timezone.utc).isoformat()
    # ¿Ya hay una incidencia de taller ABIERTA para este vehiculo, sea
    # automatica o escrita a mano con el mismo titulo? No se duplica. Antes se
    # comparaba el titulo exacto y bastaba que la matricula se hubiera
    # escrito "9886NFX" en vez de "9886 NFX" para abrir otra: 13 parejas
    # abiertas en produccion el 02-09-2026.
    abierta = await db.incidents.find_one(
        {"vehicle_id": vehicle_id, "status": "open",
         "$or": [{"auto_created": True}, {"title": {"$regex": "^Veh[ií]culo en taller"}}]},
        {"_id": 0, "id": 1})
    if abierta:
        return
    existing = await db.incidents.find_one({"vehicle_id": vehicle_id, "title": titulo})
    if existing:
        if existing.get("status") in ("resolved", "closed"):
            await db.incidents.update_one(
                {"id": existing["id"]},
                {"$set": {"status": "open", "resolved_at": None, "reopened_at": now_iso},
                 "$push": {"history": {"date": now_iso, "event": "Reabierta: vuelve a entrar en taller"}}}
            )
            logger.info(f"Incidencia de taller reabierta para {plate}")
        return
    inc = Incident(
        vehicle_id=vehicle_id,
        title=titulo,
        description=f"Entrada en taller registrada automáticamente el {now_iso[:10]}.",
        severity="media",
        status="open",
    )
    doc = serialize_doc(inc.model_dump())
    doc["auto_created"] = True
    await db.incidents.insert_one(doc)
    logger.info(f"Incidencia de taller creada automáticamente para {plate}")


@api_router.get("/incidents")
async def get_incidents(vehicle_id: Optional[str] = None, status: Optional[str] = None,
                        center: Optional[str] = None, user: dict = Depends(require_any_auth)):
    """Incidencias, acotadas por furgoneta, estado y centro.

    `status` y `center` no existian: el panel mandaba `?status=open` y esto
    devolvia TODAS (56, con 16 resueltas), y "Mi dia" las contaba como
    abiertas del centro cuando eran de toda la empresa (02-09-2026). Las
    incidencias no tienen centro: se acotan por furgoneta (gotcha 6).
    """
    query = {}
    if user["role"] == "driver":
        query["driver_id"] = user["sub"]
        if vehicle_id:
            query["vehicle_id"] = vehicle_id
    else:
        permitido = await _filtro_por_vehiculos(user, center)
        if vehicle_id:
            if permitido and vehicle_id not in permitido["vehicle_id"]["$in"]:
                raise HTTPException(403, "No tienes acceso a ese vehículo")
            query["vehicle_id"] = vehicle_id
        else:
            query.update(permitido)
    if status in ("open", "resolved"):
        query["status"] = status
    incidents = await db.incidents.find(query, {"_id": 0}).sort("created_at", -1).to_list(200)
    return incidents


@api_router.post("/incidents")
async def create_incident(data: IncidentCreate, user: dict = Depends(require_any_auth)):
    incident = Incident(**data.model_dump())
    if user["role"] == "driver":
        incident.driver_id = user["sub"]
        today = _dia_negocio()
        assigned_today = await db.daily_assignments.find_one({
            "date": today,
            "slots": {"$elemMatch": {"driver_id": user["sub"], "vehicle_id": incident.vehicle_id}}
        }, {"_id": 0, "id": 1})
        inspected_today = None
        if not assigned_today:
            inspected_today = await db.inspections.find_one({
                "vehicle_id": incident.vehicle_id,
                "driver_id": user["sub"],
                "created_at": {"$regex": f"^{today}"}
            }, {"_id": 0, "id": 1})
        if not assigned_today and not inspected_today:
            raise HTTPException(status_code=403, detail="Solo puedes crear incidencias en tu vehículo asignado")
    incident.created_by_name = user.get("name") or user.get("username") or "Admin"
    doc = serialize_doc(incident.model_dump())
    await db.incidents.insert_one(doc)
    logger.info(f"Incidencia creada: {incident.id} — vehículo {incident.vehicle_id}")
    # Push a los coordinadores del centro de ese vehículo
    try:
        veh = await db.vehicles.find_one({"id": incident.vehicle_id}, {"_id": 0, "center": 1, "license_plate": 1})
        _center = (veh or {}).get("center") or ""
        _plate = (veh or {}).get("license_plate") or ""
        await push_center_event(
            _center, f"⚠️ Incidencia · {_center}".strip(),
            f"{_plate}: {incident.title or incident.description[:60]}",
            url="/panel/incidencias", exclude_id=user.get("sub"))
    except Exception as _pe:
        logger.debug(f"push incidencia: {_pe}")

    # ── Y UN WHATSAPP AL TALLER, si es grave y esta encendido ────────────────
    # Solo grave o critica: mandarlas todas convierte el aviso en ruido y el
    # taller deja de mirarlo, que es peor que no avisar.
    # Va dentro de su propio try: una incidencia se guarda pase lo que pase con
    # el aviso, y la persona que la esta creando esta en la calle esperando.
    try:
        if str(getattr(incident, "severity", "") or "").lower() in ("critica", "crítica", "grave", "critical", "high")                 and await whatsapp.puede_avisar(db, "avisar_incidencia"):
            _veh = await db.vehicles.find_one(
                {"id": incident.vehicle_id},
                {"_id": 0, "license_plate": 1, "workshop_id": 1, "center": 1})
            _tallerid = (_veh or {}).get("workshop_id")
            _taller = await db.workshops.find_one({"id": _tallerid}, {"_id": 0, "name": 1, "phone": 1})                 if _tallerid else None
            if _taller and _taller.get("phone"):
                _cfgw = await whatsapp.config(db)
                await whatsapp.enviar_plantilla(
                    db, _taller["phone"], _cfgw["plantilla_incidencia"],
                    [(_veh or {}).get("license_plate") or incident.vehicle_id,
                     (incident.title or incident.description or "")[:200]],
                    motivo="incidencia_critica")
    except Exception as _we:                                 # noqa: BLE001
        logger.warning(f"WhatsApp incidencia: {_we}")

    return serialize_doc(incident.model_dump())


@api_router.put("/incidents/{incident_id}/reopen")
async def reopen_incident(incident_id: str, _=Depends(require_admin)):
    """Reabre una incidencia cerrada (sin necesidad de crear otra)."""
    result = await db.incidents.update_one(
        {"id": incident_id},
        {"$set": {"status": "open", "resolved_at": None,
                  "reopened_at": datetime.now(timezone.utc).isoformat()}}
    )
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Incidencia no encontrada")
    return {"success": True}


@api_router.put("/incidents/{incident_id}/resolve")
async def resolve_incident(incident_id: str, _=Depends(require_admin)):
    result = await db.incidents.update_one(
        {"id": incident_id},
        {"$set": {"status": "resolved", "resolved_at": datetime.now(timezone.utc).isoformat()}}
    )
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Incidencia no encontrada")
    return {"success": True}


@api_router.patch("/incidents/{incident_id}")
async def update_incident(incident_id: str, request: Request, _=Depends(require_admin)):
    """Actualiza campos editables de una incidencia."""
    _ALLOWED = {"title", "description", "severity", "notes", "status"}
    try:
        data = await request.json()
    except Exception:                                        # noqa: BLE001
        # Sin cuerpo o mal formado, `request.json()` revienta y salia un 500
        # (barrido de mutaciones del 02-09-2026). Es un dato mal mandado: 400.
        raise HTTPException(status_code=400, detail="Cuerpo JSON inválido o vacío")
    if not isinstance(data, dict):
        raise HTTPException(status_code=400, detail="Cuerpo JSON inválido")
    data = {k: v for k, v in data.items() if k in _ALLOWED}
    if not data:
        raise HTTPException(status_code=400, detail="Sin campos válidos")
    data["updated_at"] = datetime.now(timezone.utc).isoformat()
    if data.get("status") == "resolved" and "resolved_at" not in data:
        data["resolved_at"] = data["updated_at"]
    elif data.get("status") == "open":
        data["resolved_at"] = None
    result = await db.incidents.update_one({"id": incident_id}, {"$set": data})
    if result.matched_count == 0:
        raise HTTPException(status_code=404, detail="Incidencia no encontrada")
    return {"success": True}


@api_router.delete("/incidents/{incident_id}")
async def delete_incident(incident_id: str, _=Depends(require_admin)):
    """Elimina permanentemente una incidencia."""
    result = await db.incidents.delete_one({"id": incident_id})
    if result.deleted_count == 0:
        raise HTTPException(status_code=404, detail="Incidencia no encontrada")
    return {"success": True}


