async def _ot_marcar_dano(ledger_id: str, orden_id: str, numero) -> None:
    """Deja escrito en el daño que ya esta en el taller.

    Va en su propia funcion y con su try: que falle marcar el daño NO puede
    tumbar la creacion de la orden, que es lo importante. Si esto falla, lo
    peor que pasa es que el daño siga saliendo en la lista de pendientes.
    """
    if not ledger_id:
        return
    try:
        from bson import ObjectId as _OId
        try:
            clave = {"_id": _OId(ledger_id)}
        except Exception:
            clave = {"_id": ledger_id}
        await db.vehicle_damage_ledger.update_one(
            clave, {"$set": {"orden_id": orden_id, "orden_numero": numero,
                             "updated_at": _ot_ahora()}})
    except Exception as e:
        logger.warning(f"No se pudo marcar el daño {ledger_id}: {e}")


async def _ot_cerrar_danos(ledger_ids: list, estado: str, numero=None) -> int:
    """Cierra (o devuelve) los daños que iban en una orden. Devuelve cuantos.

    ENTREGADA -> los daños pasan a 'repaired' y salen del libro de abiertos.
    ANULADA   -> se les quita la orden y vuelven a la lista de pendientes, que
                 es donde tienen que estar: la furgoneta no se ha arreglado.

    Se marca `repaired` y no `archived` a proposito. 'Archivado' ya se usa para
    lo que se descarta por otras razones (falso positivo de la IA, duplicado),
    y mezclar "se reparo" con "no era nada" hace imposible saber despues cuanto
    se ha arreglado de verdad — que es justo el numero que quiere un DSP.
    """
    if not ledger_ids:
        return 0
    from bson import ObjectId as _OId
    oids, planos = [], []
    for x in ledger_ids:
        try:
            oids.append(_OId(str(x)))
        except Exception:
            planos.append(str(x))
    cond = [c for c in ({"_id": {"$in": oids}} if oids else None,
                        {"_id": {"$in": planos}} if planos else None) if c]
    if not cond:
        return 0
    clave = cond[0] if len(cond) == 1 else {"$or": cond}
    if estado == "entregado":
        cambio = {"$set": {"status": "repaired", "repaired_at": _ot_ahora(),
                           "repaired_orden": numero, "updated_at": _ot_ahora()}}
    else:
        cambio = {"$set": {"status": "open", "updated_at": _ot_ahora()},
                  "$unset": {"orden_id": "", "orden_numero": ""}}
    try:
        r = await db.vehicle_damage_ledger.update_many(clave, cambio)
        return int(r.modified_count or 0)
    except Exception as e:                                   # noqa: BLE001
        # Que falle cerrar el libro NO puede tumbar el cierre de la orden: la
        # furgoneta ya ha vuelto y eso es lo que manda.
        logger.warning("No se pudieron cerrar los daños de la orden %s: %s", numero, e)
        return 0


@api_router.post("/workshops/{workshop_id}/enlace")
async def enlace_taller(workshop_id: str, user: dict = Depends(require_admin)):
    """UN enlace por taller, para siempre, con todas sus furgonetas dentro.

    Hasta ahora cada orden tenia su enlace y el taller acababa con seis
    mensajes de WhatsApp con seis enlaces distintos: abria el que tenia mas a
    mano y no el de la furgoneta que tenia delante. Con uno solo por taller
    —que se manda una vez y se guarda en favoritos— entra y ve lo que tiene
    nuestro ahora mismo, y desde ahi abre cada orden con su paso a paso de
    siempre. Es lo que hace que un taller QUIERA usarlo (Dani, 02-09-2026).
    Se reutiliza si ya existe uno vivo; rehacerlo revoca el anterior.
    """
    w = await db.workshops.find_one({"id": workshop_id}, {"_id": 0, "name": 1, "phone": 1})
    if not w:
        raise HTTPException(404, "Ese taller no existe")
    dbn = _current_db_name.get()
    vivo = await global_db.taller_enlaces.find_one(
        {"workshop_id": workshop_id, "db_name": dbn, "revocado": {"$ne": True},
         "expira_en": {"$gt": _ot_ahora()}}, {"_id": 0, "token": 1, "expira_en": 1})
    if vivo:
        token, caduca = vivo["token"], vivo["expira_en"]
    else:
        token = secrets.token_urlsafe(32)
        caduca = (datetime.now(timezone.utc) + timedelta(days=365)).isoformat()
        await global_db.taller_enlaces.insert_one({
            "token": token, "workshop_id": workshop_id, "db_name": dbn,
            "taller_nombre": w.get("name"),
            "creado_por": user.get("name") or user.get("username") or "oficina",
            "creado_en": _ot_ahora(), "expira_en": caduca, "revocado": False, "tipo": "taller",
        })
    url = "%s/taller/t/%s" % (_PORTAL_BASE_FRONT.rstrip("/"), token)
    texto = (
        "Hola, somos de la flota. Este es vuestro enlace fijo con nuestras "
        "furgonetas: %s\n\nAhí veis las que tenéis nuestras ahora mismo y, en cada "
        "una, podéis marcar el estado, subir fotos, pasar presupuesto y decir "
        "para cuándo estará. Sin registrarse. Guardadlo en favoritos: es siempre "
        "el mismo. Gracias."
    ) % url
    return {"url": url, "expira_en": caduca, "texto_whatsapp": texto,
            "taller": w.get("name"), "telefono": w.get("phone"),
            "wa": enlace_wa(w.get("phone") or "", texto)}


@api_router.get("/taller/t/{token}")
async def portal_taller_lista(token: str):
    """Lo que un taller tiene nuestro ahora mismo, sin usuario ni contraseña.

    Cada orden lleva su propio enlace de siempre (se crea si no lo tenia), asi
    el paso a paso por orden no cambia: esto solo es la puerta de entrada.
    """
    _ot_freno(token, limite=120)
    tok = (token or "").strip()
    if len(tok) < 20 or len(tok) > 120:
        raise HTTPException(404, "Este enlace no es válido")
    enlace = await global_db.taller_enlaces.find_one(
        {"token": tok, "tipo": "taller"}, {"_id": 0})
    if not enlace or enlace.get("revocado") or not enlace.get("workshop_id"):
        raise HTTPException(404, "Este enlace no es válido")
    if enlace.get("expira_en") and enlace["expira_en"] < _ot_ahora():
        raise HTTPException(404, "Este enlace ha caducado. Pídele uno nuevo a la oficina.")
    # LA LINEA QUE EVITA EL DESASTRE MULTIEMPRESA (gotcha 26).
    set_current_org_db(enlace.get("db_name"))
    ordenes = await db.ordenes_trabajo.find(
        {"workshop_id": enlace["workshop_id"], "estado": {"$nin": list(OT_ESTADOS_CERRADOS)}},
        {"_id": 0, "id": 1, "numero": 1, "matricula": 1, "modelo": 1, "estado": 1,
         "problema": 1, "fecha_entrada": 1, "fecha_entrega_estimada": 1, "presupuesto": 1,
         "creada_en": 1}).sort("creada_en", -1).to_list(100)
    salida = []
    for o in ordenes:
        e = await global_db.taller_enlaces.find_one(
            {"orden_id": o["id"], "revocado": {"$ne": True}, "expira_en": {"$gt": _ot_ahora()}},
            {"_id": 0, "token": 1})
        if not e:
            t_orden = secrets.token_urlsafe(32)
            await global_db.taller_enlaces.insert_one({
                "token": t_orden, "orden_id": o["id"], "db_name": enlace.get("db_name"),
                "numero": o.get("numero"), "creado_por": "enlace del taller",
                "creado_en": _ot_ahora(),
                "expira_en": (datetime.now(timezone.utc) + timedelta(days=60)).isoformat(),
                "revocado": False,
            })
            e = {"token": t_orden}
        # Lista blanca de campos: esto acaba en telefonos que no controlamos.
        salida.append({
            "numero": o.get("numero"), "matricula": o.get("matricula"), "modelo": o.get("modelo"),
            "estado": o.get("estado"), "estado_txt": OT_ESTADOS.get(o.get("estado"), o.get("estado")),
            "problema": (o.get("problema") or "")[:300], "fecha_entrada": o.get("fecha_entrada"),
            "fecha_entrega_estimada": o.get("fecha_entrega_estimada"),
            "presupuesto": o.get("presupuesto"), "token": e["token"],
        })
    await global_db.taller_enlaces.update_one(
        {"token": tok}, {"$set": {"ultima_visita": _ot_ahora()}, "$inc": {"visitas": 1}})
    return {"taller": enlace.get("taller_nombre"), "ordenes": salida, "total": len(salida)}


@api_router.post("/work-orders/{orden_id}/enlace")
async def enlace_orden(orden_id: str, dias: int = 60, user: dict = Depends(require_admin)):
    """Crea (o rehace) el enlace del taller y devuelve el texto listo para WhatsApp.

    Rehacerlo REVOCA el anterior a proposito: si se manda a quien no era, la
    forma de arreglarlo es que el viejo deje de abrir.
    """
    o = await db.ordenes_trabajo.find_one({"id": orden_id}, {"_id": 0})
    if not o:
        raise HTTPException(404, "Esa orden no existe")

    await global_db.taller_enlaces.update_many(
        {"orden_id": orden_id}, {"$set": {"revocado": True}})

    token = secrets.token_urlsafe(32)
    caduca = (datetime.now(timezone.utc) + timedelta(days=max(1, min(dias, 365)))).isoformat()
    await global_db.taller_enlaces.insert_one({
        "token": token,
        "orden_id": orden_id,
        # El nombre de la BD, no el id de la organizacion: es lo que hace falta
        # para fijar el contexto sin volver a consultar nada.
        "db_name": _current_db_name.get(),
        "numero": o.get("numero"),
        "creado_por": user.get("name") or user.get("username") or "oficina",
        "creado_en": _ot_ahora(),
        "expira_en": caduca,
        "revocado": False,
    })
    url = "%s/taller/%s" % (_PORTAL_BASE_FRONT.rstrip("/"), token)
    texto = (
        "Hola, os dejamos la furgoneta %s.\n\n"
        "%s\n\n"
        "En este enlace podéis ir poniendo el estado, subir fotos y decirnos "
        "para cuándo estará. No hace falta registrarse:\n%s\n\n"
        "Así nos evitamos las llamadas. Gracias."
    ) % (o.get("matricula") or "", (o.get("problema") or "").strip() or "Revisión.", url)

    await db.ordenes_trabajo.update_one(
        {"id": orden_id},
        {"$push": {"historial": _ot_apunte(user.get("name") or "oficina", "Enlace generado")},
         "$set": {"actualizada_en": _ot_ahora()}})
    # `wa` lo arma el servidor con `enlace_wa`, que pone el prefijo del pais a
    # los numeros de 9 digitos y devuelve "" cuando no hay telefono. El panel lo
    # construia a mano y abria `wa.me/981574178` —un numero que no existe— con
    # el unico taller guardado sin prefijo (gotcha 47).
    return {"url": url, "expira_en": caduca, "texto_whatsapp": texto,
            "telefono_taller": o.get("taller_telefono") or "",
            "wa": enlace_wa(o.get("taller_telefono") or "", texto)}


@api_router.patch("/work-orders/{orden_id}")
async def editar_orden(orden_id: str, data: dict = Body(...), user: dict = Depends(require_admin)):
    """La oficina. Lista blanca: lo que no este aqui se ignora."""
    o = await db.ordenes_trabajo.find_one({"id": orden_id}, {"_id": 0})
    if not o:
        raise HTTPException(404, "Esa orden no existe")

    quien = user.get("name") or user.get("username") or "oficina"
    campos, apuntes = {}, []

    if "estado" in data:
        nuevo = str(data["estado"])
        motivo = _ot_transicion_invalida(o.get("estado"), nuevo)
        if motivo:
            raise HTTPException(400 if nuevo not in OT_ESTADOS else 409, motivo)
        if nuevo != o.get("estado"):
            campos["estado"] = nuevo
            apuntes.append(_ot_apunte(quien, "Estado: " + OT_ESTADOS[nuevo]))
            if nuevo == "entregado":
                campos["fecha_entrega_real"] = _ot_ahora()[:10]
            # Al cerrar, la furgoneta vuelve a donde estaba. Solo si sigue en
            # 'taller': si alguien ya la movio a mano (o esta de baja), mandar
            # lo que decida esa persona, no lo que recuerde esta orden.
            if nuevo in ("entregado", "anulada"):
                v = await db.vehicles.find_one({"id": o.get("vehicle_id")}, {"_id": 0, "status": 1})
                if (v or {}).get("status") == "taller":
                    vuelve = o.get("vehiculo_estado_previo") or "activo"
                    await db.vehicles.update_one({"id": o["vehicle_id"]},
                                                 {"$set": {"status": vuelve}})
                    # Las mismas reglas que al cambiarla a mano en Vehiculos:
                    # sin esto `taller_desde` se quedaba puesto en una
                    # furgoneta ya activa (medido al entregar por API).
                    await _auto_incident_on_workshop(o["vehicle_id"], "taller", vuelve)
                    apuntes.append(_ot_apunte(quien, "Furgoneta de vuelta", vuelve))
            # SE CIERRA EL CIRCULO. Al entregar, los daños que iban en la orden
            # pasan a reparados en el libro; al anularla vuelven a la lista de
            # pendientes en vez de quedarse retenidos por una orden muerta.
            # Sin esto el libro no vale: un golpe ya arreglado seguia contando
            # como abierto para siempre, y una lista que no baja nunca deja de
            # mirarse — que es exactamente lo que le pasa hoy a los 213.
            _lids = list(o.get("ledger_ids") or [])
            if not _lids and o.get("ledger_id"):
                _lids = [o["ledger_id"]]
            if _lids and nuevo in ("entregado", "anulada"):
                n = await _ot_cerrar_danos(_lids, nuevo, o.get("numero"))
                if n:
                    apuntes.append(_ot_apunte(
                        quien,
                        "%d daños %s" % (n, "reparados" if nuevo == "entregado" else "devueltos"),
                        "" if nuevo == "entregado" else "la orden se anuló"))

    for campo, etiqueta in (("problema", "Problema"), ("descripcion_trabajo", "Trabajo")):
        if campo in data:
            campos[campo] = str(data[campo] or "").strip()[:2000]
            apuntes.append(_ot_apunte(quien, etiqueta + " actualizado"))

    for campo in ("fecha_entrada", "fecha_entrega_estimada"):
        if campo in data:
            f = _ot_fecha_valida(data[campo])
            if data[campo] and not f:
                raise HTTPException(400, "La fecha tiene que ser AAAA-MM-DD")
            campos[campo] = f
            apuntes.append(_ot_apunte(quien, "Fecha cambiada", f or "sin fecha"))

    for campo in ("importe_estimado", "importe_final"):
        if campo in data:
            campos[campo] = _ot_importe(data[campo])

    if "presupuesto" in data:
        p = str(data["presupuesto"])
        if p not in ("sin_presupuesto", "pendiente", "aprobado", "rechazado"):
            raise HTTPException(400, "Ese estado de presupuesto no existe")
        campos["presupuesto"] = p
        # El taller esta PARADO esperando esto. Si no se entera, espera un dia
        # y luego llama a preguntar: la llamada que este modulo venia a quitar.
        # Se apunta en el historial, que es lo primero que ve al abrir.
        campos["presupuesto_por"] = quien
        campos["presupuesto_en"] = _ot_ahora()
        apuntes.append(_ot_apunte(quien, "Presupuesto " + p,
                                  ("%.2f EUR" % o["importe_estimado"]) if o.get("importe_estimado") else ""))

    if not campos:
        return {"cambios": 0, "orden": o}

    campos["actualizada_en"] = _ot_ahora()
    cambio: dict = {"$set": campos}
    if apuntes:
        cambio["$push"] = {"historial": {"$each": apuntes}}
    await db.ordenes_trabajo.update_one({"id": orden_id}, cambio)
    return {"cambios": len(campos), "orden": await db.ordenes_trabajo.find_one({"id": orden_id}, {"_id": 0})}


# ── PORTAL DEL TALLER (publico, solo con el token) ────────────────────────

@api_router.get("/taller/{token}")
async def portal_taller(token: str):
    """Abrir el portal DEJA HUELLA, y esa huella vale mucho.

    Sin esto, mandas el enlace y te quedas a ciegas: no sabes si no hay
    novedades porque no las hay o porque el taller ni lo ha abierto. Son dos
    situaciones opuestas —en una esperas, en la otra llamas— y por pantalla se
    veian igual.

    El contador no escribe en el historial en cada visita (lo llenaria de
    ruido); solo la PRIMERA vez, que es la que de verdad significa algo.
    """
    _ot_freno(token, limite=120)                 # leer es barato
    orden = await _ot_por_token(token)
    campos = {"ultima_visita": _ot_ahora()}
    cambio: dict = {"$inc": {"visitas": 1}}
    if not orden.get("abierto_en"):
        campos["abierto_en"] = _ot_ahora()
        cambio["$push"] = {"historial": _ot_apunte(orden.get("taller_nombre") or "Taller",
                                                   "Ha abierto el enlace")}
    cambio["$set"] = campos
    await db.ordenes_trabajo.update_one({"id": orden["id"]}, cambio)
    return await _ot_publica(orden)


@api_router.post("/taller/{token}/estado")
async def portal_taller_estado(token: str, data: dict = Body(...)):
    _ot_freno(token)
    orden = await _ot_por_token(token)
    _ot_puede_escribir(orden)
    nuevo = str(data.get("estado") or "")
    if nuevo not in OT_ESTADOS_TALLER:
        raise HTTPException(400, "Ese estado no se puede poner desde aquí")
    if nuevo == orden.get("estado"):
        return await _ot_publica(orden)

    nota = str(data.get("nota") or "").strip()[:400]
    await db.ordenes_trabajo.update_one(
        {"id": orden["id"]},
        {"$set": {"estado": nuevo, "actualizada_en": _ot_ahora(),
                   "ultima_novedad_taller": _ot_ahora()},
         "$push": {"historial": _ot_apunte(orden.get("taller_nombre") or "Taller",
                                           "Estado: " + OT_ESTADOS[nuevo], nota)}})
    await _portal_apunta(orden, "Lo ha puesto en: %s%s"
                         % (OT_ESTADOS[nuevo], (" — " + nota) if nota else ""))
    if nuevo in OT_AVISA:
        await _ot_avisa(orden, "El taller lo ha puesto en: %s%s"
                        % (OT_ESTADOS[nuevo], (" — " + nota) if nota else ""))
    return await _ot_publica(await db.ordenes_trabajo.find_one({"id": orden["id"]}, {"_id": 0}))


# Motivos de retraso, en un toque. Escribir con las manos sucias y el movil
# en una mano no lo hace nadie: si el motivo hay que teclearlo, no se pone, y
# entonces la oficina llama para preguntar "¿por que?" — que es justo la
# llamada que sobra. Con cuatro botones se pone siempre.
OT_MOTIVOS = {
    "pieza": "Falta una pieza",
    "mas_trabajo": "Ha salido más trabajo del previsto",
    "saturado": "El taller va cargado",
    "espera_ok": "Esperando que aprobéis el presupuesto",
    "otro": "Otro motivo",
}


@api_router.post("/taller/{token}/entrega")
async def portal_taller_entrega(token: str, data: dict = Body(...)):
    """La fecha de entrega, que es el dato que MAS se mueve.

    Este endpoint se llama muchas veces sobre la misma orden y eso no es un
    fallo: el taller dice el martes, llega el martes, falta una pieza y hay
    que decir el jueves. Que rehacerlo sea facil es la diferencia entre que lo
    actualicen o que descuelguen el telefono.
    """
    _ot_freno(token)
    orden = await _ot_por_token(token)
    _ot_puede_escribir(orden)
    f = _ot_fecha_valida(data.get("fecha"))
    if not f:
        raise HTTPException(400, "Dinos la fecha en formato AAAA-MM-DD")

    motivo = OT_MOTIVOS.get(str(data.get("motivo") or ""), "")
    detalle_libre = str(data.get("detalle") or "").strip()[:300]
    antes = orden.get("fecha_entrega_estimada")

    # "Otro motivo" sin explicar no informa de nada: ocupa sitio y encima
    # parece que te han dicho algo. Solo cuenta si trae el detalle.
    # VA ANTES DEL GUARD DE ABAJO, y no despues: si se normaliza al final,
    # "Otro motivo" a secas sigue siendo truthy cuando el guard mira, se
    # cuela por el, y se apunta una linea de historial IDENTICA a la
    # anterior y ademas sin ninguna razon dentro — justo el duplicado que el
    # guard existe para evitar.
    if motivo == OT_MOTIVOS["otro"] and not detalle_libre:
        motivo = ""

    # Confirmar la fecha que ya estaba no es una novedad: sin esto cada
    # toque metia una linea igual en el historial. En la OT-1002 salieron
    # dos seguidas identicas y parecia que habia pasado algo dos veces.
    if antes == f and not motivo and not detalle_libre:
        return await _ot_publica(orden)

    # Cuantos dias se mueve. Decir "se retrasa 2 dias" es informacion; decir
    # "del 2 al 4" obliga a hacer la cuenta a quien lo lee.
    desfase = None
    if antes and antes != f:
        try:
            desfase = (datetime.strptime(f, "%Y-%m-%d") - datetime.strptime(antes, "%Y-%m-%d")).days
        except Exception:
            desfase = None

    partes = [p for p in (motivo, detalle_libre) if p]
    if antes and antes != f:
        que = "Entrega: %s (antes %s)" % (f, antes)
    else:
        que = "Fecha de entrega: " + f

    await db.ordenes_trabajo.update_one(
        {"id": orden["id"]},
        {"$set": {"fecha_entrega_estimada": f, "actualizada_en": _ot_ahora(),
                  "ultima_novedad_taller": _ot_ahora(),
                  # Quien la puso. La pantalla del taller decia "Dijisteis
                  # que estaria el..." tambien cuando la fecha la habia
                  # escrito la oficina al abrir la orden: les atribuia una
                  # promesa que no habian hecho.
                  "entrega_la_dijo_taller": True,
                  # El motivo Y su explicacion, no solo el motivo. Con "Otro
                  # motivo" lo unico que informa es el texto libre: guardar
                  # solo la etiqueta dejaba en pantalla un "Otro motivo" a
                  # secas, que es exactamente no decir nada.
                  "motivo_retraso": " · ".join(partes) or None},
         "$push": {"historial": _ot_apunte(orden.get("taller_nombre") or "Taller",
                                           que, " · ".join(partes))}})

    # Un retraso es exactamente la llamada que este modulo venia a quitar:
    # si la fecha se mueve, se avisa. Si se pone por primera vez, no.
    await _portal_apunta(orden, "Entrega prevista: %s%s"
                         % (f, (" — " + " · ".join(partes)) if partes else ""))
    if antes and antes != f:
        cuanto = ("se retrasa %d dias" % desfase) if desfase and desfase > 0 else (
            "se adelanta %d dias" % abs(desfase)) if desfase else "cambia"
        await _ot_avisa(orden, "La entrega %s: del %s al %s%s"
                        % (cuanto, antes, f, (" — " + " · ".join(partes)) if partes else ""))
    return await _ot_publica(await db.ordenes_trabajo.find_one({"id": orden["id"]}, {"_id": 0}))


@api_router.post("/taller/{token}/presupuesto")
async def portal_taller_presupuesto(token: str, data: dict = Body(...)):
    """El taller PROPONE, la oficina aprueba. Nunca al reves."""
    _ot_freno(token)
    orden = await _ot_por_token(token)
    _ot_puede_escribir(orden)
    importe = _ot_importe(data.get("importe"))
    if importe is None:
        raise HTTPException(400, "Pon un importe válido, en euros")
    final = bool(data.get("final"))
    detalle = str(data.get("detalle") or "").strip()[:600]

    campos = {"actualizada_en": _ot_ahora(), "ultima_novedad_taller": _ot_ahora()}
    if final:
        campos["importe_final"] = importe
        que = "Importe final: %.2f EUR" % importe
    else:
        campos["importe_estimado"] = importe
        campos["presupuesto"] = "pendiente"    # vuelve a pendiente si lo cambia
        que = "Presupuesto: %.2f EUR" % importe

    await db.ordenes_trabajo.update_one(
        {"id": orden["id"]},
        {"$set": campos,
         "$push": {"historial": _ot_apunte(orden.get("taller_nombre") or "Taller", que, detalle)}})
    await _portal_apunta(orden, que + ((" — " + detalle) if detalle else "")
                         + ("" if final else " (pendiente de aprobar)"))
    await _ot_avisa(orden, que + ((" — " + detalle) if detalle else "")
                    + ("" if final else " (pendiente de aprobar)"))
    return await _ot_publica(await db.ordenes_trabajo.find_one({"id": orden["id"]}, {"_id": 0}))


@api_router.post("/taller/{token}/nota")
async def portal_taller_nota(token: str, data: dict = Body(...)):
    _ot_freno(token)
    orden = await _ot_por_token(token)
    _ot_puede_escribir(orden)
    nota = str(data.get("nota") or "").strip()[:1000]
    if not nota:
        raise HTTPException(400, "Escribe algo antes de enviar")
    await db.ordenes_trabajo.update_one(
        {"id": orden["id"]},
        {"$set": {"actualizada_en": _ot_ahora(), "ultima_novedad_taller": _ot_ahora()},
         "$push": {"historial": _ot_apunte(orden.get("taller_nombre") or "Taller", "Nota", nota)}})
    await _portal_apunta(orden, nota)
    await _ot_avisa(orden, "Nota del taller: " + nota[:200])
    return await _ot_publica(await db.ordenes_trabajo.find_one({"id": orden["id"]}, {"_id": 0}))


@api_router.post("/taller/{token}/fotos")
async def portal_taller_fotos(token: str, files: List[UploadFile] = File(...)):
    _ot_freno(token, limite=25)
    orden = await _ot_por_token(token)
    _ot_puede_escribir(orden)
    if len(files) > 10:
        raise HTTPException(400, "Como mucho 10 fotos a la vez")

    urls = []
    for f in files:
        contenido = await f.read()
        if not contenido:
            continue
        if len(contenido) > 12_000_000:
            raise HTTPException(400, "Alguna foto pesa demasiado (máximo 12 MB)")
        # Se reprocesa SIEMPRE con la misma funcion que el resto de la app: eso
        # normaliza el formato y, de paso, tira cualquier cosa que no sea una
        # imagen de verdad, que en un endpoint sin login importa bastante.
        try:
            url, _b = await process_and_save_image(contenido, orden.get("vehicle_id") or "ot")
        except Exception as e:
            logger.warning("OT %s: foto descartada (%s)", orden.get("numero"), e)
            raise HTTPException(400, "Ese archivo no es una foto válida")
        urls.append(url)

    if not urls:
        raise HTTPException(400, "No has adjuntado ninguna foto")
    await db.ordenes_trabajo.update_one(
        {"id": orden["id"]},
        {"$push": {"fotos": {"$each": urls},
                   "historial": _ot_apunte(orden.get("taller_nombre") or "Taller",
                                           "%d foto%s" % (len(urls), "s" if len(urls) > 1 else ""))},
         "$set": {"actualizada_en": _ot_ahora(), "ultima_novedad_taller": _ot_ahora()}})
    return await _ot_publica(await db.ordenes_trabajo.find_one({"id": orden["id"]}, {"_id": 0}))


@api_router.get("/workshops", response_model=List[Workshop])
async def list_workshops(
    center: Optional[str] = None,
    category: Optional[str] = None,
    provider: Optional[str] = None,
    only_active: bool = True,
    _=Depends(require_admin),
):
    query = {}
    if only_active:
        query["active"] = {"$ne": False}
    if center:
        query["center"] = center
    if category:
        query["categories"] = category
    workshops = await db.workshops.find(query, {"_id": 0}).to_list(500)
    # Filtro por proveedor en Python (más flexible que regex en arrays)
    if provider:
        workshops = [w for w in workshops if _provider_matches(w, provider)]
    for w in workshops:
        for k in ("created_at", "updated_at"):
            if isinstance(w.get(k), str):
                try:
                    w[k] = datetime.fromisoformat(w[k])
                except Exception:
                    pass
    return workshops


@api_router.get("/workshops/nearby")
async def workshops_nearby(
    lat: float,
    lng: float,
    provider: Optional[str] = None,
    max_km: float = 80,
    limit: int = 15,
    category: Optional[str] = None,
    current_user: dict = Depends(require_any_auth),
):
    """
    Devuelve talleres ordenados por distancia al punto (lat, lng).
    Accesible para cualquier usuario autenticado (no solo admin).
    Incluye info de asistencia en carretera del proveedor.
    """
    query = {"active": {"$ne": False}}
    if category:
        query["categories"] = category

    workshops = await db.workshops.find(query, {"_id": 0}).to_list(500)

    if provider:
        workshops = [w for w in workshops if _provider_matches(w, provider)]

    # Calcular distancia y filtrar
    results = []
    for w in workshops:
        if w.get("latitude") is None or w.get("longitude") is None:
            continue
        dist = _haversine_km((lat, lng), (w["latitude"], w["longitude"])) or 9999
        if dist <= max_km:
            w["distance_km"] = round(dist, 1)
            results.append(w)

    results.sort(key=lambda x: x["distance_km"])
    results = results[:limit]

    # Inyectar info de asistencia en carretera
    roadside = _provider_roadside(provider or "")
    return {
        "workshops": results,
        "roadside": roadside,
        "provider": provider,
        "user_lat": lat,
        "user_lng": lng,
    }


