@api_router.post("/drivers/import-ids")
async def import_driver_ids(data: dict, _=Depends(require_admin)):
    """Importa Amazon Transporter IDs en masa desde un export de Cortex (pegado).
    La IA extrae pares (nombre, transporter_id) de cualquier formato y los cruza
    con los conductores de la BD por nombre (insensible a acentos)."""
    raw_text = (data.get("text") or "")[:30000]
    if not raw_text.strip():
        raise HTTPException(status_code=400, detail="Pega el contenido del export de Cortex")

    TID_RE = re.compile(r"\bA[A-Z0-9]{8,16}\b")

    # 1) Parseo con Gemini (entiende cualquier formato)
    pairs = []
    try:
        from google import genai as genai_sdk
        from google.genai import types as genai_types
        use_vertex = os.environ.get("USE_VERTEX_AI", "").lower() in ("1", "true", "yes")
        if use_vertex:
            from google.oauth2 import service_account
            import json as _json, base64 as _b64
            sa = os.environ.get("GCP_SERVICE_ACCOUNT_JSON", "").strip()
            if sa and not sa.startswith("{"):
                sa = _b64.b64decode(sa).decode("utf-8")
            creds = service_account.Credentials.from_service_account_info(
                _json.loads(sa), scopes=["https://www.googleapis.com/auth/cloud-platform"]) if sa else None
            client = genai_sdk.Client(vertexai=True, project=os.environ.get("GCP_PROJECT", ""),
                                      location=os.environ.get("GCP_LOCATION", "us-central1"), credentials=creds)
        else:
            client = genai_sdk.Client(api_key=os.environ.get("GEMINI_API_KEY", ""))
        prompt = (
            "Este texto es un export de Amazon Cortex/Scorecard con conductores (DAs). "
            "Extrae TODAS las parejas de nombre del conductor y su Transporter ID "
            "(el ID empieza por 'A' y tiene letras y numeros, ej: A1W24EJAOPQ5F0). "
            "Responde SOLO JSON sin markdown: "
            '{"pairs":[{"name":"nombre tal cual","transporter_id":"AXXXX"}]}\n\nTEXTO:\n' + raw_text
        )
        cfg = genai_types.GenerateContentConfig(temperature=0.0, response_mime_type="application/json")
        loop = asyncio.get_running_loop()
        async with _gemini_sem:
            resp = await asyncio.wait_for(
                loop.run_in_executor(_executor, lambda: client.models.generate_content(
                    model=os.environ.get("GEMINI_MODEL", "gemini-2.5-flash"), contents=[prompt], config=cfg)),
                timeout=40.0)
        gd = json.loads(_strip_markdown_json(resp.text or "{}"))
        for p in gd.get("pairs", []):
            tid = (p.get("transporter_id") or "").strip().upper()
            nm = (p.get("name") or "").strip()
            if nm and TID_RE.match(tid):
                pairs.append({"name": nm, "tid": tid})
    except Exception as _e:
        logger.warning(f"Import IDs: Gemini fallo ({_e}), usando deteccion por lineas")
        pairs = []

    # 2) Respaldo: detectar por linea (un ID + el texto restante = nombre)
    if not pairs:
        for line in raw_text.splitlines():
            m = TID_RE.search(line.upper())
            if not m:
                continue
            tid = m.group(0)
            name = re.sub(TID_RE, "", line, flags=re.I)
            name = re.sub(r"[\t,;|]+", " ", name).strip()
            if len(name) > 3:
                pairs.append({"name": name, "tid": tid})

    if not pairs:
        raise HTTPException(status_code=400, detail="No se encontraron pares nombre + Transporter ID en el texto.")

    # 3) Cruce con la BD por nombre (insensible a acentos)
    import unicodedata as _ud

    def _fold(s):
        s = _ud.normalize("NFD", (s or "").lower())
        return "".join(c for c in s if _ud.category(c) != "Mn")

    def _words(s):
        return set(w for w in re.sub(r"[^a-z ]", " ", _fold(s)).split() if len(w) > 1)

    drivers = await db.drivers.find({"status": {"$ne": "deleted"}}, {"_id": 0, "id": 1, "name": 1}).to_list(1000)
    driver_words = [(d, _words(d.get("name", ""))) for d in drivers]

    matched, ambiguous, unmatched = 0, [], []
    for p in pairs:
        pw = _words(p["name"])
        scored = []
        for d, dw in driver_words:
            inter = pw & dw
            if inter:
                scored.append((sum(2 if len(w) >= 5 else 1 for w in inter), d))
        scored.sort(key=lambda x: -x[0])
        best = scored[0] if scored else None
        second = scored[1] if len(scored) > 1 else None
        ok = best and (best[0] >= 3 or (best[0] >= 2 and (not second or second[0] < best[0])))
        if ok and second and second[0] == best[0]:
            ok = False
            ambiguous.append(p["name"])
        if ok:
            await db.drivers.update_one({"id": best[1]["id"]}, {"$set": {"driver_id": p["tid"]}})
            matched += 1
        elif p["name"] not in ambiguous:
            unmatched.append(p["name"])

    logger.info(f"Import IDs Cortex: {matched}/{len(pairs)} asignados")
    return {"success": True, "total": len(pairs), "matched": matched,
            "ambiguous": ambiguous[:20], "unmatched": unmatched[:20]}


# =========================
# CUADRANTE DE TURNOS (shifts) + solicitudes de días
#   shifts:        {center, driver_id, driver_name, date "YYYY-MM-DD", type,
#                   cod?, hora?}
#                  type ∈ trabaja | libre | extra   (lo que entiende la app)
#                  cod  = el codigo tal cual venia del cuadrante ("BKP", "V",
#                         "N/D"…). Opcional: los turnos guardados antes de que
#                         se empezara a guardar no lo tienen.
#                  hora = la hora entre parentesis de la celda ("05:43").
#   shift_requests:{id, center, driver_id, driver_name, date, type(libre|extra),
#                   status(pendiente|aprobado|rechazado), created_at, resolved_by, note}
#   shift_settings:{center, min_cobertura}  -> para auto-aprobar si sobra gente
# =========================

VALID_SHIFT_TYPE = {"trabaja", "libre", "extra"}

# Motivos por los que un conductor pide un día. El motivo cambia la decisión,
# así que se pide siempre y no se deja escribir libre a secas: con texto libre
# acaban poniendo "personal" y hay que preguntar igual.
MOTIVOS_PETICION = {
    "asuntos": "Asuntos propios",
    "medico": "Médico",
    "familia": "Asunto familiar",
    "viaje": "Viaje",
    "otro": "Otro",
}


def _puede(user: dict, clave: str) -> bool:
    """¿Tiene este usuario el permiso `clave`? Comprobado en el SERVIDOR.

    El panel esconde los botones según los permisos, pero esconder un botón no
    es proteger nada: quien sepa la dirección de la API llega igual. Para
    aprobar días —que decide si alguien trabaja o no— hace falta comprobarlo
    aquí, no solo en la pantalla.

    `permissions = None` significa sin restricción, que es como están los
    usuarios antiguos: quitarles el acceso de golpe sería peor que el problema.
    """
    if user.get("sa") or user.get("account_type") == "owner":
        return True
    perms = user.get("permissions")
    if perms is None:
        return True
    return clave in perms


async def _user_center(user: dict) -> Optional[str]:
    """Centro del usuario. Admin -> None (ve todos)."""
    if user.get("role") == "admin":
        return None
    d = await db.drivers.find_one({"id": user.get("sub")}, {"_id": 0, "center": 1})
    return d.get("center") if d else None


async def _min_cobertura(center: str) -> int:
    s = await db.shift_settings.find_one({"center": center}, {"_id": 0, "min_cobertura": 1})
    if s and isinstance(s.get("min_cobertura"), int):
        return s["min_cobertura"]
    return 0  # 0 = auto-aprobado desactivado (todo pasa a pendiente)


async def _coverage_for_date(center: str, date: str) -> int:
    """Conductores que ese día SACAN RUTA (no los que simplemente trabajan)."""
    return await db.shifts.count_documents(
        {"center": center, "date": date, **_FILTRO_RUTA})


async def _upsert_turno(filtro: dict, cambio: dict):
    """Upsert de un turno que aguanta dos peticiones a la vez.

    Con el unico `turno_unico`, el que pierde la carrera recibe
    `DuplicateKeyError` en vez de crear un segundo documento; entonces repite
    sin upsert, que ya encuentra el que insertó el otro (gotchas 9 y 46).
    """
    try:
        await db.shifts.update_one(filtro, cambio, upsert=True)
    except DuplicateKeyError:
        await db.shifts.update_one(filtro, cambio)


async def _bulk_turnos(ops: list):
    """bulk_write de upserts de turnos con la misma garantia que _upsert_turno.

    `ordered=False` aplica todos los que puede; si alguno choca con el unico,
    la segunda pasada los encuentra ya creados y solo actualiza. Volver a
    aplicar un `$set` identico es idempotente.
    """
    if not ops:
        return
    try:
        await db.shifts.bulk_write(ops, ordered=False)
    except BulkWriteError:
        await db.shifts.bulk_write(ops, ordered=False)


@api_router.get("/shifts")
async def get_shifts(center: Optional[str] = None, desde: Optional[str] = None,
                     hasta: Optional[str] = None, user: dict = Depends(require_admin)):
    # Los centros NO se mezclan. Sin esto, quien lleva DGA1 abría la pantalla
    # sin elegir centro y veía —y podía tocar— el cuadrante entero de OGA5.
    q = dict(_filtro_centro(user, center))
    if desde or hasta:
        rng = {}
        if desde:
            rng["$gte"] = desde
        if hasta:
            rng["$lte"] = hasta
        q["date"] = rng
    docs = await db.shifts.find(q, {"_id": 0}).to_list(20000)
    return {"shifts": docs}


@api_router.post("/shifts/bulk")
async def save_shifts_bulk(data: dict = Body(...), user: dict = Depends(require_admin)):
    """Guarda/actualiza varios turnos.

    body: {items:[{driver_id, driver_name, center, date, type, cod?, hora?}]}
    `cod` es el codigo del cuadrante ("BKP", "V", "N/D"...) y manda sobre
    `type` cuando los dos vienen y no cuadran: el codigo es lo que se vio en la
    pantalla al pintarlo.
    """
    items = data.get("items") or []
    doc = await db.app_meta.find_one({"_id": "codigos_cuadrante"}) or {}
    mapa_cod = dict(CODIGOS_CUADRANTE_DEF)
    mapa_cod.update({str(k).upper(): v for k, v in (doc.get("mapa") or {}).items()})

    # ── LOS DIAS APROBADOS NO SE PISAN ─────────────────────────────────────
    # Un dia libre aprobado es un compromiso con una persona: se lo dijiste, se
    # organizo. Que cualquiera con acceso al panel pueda repintar esa casilla
    # —a mano, arrastrando, o sin querer al pegar el cuadrante del mes— y que
    # nadie se entere hasta que esa persona no aparece, es el fallo mas caro
    # que puede tener esta pantalla.
    #
    # Se comprueba AQUI y no solo escondiendo el boton: esconder un boton no
    # protege nada, quien sepa la direccion de la API llega igual.
    #
    # Quien SI puede quitarlo es quien puede aprobarlo (el permiso
    # 'aprobar-dias'), porque cambiar de opinion sobre un dia que tu mismo
    # concediste es una decision legitima, y porque si no lo pudiera tocar
    # nadie la unica salida seria editar la base de datos a mano.
    puede_tocar_aprobados = _puede(user, "aprobar-dias")
    protegidos = {}
    if not puede_tocar_aprobados and items:
        fechas = sorted({str(it.get("date") or "")[:10] for it in items if it.get("date")})
        conductores = sorted({it.get("driver_id") for it in items if it.get("driver_id")})
        if fechas and conductores:
            cur = db.shift_requests.find(
                {"status": "aprobado", "driver_id": {"$in": conductores},
                 "date": {"$gte": fechas[0], "$lte": fechas[-1]}},
                {"_id": 0, "driver_id": 1, "date": 1, "type": 1, "driver_name": 1})
            async for r in cur:
                protegidos[f"{r['driver_id']}|{r['date']}"] = r

    saved, bloqueados = 0, []
    for it in items:
        did = it.get("driver_id")
        date = it.get("date")
        center = it.get("center")
        typ = it.get("type")
        if not (did and date and center and typ in VALID_SHIFT_TYPE):
            continue
        # El codigo que se pinto en la rejilla. Se comprueba contra el mapa: si
        # no cuadra con el tipo, manda el codigo, porque es lo que se vio al
        # pintarlo. Sin codigo se guarda igual —turnos viejos y la app movil no
        # lo mandan— y la pantalla cae al color generico del tipo.
        cod = str(it.get("cod") or "").strip().upper()[:20]
        if cod and cod in mapa_cod and mapa_cod[cod]:
            typ = mapa_cod[cod]
        # Lo que se bloquea es el cambio que HACE DANO, no cualquier cambio.
        #
        # Comparar el codigo exacto ('N/T APROB') parecia lo obvio y era un
        # falso positivo garantizado: los turnos guardados antes de que se
        # empezara a guardar el codigo no lo tienen, asi que llegan como 'N/T'
        # y se habrian rechazado todos — la pantalla acusando de pisar dias
        # aprobados a quien solo estaba guardando el cuadrante sin tocarlos.
        #
        # Lo unico que no puede pasar es que un dia libre concedido se
        # convierta en dia de trabajo (o al reves con un extra concedido). Que
        # la celda ponga 'N/T' o 'N/T APROB' es cosmetico; que esa persona
        # aparezca puesta a ruta el dia que le diste libre, no.
        prot = protegidos.get(f"{did}|{date}")
        if prot is not None:
            aprobado = prot.get("type")
            rompe = ((aprobado == "libre" and typ in ("trabaja", "extra"))
                     or (aprobado == "extra" and typ == "libre"))
            if rompe:
                bloqueados.append({"driver_name": prot.get("driver_name") or "",
                                   "date": date, "type": aprobado})
                continue
        # Un turno de otro centro se ignora en silencio pero se deja anotado:
        # el cuadrante se envía entero desde la pantalla, y un 403 a mitad
        # dejaría la mitad guardada y la otra mitad no.
        if not _user_can_see_center(user, center):
            logger.warning("Turnos: %s intentó guardar en %s, sin acceso", user.get("name"), center)
            continue
        campos = {"driver_id": did, "driver_name": it.get("driver_name", ""),
                  "center": center, "date": date, "type": typ}
        # Lo que no viene se QUITA, no se guarda a vacio: si una celda que era
        # "V (05:43)" se repinta como "1", esa hora ya no significa nada y
        # dejarla ahi seria mentira. Y un campo no puede ir en $set y $unset a
        # la vez: Mongo rechaza la operacion entera y no se guardaria ni un
        # turno.
        cambio, quitar = {"$set": campos}, {}
        hora = str(it.get("hora") or "").strip()[:5]
        for clave, valor in (("cod", cod), ("hora", hora)):
            if valor:
                campos[clave] = valor
            else:
                quitar[clave] = ""
        if quitar:
            cambio["$unset"] = quitar
        await _upsert_turno({"driver_id": did, "date": date}, cambio)
        saved += 1
    if bloqueados:
        logger.info("Turnos: %s intento cambiar %d dias aprobados sin permiso",
                    user.get("name"), len(bloqueados))
    return {"success": True, "saved": saved, "bloqueados": bloqueados[:20],
            "n_bloqueados": len(bloqueados)}


@api_router.get("/shifts/coverage")
async def get_coverage(center: str, desde: str, hasta: str, _=Depends(require_admin)):
    """Nº de conductores disponibles (trabaja+extra) por día en el rango."""
    cur = db.shifts.find(
        {"center": center, "date": {"$gte": desde, "$lte": hasta}, **_FILTRO_RUTA},
        {"_id": 0, "date": 1},
    )
    counts: dict = {}
    async for s in cur:
        counts[s["date"]] = counts.get(s["date"], 0) + 1
    return {"coverage": counts, "min": await _min_cobertura(center)}


@api_router.post("/shifts/settings")
async def set_shift_settings(data: dict = Body(...), _=Depends(require_admin)):
    center = data.get("center")
    mn = data.get("min_cobertura")
    if not center or not isinstance(mn, int):
        raise HTTPException(status_code=400, detail="center y min_cobertura (int) requeridos")
    await db.shift_settings.update_one(
        {"center": center}, {"$set": {"center": center, "min_cobertura": mn}}, upsert=True
    )
    return {"success": True}


@api_router.get("/shifts/mine")
async def get_my_shifts(desde: Optional[str] = None, hasta: Optional[str] = None,
                        user: dict = Depends(require_any_auth)):
    """Calendario propio del conductor: sus turnos + sus solicitudes."""
    did = user.get("sub")
    q = {"driver_id": did}
    if desde or hasta:
        rng = {}
        if desde:
            rng["$gte"] = desde
        if hasta:
            rng["$lte"] = hasta
        q["date"] = rng
    shifts = await db.shifts.find(q, {"_id": 0}).to_list(2000)
    reqs = await db.shift_requests.find(
        {"driver_id": did}, {"_id": 0}
    ).sort("date", 1).to_list(500)
    # Respuestas que todavía no ha leído. Van aparte para que la pantalla
    # pueda enseñarlas arriba del todo sin que el conductor tenga que ir a
    # buscarlas entre las suyas.
    sin_ver = [r for r in reqs
               if r.get("status") in ("aprobado", "rechazado") and not r.get("visto_at")]
    return {"shifts": shifts, "requests": reqs, "sin_ver": sin_ver}




# ─── BLOQUEAR LA PETICIÓN DE DÍAS ────────────────────────────────────────────
#
# Hay semanas en las que no se puede dar ni un día: pico de volumen, Navidad,
# Prime Day. Hasta ahora la única forma de gestionarlo era dejar que pidieran y
# rechazar uno por uno, que es trabajo para la oficina y un "no" para el
# conductor después de haberse hecho ilusiones.
#
# Un bloqueo dice ANTES que ese día no se puede pedir, y dice por qué. El
# conductor lo ve en su calendario y no lo marca siquiera.
#
# DOS ALCANCES, y la diferencia importa:
#   · de centro  → afecta a toda la nave.
#   · de persona → sólo a ese conductor. Sirve para el que ya ha gastado sus
#     días, o para quien está en un plan de mejora.
#
# Lo que NO hace: tocar las peticiones ya hechas. Un bloqueo puesto hoy no
# rechaza lo que se pidió ayer — eso sigue decidiéndolo una persona. Bloquear
# hacia atrás sería cambiarle a alguien una respuesta que ya estaba dada.


def _bloqueo_doc(b: dict) -> dict:
    return {
        "id": b.get("id") or str(uuid.uuid4()),
        "center": (b.get("center") or "").strip(),
        "driver_id": (b.get("driver_id") or "").strip() or None,
        "desde": (b.get("desde") or "").strip(),
        "hasta": (b.get("hasta") or "").strip(),
        "motivo": (b.get("motivo") or "").strip()[:200],
        "creado_por": b.get("creado_por"),
        "creado_en": b.get("creado_en") or datetime.now(timezone.utc).isoformat(),
    }


async def _bloqueos_que_afectan(driver_id: str, center: str, fechas: list) -> list:
    """Los bloqueos que pisan alguna de esas fechas para ese conductor."""
    if not fechas:
        return []
    docs = await db.shift_blocks.find(
        {"$and": [
            {"$or": [{"center": {"$regex": re.escape((center or "")[:4]), "$options": "i"}},
                     {"center": ""}]},
            {"$or": [{"driver_id": None}, {"driver_id": driver_id}]},
            {"desde": {"$lte": max(fechas)}},
            {"hasta": {"$gte": min(fechas)}},
        ]}, {"_id": 0}).to_list(200)
    fuera = []
    for b in docs:
        pisadas = [f for f in fechas if b["desde"] <= f <= b["hasta"]]
        if pisadas:
            fuera.append({**b, "dias_afectados": sorted(pisadas)})
    return fuera


@api_router.get("/shift-blocks")
async def listar_bloqueos(center: str = "", admin: dict = Depends(require_admin)):
    """Los bloqueos vigentes. Cada uno con a quién afecta."""
    q = {}
    if center and center not in ("Todos", "todos"):
        q["center"] = {"$regex": re.escape(center.strip()), "$options": "i"}
    docs = await db.shift_blocks.find(q, {"_id": 0}).sort("desde", 1).to_list(500)
    # Sólo los de los centros que este admin puede ver: un bloqueo de otra nave
    # no es asunto suyo, igual que sus peticiones.
    docs = [d for d in docs if _user_can_see_center(admin, d.get("center") or "")]
    ids = [d["driver_id"] for d in docs if d.get("driver_id")]
    nombres = {}
    if ids:
        nombres = {d["id"]: d.get("name", "") for d in await db.drivers.find(
            {"id": {"$in": ids}}, {"_id": 0, "id": 1, "name": 1}).to_list(500)}
    for d in docs:
        d["driver_name"] = nombres.get(d.get("driver_id")) if d.get("driver_id") else None
    return {"bloqueos": docs, "total": len(docs)}


@api_router.post("/shift-blocks")
async def crear_bloqueo(data: dict = Body(...), admin: dict = Depends(require_admin)):
    """Bloquea un rango de días. body: {center, desde, hasta, motivo, driver_id?}

    El motivo es obligatorio y lo lee el conductor. Un bloqueo sin explicación
    es un "no" sin cara: manda a preguntar por WhatsApp, que es lo que este
    módulo viene a quitar.
    """
    if not _puede(admin, "aprobar-dias"):
        raise HTTPException(status_code=403,
                            detail="No tienes permiso para bloquear días")
    b = _bloqueo_doc({**data, "creado_por": admin.get("name", "admin")})
    if not b["center"]:
        raise HTTPException(400, "Falta el centro")
    if not _user_can_see_center(admin, b["center"]):
        raise HTTPException(403, "Ese centro no es tuyo")
    for campo in ("desde", "hasta"):
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", b[campo] or ""):
            raise HTTPException(400, f"{campo} va en formato AAAA-MM-DD")
    if b["hasta"] < b["desde"]:
        raise HTTPException(400, "La fecha de fin es anterior a la de inicio")
    if len(b["motivo"]) < 4:
        raise HTTPException(400, "Escribe el motivo: lo va a leer el conductor")
    if b["driver_id"]:
        existe = await db.drivers.find_one({"id": b["driver_id"]}, {"_id": 0, "id": 1})
        if not existe:
            raise HTTPException(404, "Ese conductor no existe")
    await db.shift_blocks.insert_one(dict(b))
    logger.info("Bloqueo de dias: %s %s..%s (%s)", b["center"], b["desde"], b["hasta"],
                b["driver_id"] or "todo el centro")
    return {"success": True, "bloqueo": b}


@api_router.delete("/shift-blocks/{block_id}")
async def borrar_bloqueo(block_id: str, admin: dict = Depends(require_admin)):
    if not _puede(admin, "aprobar-dias"):
        raise HTTPException(status_code=403, detail="No tienes permiso")
    b = await db.shift_blocks.find_one({"id": block_id}, {"_id": 0})
    if not b:
        raise HTTPException(404, "Ese bloqueo ya no existe")
    if not _user_can_see_center(admin, b.get("center") or ""):
        raise HTTPException(403, "Ese bloqueo es de otro centro")
    await db.shift_blocks.delete_one({"id": block_id})
    return {"success": True}


@api_router.get("/shift-blocks/mios")
async def bloqueos_del_conductor(user: dict = Depends(get_current_user)):
    """Para el portal: qué días NO puede pedir, y por qué.

    Se devuelven los rangos tal cual, no día a día: la pantalla los pinta y
    enseña el motivo al tocarlos. Sólo de hoy en adelante — los de antes ya no
    le sirven para nada.
    """
    if user.get("role") != "driver":
        raise HTTPException(status_code=403, detail="Solo conductores")
    did = user["sub"]
    drv = await db.drivers.find_one({"id": did}, {"_id": 0, "center": 1, "email": 1, "id": 1})
    # Sus otras fichas cuentan igual: si esta duplicado, un bloqueo puesto sobre
    # la otra ficha tiene que valerle (gotcha 15).
    mis_ids, centro = await _fichas_misma_persona(drv or {"id": did})
    hoy = _dia_negocio()
    docs = await db.shift_blocks.find(
        {"hasta": {"$gte": hoy},
         "$or": [{"driver_id": None}, {"driver_id": {"$in": list(mis_ids)}}]},
        {"_id": 0}).sort("desde", 1).to_list(200)
    if centro:
        docs = [d for d in docs
                if not d.get("center")
                or re.search(re.escape(centro[:4]), d.get("center") or "", re.I)]
    return {"bloqueos": docs}


@api_router.post("/shift-requests/vistas")
async def marcar_respuestas_vistas(data: dict = Body(default={}),
                                   user: dict = Depends(require_any_auth)):
    """El conductor ha leído las respuestas: dejan de salir como novedad.

    Se marcan sólo las SUYAS y sólo las ya resueltas, y se pasa por `grupo` o
    por lista de ids para no borrar el aviso de una respuesta que no ha visto.
    """
    q = {"driver_id": user.get("sub"), "status": {"$in": ["aprobado", "rechazado"]},
         "visto_at": None}
    if data.get("grupo"):
        q["grupo"] = str(data["grupo"])
    elif data.get("ids"):
        q["id"] = {"$in": [str(x) for x in data["ids"]][:200]}
    r = await db.shift_requests.update_many(
        q, {"$set": {"visto_at": datetime.now(timezone.utc).isoformat()}})
    return {"ok": True, "marcadas": r.modified_count}


@api_router.post("/shift-requests")
async def create_shift_request(data: dict = Body(...), user: dict = Depends(require_any_auth)):
    """El conductor pide uno o varios días.

    Se manda `dates: ["YYYY-MM-DD", ...]` y se guarda UNA FILA POR DÍA, todas
    con el mismo `grupo`. Así la oficina lo ve como una sola petición ("Razavi,
    3 días") pero cada día sigue siendo su propio registro — que es lo que hace
    falta para poder aprobar unos días sí y otros no, y para que el día
    aprobado pueda ir al cuadrante por su cuenta.

    Se acepta `date` suelto por compatibilidad con la pantalla antigua.

    NADA se auto-aprueba. El cuadrante lo lleva la oficina, y una aprobación
    automática calculada sobre un cuadrante que puede no estar cargado sería
    exactamente el falso positivo que no se quiere: aprobar por no tener datos.
    """
    dates = data.get("dates") or ([data["date"]] if data.get("date") else [])
    typ = data.get("type", "libre")
    if typ not in {"libre", "extra"}:
        raise HTTPException(status_code=400, detail="type debe ser libre o extra")
    vistas, limpias = set(), []
    for d in dates:
        s = str(d)[:10]
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", s):
            raise HTTPException(status_code=400, detail=f"Fecha no válida: {d}")
        if s not in vistas:
            vistas.add(s); limpias.append(s)
    if not limpias:
        raise HTTPException(status_code=400, detail="Marca al menos un día")
    if len(limpias) > 31:
        raise HTTPException(status_code=400, detail="Demasiados días en una sola petición (máx. 31)")

    motivo = data.get("motivo") or "otro"
    if motivo not in MOTIVOS_PETICION:
        raise HTTPException(status_code=400, detail="Motivo no válido")

    # LA EXPLICACION ES OBLIGATORIA, y se exige AQUI ademas de en la pantalla.
    # Comprobarlo solo en el navegador no es exigirlo: una pestaña vieja abierta
    # de antes, o una llamada a mano, entrarian igual. El motivo de la chapa dice
    # la categoria ("Asuntos propios"); esto dice el caso, que es lo que necesita
    # quien tiene que decidir. Sin ello la oficina acaba preguntando por
    # WhatsApp, que es la conversacion que este modulo venia a quitar.
    nota = (data.get("note") or data.get("nota") or "").strip()
    if len(nota) < 4:
        raise HTTPException(
            status_code=400,
            detail="Cuenta un poco de qué va: quien lo aprueba necesita saberlo")

    did = user.get("sub")
    drv = await db.drivers.find_one({"id": did}, {"_id": 0, "name": 1, "center": 1})
    if not drv:
        raise HTTPException(status_code=404, detail="Conductor no encontrado")

    # DIAS BLOQUEADOS: se comprueba AQUI, que es donde se decide de verdad.
    # La pantalla ya no los deja marcar, pero una pestaña abierta de antes del
    # bloqueo, o una llamada a mano, entrarian igual.
    choques = await _bloqueos_que_afectan(did, drv.get("center") or "", limpias)
    if choques:
        b = choques[0]
        dias = ", ".join(b["dias_afectados"][:5])
        raise HTTPException(
            status_code=409,
            detail=f"Esos dias estan bloqueados ({dias}): {b.get('motivo') or 'sin motivo'}")

    # Un día ya pedido y sin resolver no se pide dos veces: si no, la oficina
    # ve la misma petición repetida y no sabe cuál contestar.
    ya = await db.shift_requests.distinct(
        "date", {"driver_id": did, "date": {"$in": limpias}, "status": "pendiente"})
    nuevas = [d for d in limpias if d not in ya]
    if not nuevas:
        raise HTTPException(status_code=409, detail="Ya has pedido esos días y están sin contestar")

    grupo = str(uuid.uuid4())
    ahora = datetime.now(timezone.utc).isoformat()
    filas = [{
        "id": str(uuid.uuid4()), "grupo": grupo, "center": drv.get("center"),
        "driver_id": did, "driver_name": drv.get("name", ""),
        "date": d, "type": typ, "status": "pendiente",
        "motivo": motivo, "motivo_label": MOTIVOS_PETICION[motivo],
        "note": (data.get("note") or "").strip()[:300],
        "created_at": ahora, "resolved_by": None, "resolved_at": None,
    } for d in nuevas]
    await db.shift_requests.insert_many([dict(f) for f in filas])

    # Que la oficina se entere sin tener que estar mirando la pantalla.
    try:
        await push_center_event(
            drv.get("center") or "",
            f"📅 {drv.get('name', 'Un conductor')} pide {len(nuevas)} día{'s' if len(nuevas) > 1 else ''}",
            f"{MOTIVOS_PETICION[motivo]} · {', '.join(nuevas[:4])}",
            "/panel/turnos")
    except Exception as e:
        logger.debug("Push petición de días: %s", e)

    for f in filas:
        f.pop("_id", None)
    return {"success": True, "grupo": grupo, "dias": nuevas,
            "ignorados": [d for d in limpias if d in ya], "requests": filas}


@api_router.get("/shift-requests/pendientes")
async def contar_peticiones_pendientes(center: Optional[str] = None,
                                       user: dict = Depends(require_admin)):
    """Cuantas peticiones de dias estan sin contestar. Para el aviso del menu.

    SE CUENTAN PETICIONES, NO DIAS. En la base hay un documento POR DIA, pero
    el conductor las pidio de golpe y en pantalla salen como una sola fila:
    "4 dias, del 16 al 19". Contando documentos, siete peticiones de verdad
    daban 17 y el numero del menu no cuadraba con lo que se ve — pasó, y el
    aviso deja de servir en cuanto no coincide con la pantalla.

    La clave del grupo es `grupo`, y `id` cuando falta: exactamente la misma
    que usa la pantalla para juntar las filas. Si se cambia alli, hay que
    cambiarla aqui.

    Tampoco son personas: dos conductores con tres peticiones entre los dos son
    3, porque hay que contestar tres veces. `personas` va aparte por si alguna
    pantalla quiere decir "2 personas, 3 peticiones".

    Endpoint propio y no `/shift-requests?status=pendiente` porque esto lo pide
    el menu cada dos minutos en TODAS las pantallas: la lista devuelve hasta
    mil documentos enteros —con nombre y motivo— para acabar mirando su
    longitud. Aqui lo cuenta Mongo y viajan dos numeros.

    OJO AL ORDEN: va declarado ANTES que cualquier `/shift-requests/{algo}`.
    FastAPI casa por orden de declaracion y, puesto despues, la palabra
    'pendientes' entraria como si fuera un id (gotcha del /work-orders/export).
    """
    filtro = dict(_filtro_centro(user, center))
    filtro["status"] = "pendiente"
    filas = await db.shift_requests.aggregate([
        {"$match": filtro},
        {"$group": {"_id": {"$ifNull": ["$grupo", "$id"]},
                    "conductor": {"$first": "$driver_id"}}},
        {"$group": {"_id": None, "peticiones": {"$sum": 1},
                    "personas": {"$addToSet": "$conductor"}}},
    ]).to_list(1)
    if not filas:
        return {"pendientes": 0, "personas": 0, "dias": 0}
    r = filas[0]
    return {"pendientes": r["peticiones"],
            "personas": len([p for p in r["personas"] if p]),
            # Los dias sueltos, por si hacen falta: es el numero de documentos.
            "dias": await db.shift_requests.count_documents(filtro)}


@api_router.get("/shift-requests")
async def list_shift_requests(center: Optional[str] = None, status: Optional[str] = None,
                              desde: Optional[str] = None, hasta: Optional[str] = None,
                              driver_id: Optional[str] = None, q: Optional[str] = None,
                              limit: int = 1000,
                              user: dict = Depends(require_admin)):
    """Las peticiones de dias. Sirve para la bandeja y para el historial.

    `status` admite varios separados por coma ("aprobado,rechazado"), y hay
    rango de fechas, conductor y busqueda por nombre: sin eso, el historial de
    un ano son mil filas y encontrar "cuando le di el dia a Estela" es
    imposible.
    """
    # Igual que el cuadrante: sin filtro por centro, quien lleva un centro veía
    # las peticiones de días de TODA la empresa, con nombre y motivo.
    filtro = dict(_filtro_centro(user, center))
    if status:
        estados = [s.strip() for s in str(status).split(",") if s.strip()]
        filtro["status"] = estados[0] if len(estados) == 1 else {"$in": estados}
    if desde or hasta:
        rango = {}
        if desde:
            rango["$gte"] = str(desde)[:10]
        if hasta:
            rango["$lte"] = str(hasta)[:10]
        filtro["date"] = rango
    if driver_id:
        filtro["driver_id"] = driver_id
    if q:
        # Escapado: un nombre con un parentesis no puede tumbar la consulta.
        filtro["driver_name"] = {"$regex": re.escape(str(q).strip()), "$options": "i"}
    reqs = await db.shift_requests.find(filtro, {"_id": 0}).sort(
        "date", -1).to_list(max(1, min(int(limit or 1000), 3000)))
    return {"requests": reqs}


@api_router.post("/shift-requests/{req_id}/resolve")
async def resolve_shift_request(req_id: str, data: dict = Body(...),
                                admin: dict = Depends(require_admin)):
    """Aprobar o rechazar. body: {action: aprobar|rechazar, motivo}

    Rechazar EXIGE motivo. Un "no" a secas manda al conductor a preguntar por
    WhatsApp por qué, y la discusión vuelve al sitio del que se la quería sacar
    — que es el problema entero que resuelve tener esto por escrito.
    """
    action = data.get("action")
    if action not in {"aprobar", "rechazar"}:
        raise HTTPException(status_code=400, detail="action debe ser aprobar|rechazar")
    req = await db.shift_requests.find_one({"id": req_id}, {"_id": 0})
    if not req:
        raise HTTPException(status_code=404, detail="Solicitud no encontrada")
    if not _user_can_see_center(admin, req.get("center") or ""):
        raise HTTPException(status_code=403, detail="Esa petición es de otro centro")
    # Ver las peticiones lo puede hacer cualquiera del centro; DECIDIR no.
    if not _puede(admin, "aprobar-dias"):
        raise HTTPException(status_code=403,
                            detail="No tienes permiso para aprobar o rechazar días")
    motivo = (data.get("motivo") or "").strip()[:300]
    if action == "rechazar" and len(motivo) < 3:
        raise HTTPException(status_code=400,
                            detail="Para rechazar hay que escribir el motivo: lo va a leer el conductor")
    new_status = "aprobado" if action == "aprobar" else "rechazado"
    await db.shift_requests.update_one(
        {"id": req_id},
        # `resolved_at` faltaba: se guardaba QUIÉN contestó pero no CUÁNDO, así
        # que "¿cuándo me dijiste que no?" no tenía respuesta.
        # `visto_at: None` = el conductor todavía no ha leído la respuesta. El
        # push puede no llegar (avisos desactivados, iOS, móvil apagado), así
        # que la respuesta TAMBIÉN espera dentro de la app hasta que la abra.
        # Fiar el aviso sólo al push sería fiarlo a algo que falla en silencio.
        {"$set": {"status": new_status, "resolved_by": admin.get("name", "admin"),
                  "resolved_at": datetime.now(timezone.utc).isoformat(),
                  "motivo_respuesta": motivo or None, "visto_at": None}},
    )
    # Que se entere: si la respuesta no llega, el conductor vuelve a preguntar
    # de palabra y no hemos arreglado nada.
    try:
        await send_web_push_to_users(
            [req["driver_id"]],
            f"Tu petición del {req['date']}: {'aprobada' if new_status == 'aprobado' else 'rechazada'}",
            motivo or ("Ya puedes verlo en tus turnos." if new_status == "aprobado" else ""),
            # Al CONDUCTOR se le manda a SU portal. Estaba apuntando a
            # /panel/portal-conductor, que es la pantalla de administracion:
            # tocar el aviso le llevaba a un sitio donde no puede entrar.
            "/conductor")
    except Exception as e:
        logger.debug("Push respuesta petición: %s", e)
    if new_status == "aprobado":
        # Entra en el cuadrante en el acto, y con el CODIGO que le corresponde.
        # Sin `cod` la celda caia en el 'N/T' generico y en la rejilla no habia
        # forma de distinguir "libra porque toca" de "libra porque se lo
        # aprobaste" — que es justo lo que no se puede confundir, porque lo
        # segundo no se puede cambiar sin hablar con la persona.
        cod = "N/T APROB" if req["type"] == "libre" else "EXTRA"
        await _upsert_turno(
            {"driver_id": req["driver_id"], "date": req["date"]},
            {"$set": {"driver_id": req["driver_id"], "driver_name": req.get("driver_name", ""),
                      "center": req["center"], "date": req["date"], "type": req["type"],
                      "cod": cod, "aprobado_req": req_id},
             "$unset": {"hora": ""}},
        )
    elif req.get("status") == "aprobado":
        # Se ha desaprobado algo que ya estaba aprobado: la marca del cuadrante
        # tiene que irse con ello, o la celda seguiria bloqueada para siempre.
        await db.shifts.update_one(
            {"driver_id": req["driver_id"], "date": req["date"], "aprobado_req": req_id},
            {"$unset": {"aprobado_req": ""}},
        )
    return {"success": True, "status": new_status}




# ─── IMPORTAR EL CUADRANTE PEGÁNDOLO DESDE SHEETS ────────────────────────────
#
# El importador de Excel funciona, pero depende de que el fichero tenga la fila
# de días de la semana justo encima de la cabecera y la columna del nombre donde
# toca. Cuando el fichero no es exactamente ése —y en una nave real nunca lo
# es— falla o se deja filas por el camino.
#
# Pegar es más tosco y por eso más fiable: se selecciona el bloque en Sheets,
# se copia, se pega. Lo que se ve es lo que entra. Sin macros, sin formatos y
# sin que importe dónde esté cada cosa en el fichero original.
#
# ── LO QUE DE VERDAD FALLA AL IMPORTAR: LOS NOMBRES ──────────────────────────
# Medido con el cuadrante de agosto: el fichero traía 61 conductores y se
# guardaron 47. Los otros 14 se cayeron porque su nombre en el Sheets no es
# exactamente el de su ficha. Y con 17 personas dadas de alta dos veces y 26
# nombres con espacios de más (gotcha 15), eso va a pasar TODOS los meses.
#
# Por eso los alias: cuando dices una vez que "ROJAS PEREZ, SERGIO L." es
# Sergio Luis Rojas Pérez, queda guardado y el mes que viene entra solo.

_ALIAS_DOC = "alias_nombres_cuadrante"


async def _alias_cuadrante() -> dict:
    """Nombre tal y como viene en el cuadrante → id del conductor."""
    doc = await db.app_meta.find_one({"_id": _ALIAS_DOC}) or {}
    return {k: v for k, v in (doc.get("mapa") or {}).items() if v}


def _celdas_pegadas(texto: str) -> list:
    """Convierte lo pegado en una rejilla.

    Sheets y Excel copian con TABULADOR entre columnas. Se admite también el
    punto y coma por si alguien pega desde un CSV exportado a la española.
    """
    filas = []
    for linea in str(texto or "").replace("\r\n", "\n").replace("\r", "\n").split("\n"):
        if not linea.strip():
            continue
        sep = "\t" if "\t" in linea else (";" if linea.count(";") >= 3 else "\t")
        filas.append([c.strip() for c in linea.split(sep)])
    return filas


def _rejilla_pegada(filas: list) -> tuple:
    """Se orienta sola dentro de lo pegado. Devuelve (col_nombre, {col: dia}, i_datos).

    NO se puede dar por hecho que la primera celda sea el nombre. El cuadrante
    real de OGA5 tiene DOS columnas antes —'Orden' y 'Nombre'— y DOS filas de
    cabecera: una con los días de la semana y otra con los números del día. Al
    suponer que la primera celda era el nombre, se leían los números de orden
    ('1', '2', '3'…) como si fueran personas: 62 nombres sin encontrar y cero
    turnos guardados.

    La pista buena es la FILA DE NÚMEROS DE DÍA: es la única que tiene una
    tirada larga de enteros del 1 al 31 subiendo. De ella salen dos cosas:

      · dónde empieza el bloque de días, y por tanto dónde está el nombre
        (la última celda con texto justo antes);
      · QUÉ DÍA es cada columna. Esto es mejor que contar posiciones: si se pega
        media hoja, del 10 al 20, los números lo dicen y no hay que adivinarlo.
    """
    mejor = None
    for i, fila in enumerate(filas[:8]):        # la cabecera está arriba
        seguidos, ini = [], None
        for j, c in enumerate(fila):
            txt = str(c or "").strip()
            if txt.isdigit() and 1 <= int(txt) <= 31:
                n = int(txt)
                if seguidos and n == seguidos[-1][1] + 1:
                    seguidos.append((j, n))
                else:
                    if len(seguidos) >= 5:
                        break
                    seguidos, ini = [(j, n)], j
            elif seguidos:
                if len(seguidos) >= 5:
                    break
                seguidos, ini = [], None
        if len(seguidos) >= 5 and (mejor is None or len(seguidos) > len(mejor[1])):
            mejor = (i, seguidos)
    if not mejor:
        return None, None, None

    i_num, seguidos = mejor
    cols_dia = {j: n for j, n in seguidos}
    primera_col = min(cols_dia)

    # El nombre: la cabecera que ponga "NOMBRE", y si no, la última celda con
    # texto antes del bloque de días.
    col_nombre = None
    for fila in filas[:i_num + 1]:
        for j in range(min(primera_col, len(fila))):
            if "NOMBRE" in _sin_tildes(str(fila[j] or "")).upper():
                col_nombre = j
                break
        if col_nombre is not None:
            break
    if col_nombre is None:
        col_nombre = primera_col - 1 if primera_col > 0 else 0

    return col_nombre, cols_dia, i_num + 1


@api_router.post("/shifts/import-pegado")
async def import_shifts_pegado(data: dict = Body(...), _=Depends(require_admin)):
    """Importa el cuadrante pegado desde Sheets. body: {center, mes, texto, confirmar}

    Cada línea es un conductor: la primera celda es el nombre y las siguientes
    son los días 1, 2, 3… del mes, en orden.

    Si la primera línea son días de la semana (LUN, MAR…) se usa para COMPROBAR
    que el bloque empieza donde dice el mes elegido, igual que hace el
    importador de Excel. Si no viene, se avisa de que no se ha podido comprobar
    en vez de callarlo: un cuadrante corrido un día es peor que ninguno.

    Un mes a medias es legítimo — el cuadrante de agosto estaba relleno sólo
    hasta el día 23 — así que no se exige el mes entero. Lo que no se admite es
    pasarse de los días que tiene el mes.
    """
    center = (data.get("center") or "").strip()
    mes = (data.get("mes") or "").strip()
    confirmar = bool(data.get("confirmar"))
    if not center:
        raise HTTPException(400, "Falta el centro")
    m = re.fullmatch(r"(\d{4})-(\d{2})", mes)
    if not m:
        raise HTTPException(400, "El mes va como AAAA-MM")
    anio, mesn = int(m.group(1)), int(m.group(2))
    if not (1 <= mesn <= 12):
        raise HTTPException(400, "Mes fuera de rango")

    filas = _celdas_pegadas(data.get("texto"))
    if len(filas) < 2:
        raise HTTPException(400, "Pega al menos la cabecera y una fila de conductor")

    dias_mes = calendar.monthrange(anio, mesn)[1]

    col_nombre, cols_dia, i_datos = _rejilla_pegada(filas)
    if not cols_dia:
        raise HTTPException(400,
            "No encuentro la fila con los números de los días (1, 2, 3…). "
            "Copia también las cabeceras de tu hoja, no sólo las filas de gente.")
    fuera_de_mes = [n for n in cols_dia.values() if n > dias_mes]
    if fuera_de_mes:
        raise HTTPException(400,
            f"Lo pegado llega al día {max(fuera_de_mes)} y {mes} sólo tiene {dias_mes}.")

    # ── LA COMPROBACIÓN QUE EVITA EL DESASTRE ───────────────────────────────
    # Con los números de día ya no hace falta adivinar dónde empieza nada. Lo
    # que sí se comprueba, si la hoja trae la fila de días de la semana, es que
    # el mes elegido sea el del cuadrante: 'sáb' encima del día 1 sólo cuadra
    # con los meses que empiezan en sábado. Cuadrar 20 columnas por casualidad
    # es imposible, así que un fallo aquí es que el mes está mal.
    DOW = {"LUN": 0, "MAR": 1, "MIE": 2, "MIER": 2, "JUE": 3, "VIE": 4,
           "SAB": 5, "DOM": 6, "X": 2}
    aviso_alineacion = None
    fila_dow = None
    for fila in filas[:i_datos]:
        etiquetas = [_sin_tildes(str(c or "")).strip().rstrip(".").upper() for c in fila]
        if sum(1 for e in etiquetas if e in DOW) >= 5:
            fila_dow = etiquetas
            break
    if fila_dow:
        MESES = ["", "enero", "febrero", "marzo", "abril", "mayo", "junio", "julio",
                 "agosto", "septiembre", "octubre", "noviembre", "diciembre"]
        DIAS_SEM = ["lunes", "martes", "miércoles", "jueves", "viernes", "sábado", "domingo"]
        fallos = []
        for j, n in sorted(cols_dia.items()):
            etq = fila_dow[j] if j < len(fila_dow) else ""
            if etq in DOW and DOW[etq] != date_cls(anio, mesn, n).weekday():
                fallos.append((n, etq))
        if len(fallos) > 1:
            n, etq = fallos[0]
            raise HTTPException(400,
                f"En tu hoja el día {n} es {etq.lower()}, pero el {n} de "
                f"{MESES[mesn]} de {anio} cae en {DIAS_SEM[date_cls(anio, mesn, n).weekday()]}. "
                f"El mes elegido no es el de este cuadrante. No se ha guardado nada.")
    else:
        aviso_alineacion = ("No has pegado la fila de días de la semana (lun, mar…), así que "
                            "no he podido comprobar que el mes sea el correcto. Mira el "
                            "resumen antes de guardar.")

    doc = await db.app_meta.find_one({"_id": "codigos_cuadrante"}) or {}
    mapa = dict(CODIGOS_CUADRANTE_DEF)
    mapa.update({str(k).upper(): v for k, v in (doc.get("mapa") or {}).items()})

    # Se traen TAMBIEN los dados de baja. Hay 71 fichas con active=False de 202,
    # y varias son gente que sigue saliendo en el cuadrante: excluirlas hacia
    # desaparecer sus filas sin decir nada. Se encuentran, y se avisa.
    drivers = await db.drivers.find(
        {"center": {"$regex": re.escape(center), "$options": "i"}},
        {"_id": 0, "id": 1, "name": 1, "active": 1}).to_list(2000)
    por_nombre = {_clave_nombre(d.get("name")): d for d in drivers}
    por_id = {d["id"]: d for d in drivers}
    alias = await _alias_cuadrante()

    items, sin_conductor, sin_codigo, de_baja = [], [], {}, set()
    for fila in filas[i_datos:]:
        if not fila or col_nombre >= len(fila):
            continue
        nombre = (fila[col_nombre] or "").strip()
        # Una fila cuyo "nombre" es un número es la de totales o un resto de la
        # hoja, no una persona.
        if not nombre or nombre.isdigit():
            continue
        drv, motivo = _empareja_conductor(nombre, drivers, alias)
        if not drv:
            sin_conductor.append({"nombre": nombre, "motivo": motivo})
            continue
        if drv.get("active") is False:
            de_baja.add(drv["name"])
        for j, n in sorted(cols_dia.items()):
            crudo = fila[j] if j < len(fila) else None
            if crudo in (None, ""):
                continue
            cod, hora = _despieza_codigo(crudo)
            if cod not in mapa:
                sin_codigo[cod] = sin_codigo.get(cod, 0) + 1
                continue
            tipo = mapa[cod]
            if not tipo:
                continue
            it = {"driver_id": drv["id"], "driver_name": drv["name"],
                  "center": center, "date": f"{anio:04d}-{mesn:02d}-{n:02d}",
                  "type": tipo, "cod": cod}
            if hora:
                it["hora"] = hora
            items.append(it)

    dias_con_datos = sorted({i["date"] for i in items})
    resumen = {
        "mes": f"{anio:04d}-{mesn:02d}", "center": center,
        "dias": len(dias_con_datos),
        "primer_dia": dias_con_datos[0] if dias_con_datos else None,
        "ultimo_dia": dias_con_datos[-1] if dias_con_datos else None,
        "conductores": len({i["driver_id"] for i in items}),
        "turnos": len(items),
        "trabaja": sum(1 for i in items if i["type"] == "trabaja"),
        "libre": sum(1 for i in items if i["type"] == "libre"),
        "extra": sum(1 for i in items if i["type"] == "extra"),
        "sin_conductor": sin_conductor[:60],
        "n_sin_conductor": len(sin_conductor),
        "de_baja": sorted(de_baja),
        "codigos_desconocidos": dict(sorted(sin_codigo.items(), key=lambda x: -x[1])),
        "guardado": False,
    }
    if aviso_alineacion:
        resumen["aviso_alineacion"] = aviso_alineacion
    if sin_codigo and not confirmar:
        resumen["aviso"] = ("Hay códigos que no sé qué significan. Tradúcelos antes de "
                            "guardar, o confirma para importar sólo el resto.")
        return resumen
    if not confirmar:
        return resumen
    if not items:
        raise HTTPException(400, "No hay ni un turno que guardar")

    items, respetados = await _respeta_aprobados(items)

    guardados = 0
    for i in range(0, len(items), 500):
        lote = items[i:i + 500]
        await _bulk_turnos([
            UpdateOne({"driver_id": it["driver_id"], "date": it["date"]},
                      {"$set": it}, upsert=True) for it in lote])
        guardados += len(lote)
    resumen["guardado"] = True
    resumen["saved"] = guardados
    resumen["respetados"] = respetados[:30]
    resumen["n_respetados"] = len(respetados)
    logger.info("Cuadrante pegado: %s %s - %s turnos", center, resumen["mes"], guardados)
    return resumen


# Los mismos cinco colores de la pantalla, pero para papel blanco. En la app el
# fondo es oscuro y valen tintes translucidos; en Excel hay que dar el color
# opaco y un texto que se lea encima. Se mantienen las cinco familias: si aqui
# hubiera dieciseis colores, la hoja descargada seria justo el arcoiris del que
# se venia huyendo.
COLOR_FAMILIA_XLSX = {
    "ruta":     ("D6EAD7", "1E5B2A"),
    "apoyo":    ("D5EFEC", "12554E"),
    "libre":    ("F1F1EF", "72726C"),
    "previsto": ("DBEAF7", "12456F"),
    "aprobado": ("F8DCE8", "7A2447"),
    "aviso":    ("FADCDC", "8C1D1D"),
}
FAMILIA_NOMBRE_XLSX = {
    "ruta": "Sale a ruta", "apoyo": "Trabaja sin ruta", "libre": "Dia libre",
    "previsto": "Ausencia prevista", "aprobado": "Dia concedido (no se toca)",
    "aviso": "Ausencia no prevista",
}
DIAS_SEM_CORTO = ["lun", "mar", "mie", "jue", "vie", "sab", "dom"]
MESES_ES = ["", "enero", "febrero", "marzo", "abril", "mayo", "junio", "julio",
            "agosto", "septiembre", "octubre", "noviembre", "diciembre"]


@api_router.get("/shifts/export")
async def exportar_cuadrante(center: str, desde: str, hasta: str,
                             user: dict = Depends(require_admin)):
    """El cuadrante, en un .xlsx que se abre en Excel y en Sheets.

    Se genera aqui y no en el navegador a proposito: asi la hoja lleva colores,
    cabeceras congeladas y anchos de columna sin meter una libreria de Excel en
    el bundle del panel, y sale igual desde cualquier ordenador.

    Dos hojas:
      · "Cuadrante" — la rejilla tal cual se ve, para mirarla o imprimirla.
      · "Por conductor" — una fila por persona y dia. Es la que sirve para
        filtrar, ordenar o mandarle a alguien solo lo suyo; una rejilla no se
        puede filtrar.
    """
    import openpyxl, io as _io
    from openpyxl.styles import PatternFill, Font, Alignment, Border, Side
    from openpyxl.utils import get_column_letter
    from openpyxl.comments import Comment

    dias = _date_range(desde, hasta)

    q = dict(_filtro_centro(user, center))
    q["date"] = {"$gte": desde, "$lte": hasta}
    turnos = await db.shifts.find(q, {"_id": 0}).to_list(20000)

    dem = {d["date"]: d for d in await db.route_demand.find(
        {"center": center, "date": {"$gte": desde, "$lte": hasta}}, {"_id": 0}).to_list(400)}

    doc = await db.app_meta.find_one({"_id": "codigos_cuadrante"}) or {}
    mapa = dict(CODIGOS_CUADRANTE_DEF)
    mapa.update({str(k).upper(): v for k, v in (doc.get("mapa") or {}).items()})

    def info(cod):
        base = CODIGOS_CUADRANTE_INFO.get(cod)
        if base:
            return base[1], base[2]
        return cod, "libre"

    # Solo sale quien tenga algo puesto. Bajar una hoja con veinte filas vacias
    # de gente que ya no esta es exactamente el problema que se acaba de quitar
    # de la pantalla.
    por_id = {}
    for s in turnos:
        did = s.get("driver_id")
        if not did:
            continue
        f = por_id.setdefault(did, {"nombre": s.get("driver_name") or "", "dias": {}})
        cod = s.get("cod") or {"trabaja": "1", "libre": "N/T", "extra": "EXTRA"}.get(s.get("type"), "")
        f["dias"][s["date"]] = (cod, s.get("hora") or "")
        if s.get("driver_name"):
            f["nombre"] = s["driver_name"]
    filas = sorted(por_id.values(), key=lambda x: _clave_nombre(x["nombre"]))

    fino = Side(style="thin", color="D9D9D9")
    medio = Side(style="thin", color="9C9C9C")
    borde = Border(left=fino, right=fino, top=fino, bottom=fino)
    centro = Alignment(horizontal="center", vertical="center")

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "Cuadrante"

    d0 = datetime.strptime(dias[0], "%Y-%m-%d")
    ws.cell(row=1, column=1,
            value=f"Cuadrante {center} - {MESES_ES[d0.month]} de {d0.year}").font = Font(bold=True, size=14)
    ws.cell(row=1, column=3, value=f"{dias[0]} a {dias[-1]}").font = Font(color="808080", size=10)

    ws.cell(row=2, column=1, value="CONDUCTOR").font = Font(bold=True, size=9, color="606060")
    ws.cell(row=2, column=2, value="Dias").font = Font(bold=True, size=9, color="606060")
    for j, f in enumerate(dias):
        d = datetime.strptime(f, "%Y-%m-%d")
        finde = d.weekday() >= 5
        c1 = ws.cell(row=2, column=3 + j, value=DIAS_SEM_CORTO[d.weekday()])
        c1.font = Font(size=8, color="A00000" if finde else "808080")
        c1.alignment = centro
        if d.weekday() == 6:
            c1.border = Border(left=medio)
            ws.cell(row=3, column=3 + j).border = Border(left=medio)
        c2 = ws.cell(row=3, column=3 + j, value=d.day)
        c2.font = Font(bold=True, size=10, color="A00000" if finde else "303030")
        c2.alignment = centro
        if finde:
            for r in (2, 3):
                ws.cell(row=r, column=3 + j).fill = PatternFill("solid", fgColor="F2F2F2")
    ws.cell(row=3, column=1, value="Nombre").font = Font(bold=True, size=9, color="606060")

    for i, fila in enumerate(filas):
        r = 4 + i
        cn = ws.cell(row=r, column=1, value=fila["nombre"])
        cn.font = Font(size=10)
        cn.border = borde
        trabajados = sum(1 for cod, _ in fila["dias"].values()
                         if mapa.get(cod) in ("trabaja", "extra"))
        ct = ws.cell(row=r, column=2, value=trabajados)
        ct.font = Font(bold=True, size=10, color="606060")
        ct.alignment = centro
        ct.border = borde
        for j, f in enumerate(dias):
            cod, hora = fila["dias"].get(f, ("", ""))
            cel = ws.cell(row=r, column=3 + j, value=cod)
            cel.alignment = centro
            # Linea mas marcada donde empieza la semana. La semana de Amazon va
            # de DOMINGO a sabado: cortando en lunes, la raya cae en medio de
            # cada una de sus semanas y las cuentas no cuadran con las suyas.
            cel.border = (Border(left=medio, right=fino, top=fino, bottom=fino)
                          if datetime.strptime(f, "%Y-%m-%d").weekday() == 6 else borde)
            if cod:
                etiqueta, fam = info(cod)
                bg, fg = COLOR_FAMILIA_XLSX.get(fam, COLOR_FAMILIA_XLSX["libre"])
                cel.fill = PatternFill("solid", fgColor=bg)
                cel.font = Font(bold=True, size=9, color=fg)
                # La hora no cabe en la celda, pero no se tira: va al
                # comentario, que se ve al pasar por encima y no ensucia
                # la rejilla.
                if hora:
                    cel.comment = Comment(f"{etiqueta} - entra a las {hora}", "FlotaDSP")

    # Las tres cifras del dia, juntas y en el mismo orden que en la hoja de la
    # que sale esto. Solas no dicen nada: 39 personas es mucho o poco segun lo
    # que pidan, y no llegar al maximo comprometido es lo que hace que la
    # proxima vez no te ofrezcan rutas.
    rcob = 4 + len(filas) + 1
    cobs = []
    for j, f in enumerate(dias):
        n = sum(1 for fila in filas
                if fila["dias"].get(f, ("", ""))[0] in CODIGOS_QUE_SACAN_RUTA)
        cobs.append(n)

    for k, (titulo, saca, bg) in enumerate([
        ("Salen a ruta", lambda j, f: cobs[j], "DCEAF7"),
        ("Rutas que piden", lambda j, f: dem.get(f, {}).get("objetivo"), None),
        ("Maximas comprometidas", lambda j, f: dem.get(f, {}).get("maximo"), "FBE3C8"),
    ]):
        r = rcob + k
        ct = ws.cell(row=r, column=1, value=titulo)
        ct.font = Font(bold=True, size=9, color="606060")
        for j, f in enumerate(dias):
            v = saca(j, f)
            c = ws.cell(row=r, column=3 + j, value=v)
            c.font = Font(bold=True, size=10)
            c.alignment = centro
            c.border = Border(top=medio if k == 0 else fino,
                              bottom=medio if k == 2 else fino, left=fino, right=fino)
            if bg:
                c.fill = PatternFill("solid", fgColor=bg)
            # Rojo si ese dia no llegas a lo que piden: es una ruta sin cubrir.
            if k == 0:
                piden = dem.get(f, {}).get("objetivo")
                if piden is not None and cobs[j] < piden:
                    c.font = Font(bold=True, size=10, color="C00000")

    # Leyenda, por familias. Debajo de la tabla para que salga al imprimir.
    rl = rcob + 4
    ws.cell(row=rl, column=1, value="LEYENDA").font = Font(bold=True, size=9, color="606060")
    for k, (fam, nombre) in enumerate(FAMILIA_NOMBRE_XLSX.items()):
        codigos = [c for c, v in CODIGOS_CUADRANTE_INFO.items() if v[2] == fam]
        bg, fg = COLOR_FAMILIA_XLSX[fam]
        c = ws.cell(row=rl + 1 + k, column=1, value=", ".join(codigos))
        c.fill = PatternFill("solid", fgColor=bg)
        c.font = Font(bold=True, size=9, color=fg)
        c.alignment = centro
        c.border = borde
        ws.cell(row=rl + 1 + k, column=2, value=nombre).font = Font(size=9, color="606060")

    ws.freeze_panes = "C4"
    ws.column_dimensions["A"].width = 32
    ws.column_dimensions["B"].width = 6
    for j in range(len(dias)):
        ws.column_dimensions[get_column_letter(3 + j)].width = 5.5
    ws.sheet_view.showGridLines = False

    # ── Hoja 2: una fila por persona y dia ────────────────────────────────
    ws2 = wb.create_sheet("Por conductor")
    for j, cab in enumerate(["Conductor", "Fecha", "Dia", "Codigo", "Significado", "Entra a las"]):
        c = ws2.cell(row=1, column=1 + j, value=cab)
        c.font = Font(bold=True, size=9, color="FFFFFF")
        c.fill = PatternFill("solid", fgColor="595959")
        c.alignment = centro
    r = 2
    for fila in filas:
        for f in dias:
            cod, hora = fila["dias"].get(f, ("", ""))
            if not cod:
                continue
            etiqueta, _fam = info(cod)
            d = datetime.strptime(f, "%Y-%m-%d")
            for j, v in enumerate([fila["nombre"], f, DIAS_SEM_CORTO[d.weekday()],
                                   cod, etiqueta, hora]):
                ws2.cell(row=r, column=1 + j, value=v).font = Font(size=10)
            r += 1
    ws2.freeze_panes = "A2"
    ws2.auto_filter.ref = f"A1:F{max(1, r - 1)}"
    for col, ancho in zip("ABCDEF", (32, 12, 6, 11, 20, 12)):
        ws2.column_dimensions[col].width = ancho

    buf = _io.BytesIO()
    wb.save(buf)
    buf.seek(0)
    nombre = f"cuadrante-{re.sub(r'[^A-Za-z0-9]+', '', center) or 'centro'}-{dias[0]}-a-{dias[-1]}.xlsx"
    logger.info("Cuadrante exportado: %s %s a %s, %d conductores", center, dias[0], dias[-1], len(filas))
    return StreamingResponse(
        buf,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f'attachment; filename="{nombre}"'},
    )


# =========================================================================
# REPORTES DIARIOS DE CORTEX: DNR, RTS, POD y Contact Compliance
#
# De donde sale esto y por que esta hecho asi esta medido, no supuesto: en
# docs/REPORTES_DIARIOS.md hay 131 reportes analizados y 4 semanas conciliadas
# contra la scorecard real de Amazon. Los dos hechos que mandan:
#
#   1. EL DESFASE DE DOS DIAS. El reporte de la fecha F trae el bloque DNR de
#      F-2. Verificado en 131 de 131 reportes. Por eso la fecha que cuenta es
#      la de CONCESION (F-2), no la del reporte ni la de entrega del paquete:
#      asignando por fecha de entrega, la conciliacion con la scorecard falla
#      en las 4 semanas.
#
#   2. LA COLUMNA DSC SE RELLENA TARDE. Si el reporte se baja a los 2 dias, la
#      columna DSC viene entera a 'N' y saldrian CERO defectos. Los mismos
#      tracking IDs, rebajados 2-4 dias despues, ya traen sus 'Y'. Demostrado
#      en 2026-06-21 (0 -> 2), 2026-07-12 (0 -> 7) y 2026-07-15 (0 -> 4).
#      Por eso: una fila NUNCA baja de 'Y' a 'N' al volver a pegarla, y un
#      bloque que llega entero a 'N' se marca como sin clasificar en vez de
#      contarse como cero defectos.
#
# Y LO QUE CUENTA COMO DEFECTO ES DSC = 'Y'. No al reves. La regla conciliada
# es: defectos DSC de la semana W = filas con DSC='Y' cuya fecha de concesion
# cae en la semana W de Amazon (domingo a sabado).
# =========================================================================

_DIARIO_TITULO = re.compile(
    r"Daily\s+Report\s+(\d{4}-\d{2}-\d{2})", re.I)
_DIARIO_CENTRO = re.compile(r"\bES\s+TDSL\s+([A-Z0-9]{3,6})\b", re.I)
_DNR_TITULO = re.compile(r"^\s*DNR\s*\((\d{4}-\d{2}-\d{2})\)\s*$", re.I | re.M)
_DIA_TID = re.compile(r"^A[A-Z0-9]{8,16}$")


def _dia_celda(v):
    """'None', '-' y vacio son lo mismo: no hay dato."""
    s = str(v or "").strip()
    return "" if s.lower() in ("none", "-", "n/a", "") else s


def _dia_num(v):
    s = _dia_celda(v)
    if not s:
        return 0
    try:
        return int(float(s.replace(",", ".")))
    except ValueError:
        return 0


def _dia_euros(v) -> float:
    """'€130.57' -> 130.57. Devuelve 0.0 si no hay numero.

    Se acepta coma y punto porque Cortex ha cambiado de formato antes y un
    valor mal leido aqui no da error: da una cifra de dinero equivocada, que
    es peor. Con las dos separaciones ('1.234,56') manda la ultima: es la
    decimal en los dos convenios.
    """
    s = re.sub(r"[^0-9.,-]", "", str(v or "").strip())
    if not s:
        return 0.0
    if "," in s and "." in s:
        s = s.replace(",", "") if s.rfind(".") > s.rfind(",") else s.replace(".", "").replace(",", ".")
    elif "," in s:
        s = s.replace(",", ".")
    try:
        return round(float(s), 2)
    except ValueError:
        return 0.0


def _dia_menos(iso: str, n: int) -> str:
    return (datetime.strptime(iso, "%Y-%m-%d") - timedelta(days=n)).strftime("%Y-%m-%d")


def _dia_semana(iso: str) -> str:
    """Etiqueta de la semana de Amazon (domingo a sabado) de una fecha."""
    d = datetime.strptime(iso, "%Y-%m-%d")
    dom = d - timedelta(days=(d.weekday() + 1) % 7)
    return dom.strftime("%Y-%m-%d")


# ── EL REPORTE EN HTML, TAL CUAL SE DESCARGA DE CORTEX ──────────────────────
#
# Copiar y pegar de la pantalla se pierde tres de las cinco tablas y depende de
# como el navegador convierta la seleccion a texto. El fichero .html las trae
# todas y siempre igual. Validado contra 92 reportes reales de marzo a agosto
# de 2026: los 92 se leen sin un solo fallo de parseo.
#
# LAS CINCO TABLAS:
#   1. resumen  Transporter ID | RTS | DNR | POD Fails | CC Fails
#   2. rts      un devuelto por fila, CON SU MOTIVO
#   3. dnr      una concesion por fila, con DSC y el valor en euros
#   4. pod      un fallo de foto por fila, con el motivo
#   5. cc       un fallo de contacto por fila, con tipo y duracion de llamada
#
# DOS TRAMPAS DEL FORMATO, las dos comprobadas:
#
#   · En las tablas 2 a 5 el unico <th> es el boton "Download This Table" y los
#     nombres de columna DE VERDAD estan en la primera fila del cuerpo. Tomando
#     el <th> como cabecera, todas las columnas se leen desplazadas.
#
#   · Los reportes anteriores al 13-05-2026 NO TIENEN columna DSC. Tienen su
#     seccion DNR igual, pero sin clasificar. Por eso la tabla DNR se reconoce
#     por 'delivery date' + 'delivery scan' y NO por la presencia de DSC: si se
#     exigiera DSC, medio ano de reportes se leeria como si no tuviera DNRs.

_DIA_FILA = re.compile(r"<tr.*?</tr>", re.S | re.I)
_DIA_CELDA = re.compile(r"<t[dh][^>]*>(.*?)</t[dh]>", re.S | re.I)
_DIA_TABLA = re.compile(r"<table.*?</table>", re.S | re.I)
_DIA_H = re.compile(r"<h([12])[^>]*>(.*?)</h\1>", re.S | re.I)


def _dia_texto_html(s: str) -> str:
    import html as _html
    return _html.unescape(re.sub(r"\s+", " ", re.sub(r"<[^>]+>", " ", s or ""))).strip()


def _dia_tablas_html(texto: str):
    """Devuelve (cabecera_en_minusculas, filas) por cada tabla del documento."""
    for tb in _DIA_TABLA.findall(texto):
        filas = _DIA_FILA.findall(tb)
        if not filas:
            continue
        celdas = [[_dia_texto_html(c) for c in _DIA_CELDA.findall(f)] for f in filas]
        cab, datos = celdas[0], celdas[1:]
        # El boton de descarga no es una cabecera: la de verdad va debajo.
        if len(cab) <= 1 and datos:
            cab, datos = datos[0], datos[1:]
        yield [c.lower() for c in cab], [d for d in datos if any(d)]


def _parsea_diario_html(texto: str) -> dict:
    """Lee un Daily Report descargado de Cortex (.html). Las cinco tablas."""
    titulo = ""
    fecha_dnr = None
    for nivel, cuerpo in _DIA_H.findall(texto):
        txt = _dia_texto_html(cuerpo)
        if nivel == "1" and not titulo:
            titulo = txt
        md = re.match(r"DNR\s*\((\d{4}-\d{2}-\d{2})\)", txt, re.I)
        if md:
            fecha_dnr = md.group(1)

    m = re.search(r"(\d{4}-\d{2}-\d{2})", titulo)
    fecha_rep = m.group(1) if m else None
    mc = re.search(r"\bES\s+TDSL\s+([A-Z0-9]{3,6})\b", titulo, re.I)
    centro = mc.group(1).upper() if mc else None
    if not fecha_dnr and fecha_rep:
        fecha_dnr = _dia_menos(fecha_rep, 2)

    out = {"centro": centro, "fecha_reporte": fecha_rep, "fecha_dnr": fecha_dnr,
           "resumen": [], "dnr": [], "rts": [], "pod": [], "cc": [], "avisos": []}
    sin_dsc = False

    for cab, filas in _dia_tablas_html(texto):
        tiene = set(cab)

        def col(f, *nombres):
            for n in nombres:
                if n in cab:
                    i = cab.index(n)
                    if i < len(f):
                        return f[i]
            return ""

        def par(f):
            """(transporter_id, tracking_id) si los dos son validos."""
            tid = col(f, "transporter id").upper()
            tr = _dia_celda(col(f, "tracking id")).upper()
            return (tid, tr) if (_DIA_TID.match(tid) and tr) else (None, None)

        if {"transporter id", "rts", "dnr"} <= tiene:
            for f in filas:
                tid = col(f, "transporter id").upper()
                if _DIA_TID.match(tid):
                    out["resumen"].append({
                        "transporter_id": tid, "rts": _dia_num(col(f, "rts")),
                        "dnr": _dia_num(col(f, "dnr")),
                        "pod_fails": _dia_num(col(f, "pod fails")),
                        "cc_fails": _dia_num(col(f, "cc fails"))})

        elif "delivery date" in tiene and "delivery scan" in tiene:
            if "dsc" not in tiene:
                sin_dsc = True
            for f in filas:
                tid, tr = par(f)
                if not tid:
                    continue
                dsc = _dia_celda(col(f, "dsc")).upper()
                fila = {"tracking_id": tr, "transporter_id": tid,
                        "fecha_entrega": _dia_celda(col(f, "delivery date")),
                        "dsc": dsc if dsc in ("Y", "N") else "",
                        "scan": _dia_celda(col(f, "delivery scan")),
                        "phr": _dia_celda(col(f, "phr")),
                        "mas_25m": _dia_celda(col(f, "delivered \u2265 25m", "delivered >= 25m")),
                        "simultaneas": _dia_celda(col(f, "simultaneous deliveries")),
                        "contacto": _dia_celda(col(f, "contact compliance")),
                        "excepcion": _dia_celda(col(f, "delivery exception")),
                        "valor": _dia_celda(col(f, "value")),
                        "valor_eur": _dia_euros(col(f, "value")),
                        "cp": _dia_celda(col(f, "postal code"))}
                # El '1' de los reportes de mayo NO se traduce a 'Y'. Es lo mas
                # probable, pero no esta demostrado (docs/REPORTES_DIARIOS.md) y
                # convertirlo inventaria defectos que nadie ha confirmado.
                if dsc and dsc not in ("Y", "N"):
                    fila["dsc_crudo"] = dsc
                out["dnr"].append(fila)

        elif "rts reason" in tiene:
            for f in filas:
                tid, tr = par(f)
                if tid:
                    out["rts"].append({"tracking_id": tr, "transporter_id": tid,
                                       "motivo": _dia_celda(col(f, "rts reason")),
                                       "cp": _dia_celda(col(f, "postal code")),
                                       "lejos_100m": _dia_celda(
                                           col(f, "scanned \u2265 100m away", "scanned >= 100m away"))})

        elif "pod audit" in tiene:
            for f in filas:
                tid, tr = par(f)
                if tid:
                    out["pod"].append({"tracking_id": tr, "transporter_id": tid,
                                       "motivo": _dia_celda(col(f, "delivery/attempt reason")),
                                       "fallo": _dia_celda(col(f, "pod audit"))})

        elif "cc type" in tiene or "call duration (seconds)" in tiene:
            for f in filas:
                tid, tr = par(f)
                if tid:
                    out["cc"].append({"tracking_id": tr, "transporter_id": tid,
                                      "motivo": _dia_celda(col(f, "delivery/attempt reason")),
                                      "tipo": _dia_celda(col(f, "cc type")),
                                      "segundos": _dia_num(col(f, "call duration (seconds)"))})

    if not out["resumen"] and not out["dnr"]:
        raise HTTPException(400, "Ese HTML no parece un Daily Report de Cortex: "
                                 "no encuentro ni la tabla resumen ni la de DNR.")
    # Igual que en el pegado: un bloque entero sin una sola 'Y' casi nunca es un
    # dia perfecto, es Amazon que todavia no ha clasificado.
    out["sin_clasificar"] = bool(out["dnr"]) and all(r["dsc"] != "Y" for r in out["dnr"])
    if sin_dsc and out["dnr"]:
        out["avisos"].append(
            f"Este reporte es de antes del 13-05-2026 y no trae la columna DSC. "
            f"Sus {len(out['dnr'])} DNR se guardan SIN CLASIFICAR: existen, pero "
            f"no se puede saber cuáles puntúan.")
    return out


def _parsea_diario(texto: str) -> dict:
    """Despieza lo pegado de Cortex. Devuelve {centro, fecha, resumen, dnr, ...}.

    Se aceptan las dos tablas juntas o por separado, y en cualquier orden, que
    es como salen al copiarlas de la pantalla de Cortex.
    """
    texto = (texto or "").replace("\r\n", "\n").replace("\r", "\n")
    filas = [l.split("\t") for l in texto.split("\n")]

    fecha_rep = None
    m = _DIARIO_TITULO.search(texto)
    if m:
        fecha_rep = m.group(1)
    centro = None
    mc = _DIARIO_CENTRO.search(texto)
    if mc:
        centro = mc.group(1).upper()

    # La fecha del bloque DNR viene en su propio titulo, "DNR (2026-08-18)".
    # Si no esta, se deduce del desfase de dos dias.
    md = _DNR_TITULO.search(texto)
    fecha_dnr = md.group(1) if md else (_dia_menos(fecha_rep, 2) if fecha_rep else None)

    resumen, dnr, avisos = [], [], []
    modo, cols = None, []
    for fila in filas:
        limpia = [c.strip() for c in fila]
        cab = [c.lower() for c in limpia]
        # ¿Es una cabecera?
        if "transporter id" in cab and "rts" in cab and "dnr" in cab:
            modo, cols = "resumen", cab
            continue
        if "tracking id" in cab and "transporter id" in cab:
            modo, cols = "dnr", cab
            continue
        if not any(limpia):
            continue
        if modo is None:
            continue

        def col(*nombres):
            for n in nombres:
                if n in cols:
                    i = cols.index(n)
                    if i < len(limpia):
                        return limpia[i]
            return ""

        if modo == "resumen":
            tid = col("transporter id").upper()
            if not _DIA_TID.match(tid):
                continue
            resumen.append({
                "transporter_id": tid,
                "rts": _dia_num(col("rts")),
                "dnr": _dia_num(col("dnr")),
                "pod_fails": _dia_num(col("pod fails", "pod")),
                "cc_fails": _dia_num(col("cc fails", "cc")),
            })
        else:
            tid = col("transporter id").upper()
            tracking = _dia_celda(col("tracking id")).upper()
            if not (_DIA_TID.match(tid) and tracking):
                continue
            dsc = _dia_celda(col("dsc")).upper()
            dnr.append({
                "tracking_id": tracking,
                "transporter_id": tid,
                "fecha_entrega": _dia_celda(col("delivery date")),
                "dsc": dsc if dsc in ("Y", "N") else "",
                "scan": _dia_celda(col("delivery scan")),
                "phr": _dia_celda(col("phr")),
                "mas_25m": _dia_celda(col("delivered ≥ 25m", "delivered >= 25m")),
                "simultaneas": _dia_celda(col("simultaneous deliveries")),
                "contacto": _dia_celda(col("contact compliance")),
                "excepcion": _dia_celda(col("delivery exception")),
                "valor": _dia_celda(col("value")),
                "valor_eur": _dia_euros(col("value")),
                "cp": _dia_celda(col("postal code")),
            })

    if not resumen and not dnr:
        raise HTTPException(400, "No he reconocido ninguna tabla. Copia la tabla "
                                 "entera de Cortex, con su fila de cabecera.")
    if dnr and not fecha_dnr:
        raise HTTPException(400, "No sé de qué día es el bloque DNR. Copia también "
                                 "el título ('DNR (2026-08-18)') o el del reporte.")

    # Un bloque entero a 'N' casi nunca es un dia sin defectos: es Amazon que
    # todavia no ha clasificado. Se avisa y se marca, no se cuenta como cero.
    clasificados = [r for r in dnr if r["dsc"] in ("Y", "N")]
    sin_clasificar = bool(dnr) and all(r["dsc"] != "Y" for r in clasificados)
    if sin_clasificar and fecha_rep and fecha_dnr:
        avisos.append(
            f"Las {len(dnr)} filas del {fecha_dnr} vienen con DSC = N. Amazon suele "
            f"tardar 2-4 días más en clasificarlas, así que probablemente todavía no "
            f"están. Se guardan marcadas como SIN CLASIFICAR y no cuentan como "
            f"defectos: vuelve a bajar el reporte dentro de unos días y pégalo otra vez.")

    return {"centro": centro, "fecha_reporte": fecha_rep, "fecha_dnr": fecha_dnr,
            "resumen": resumen, "dnr": dnr, "sin_clasificar": sin_clasificar,
            "avisos": avisos}


@api_router.post("/diarios/pegar")
async def pegar_diario(data: dict = Body(...), user: dict = Depends(require_admin)):
    """Ingesta el Daily Report pegado de Cortex. body: {texto, center?, confirmar?}"""
    crudo = data.get("texto") or ""
    # Un fichero .html entero o un pegado normal: se decide por lo que hay.
    # El pegado sigue funcionando exactamente igual que antes.
    es_html = "<table" in crudo.lower() or "<h1" in crudo.lower()
    p = _parsea_diario_html(crudo) if es_html else _parsea_diario(crudo)
    # EL CENTRO DEL FICHERO MANDA sobre el que este seleccionado en pantalla.
    #
    # El titulo dice "ES TDSL OGA5 Daily Report ...": es el propio documento
    # quien declara de que centro es, y eso es mas fiable que el selector. Al
    # reves —el selector mandando— subir el reporte de DGA1 estando en OGA5 lo
    # guardaba entero como OGA5, en silencio, y esos DNR se le colgaban a la
    # gente equivocada. El selector solo se usa cuando el fichero no lo dice
    # (por ejemplo en un pegado suelto sin titulo).
    center = (p.get("centro") or data.get("center") or "").strip()
    if not center:
        raise HTTPException(400, "No sé de qué centro es. Elige el centro arriba.")
    if not _user_can_see_center(user, center):
        raise HTTPException(403, "No tienes acceso a ese centro")

    resumen = {
        "center": center, "fecha_reporte": p["fecha_reporte"], "fecha_dnr": p["fecha_dnr"],
        "semana": _dia_semana(p["fecha_dnr"]) if p["fecha_dnr"] else None,
        "conductores": len(p["resumen"]), "filas_dnr": len(p["dnr"]),
        "filas_rts": len(p.get("rts") or []), "filas_pod": len(p.get("pod") or []),
        "filas_cc": len(p.get("cc") or []),
        "sin_clasificar": p.get("sin_clasificar", False), "avisos": list(p["avisos"]),
    }

    # EL CRUCE. La columna DNR del resumen tiene que cuadrar con las filas del
    # detalle, conductor a conductor. Es la unica forma de saber que lo pegado
    # esta completo: si falta media tabla, aqui se ve.
    del_resumen = {r["transporter_id"]: r["dnr"] for r in p["resumen"] if r["dnr"]}
    del_detalle = {}
    for r in p["dnr"]:
        del_detalle[r["transporter_id"]] = del_detalle.get(r["transporter_id"], 0) + 1
    descuadres = []
    if p["resumen"] and p["dnr"]:
        for tid in sorted(set(del_resumen) | set(del_detalle)):
            a, b = del_resumen.get(tid, 0), del_detalle.get(tid, 0)
            if a != b:
                descuadres.append({"transporter_id": tid, "dice_el_resumen": a,
                                   "filas_de_detalle": b})
    resumen["descuadres"] = descuadres
    resumen["dnr_resumen"] = sum(del_resumen.values())
    resumen["dnr_detalle"] = sum(del_detalle.values())

    if not data.get("confirmar"):
        return resumen

    guardados_res = guardados_dnr = subidos = 0
    if p["resumen"] and p["fecha_reporte"]:
        ops = [UpdateOne(
            {"center": center, "fecha": p["fecha_reporte"], "transporter_id": r["transporter_id"]},
            {"$set": {**r, "center": center, "fecha": p["fecha_reporte"],
                      "fecha_dnr": p["fecha_dnr"],
                      "actualizado": datetime.now(timezone.utc).isoformat()}},
            upsert=True) for r in p["resumen"]]
        if ops:
            await db.daily_reports.bulk_write(ops)
            guardados_res = len(ops)

    for r in p["dnr"]:
        doc = {**r, "center": center, "fecha_concesion": p["fecha_dnr"],
               "semana": _dia_semana(p["fecha_dnr"]),
               "actualizado": datetime.now(timezone.utc).isoformat()}
        previo = await db.dnr_rows.find_one({"tracking_id": r["tracking_id"]}, {"_id": 0, "dsc": 1})
        # UNA FILA NUNCA BAJA DE 'Y' A 'N'. Volver a pegar un reporte viejo
        # —que trae la columna sin clasificar— borraria defectos ya conocidos.
        if previo and previo.get("dsc") == "Y" and doc["dsc"] != "Y":
            doc["dsc"] = "Y"
        else:
            if previo and previo.get("dsc") != doc["dsc"] and doc["dsc"] == "Y":
                subidos += 1
        await db.dnr_rows.update_one({"tracking_id": r["tracking_id"]},
                                     {"$set": doc}, upsert=True)
        guardados_dnr += 1

    # ── LAS OTRAS TRES TABLAS ───────────────────────────────────────────
    # RTS, POD y Contact Compliance NO llevan fecha propia en el reporte, asi
    # que se guardan con la del REPORTE y el campo se llama asi para que nadie
    # lo confunda con la fecha del hecho: no sabemos cuando ocurrio, sabemos en
    # que reporte salio.
    #
    # La clave es (tracking, fecha del reporte) y NO el tracking solo: medido
    # sobre 92 reportes, 763 trackings de RTS aparecen en mas de un dia. Con el
    # tracking como clave unica se perderian esas 763 filas en silencio.
    otras = 0
    for clave, coleccion in (("rts", db.rts_rows), ("pod", db.pod_rows), ("cc", db.cc_rows)):
        filas = p.get(clave) or []
        if not filas or not p["fecha_reporte"]:
            continue
        ops = [UpdateOne(
            {"tracking_id": f["tracking_id"], "fecha_reporte": p["fecha_reporte"]},
            {"$set": {**f, "center": center, "fecha_reporte": p["fecha_reporte"],
                      "actualizado": datetime.now(timezone.utc).isoformat()}},
            upsert=True) for f in filas]
        for i in range(0, len(ops), 500):
            await coleccion.bulk_write(ops[i:i + 500])
        otras += len(ops)

    resumen.update({"guardado": True, "resumen_guardados": guardados_res,
                    "dnr_guardados": guardados_dnr, "clasificados_ahora": subidos,
                    "otras_guardadas": otras})
    logger.info("Diario pegado: %s reporte=%s dnr=%s (%s filas, %s recien clasificadas)",
                center, p["fecha_reporte"], p["fecha_dnr"], guardados_dnr, subidos)
    return resumen


@api_router.post("/diarios/subir")
async def subir_diarios(files: List[UploadFile] = File(...),
                        center: Optional[str] = Form(default=None),
                        confirmar: str = Form(default=""),
                        user: dict = Depends(require_admin)):
    """Sube uno o varios Daily Report .html tal cual se descargan de Cortex.

    Es la via buena y el pegado se queda como respaldo. Copiando de la pantalla
    se pierden TRES de las cinco tablas —RTS con su motivo, los fallos de foto y
    los de contacto— porque solo se selecciona lo que se ve, y ademas depende de
    como el navegador convierta esa seleccion a texto. El fichero las trae todas
    y siempre igual.

    Se aceptan varios de una vez: son 92 dias de historico y subirlos de uno en
    uno no lo hace nadie.
    """
    if not files:
        raise HTTPException(400, "No has adjuntado ningún fichero")
    if len(files) > 120:
        raise HTTPException(400, "Como mucho 120 ficheros de una vez")

    hecho = str(confirmar).lower() in ("1", "true", "si", "sí", "yes")
    resultados, total = [], {"dnr": 0, "otras": 0, "resumen": 0, "reportes": 0}
    for f in files:
        nombre = (f.filename or "sin nombre")[:120]
        try:
            crudo = (await f.read())[:8_000_000].decode("utf-8", errors="replace")
        except Exception as e:
            resultados.append({"fichero": nombre, "error": f"no se pudo leer: {e}"})
            continue
        try:
            r = await pegar_diario({"texto": crudo, "center": center,
                                    "confirmar": hecho}, user)
        except HTTPException as e:
            resultados.append({"fichero": nombre, "error": e.detail})
            continue
        resultados.append({
            "fichero": nombre, "centro": r.get("center"),
            "fecha_reporte": r.get("fecha_reporte"), "fecha_dnr": r.get("fecha_dnr"),
            "dnr": r.get("filas_dnr"), "rts": r.get("filas_rts"),
            "pod": r.get("filas_pod"), "cc": r.get("filas_cc"),
            "conductores": r.get("conductores"),
            "descuadres": len(r.get("descuadres") or []),
            "avisos": r.get("avisos") or [],
            "guardado": bool(r.get("guardado"))})
        total["reportes"] += 1
        total["dnr"] += r.get("dnr_guardados") or r.get("filas_dnr") or 0
        total["otras"] += r.get("otras_guardadas") or 0
        total["resumen"] += r.get("resumen_guardados") or r.get("conductores") or 0

    fechas = sorted({x.get("fecha_dnr") for x in resultados if x.get("fecha_dnr")})
    con_error = [x for x in resultados if x.get("error")]
    logger.info("Diarios subidos: %d ficheros, %d con error, guardado=%s",
                len(files), len(con_error), hecho)
    return {"guardado": hecho, "ficheros": len(files), "resultados": resultados,
            "totales": total, "con_error": len(con_error),
            # Para que la pantalla pueda saltar a donde estan los datos en vez
            # de dejar al usuario mirando una semana vacia.
            "primer_dia": fechas[0] if fechas else None,
            "ultimo_dia": fechas[-1] if fechas else None}


@api_router.get("/diarios/conductores")
async def diarios_por_conductor(center: str, desde: str, hasta: str,
                                user: dict = Depends(require_admin)):
    """Cuenta DNRs por conductor en un rango, con su nombre si se conoce el ID.

    `desde`/`hasta` van por FECHA DE CONCESION, que es la que usa la scorecard.
    """
    if not _user_can_see_center(user, center):
        raise HTTPException(403, "No tienes acceso a ese centro")
    _date_range(desde, hasta)      # valida el formato y el rango

    filas = await db.dnr_rows.find(
        {"center": center, "fecha_concesion": {"$gte": desde, "$lte": hasta}},
        {"_id": 0}).to_list(20000)
    reportes = await db.daily_reports.find(
        {"center": center, "fecha_dnr": {"$gte": desde, "$lte": hasta}},
        {"_id": 0}).to_list(5000)

    nombres = {}
    # Las de baja primero para que una activa con el mismo id la pise: si dos
    # fichas comparten id, manda la que sigue trabajando.
    async for d in db.drivers.find(
            {"transporter_id": {"$nin": [None, ""]}},
            {"_id": 0, "name": 1, "transporter_id": 1, "id": 1, "active": 1}).sort("active", 1):
        nombres[(d.get("transporter_id") or "").upper()] = {
            "name": d["name"], "id": d["id"], "de_baja": d.get("active") is False}
    # Etiquetas sueltas: gente sin ficha de conductor (oficina, o que se fue).
    doc_alias = await db.app_meta.find_one({"_id": "transporter_alias"}) or {}
    for tid, nm in (doc_alias.get("mapa") or {}).items():
        nombres.setdefault(tid.upper(), {"name": nm, "id": None, "sin_ficha": True})
    # Los ids que ninguna ficha reclama: el nombre se saca del historial de
    # rutas, que trae las dos cosas. Mejor un nombre viejo que un codigo.
    #
    # Y AQUI SE MIRA SI ESA PERSONA TIENE FICHA. Antes se daba por hecho que no
    # y se pintaba "sin ficha", que era FALSO: Nicolas Rey Jimenez y Angel
    # Manuel Seoane Grille tienen ficha activa en DGA1: lo que faltaba era el
    # enlace, no la persona. Etiquetar mal un dato es peor que no etiquetarlo,
    # porque manda a dar de alta a alguien que ya esta.
    faltan = {f["transporter_id"] for f in filas} - set(nombres)
    if faltan:
        por_clave = {}
        async for d in db.drivers.find({}, {"_id": 0, "id": 1, "name": 1, "active": 1}):
            por_clave.setdefault(_clave_nombre(d.get("name")), []).append(d)
        async for r in db.route_history.find(
                {"transporter_id": {"$in": sorted(faltan)}},
                {"_id": 0, "transporter_id": 1, "driver_name": 1}):
            tid = (r.get("transporter_id") or "").upper()
            nm = (r.get("driver_name") or "").strip()
            if not (tid and nm) or tid in nombres:
                continue
            fichas = por_clave.get(_clave_nombre(nm), [])
            nombres[tid] = {"name": nm, "id": None, "solo_historial": True,
                            "ficha_sin_vincular": len(fichas) == 1,
                            "ficha_id": fichas[0]["id"] if len(fichas) == 1 else None}

    por_tid = {}
    for f in filas:
        tid = f["transporter_id"]
        e = por_tid.setdefault(tid, {"transporter_id": tid, "dnr_total": 0, "defectos": 0,
                                     "limpias": 0, "sin_clasificar": 0,
                                     "euros": 0.0, "euros_defectos": 0.0, "detalle": []})
        e["dnr_total"] += 1
        # Las filas guardadas antes de que se guardara el numero solo tienen el
        # texto ('€10.74'). Se lee de ahi en vez de dar cero: un cero en una
        # cifra de dinero no se distingue de "ese dia no hubo nada".
        eur = f.get("valor_eur")
        if eur is None:
            eur = _dia_euros(f.get("valor"))
        e["euros"] += eur
        if f.get("dsc") == "Y":
            e["defectos"] += 1
            e["euros_defectos"] += eur
        elif f.get("dsc") == "N":
            e["limpias"] += 1
        else:
            e["sin_clasificar"] += 1
        e["detalle"].append({**{k: f.get(k) for k in
                                ("tracking_id", "fecha_concesion", "fecha_entrega", "dsc",
                                 "scan", "valor", "cp")},
                             "valor_eur": eur})
    for r in reportes:
        e = por_tid.setdefault(r["transporter_id"], {
            "transporter_id": r["transporter_id"], "dnr_total": 0, "defectos": 0,
            "limpias": 0, "sin_clasificar": 0, "euros": 0.0, "euros_defectos": 0.0,
            "detalle": []})
        e["rts"] = e.get("rts", 0) + (r.get("rts") or 0)
        e["pod_fails"] = e.get("pod_fails", 0) + (r.get("pod_fails") or 0)
        e["cc_fails"] = e.get("cc_fails", 0) + (r.get("cc_fails") or 0)

    salida = []
    for tid, e in por_tid.items():
        n = nombres.get(tid)
        e["driver_name"] = n["name"] if n else ""
        e["driver_id"] = (n or {}).get("id")
        e["solo_historial"] = bool((n or {}).get("solo_historial"))
        e["de_baja"] = bool((n or {}).get("de_baja"))
        e["sin_ficha"] = bool((n or {}).get("sin_ficha"))
        # Tiene ficha, pero el id no esta puesto en ella. Es un enlace que
        # falta, no una persona que falta.
        e["ficha_sin_vincular"] = bool((n or {}).get("ficha_sin_vincular"))
        e["detalle"].sort(key=lambda x: x.get("fecha_concesion") or "")
        e["euros"] = round(e["euros"], 2)
        e["euros_defectos"] = round(e["euros_defectos"], 2)
        salida.append(e)
    # Se ordena por DINERO de los defectos, no por numero de DNRs. Cuatro
    # paquetes de 10 euros y uno de 130 no son el mismo problema, y el que hay
    # que mirar primero es el segundo.
    salida.sort(key=lambda x: (-x["euros_defectos"], -x["defectos"], -x["dnr_total"],
                               x["driver_name"] or x["transporter_id"]))

    # RTS, POD y CC del rango, contados por conductor. Van por fecha del
    # REPORTE (esas tablas no traen fecha propia), asi que se piden con el mismo
    # rango pero por ese campo. Es una aproximacion honesta y esta dicho en la
    # pantalla; inventar una fecha de hecho que el reporte no da seria peor.
    for coleccion, clave in ((db.rts_rows, "rts_filas"), (db.pod_rows, "pod_filas"),
                             (db.cc_rows, "cc_filas")):
        async for g in coleccion.aggregate([
                {"$match": {"center": center, "fecha_reporte": {"$gte": desde, "$lte": hasta}}},
                {"$group": {"_id": "$transporter_id", "n": {"$sum": 1}}}]):
            tid = g.get("_id")
            if not tid:
                continue
            e = por_tid.setdefault(tid, {"transporter_id": tid, "dnr_total": 0,
                                         "defectos": 0, "limpias": 0, "sin_clasificar": 0,
                                         "euros": 0.0, "euros_defectos": 0.0, "detalle": []})
            e[clave] = g["n"]

    dias = sorted({r["fecha_dnr"] for r in reportes if r.get("fecha_dnr")})

    # DONDE HAY DATOS, mires donde mires.
    #
    # La pantalla arranca en la semana en curso y el desfase de Amazon es de dos
    # dias, asi que por diseno casi nunca cae dentro lo que se acaba de subir:
    # se guardaban 14 filas del dia 19 y la vista estaba en el 23-29. Guardaba
    # bien y ensenaba una ventana vacia, sin decir nada. Con este par de fechas
    # la pantalla puede colocarse sola donde hay algo que ver.
    extremos = await db.dnr_rows.aggregate([
        {"$match": {"center": center}},
        {"$group": {"_id": None, "min": {"$min": "$fecha_concesion"},
                    "max": {"$max": "$fecha_concesion"}}}]).to_list(1)
    disponible = ({"primer_dia": extremos[0].get("min"), "ultimo_dia": extremos[0].get("max")}
                  if extremos else {"primer_dia": None, "ultimo_dia": None})

    return {
        "conductores": salida,
        "totales": {
            "dnr_total": sum(e["dnr_total"] for e in salida),
            "defectos": sum(e["defectos"] for e in salida),
            "limpias": sum(e["limpias"] for e in salida),
            "sin_clasificar": sum(e["sin_clasificar"] for e in salida),
            "euros": round(sum(e["euros"] for e in salida), 2),
            "euros_defectos": round(sum(e["euros_defectos"] for e in salida), 2),
        },
        # Por semana de Amazon (domingo a sabado), que es como se factura y como
        # se mira la scorecard. Un rango a caballo de dos semanas mezclaria dos
        # cosas que se deciden por separado.
        "por_semana": [
            {"semana": s,
             "dnr": sum(1 for f in filas if _dia_semana(f["fecha_concesion"]) == s),
             "defectos": sum(1 for f in filas
                             if _dia_semana(f["fecha_concesion"]) == s and f.get("dsc") == "Y"),
             "euros_defectos": round(sum(
                 (f.get("valor_eur") if f.get("valor_eur") is not None else _dia_euros(f.get("valor")))
                 for f in filas
                 if _dia_semana(f["fecha_concesion"]) == s and f.get("dsc") == "Y"), 2)}
            for s in sorted({_dia_semana(f["fecha_concesion"]) for f in filas})
        ],
        "dias_con_datos": dias,
        "sin_nombre": sorted({e["transporter_id"] for e in salida if not e["driver_name"]}),
        # Los que tienen ficha esperando a que se les ponga el id. Se cuenta
        # para poder ofrecer el arreglo en vez de solo señalar el problema.
        "vinculables": sum(1 for e in salida if e.get("ficha_sin_vincular")),
        "disponible": disponible,
    }


def _dia_parece_nombre(s: str) -> bool:
    """¿Esto es el nombre de una persona, o una fila de datos con un ID dentro?

    Sin esta comprobacion, cada fila del detalle de DNR —que lleva su
    Transporter ID en medio— pasaba por una pareja valida y se guardaba como
    "nombre" un churro de cuarenta campos.

    Se pide lo minimo que cumple cualquier nombre y no cumple ninguna fila de
    datos: solo letras y separadores, entre dos y seis palabras, y nada de
    cifras (los codigos postales, los importes y las fechas caen aqui).
    """
    s = (s or "").strip()
    if not (4 <= len(s) <= 60):
        return False
    if re.search(r"\d", s):
        return False
    # Se parte SOLO por espacios y puntos. El apostrofo y el guion van DENTRO
    # de la palabra: partiendo por ellos, "O'Donnell" daba un trozo de una sola
    # letra y el nombre entero se rechazaba.
    palabras = [p for p in re.split(r"[\s.]+", s) if p]
    if not (2 <= len(palabras) <= 6):
        return False
    LETRA = "A-Za-zÁÉÍÓÚÜÑÀÂÊÔÇáéíóúüñàâêôç"
    return all(re.fullmatch(f"[{LETRA}]+(?:['’-][{LETRA}]+)*", p) and len(p) >= 2
               for p in palabras)


@api_router.post("/diarios/id-conductor")
async def asignar_id_conductor(data: dict = Body(...), user: dict = Depends(require_admin)):
    """Pone un Transporter ID en la ficha de un conductor. body: {transporter_id, driver_id}

    Es la salida cuando no hay lista que pegar ni historial del que sacarlo:
    los ids se ven en la tabla, se elige la persona de un desplegable y ya.
    Sin emparejar nombres, sin formatos y sin adivinar nada — se elige la ficha
    a dedo, que es la unica forma que no puede equivocarse.

    `driver_id` vacio QUITA el id de quien lo tuviera: hace falta para arreglar
    uno mal puesto sin tener que ir a la ficha.
    """
    tid = str(data.get("transporter_id") or "").strip().upper()
    if not _DIA_TID.match(tid):
        raise HTTPException(400, "Ese no parece un Transporter ID")
    did = str(data.get("driver_id") or "").strip()

    if not did:
        r = await db.drivers.update_many({"transporter_id": tid},
                                         {"$unset": {"transporter_id": ""}})
        return {"ok": True, "quitado_de": r.modified_count}

    drv = await db.drivers.find_one({"id": did}, {"_id": 0, "id": 1, "name": 1, "center": 1})
    if not drv:
        raise HTTPException(404, "Ese conductor no existe")
    if not _user_can_see_center(user, drv.get("center") or ""):
        raise HTTPException(403, "Ese conductor es de otro centro")

    # Un id no puede estar en dos fichas: se quita de donde estuviera antes.
    # Si no, la busqueda por transporter_id devolveria dos y el nombre que
    # saliera dependeria del orden en que Mongo los tuviera guardados.
    await db.drivers.update_many({"transporter_id": tid, "id": {"$ne": did}},
                                 {"$unset": {"transporter_id": ""}})
    await db.drivers.update_one({"id": did}, {"$set": {"transporter_id": tid}})
    # Y si el id estaba puesto como etiqueta suelta, sobra: manda la ficha.
    await db.app_meta.update_one({"_id": "transporter_alias"},
                                 {"$unset": {f"mapa.{tid}": ""}})
    logger.info("Transporter ID %s asignado a %s", tid, drv["name"])
    return {"ok": True, "driver_name": drv["name"], "transporter_id": tid}


@api_router.post("/diarios/ids")
async def vincular_transporter_ids(data: dict = Body(...), user: dict = Depends(require_admin)):
    """Vincula Transporter IDs pegando una lista 'NOMBRE<tab>ID'.

    Sin esto el contador de DNRs muestra codigos como 'A2H4XH0AEQTVZY' en vez
    de personas, que es igual de util que no tenerlo.

    Se empareja con `_empareja_conductor`, el mismo del cuadrante, porque los
    nombres NO coinciden letra a letra con las fichas y nunca lo van a hacer:
    'ALEX FANDINO OTERO' esta como 'ALEX FANDINO' en la app, 'IAGO OTERO
    BARREIRO' esta guardado como 'IAGO BARREIRO OTERO' —apellidos al reves— y
    'PABLO FRANCISCO BIRICHINAG' va sin la ultima 'a'. Comparando letra a letra
    se caen 15 de 69.

    Y SE COMPRUEBA CONTRA EL HISTORIAL DE RUTAS, que trae el id y el nombre
    juntos en cada snapshot y viene de Amazon, no de una hoja escrita a mano.
    Si la lista pegada dice una cosa y el historial otra, NO se elige: se avisa.
    Un id mal puesto le cuelga los defectos de uno a otro, y eso no se descubre
    nunca porque el numero siempre parece razonable.
    """
    # SIN PEGAR NADA: los pares salen del historial de rutas.
    #
    # Cada snapshot de ruta trae el Transporter ID y el nombre juntos, y viene
    # de Amazon. Son 73 parejas que ya estaban en la base de datos sin que nadie
    # las usara, mientras las 86 fichas de DGA1 seguian sin un solo ID y sus
    # DNR salian como codigo. Pedir una lista escrita a mano para un dato que
    # ya se tiene, y encima de mejor fuente, no tiene sentido.
    # EL CENTRO ACOTA. Estando en DGA1 no tiene sentido proponer las parejas de
    # OGA5: son gente de otro centro y sus DNR se cuentan aparte. Antes se
    # recorria el historial entero y salian nombres de todas partes.
    centro = (data.get("center") or "").strip()
    if centro and centro.lower() != "todos" and not _user_can_see_center(user, centro):
        raise HTTPException(403, "No tienes acceso a ese centro")
    filtro_centro = {}
    if centro and centro.lower() != "todos":
        filtro_centro = {"center": {"$regex": re.escape(centro), "$options": "i"}}

    if data.get("desde_historial"):
        cuenta = {}
        async for r in db.route_history.find(filtro_centro, {"_id": 0, "transporter_id": 1, "driver_name": 1}):
            tid = (r.get("transporter_id") or "").upper()
            nm = (r.get("driver_name") or "").strip()
            if tid and nm:
                cuenta.setdefault(tid, {})[nm] = cuenta.setdefault(tid, {}).get(nm, 0) + 1
        # Si un id aparece con dos nombres distintos, manda el que mas veces
        # sale: un snapshot suelto puede llevar el nombre del que le cubrio.
        texto = chr(10).join(
            f"{max(nombres.items(), key=lambda x: x[1])[0]}\t{tid}"
            for tid, nombres in cuenta.items())
    else:
        texto = str(data.get("texto") or "")

    # ¿Esto es un Daily Report en vez de una lista de IDs? Se mira ANTES de
    # intentar leerlo. Cada fila de DNR trae un Transporter ID y un monton de
    # texto detras, asi que sin esta guarda el lector se lo tragaba y contestaba
    # "4 parejas leidas", con la fila entera puesta como si fuera el nombre de
    # una persona. Un mensaje equivocado es peor que un error: manda a buscar el
    # fallo donde no esta.
    bajo = texto.lower()
    if ("tracking id" in bajo and "delivery" in bajo) or "daily report" in bajo:
        raise HTTPException(400,
            "Eso es un Daily Report, no una lista de IDs. Pegalo en el boton "
            "«Pegar Daily Report». Aqui va una persona por linea: el nombre, "
            "un tabulador y su Transporter ID.")

    # SE LEE POR TROZOS, NO POR LINEAS.
    #
    # Leer linea a linea daba por hecho un formato —un nombre, un tabulador, un
    # id— que no es el unico que sale al copiar de sitios distintos. La lista de
    # DGA1 venia separada por barras y con VARIAS personas en la misma linea, y
    # el lector la rechazaba entera diciendo "no traian ningun ID", con un
    # churro de sesenta caracteres como ejemplo. El dato estaba bien; el que no
    # sabia leerlo era yo.
    #
    # Ahora se parte por CUALQUIER separador —barra, tabulador, punto y coma,
    # coma, salto de linea o dos espacios— y se recorre la lista de trozos: cada
    # vez que aparece un id, su nombre es lo que venia justo antes. Da igual si
    # hay uno por linea, cinco por linea o todo seguido.
    trozos = [c.strip() for c in re.split(r"[|\t;,\n\r]|\s{2,}", texto) if c.strip()]
    es_id = [bool(_DIA_TID.match(c.upper())) for c in trozos]

    # ── DOS COLUMNAS: todos los nombres y DESPUES todos los ids ────────────
    # Sale asi al copiar dos columnas de una hoja que no estan pegadas. Leido
    # "cada id va con lo de antes" se juntarian dos personas en un nombre y se
    # emparejaria mal, que es peor que no leerlo. Se detecta el caso exacto
    # —ningun id antes del ultimo nombre y misma cantidad de cada— y se
    # empareja POR ORDEN, diciendo que se ha hecho asi para que se pueda mirar.
    nombres_sueltos = [c for c, e in zip(trozos, es_id) if not e]
    ids_sueltos = [c.upper() for c, e in zip(trozos, es_id) if e]
    formato = "seguidos"
    if (ids_sueltos and nombres_sueltos
            and len(ids_sueltos) == len(nombres_sueltos)
            and all(_dia_parece_nombre(n) for n in nombres_sueltos)
            and (not any(es_id[:len(nombres_sueltos)]))
            and all(es_id[len(nombres_sueltos):])):
        return await _dia_vincula(
            [{"nombre": n, "tid": i} for n, i in zip(nombres_sueltos, ids_sueltos)],
            [], [], "dos columnas emparejadas por orden", data, user)

    pares, mal, no_parecen = [], [], []
    pendiente = []
    for c in trozos:
        if _DIA_TID.match(c.upper()):
            nombre = " ".join(pendiente).strip()
            if _dia_parece_nombre(nombre):
                pares.append({"nombre": nombre, "tid": c.upper()})
            elif nombre:
                no_parecen.append(nombre[:60])
            else:
                mal.append(c.upper())        # un id suelto, sin nombre delante
            pendiente = []
        else:
            pendiente.append(c)
    # Lo que quede al final no llego a tener id.
    resto = " ".join(pendiente).strip()
    if resto:
        mal.append(resto[:60])
    if not pares:
        detalle = "No he encontrado ninguna pareja nombre + ID."
        if no_parecen:
            detalle += (f" Hay {len(no_parecen)} lineas con un ID pero lo de al lado "
                        f"no parece el nombre de una persona, por ejemplo: "
                        f"«{no_parecen[0]}».")
        detalle += (" Pega una persona por linea: el nombre, un tabulador y el ID.")
        raise HTTPException(400, detalle)

    return await _dia_vincula(pares, mal, no_parecen, formato, data, user)


async def _dia_vincula(pares, mal, no_parecen, formato, data, user):
    """Empareja los pares ya leidos con las fichas y, si se confirma, los guarda."""
    centro = (data.get("center") or "").strip()
    filtro_centro = {}
    if centro and centro.lower() != "todos":
        filtro_centro = {"center": {"$regex": re.escape(centro), "$options": "i"}}

    # Dos personas con el MISMO id es imposible, y hay que verlo antes de escribir.
    vistos, repetidos = {}, []
    for p in pares:
        anterior = vistos.get(p["tid"])
        if anterior and _clave_nombre(anterior) != _clave_nombre(p["nombre"]):
            repetidos.append({"transporter_id": p["tid"],
                              "nombres": [anterior, p["nombre"]]})
        vistos[p["tid"]] = p["nombre"]

    hist = {}
    async for r in db.route_history.find({}, {"_id": 0, "transporter_id": 1, "driver_name": 1}):
        tid = (r.get("transporter_id") or "").upper()
        nm = (r.get("driver_name") or "").strip()
        if tid and nm:
            hist.setdefault(tid, set()).add(nm)

    # TODAS las fichas, tambien las de baja. Un DNR de hace tres semanas es de
    # quien lo hizo, aunque esa persona ya no trabaje aqui: dejarlo como codigo
    # porque se fue seria perder el dato justo cuando se va a mirar hacia atras.
    # Las activas van primero para que, ante dos fichas con el mismo nombre,
    # `_empareja_conductor` se quede con la que sigue trabajando.
    todas = await db.drivers.find(
        dict(filtro_centro),
        {"_id": 0, "id": 1, "name": 1, "transporter_id": 1, "center": 1, "active": 1}
    ).to_list(3000)
    drivers = ([d for d in todas if d.get("active") is not False]
               + [d for d in todas if d.get("active") is False])
    alias = await _alias_cuadrante()

    vinculan, sin_ficha, ambiguos, conflictos, discrepan = [], [], [], [], []
    iguales = 0
    for p in pares:
        drv, motivo = _empareja_conductor(p["nombre"], drivers, alias)
        # El historial de Amazon, como segunda opinion.
        if p["tid"] in hist:
            del_hist = {_clave_nombre(x) for x in hist[p["tid"]]}
            propios = {_clave_nombre(p["nombre"])}
            if drv:
                propios.add(_clave_nombre(drv["name"]))
            if not (propios & del_hist):
                discrepan.append({"transporter_id": p["tid"], "tu_lista": p["nombre"],
                                  "el_historial": sorted(hist[p["tid"]])[0]})
        if not drv:
            (ambiguos if motivo == "ambiguo" else sin_ficha).append(
                {"nombre": p["nombre"], "transporter_id": p["tid"], "motivo": motivo})
            continue
        actual = (drv.get("transporter_id") or "").upper()
        if actual == p["tid"]:
            iguales += 1
            continue
        if actual:
            conflictos.append({"nombre": drv["name"], "tenia": actual,
                               "quieres": p["tid"]})
            continue
        vinculan.append({"nombre": drv["name"], "escrito": p["nombre"],
                         "transporter_id": p["tid"], "driver_id": drv["id"],
                         "como": motivo, "de_baja": drv.get("active") is False})

    # Ids que ya salen en los reportes y que esta lista NO cubre: son los que
    # seguirian apareciendo como codigo en vez de como persona.
    en_reportes = set(await db.dnr_rows.distinct("transporter_id"))
    en_reportes |= set(await db.daily_reports.distinct("transporter_id"))
    ya_en_fichas = {(d.get("transporter_id") or "").upper() for d in drivers}
    sin_cubrir = sorted(en_reportes - set(vistos) - ya_en_fichas)

    salida = {
        "centro": centro or "todos", "formato": formato,
        "pares_leidos": len(pares), "sin_id": mal[:30],
        "no_parecen_nombre": no_parecen[:10], "n_no_parecen": len(no_parecen),
        "vinculan": vinculan, "n_vinculan": len(vinculan), "ya_estaban": iguales,
        "sin_ficha": sin_ficha, "ambiguos": ambiguos,
        "conflictos": conflictos, "repetidos": repetidos, "discrepan": discrepan,
        "sin_cubrir": [{"transporter_id": x, "historial": sorted(hist.get(x, []))[:1]}
                       for x in sin_cubrir],
    }
    if not data.get("confirmar"):
        return salida

    for v in vinculan:
        await db.drivers.update_one({"id": v["driver_id"]},
                                    {"$set": {"transporter_id": v["transporter_id"]}})

    # Los que no tienen ficha ninguna —gente de oficina, o que se fue antes de
    # que existiera la app— se guardan como simple etiqueta id -> nombre. No se
    # les crea una ficha de conductor falsa por eso: no lo son, y saldrian en el
    # cuadrante y en la asignacion. Pero su nombre se enseña, que es de lo que
    # se trata: un DNR de hace tres semanas sigue siendo de alguien.
    if sin_ficha:
        etiquetas = {s["transporter_id"]: s["nombre"] for s in sin_ficha}
        await db.app_meta.update_one(
            {"_id": "transporter_alias"},
            {"$set": {f"mapa.{k}": v for k, v in etiquetas.items()}},
            upsert=True)
        salida["etiquetados"] = len(etiquetas)
    salida["guardado"] = True
    logger.info("Transporter IDs vinculados: %d de %d pares", len(vinculan), len(pares))
    return salida


@api_router.get("/shifts/alias-nombres")
async def listar_alias_cuadrante(_=Depends(require_admin)):
    """Los nombres del cuadrante que ya se han emparejado a mano con su ficha."""
    return {"mapa": await _alias_cuadrante()}


@api_router.put("/shifts/alias-nombres")
async def guardar_alias_cuadrante(data: dict = Body(...), _=Depends(require_admin)):
    """Guarda 'este nombre del cuadrante es este conductor'. body: {mapa: {...}}

    Se guarda una vez y sirve para siempre: es lo que hace que el mes que viene
    no haya que volver a emparejar a los mismos catorce.
    """
    mapa = data.get("mapa")
    if not isinstance(mapa, dict):
        raise HTTPException(400, "mapa debe ser un objeto {nombre: driver_id}")
    limpio = {}
    for k, v in mapa.items():
        nombre = str(k).strip()[:120]
        did = str(v or "").strip()
        if not nombre:
            continue
        if did:
            limpio[nombre] = did      # emparejado
        # Un valor vacío borra el alias, que es como se deshace un error.
    if len(limpio) > 2000:
        raise HTTPException(400, "Demasiados alias")
    # Comprobar que los conductores existen: un alias a un id fantasma haría que
    # esas filas se perdieran en silencio, que es justo lo que se quiere evitar.
    ids = list({v for v in limpio.values()})
    existen = set()
    if ids:
        existen = {d["id"] for d in await db.drivers.find(
            {"id": {"$in": ids}}, {"_id": 0, "id": 1}).to_list(2000)}
    malos = sorted({k for k, v in limpio.items() if v not in existen})
    if malos:
        raise HTTPException(400, f"Estos alias apuntan a un conductor que no existe: {malos[:5]}")
    await db.app_meta.update_one(
        {"_id": _ALIAS_DOC},
        {"$set": {"mapa": limpio, "actualizado_en": datetime.now(timezone.utc).isoformat()}},
        upsert=True)
    return {"success": True, "alias": len(limpio)}


# Códigos del cuadrante mensual de Amazon. Se editan desde el panel porque
# cada nave usa los suyos; esto es sólo el punto de partida conocido.
# Cada codigo del cuadrante: (tipo, etiqueta, color).
#
# El TIPO es lo unico que entiende el resto de la app (cobertura, peticiones de
# dias, portal del conductor) y son solo tres. La ETIQUETA y el COLOR existen
# porque el tipo, solo, no basta para nadie que mire la pantalla: 'V',
# 'COMP', 'N/D' y 'N/P' son los cuatro "libre", y significan cosas muy
# distintas. Hasta que se guardo el codigo, pegar el cuadrante de OGA5 daba una
# pared de dos letras que no se parecia a la hoja de la que salio.
#
# El color es un nombre, no una clase de CSS: el backend no sabe de Tailwind y
# la pantalla no deberia tener que saberse los codigos de memoria.
#
# SON CINCO COLORES PARA DIECISEIS CODIGOS, Y ES A PROPOSITO. Con un color por
# codigo la rejilla era un arcoiris en el que no se distinguia nada: la
# recomendacion que se repite en todas las guias de accesibilidad y de
# visualizacion (Okabe-Ito, IBM, AudioEye) es NO PASAR DE SEIS colores
# categoricos, porque a partir de ahi dejan de diferenciarse a tamano pequeno
# —y una celda de cuadrante son 22 px—. El color dice de que FAMILIA es el dia
# y el texto del codigo, que siempre se ve, dice cual es exactamente. Asi el
# color se lee de un vistazo desde lejos y el detalle esta ahi cuando hace
# falta. Las familias:
#   ruta     -> sale a repartir
#   apoyo    -> trabaja, pero no en ruta (backup, oficina, ride along, extra)
#   libre    -> dia libre normal
#   previsto -> ausencia planificada (vacaciones, compensa)
#   aprobado -> dia concedido por la oficina: el unico que no se puede tocar
#   aviso    -> ausencia NO prevista (no disponible, no presentado, suspendido)
# La cuarta columna es SI ESE DIA SACA RUTA, y no es lo mismo que "trabaja".
#
# BKP y Site trabajan —cobran, estan en la nave— pero no sacan furgoneta, y
# el ride along va de acompanante en la de otro. Meterlos en la cuenta hacia
# que la fila de cobertura dijera 39 cuando a la calle salian 36, justo el
# numero que se compara con lo que pide Amazon. Un numero que se usa para
# decidir y que esta inflado es peor que no tenerlo.
CODIGOS_CUADRANTE_INFO = {
    # ── TRABAJA ────────────────────────────────────────────────────────────
    #              tipo        etiqueta            color      ¿saca ruta?
    "1":         ("trabaja", "Trabaja", "ruta", True),
    "T":         ("trabaja", "Trabaja", "ruta", True),
    "X":         ("trabaja", "Trabaja", "ruta", True),
    "BKP":       ("trabaja", "Backup", "apoyo", False),
    "S":         ("trabaja", "Site (oficina)", "apoyo", False),
    "RIDE":      ("trabaja", "Ride along", "apoyo", False),
    "RA":        ("trabaja", "Ride along", "apoyo", False),
    # El extra SI cuenta: es un dia de mas que alguien hace, y lo hace en ruta.
    "EXTRA":     ("extra", "Extra", "apoyo", True),
    # ── LIBRE ──────────────────────────────────────────────────────────────
    "N/T":       ("libre", "No trabaja", "libre", False),
    "L":         ("libre", "Libre", "libre", False),
    "V":         ("libre", "Vacaciones", "previsto", False),
    "COMP":      ("libre", "Compensa", "previsto", False),
    # Familia propia, no "previsto" con las vacaciones. Un dia concedido no es
    # una ausencia mas: es la unica casilla del cuadrante que NO se puede tocar
    # sin hablar con la persona, y tiene que distinguirse desde el otro lado de
    # la mesa. Es el sexto color, y ahi se para: seis es el limite por encima
    # del cual dejan de diferenciarse a tamano de celda.
    "N/T APROB": ("libre", "Libre aprobado", "aprobado", False),
    # ── AUSENCIAS QUE NO ESTABAN PREVISTAS ────────────────────────────────
    "N/D":       ("libre", "No disponible", "aviso", False),
    "N/P":       ("libre", "No presentado", "aviso", False),
    "SUSP":      ("libre", "Suspendido", "aviso", False),
}

CODIGOS_CUADRANTE_DEF = {k: v[0] for k, v in CODIGOS_CUADRANTE_INFO.items()}

# Los codigos que cuentan como ruta. Un codigo que no este aqui NO suma en la
# cobertura, aunque su tipo sea "trabaja".
CODIGOS_QUE_SACAN_RUTA = {k for k, v in CODIGOS_CUADRANTE_INFO.items() if v[3]}

# Como se cuenta un turno guardado ANTES de que hubiera codigos: solo tiene
# tipo. Se cuenta como ruta si trabajaba, que es lo que se venia haciendo; asi
# los meses viejos no cambian de numero de golpe sin motivo.
_FILTRO_RUTA = {"$or": [
    {"cod": {"$in": sorted(CODIGOS_QUE_SACAN_RUTA)}},
    {"cod": {"$exists": False}, "type": {"$in": ["trabaja", "extra"]}},
    {"cod": None, "type": {"$in": ["trabaja", "extra"]}},
]}


async def _respeta_aprobados(items: list) -> tuple:
    """Quita de `items` los dias que romperian una peticion ya aprobada.

    Devuelve (items_que_si_van, [{driver_name, date, type}, ...]).

    Existe porque el candado de la rejilla no bastaba. Pegar el cuadrante del
    mes desde Sheets escribe DIRECTO en la coleccion, sin pasar por
    /shifts/bulk, asi que se saltaba la proteccion entera: la hoja de Sheets no
    sabe nada de los dias que se aprobaron en la app, y al pegarla el mes que
    viene los borraba a todos de una vez y en silencio. Es el mismo fallo, pero
    peor, porque en vez de una celda son sesenta a la vez.

    Aqui se respeta SIEMPRE, tenga o no permiso quien pega. Pegar el cuadrante
    no es decidir sobre el dia de nadie: es traer la hoja del mes. Si de verdad
    hay que quitarle el dia a alguien, se hace en su casilla, a proposito y
    dejando rastro.
    """
    if not items:
        return items, []
    fechas = sorted({it["date"] for it in items})
    conductores = sorted({it["driver_id"] for it in items})
    aprobados = {}
    cur = db.shift_requests.find(
        {"status": "aprobado", "driver_id": {"$in": conductores},
         "date": {"$gte": fechas[0], "$lte": fechas[-1]}},
        {"_id": 0, "driver_id": 1, "date": 1, "type": 1, "driver_name": 1})
    async for r in cur:
        aprobados[f"{r['driver_id']}|{r['date']}"] = r
    if not aprobados:
        return items, []

    limpios, respetados = [], []
    for it in items:
        prot = aprobados.get(f"{it['driver_id']}|{it['date']}")
        if prot is None:
            limpios.append(it)
            continue
        aprobado = prot.get("type")
        rompe = ((aprobado == "libre" and it.get("type") in ("trabaja", "extra"))
                 or (aprobado == "extra" and it.get("type") == "libre"))
        if rompe:
            respetados.append({"driver_name": prot.get("driver_name") or it.get("driver_name") or "",
                               "date": it["date"], "type": aprobado})
        else:
            limpios.append(it)
    return limpios, respetados


def _despieza_codigo(crudo) -> tuple:
    """'V (05:43)' -> ('V', '05:43'). Devuelve (codigo, hora o '').

    Antes el parentesis se tiraba a la basura. Es la hora de entrada, y en el
    cuadrante de OGA5 aparece en la mitad de las celdas de vacaciones y de
    trabajo. Al conductor le importa mas esa hora que el codigo, asi que se
    guarda aparte en vez de perderla.
    """
    txt = str(crudo or "").strip()
    m = re.search(r"\(([^)]*)\)", txt)
    hora = ""
    if m:
        dentro = m.group(1).strip()
        if re.fullmatch(r"\d{1,2}[:.]\d{2}", dentro):
            hora = dentro.replace(".", ":")
        txt = re.sub(r"\s*\(.*?\)", "", txt)
    return re.sub(r"\s+", " ", txt).strip().upper(), hora


def _sin_tildes(s: str) -> str:
    tabla = str.maketrans("ÁÀÄÂÉÈËÊÍÌÏÎÓÒÖÔÚÙÜÛÑÇ", "AAAAEEEEIIIIOOOOUUUUNC")
    return (s or "").upper().translate(tabla)


def _clave_nombre(s: str) -> str:
    """Nombre comparable: sin tildes, sin espacios dobles, en mayúsculas."""
    return re.sub(r"\s+", " ", _sin_tildes(str(s or ""))).strip()


# ─── EMPAREJAR EL NOMBRE DEL CUADRANTE CON SU FICHA ──────────────────────────
#
# Aquí es donde se pierde el cuadrante. Medido con el de agosto: el fichero
# traía 61 conductores y se guardaron 47. Los otros 14 se cayeron en silencio.
# Dos motivos, ninguno tiene que ver con el Excel:
#
#  1. EL ORDEN DEL NOMBRE. La comparación era por igualdad del nombre
#     normalizado, y `_clave_nombre` casi no normaliza: 'ROJAS PEREZ, SERGIO L.'
#     se queda tal cual. Un cuadrante escrito "APELLIDOS, NOMBRE" no casa NUNCA
#     con una ficha que pone "NOMBRE APELLIDOS".
#
#  2. LOS DADOS DE BAJA. El importador sólo miraba fichas con `active != False`,
#     y hay 71 de 202 con `active: False` — 16 sólo en OGA5, varios de ellos
#     gente que sigue en el cuadrante. Sus filas desaparecían sin decir nada.
#
# Lo que se hace ahora:
#   · se comparan las PALABRAS del nombre, no la cadena entera;
#   · si el nombre corto está entero dentro del largo, es la misma persona;
#   · si encajan DOS fichas, no se elige ninguna — se dice que es ambiguo. Meter
#     los turnos de un hermano en la ficha del otro es peor que no meterlos;
#   · a los dados de baja se les encuentra igual, pero se avisa de que lo están
#     en vez de tragárselos.

_RELLENO_NOMBRE = {"DE", "DEL", "DA", "DO", "LA", "LAS", "LOS", "Y", "E", "SAN"}


def _palabras_nombre(s: str) -> set:
    """Las palabras que identifican a una persona, sin ruido.

    Fuera acentos, comas, puntos, iniciales sueltas y palabras de relleno.
    'ROJAS PEREZ, SERGIO L.' y 'Sergio Luis Rojas Pérez' acaban compartiendo
    {ROJAS, PEREZ, SERGIO}.
    """
    t = _sin_tildes(str(s or "")).upper()
    t = re.sub(r"[^A-Z0-9 ]+", " ", t)
    return {p for p in t.split()
            if len(p) > 1 and p not in _RELLENO_NOMBRE}


def _empareja_conductor(nombre: str, fichas: list, alias: dict):
    """Devuelve (ficha, motivo). La ficha es None si no se puede afirmar.

    motivo: 'alias' | 'exacto' | 'palabras' | 'no_encontrado' | 'ambiguo'
    """
    # 1. Lo que dijo una persona manda sobre cualquier heurística.
    did = alias.get((nombre or "").strip())
    if did:
        for f in fichas:
            if f["id"] == did:
                return f, "alias"

    clave = _clave_nombre(nombre)
    exactas = [f for f in fichas if _clave_nombre(f.get("name")) == clave]
    if len(exactas) == 1:
        return exactas[0], "exacto"
    if len(exactas) > 1:
        return None, "ambiguo"

    # 2. Por palabras. El nombre corto tiene que estar ENTERO dentro del largo,
    #    y con al menos dos palabras: con una sola, 'GARCIA' emparejaría media
    #    plantilla.
    pal = _palabras_nombre(nombre)
    if len(pal) < 2:
        return None, "no_encontrado"
    candidatas = []
    for f in fichas:
        pf = _palabras_nombre(f.get("name"))
        if len(pf) < 2:
            continue
        corto, largo = (pal, pf) if len(pal) <= len(pf) else (pf, pal)
        if corto and corto <= largo and len(corto) >= 2:
            candidatas.append(f)
    if len(candidatas) == 1:
        return candidatas[0], "palabras"
    if len(candidatas) > 1:
        # Dos personas encajan: no se elige. Meter los turnos de uno en la ficha
        # del otro es peor que dejarlos fuera y decirlo.
        return None, "ambiguo"
    return None, "no_encontrado"


@api_router.get("/route-demand")
async def get_route_demand(center: str, desde: str, hasta: str,
                           user: dict = Depends(require_admin)):
    """Rutas que pide Amazon cada día. Es de lo que cuelga el cuadrante entero.

    Estas dos rutas NO EXISTÍAN. La pantalla de Turnos las llamaba, el
    generador leía la colección, pero nadie las había escrito nunca: devolvían
    404 y, como la pantalla pide las cinco cosas a la vez, ese 404 tumbaba la
    carga completa. Resultado: "No se pudo cargar la cobertura" y ni un
    conductor en pantalla, en un centro con 61. Llevaba así desde siempre y no
    se había visto porque la pantalla tampoco estaba en el menú.
    """
    if not _user_can_see_center(user, center):
        raise HTTPException(403, "No tienes acceso a ese centro")
    docs = await db.route_demand.find(
        {"center": center, "date": {"$gte": desde, "$lte": hasta}}, {"_id": 0}).to_list(400)
    return {"demand": {d["date"]: {"objetivo": d.get("objetivo"), "maximo": d.get("maximo")}
                       for d in docs}}


@api_router.post("/route-demand")
async def set_route_demand(data: dict = Body(...), user: dict = Depends(require_admin)):
    """Guarda las rutas de cada día. `null` borra ese dato.

    Son DOS numeros independientes y no se pueden tratar como uno:

      · `maximo`   — el techo comprometido con Amazon: lo que habria que poder
                     cubrir si lo pidieran todo. Se rellena con semanas de
                     antelacion, cuando todavia no se sabe lo que van a pedir.
      · `objetivo` — las rutas que piden ESE dia. Llega mucho mas tarde.

    Antes bastaba con que `objetivo` viniera vacio para BORRAR el documento
    entero, y con el se iba el maximo que ya estaba puesto. Como el maximo se
    rellena primero y el objetivo despues, ese era exactamente el orden en que
    se usa: rellenar las maximas del mes y verlas desaparecer. Ahora cada uno
    se guarda o se quita por su cuenta, y el dia solo se borra cuando no queda
    ninguno de los dos.

    Se borra en vez de guardar un cero porque no son lo mismo: cero rutas es
    un día sin operación, y "no lo sé todavía" es un día sin rellenar. El
    generador exige que haya objetivo para funcionar, así que confundirlos
    haría que generase un cuadrante vacío creyendo que ese día no se trabaja.
    """
    center = (data.get("center") or "").strip()
    if not center:
        raise HTTPException(400, "Falta el centro")
    if not _user_can_see_center(user, center):
        raise HTTPException(403, "No tienes acceso a ese centro")

    def _numero(crudo, fecha, que):
        if crudo in (None, ""):
            return None
        try:
            n = int(str(crudo).strip())
        except ValueError:
            raise HTTPException(400, f"{que} del {fecha} tiene que ser un número")
        if not 0 <= n <= 999:
            raise HTTPException(400, f"{que} del {fecha} está fuera de rango")
        return n

    ops, borrar = [], []
    for it in (data.get("items") or []):
        fecha = str(it.get("date") or "")[:10]
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", fecha):
            continue
        objetivo = _numero(it.get("objetivo"), fecha, "Las rutas que piden")
        maximo = _numero(it.get("maximo"), fecha, "El máximo")
        if objetivo is None and maximo is None:
            borrar.append(fecha)
            continue
        doc = {"center": center, "date": fecha,
               "updated_at": datetime.now(timezone.utc).isoformat(),
               "updated_by": user.get("name")}
        quitar = {}
        for clave, valor in (("objetivo", objetivo), ("maximo", maximo)):
            if valor is None:
                quitar[clave] = ""
            else:
                doc[clave] = valor
        cambio = {"$set": doc}
        if quitar:
            cambio["$unset"] = quitar
        ops.append(UpdateOne({"center": center, "date": fecha}, cambio, upsert=True))

    if ops:
        await db.route_demand.bulk_write(ops)
    if borrar:
        await db.route_demand.delete_many({"center": center, "date": {"$in": borrar}})
    return {"ok": True, "guardados": len(ops), "borrados": len(borrar)}


@api_router.get("/shifts/codigos")
async def get_codigos_cuadrante(_=Depends(require_admin)):
    """Qué significa cada código del Excel mensual."""
    doc = await db.app_meta.find_one({"_id": "codigos_cuadrante"}) or {}
    mapa = dict(CODIGOS_CUADRANTE_DEF)
    mapa.update({str(k).upper(): v for k, v in (doc.get("mapa") or {}).items()})
    # `info` lleva la etiqueta y el color de cada codigo. Los que anadio el
    # usuario a mano no estan en la tabla de arriba, asi que se les da una
    # etiqueta con su propio nombre y el color gris: mejor eso que no salir.
    info = {}
    for cod, tipo in mapa.items():
        base = CODIGOS_CUADRANTE_INFO.get(cod)
        info[cod] = {"tipo": tipo,
                     "etiqueta": base[1] if base else cod,
                     "color": base[2] if base else "libre",
                     # Sin base, un codigo anadido a mano cuenta como ruta si
                     # es de trabajar: es lo que espera quien lo anadio.
                     "ruta": bool(base[3]) if base else tipo in ("trabaja", "extra")}
    return {"codigos": doc.get("mapa") or CODIGOS_CUADRANTE_DEF,
            "mapa": mapa, "info": info,
            "tipos": sorted(VALID_SHIFT_TYPE)}


@api_router.put("/shifts/codigos")
async def set_codigos_cuadrante(data: dict = Body(...), _=Depends(require_admin)):
    """Traduce los códigos del Excel a turnos. Vacío = reconocido y se ignora."""
    mapa = {}
    for k, v in (data.get("codigos") or {}).items():
        k = str(k).strip().upper()[:20]
        if not k:
            continue
        if v in (None, "", "ignorar"):
            mapa[k] = None
        elif v in VALID_SHIFT_TYPE:
            mapa[k] = v
        else:
            raise HTTPException(400, f"Tipo no válido para {k}")
    await db.app_meta.update_one({"_id": "codigos_cuadrante"},
                                 {"$set": {"mapa": mapa}}, upsert=True)
    return {"codigos": mapa}


@api_router.post("/shifts/import")
async def import_shifts(file: UploadFile = File(...), center: str = Form(...),
                        mes: str = Form(...), confirmar: str = Form(default=""),
                        user: dict = Depends(require_admin)):
    """Importa el cuadrante mensual de Amazon (hoja MENSUAL).

    ── POR QUÉ NO SE FÍA DEL FICHERO ────────────────────────────────────────
    El Excel real trae dos cosas que, tomadas al pie de la letra, meten un
    cuadrante equivocado para toda la nave:

      1. La cabecera pone "Desde: 01-06-2026 hasta: 30-06-2026" en un fichero
         que es de AGOSTO — el texto se queda del mes anterior al reutilizar
         la plantilla. Por eso el mes lo pone QUIEN IMPORTA, no el fichero.

      2. La fila de números de día viene rota: repite el 22, se salta el 23 y
         pone 1, 2, 3, 4 donde van 27, 28, 29 y 30. Fiarse de esos números
         escribiría turnos en días que no son. Se usa la POSICIÓN de la
         columna, que sí es correlativa, y el bloque de días se delimita con
         la fila de días de la semana, la única fiable de la cabecera.

    Y antes de escribir nada se comprueba que el día 1 del mes elegido caiga
    en el día de la semana que dice el Excel. Si no cuadra, se para: con 61
    conductores, un mes de desfase son más de 1.800 turnos mal puestos.

    Sin `confirmar` no guarda nada: primero devuelve el resumen de lo que hará.
    """
    if not _user_can_see_center(user, center):
        raise HTTPException(403, "No tienes acceso a ese centro")
    m = re.fullmatch(r"(\d{4})-(\d{1,2})", (mes or "").strip())
    if not m:
        raise HTTPException(400, "Elige el mes del cuadrante (YYYY-MM)")
    anio, mesn = int(m.group(1)), int(m.group(2))
    if not 1 <= mesn <= 12:
        raise HTTPException(400, "Mes fuera de rango")

    content = await file.read()
    try:
        import openpyxl, io
        wb = openpyxl.load_workbook(io.BytesIO(content), data_only=True)
        ws = wb["MENSUAL"] if "MENSUAL" in wb.sheetnames else wb[wb.sheetnames[0]]
        celdas = [[ws.cell(r, c).value for c in range(1, ws.max_column + 1)]
                  for r in range(1, min(ws.max_row, 400) + 1)]
    except Exception as e:
        raise HTTPException(400, f"No se pudo leer el Excel: {e}")

    # ── Cabecera: la fila que tiene "Nombre" ─────────────────────────────────
    fila_cab = col_nombre = None
    for i, fila in enumerate(celdas):
        for j, v in enumerate(fila):
            if _sin_tildes(str(v or "")).strip() == "NOMBRE":
                fila_cab, col_nombre = i, j
                break
        if fila_cab is not None:
            break
    if not fila_cab:
        raise HTTPException(400, "No encontré la fila de cabecera con la columna Nombre")

    # ── Días: el bloque que tiene día de la semana en la fila de encima ──────
    DOW = {"LUN": 0, "MAR": 1, "MIE": 2, "MIER": 2, "JUE": 3, "VIE": 4, "SAB": 5, "DOM": 6}
    fila_dow = celdas[fila_cab - 1]
    cols_dia, dow_primero = [], None
    for j in range(col_nombre + 1, len(fila_dow)):
        etiqueta = _sin_tildes(str(fila_dow[j] or "")).strip().rstrip(".")
        if etiqueta not in DOW:
            if cols_dia:
                break
            continue
        if dow_primero is None:
            dow_primero = DOW[etiqueta]
        cols_dia.append(j)
    if len(cols_dia) < 28:
        raise HTTPException(400,
            "No encontré la fila de días de la semana encima de la cabecera. "
            "Comprueba que es la hoja MENSUAL del cuadrante de Amazon.")

    dias_mes = calendar.monthrange(anio, mesn)[1]
    if len(cols_dia) > dias_mes:
        cols_dia = cols_dia[:dias_mes]

    # ── La comprobación que evita el desastre ────────────────────────────────
    DIAS_SEM = ["lunes", "martes", "miércoles", "jueves", "viernes", "sábado", "domingo"]
    MESES_ES = ["", "enero", "febrero", "marzo", "abril", "mayo", "junio", "julio",
                "agosto", "septiembre", "octubre", "noviembre", "diciembre"]
    dow_real = date_cls(anio, mesn, 1).weekday()
    if dow_primero != dow_real:
        raise HTTPException(400,
            f"Este cuadrante empieza en {DIAS_SEM[dow_primero]} y el 1 de {MESES_ES[mesn]} "
            f"de {anio} cae en {DIAS_SEM[dow_real]}. O el mes elegido no es el del fichero, "
            f"o el Excel no es el que crees. No se ha guardado nada.")

    doc = await db.app_meta.find_one({"_id": "codigos_cuadrante"}) or {}
    mapa = dict(CODIGOS_CUADRANTE_DEF)
    mapa.update({str(k).upper(): v for k, v in (doc.get("mapa") or {}).items()})

    # Se traen TAMBIEN los dados de baja. Hay 71 fichas con active=False de 202,
    # y varias son gente que sigue saliendo en el cuadrante: excluirlas hacia
    # desaparecer sus filas sin decir nada. Se encuentran, y se avisa.
    drivers = await db.drivers.find(
        {"center": {"$regex": re.escape(center), "$options": "i"}},
        {"_id": 0, "id": 1, "name": 1, "active": 1}).to_list(2000)
    por_nombre = {_clave_nombre(d.get("name")): d for d in drivers}
    alias = await _alias_cuadrante()

    items, sin_conductor, sin_codigo, de_baja = [], [], {}, set()
    for fila in celdas[fila_cab + 1:]:
        if col_nombre >= len(fila):
            continue
        nombre = str(fila[col_nombre] or "").strip()
        if not nombre:
            continue
        drv, motivo = _empareja_conductor(nombre, drivers, alias)
        if not drv:
            sin_conductor.append({"nombre": nombre, "motivo": motivo})
            continue
        if drv.get("active") is False:
            de_baja.add(drv["name"])
        for n, j in enumerate(cols_dia, start=1):
            if j >= len(fila):
                continue
            crudo = fila[j]
            if crudo in (None, ""):
                continue
            cod, hora = _despieza_codigo(crudo)
            if cod not in mapa:
                sin_codigo[cod] = sin_codigo.get(cod, 0) + 1
                continue
            tipo = mapa[cod]
            if not tipo:
                continue
            it = {"driver_id": drv["id"], "driver_name": drv["name"],
                  "center": center, "date": f"{anio:04d}-{mesn:02d}-{n:02d}",
                  "type": tipo, "cod": cod}
            if hora:
                it["hora"] = hora
            items.append(it)

    resumen = {
        "mes": f"{anio:04d}-{mesn:02d}", "center": center,
        "dias": len(cols_dia), "conductores": len({i["driver_id"] for i in items}),
        "turnos": len(items),
        "trabaja": sum(1 for i in items if i["type"] == "trabaja"),
        "libre": sum(1 for i in items if i["type"] == "libre"),
        "extra": sum(1 for i in items if i["type"] == "extra"),
        "sin_conductor": sin_conductor[:40],
        "n_sin_conductor": len(sin_conductor),
        "de_baja": sorted(de_baja),
        "codigos_desconocidos": dict(sorted(sin_codigo.items(), key=lambda x: -x[1])),
        "guardado": False,
    }

    # Un código sin traducir es un día que se quedaría sin poner. Se avisa
    # ANTES: un cuadrante a medias es peor que uno sin importar, porque parece
    # completo y ya nadie vuelve a mirarlo.
    if sin_codigo and not confirmar:
        resumen["aviso"] = ("Hay códigos que no sé qué significan. Tradúcelos antes de guardar, "
                            "o confirma para importar sólo el resto.")
        return resumen
    if not confirmar:
        return resumen

    items, respetados = await _respeta_aprobados(items)

    guardados = 0
    for i in range(0, len(items), 500):
        lote = items[i:i + 500]
        if lote:
            await _bulk_turnos([
                UpdateOne({"driver_id": it["driver_id"], "date": it["date"]},
                          {"$set": it}, upsert=True) for it in lote])
            guardados += len(lote)
    resumen["guardado"] = True
    resumen["saved"] = guardados
    resumen["respetados"] = respetados[:30]
    resumen["n_respetados"] = len(respetados)
    logger.info("Cuadrante importado: %s %s - %s turnos", center, resumen["mes"], guardados)
    return resumen


def _date_range(desde: str, hasta: str) -> list:
    """Los dias, en ISO, entre dos fechas incluidas las dos.

    NO EXISTIA. La llamaban /shifts/generate y /shifts/generate-auto, asi que
    las dos reventaban con NameError en la primera linea util. Y una de ellas
    tiene un boton detras: "Generar cuadrante" en la pantalla de Turnos llevaba
    devolviendo 500 desde siempre. Lo destapo el unico test que fallaba del CI,
    que llevaba semanas en rojo sin que nadie pudiera leer el log.

    Aqui no aplica el lio de husos horarios del gotcha 11: se entra y se sale en
    texto ISO, sin pasar por fechas locales en ningun momento.
    """
    try:
        a = datetime.strptime(desde, "%Y-%m-%d")
        b = datetime.strptime(hasta, "%Y-%m-%d")
    except (TypeError, ValueError):
        raise HTTPException(status_code=400,
                            detail="Las fechas van en formato AAAA-MM-DD")
    if b < a:
        raise HTTPException(status_code=400,
                            detail="La fecha de fin es anterior a la de inicio")
    # Un tope, porque el que llama manda las fechas y un rango de anos montaria
    # un cuadrante enorme y tumbaria la maquina por memoria.
    if (b - a).days > 366:
        raise HTTPException(status_code=400,
                            detail="Como mucho un ano de una vez")
    return [(a + timedelta(days=i)).strftime("%Y-%m-%d")
            for i in range((b - a).days + 1)]


# EL GENERADOR CON IA SE HA BORRADO (22-08-2026).
#
# Eran 155 lineas que no funcionaron jamas: llamaban a
# `_generate_schedule_with_gemini`, una funcion que nunca se escribio, dentro
# de un try que convertia el NameError en un 502 diciendo "la IA no pudo
# generar el cuadrante; reintenta". Un mensaje falso — no era la IA, y
# reintentar no iba a servir de nada.
#
# Ninguna pantalla la llamaba. Y el generador AUTOMATICO de aqui abajo hace lo
# mismo mejor: es instantaneo, deterministra, gratis y no gasta cuota de IA,
# que ademas se agota a diario. Esta en el historial de git por si algun dia
# se quiere retomar.

# Presupuesto de días/semana por nivel (carga progresiva de novatos)
_NIVEL_BUDGET = {"L1": 3, "L2": 4, "L3": 5, "pleno": 5}
_NOVATOS = {"L1", "L2", "L3"}


@api_router.post("/shifts/generate-auto")
async def generate_schedule_auto(data: dict = Body(...), _=Depends(require_admin)):
    """Genera el cuadrante con un ALGORITMO DETERMINISTA (sin IA): instantáneo,
    gratis y siempre consistente. Cubre la demanda de Amazon por eficiencia real,
    respeta empresa(L-V)/ETT y protege a los novatos. No guarda: devuelve propuesta."""
    center = data.get("center")
    desde = data.get("desde")
    hasta = data.get("hasta")
    if not (center and desde and hasta):
        raise HTTPException(status_code=400, detail="center, desde y hasta requeridos")
    days = _date_range(desde, hasta)

    drivers = await db.drivers.find(
        {"center": {"$regex": re.escape(center), "$options": "i"}, "active": {"$ne": False}},
        {"_id": 0, "id": 1, "name": 1, "driver_id": 1, "contrato": 1, "nivel": 1},
    ).to_list(1000)
    if not drivers:
        raise HTTPException(status_code=404, detail=f"No hay conductores en {center}")

    # demanda
    dem_docs = await db.route_demand.find(
        {"center": center, "date": {"$gte": desde, "$lte": hasta}}, {"_id": 0}
    ).to_list(400)
    demand = {d["date"]: d for d in dem_docs}
    if not any(demand.get(dd, {}).get("objetivo") for dd in days):
        raise HTTPException(status_code=400,
            detail="Falta la demanda de Amazon: pon las rutas objetivo de cada día antes de generar.")

    # ritmo real (paradas/hora) por transporter_id
    tids = [d.get("driver_id") for d in drivers if d.get("driver_id")]
    pace = {}
    if tids:
        cur = db.route_history.find(
            {"transporter_id": {"$in": [t.upper() for t in tids]}},
            {"_id": 0, "transporter_id": 1, "date": 1, "rate": 1})
        tmp = {}
        async for s in cur:
            if s.get("rate"):
                tmp.setdefault(s.get("transporter_id"), {})[s.get("date")] = s["rate"]
        for t, byday in tmp.items():
            vals = list(byday.values())
            if vals:
                pace[t] = sum(vals) / len(vals)

    # scorecard (media tier_score 1-6) por driver_id
    sc = {}
    sc_cur = db.driver_scorecard.find(
        {"$or": [{"driver_id": {"$in": [d["id"] for d in drivers]}},
                 {"transporter_id": {"$in": [t.upper() for t in tids]}}]},
        {"_id": 0, "driver_id": 1, "transporter_id": 1, "tier_score": 1, "imported_at": 1},
    ).sort("imported_at", -1)
    tid_to_id = {(d.get("driver_id") or "").upper(): d["id"] for d in drivers if d.get("driver_id")}
    tmp_sc = {}
    async for s in sc_cur:
        did = s.get("driver_id") or tid_to_id.get((s.get("transporter_id") or "").upper())
        if not did:
            continue
        e = tmp_sc.setdefault(did, [])
        if len(e) < 4 and isinstance(s.get("tier_score"), (int, float)):
            e.append(s["tier_score"])
    for did, vals in tmp_sc.items():
        if vals:
            sc[did] = sum(vals) / len(vals)

    # días ya trabajados últimas 2 semanas (para no recargar siempre a los mismos)
    d14 = (datetime.strptime(desde, "%Y-%m-%d") - timedelta(days=14)).strftime("%Y-%m-%d")
    worked = {}
    cur2 = db.shifts.find(
        {"center": {"$regex": re.escape(center), "$options": "i"}, "date": {"$gte": d14, "$lt": desde},
         "type": {"$in": ["trabaja", "extra"]}}, {"_id": 0, "driver_id": 1})
    async for s in cur2:
        worked[s["driver_id"]] = worked.get(s["driver_id"], 0) + 1

    # eficiencia por conductor: scorecard (1-6) + ritmo como desempate
    pace_vals = [v for v in pace.values() if v]
    pmax = max(pace_vals) if pace_vals else 1.0

    def eff(d):
        did = d["id"]
        base = sc.get(did)
        if base is None:
            base = 3.5  # sin datos = medio (no se infravalora)
        tid = (d.get("driver_id") or "").upper()
        pv = pace.get(tid)
        pn = (pv / pmax) if (pv and pmax) else 0.0
        return base + 0.3 * pn

    # agrupar en semanas (lunes inicia semana) para el cupo de ~5 días
    weeks, cur = [], []
    for dd in days:
        if datetime.strptime(dd, "%Y-%m-%d").weekday() == 0 and cur:
            weeks.append(cur); cur = []
        cur.append(dd)
    if cur:
        weeks.append(cur)

    assignments, faltas = [], []
    name_by_id = {d["id"]: d.get("name", "") for d in drivers}
    for wk in weeks:
        assigned = {d["id"]: 0 for d in drivers}   # días asignados esta semana
        for dd in wk:
            obj = demand.get(dd, {}).get("objetivo")
            if not obj:
                continue
            mx = demand.get(dd, {}).get("maximo") or obj
            need = min(int(obj), int(mx))
            is_weekend = datetime.strptime(dd, "%Y-%m-%d").weekday() >= 5

            elig = []
            for d in drivers:
                contrato = (d.get("contrato") or "ett").lower()
                if contrato == "empresa" and is_weekend:
                    continue   # empresa nunca trabaja en finde
                elig.append(d)

            def sortkey(d):
                nivel = d.get("nivel") or "pleno"
                budget = _NIVEL_BUDGET.get(nivel, 5)
                under = assigned[d["id"]] < budget
                is_nov = nivel in _NOVATOS
                grp = 0 if (is_nov and under) else (1 if under else 2)  # novatos protegidos primero
                return (grp, -eff(d), assigned[d["id"]], worked.get(d["id"], 0), d.get("name", ""))

            elig.sort(key=sortkey)
            picked = elig[:need]
            for d in picked:
                budget = _NIVEL_BUDGET.get(d.get("nivel") or "pleno", 5)
                typ = "extra" if assigned[d["id"]] >= budget else "trabaja"
                assignments.append({"driver_id": d["id"], "driver_name": name_by_id[d["id"]],
                                    "center": center, "date": dd, "type": typ})
                assigned[d["id"]] += 1
            if len(picked) < int(obj):
                faltas.append(f"{dd[8:]}/{dd[5:7]} faltan {int(obj) - len(picked)}")

    cov = {dd: 0 for dd in days}
    for a in assignments:
        if a["type"] in ("trabaja", "extra"):
            cov[a["date"]] = cov.get(a["date"], 0) + 1

    con_sc = len(sc)
    resumen = (f"Cuadrante automático por eficiencia real "
               f"({con_sc} con scorecard, {len(pace)} con ritmo). "
               f"Empresa solo L-V, novatos protegidos con carga progresiva.")
    if faltas:
        resumen += " ⚠️ Días sin cubrir el objetivo: " + ", ".join(faltas[:12])
    else:
        resumen += " Todos los días cubren el objetivo."

    return {"success": True, "assignments": assignments, "resumen": resumen,
            "coverage": cov, "con_datos_ritmo": len(pace), "con_scorecard": con_sc,
            "faltas": len(faltas)}


# =========================
# IMPORTAR SCORECARDS → rendimiento real por conductor (para el generador)
#   driver_scorecard: {center, semana, driver_name, transporter_id, tier,
#                      tier_score(1-6), posicion, score, metrics, imported_at}
# =========================

_TIER_SCORE = {"fantastic+": 6, "fantastic +": 6, "fantastic plus": 6, "fantastic": 5,
               "great": 4, "fair": 3, "poor": 2, "at risk": 1, "en riesgo": 1}


def _tier_to_score(tier):
    t = (tier or "").strip().lower()
    for k, v in _TIER_SCORE.items():
        if k in t:
            return v
    return None


_SCORECARD_EXTRACT_PROMPT = """Eres un analista de Amazon DSP. Te paso una Scorecard semanal.
Extrae el RENDIMIENTO INDIVIDUAL de CADA repartidor que aparezca (no solo los que fallan).
Para cada uno devuelve su nombre tal cual, su Transporter ID si aparece (formato tipo
A1W24EJAOPQ5F0), su tier/standing global de la semana y, si están, sus métricas clave.

Tiers posibles: "Fantastic+", "Fantastic", "Great", "Fair", "Poor", "At Risk".

Devuelve EXCLUSIVAMENTE JSON:
{"semana":"texto de la semana o fecha si aparece",
 "conductores":[
   {"name":"Nombre Apellido","transporter_id":"A1... o null",
    "tier":"Fantastic|Great|Fair|Poor|At Risk|...","posicion":<int o null>,
    "score":<número global 0-100 o null>,
    "dcr":<o null>,"dnr_dpmo":<o null>,"pod":<o null>,"cc":<o null>}
 ]}
No inventes conductores ni cifras: solo lo que aparezca en la Scorecard."""


async def _extract_scorecard_standings(text, pdf_bytes):
    from google import genai as genai_sdk
    from google.genai import types as genai_types
    use_vertex = os.environ.get("USE_VERTEX_AI", "").lower() in ("1", "true", "yes")
    if use_vertex:
        from google.oauth2 import service_account
        import json as _json, base64 as _b64
        sa = os.environ.get("GCP_SERVICE_ACCOUNT_JSON", "").strip()
        if sa and not sa.startswith("{"):
            sa = _b64.b64decode(sa).decode("utf-8")
        creds = service_account.Credentials.from_service_account_info(
            _json.loads(sa), scopes=["https://www.googleapis.com/auth/cloud-platform"]) if sa else None
        client = genai_sdk.Client(vertexai=True, project=os.environ.get("GCP_PROJECT", ""),
                                  location=os.environ.get("GCP_LOCATION", "us-central1"), credentials=creds)
    else:
        client = genai_sdk.Client(api_key=os.environ.get("GEMINI_API_KEY", ""))
    contents = [_SCORECARD_EXTRACT_PROMPT]
    if pdf_bytes:
        contents.append(genai_types.Part.from_bytes(data=pdf_bytes, mime_type="application/pdf"))
    else:
        contents.append("CONTENIDO DE LA SCORECARD:\n\n" + (text or ""))
    cfg = genai_types.GenerateContentConfig(temperature=0.1, response_mime_type="application/json")
    loop = asyncio.get_running_loop()
    async with _gemini_sem:
        resp = await asyncio.wait_for(
            loop.run_in_executor(_executor, lambda: client.models.generate_content(
                model=os.environ.get("GEMINI_MODEL", "gemini-2.5-flash"), contents=contents, config=cfg)),
            timeout=170.0)
    return json.loads(_strip_markdown_json(resp.text or "{}"))


@api_router.post("/scorecard/import")
async def import_scorecard(file: UploadFile = File(...), center: str = Form(...),
                           user: dict = Depends(require_admin)):
    """Sube una Scorecard; la IA extrae el rendimiento de cada repartidor y lo guarda
    para que el generador de cuadrantes lo use como señal de eficiencia real."""
    await _require_plan_feature(user, "scorecard")
    content = await file.read()
    text, pdf_bytes = await _extract_report_text(content, file.filename or "scorecard")
    try:
        data = await _extract_scorecard_standings(text, pdf_bytes)
    except Exception as e:
        logger.error(f"import_scorecard gemini error: {type(e).__name__}: {repr(e)}")
        raise HTTPException(status_code=502, detail="La IA no pudo leer la Scorecard; reintenta.")

    semana = (data.get("semana") or file.filename or "").strip()[:80]
    conductores = data.get("conductores") or []
    # mapa de nombres -> driver para cruzar transporter_id que falte
    drivers = await db.drivers.find({}, {"_id": 0, "id": 1, "name": 1, "driver_id": 1}).to_list(2000)
    by_tid = {(d.get("driver_id") or "").upper(): d for d in drivers if d.get("driver_id")}
    by_name = {(d.get("name") or "").strip().lower(): d for d in drivers}

    # El guardado vive en `_guardar_standings`, que usa tambien la subida
    # unificada. Dos copias del mismo trabajo acaban separandose: se arregla
    # una y la otra no, y las dos siguen respondiendo 200.
    saved = await _guardar_standings({"semana": semana, "conductores": conductores}, center)
    matched = sum(1 for c in conductores
                  if by_tid.get((c.get("transporter_id") or "").strip().upper())
                  or by_name.get((c.get("name") or "").strip().lower()))
    return {"success": True, "semana": semana, "conductores": saved,
            "cruzados": matched, "sin_cruzar": max(0, saved - matched)}


async def _guardar_standings(data: dict, center: str) -> int:
    """Guarda el rendimiento por conductor de una scorecard. Devuelve cuantos.

    Es el mismo trabajo que hace `/scorecard/import`, sacado aparte para que lo
    pueda usar tambien la subida unificada —la que si tiene boton—. Copiarlo
    seria condenar a las dos copias a separarse: la de arriba se arreglaria y
    esta no, y nadie lo notaria porque las dos responden 200.
    """
    semana = (data.get("semana") or "").strip()[:80]
    conductores = data.get("conductores") or []
    if not semana or not conductores:
        return 0
    drivers = await db.drivers.find(
        {}, {"_id": 0, "id": 1, "name": 1, "driver_id": 1}).to_list(2000)
    by_tid = {(d.get("driver_id") or "").upper(): d for d in drivers if d.get("driver_id")}
    by_name = {(d.get("name") or "").strip().lower(): d for d in drivers}

    guardados = 0
    for c in conductores:
        name = (c.get("name") or "").strip()
        tid = (c.get("transporter_id") or "").strip().upper()
        drv = by_tid.get(tid) or by_name.get(name.lower())
        if drv and not tid:
            tid = (drv.get("driver_id") or "").upper()
        if not (tid or name):
            continue                       # sin nada con que identificarlo, no se guarda
        tier = c.get("tier")
        doc = {
            "center": center, "semana": semana,
            "driver_name": drv.get("name") if drv else name,
            "transporter_id": tid or None,
            "driver_id": drv.get("id") if drv else None,
            "tier": tier, "tier_score": _tier_to_score(tier),
            "posicion": c.get("posicion"), "score": c.get("score"),
            "metrics": {"dcr": c.get("dcr"), "dnr_dpmo": c.get("dnr_dpmo"),
                        "pod": c.get("pod"), "cc": c.get("cc")},
            "imported_at": datetime.now(timezone.utc).isoformat(),
        }
        key = {"center": center, "semana": semana}
        if tid:
            key["transporter_id"] = tid
        else:
            key["driver_name"] = doc["driver_name"]
        await db.driver_scorecard.update_one(key, {"$set": doc}, upsert=True)
        guardados += 1
    logger.info("Scorecard %s (%s): %d conductores guardados", semana, center, guardados)
    return guardados


@api_router.delete("/scorecard/week")
async def delete_scorecard_week(semana: str, center: Optional[str] = None,
                               _=Depends(require_admin)):
    """Borra todas las líneas de una semana de scorecard (para reimportar o limpiar)."""
    q = {"semana": semana}
    if center:
        q["center"] = center
    r = await db.driver_scorecard.delete_many(q)
    return {"success": True, "borradas": r.deleted_count}


@api_router.get("/scorecard/standings")
async def scorecard_standings(center: Optional[str] = None, user: dict = Depends(require_admin)):
    """Últimas semanas de scorecard guardadas (para ver qué hay importado)."""
    await _require_plan_feature(user, "scorecard")
    q = {}
    if center:
        q["center"] = center
    docs = await db.driver_scorecard.find(q, {"_id": 0}).sort("imported_at", -1).to_list(2000)
    semanas = {}
    cruzados = 0
    for d in docs:
        semanas.setdefault(d.get("semana", "?"), 0)
        semanas[d["semana"]] += 1
        if d.get("driver_id"):
            cruzados += 1

    # ── CUANTOS DE LA PLANTILLA LLEGAN, QUE ES LO QUE DECIDE EL TIER ────────
    # El tier del DSP no sale de la media: Amazon mira que PORCENTAJE de los
    # repartidores llega a objetivo. Con la media, tres cracks tapan a diez que
    # van justos y el numero sale bonito mientras el tier baja.
    #
    # `tier_score` viene de `_TIER_SCORE`: 6 Fantastic+, 5 Fantastic, 4 Great,
    # 3 Fair, 2 Poor, 1 At Risk. Aqui NO se pone ningun umbral de aprobado a
    # dedo —el que se publica por ahi (86 %, 88 %) cambia y no lo hemos visto
    # en un documento de Amazon—: se da el reparto real y el porcentaje que
    # esta en Fantastic o mejor, que es un HECHO de sus datos. Poner un listón
    # inventado al lado convertiria un dato en una opinion.
    ultima = max(semanas, key=lambda s: semanas[s]) if semanas else None
    reparto: dict = {}
    de_la_ultima = [d for d in docs if d.get("semana") == ultima] if ultima else []
    for d in de_la_ultima:
        reparto[d.get("tier") or "sin tier"] = reparto.get(d.get("tier") or "sin tier", 0) + 1
    con_tier = [d for d in de_la_ultima if isinstance(d.get("tier_score"), int)]
    en_fantastic = sum(1 for d in con_tier if d["tier_score"] >= 5)
    return {
        "semanas": semanas, "total": len(docs), "cruzados": cruzados,
        "ultima_semana": ultima,
        "reparto_tiers": reparto,
        "conductores_ultima": len(de_la_ultima),
        "con_tier": len(con_tier),
        "en_fantastic_o_mejor": en_fantastic,
        "pct_fantastic_o_mejor": (round(100.0 * en_fantastic / len(con_tier), 1)
                                  if con_tier else None),
    }



# =========================
# SCORECARD EN VIVO — reportes diarios de Cortex (por centro, día a día)
#   Parsea el "Daily Report" HTML de Cortex: fallos por conductor (RTS/DNR/POD/CC)
#   + motivos de POD para coaching. Acumula la semana → proyección de tier.
#   daily_dsp: {center, date, drivers:[{transporter_id,rts,dnr,pod,cc}],
#               totals:{...}, pod_reasons:{...}, cc_reasons:{...}, uploaded_at}
# =========================

def _parse_daily_report(content: bytes, filename: str):
    html = content.decode("utf-8", errors="ignore")
    center, date = None, None
    m = re.search(r"([A-Z]{3}\d)-Daily-Report_(\d{4}-\d{2}-\d{2})", filename or "")
    if m:
        center, date = m.group(1), m.group(2)
    if not center:
        tm = re.search(r"TDSL\s+([A-Z]{3}\d)\s+Daily Report\s+(\d{4}-\d{2}-\d{2})", html)
        if tm:
            center, date = tm.group(1), tm.group(2)

    tables = re.findall(r"<table.*?</table>", html, re.S | re.I)

    def parse_rows(tbl):
        out = []
        for tr in re.findall(r"<tr.*?</tr>", tbl, re.S | re.I):
            cells = re.findall(r"<t[hd].*?</t[hd]>", tr, re.S | re.I)
            cells = [re.sub(r"\s+", " ", re.sub(r"&nbsp;", " ", re.sub(r"<[^>]+>", " ", c))).strip()
                     for c in cells]
            if any(cells):
                out.append(cells)
        return out

    def num(x):
        x = (x or "").strip()
        return int(x) if x.isdigit() else 0

    drivers, pod_reasons, cc_reasons = [], {}, {}
    for tbl in tables:
        rows = parse_rows(tbl)
        if not rows:
            continue
        # la cabecera real es la 1ª fila con >=2 celdas (las tablas empiezan
        # con una fila "Download This Table" de 1 sola celda)
        hi = next((i for i, r in enumerate(rows) if len(r) >= 2), 0)
        hdr = [c.lower() for c in rows[hi]]
        rows = rows[hi:]
        hjoin = " ".join(hdr)
        # Tabla 1: fallos por conductor
        if "transporter id" in hdr and "pod fails" in hjoin and "rts" in hdr:
            for r in rows[1:]:
                if len(r) >= 5 and re.match(r"^A[A-Z0-9]{8,}$", r[0]):
                    drivers.append({"transporter_id": r[0], "rts": num(r[1]),
                                    "dnr": num(r[2]), "pod": num(r[3]), "cc": num(r[4])})
        # Tabla 4: motivos de POD
        elif "pod audit" in hjoin:
            idx = next((i for i, h in enumerate(hdr) if "pod audit" in h), len(hdr) - 1)
            for r in rows[1:]:
                if len(r) > idx and r[idx] and r[idx] != "-":
                    pod_reasons[r[idx]] = pod_reasons.get(r[idx], 0) + 1
        # Tabla 5: motivos de Contact Compliance
        elif "cc type" in hjoin or "call duration" in hjoin:
            idx = next((i for i, h in enumerate(hdr) if "reason" in h), 2)
            for r in rows[1:]:
                if len(r) > idx and r[idx]:
                    key = r[idx].split("DELIVERED")[0].strip() or r[idx]
                    cc_reasons[key[:40]] = cc_reasons.get(key[:40], 0) + 1

    totals = {k: sum(d[k] for d in drivers) for k in ("rts", "dnr", "pod", "cc")}
    return {"center": center, "date": date, "drivers": drivers, "totals": totals,
            "pod_reasons": pod_reasons, "cc_reasons": cc_reasons}


@api_router.post("/metrics/upload-daily")
async def upload_daily_report(file: UploadFile = File(...), _=Depends(require_admin)):
    """Sube un Daily Report de Cortex (HTML). Guarda fallos por conductor del día."""
    content = await file.read()
    parsed = _parse_daily_report(content, file.filename or "")
    if not parsed.get("center") or not parsed.get("date"):
        raise HTTPException(status_code=400,
            detail="No reconozco el reporte. ¿Es un Daily Report de Cortex (HTML)?")
    if not parsed.get("drivers"):
        raise HTTPException(status_code=400, detail="No encontré la tabla de fallos por conductor")
    doc = dict(parsed)
    doc["uploaded_at"] = datetime.now(timezone.utc).isoformat()
    await db.daily_dsp.update_one(
        {"center": parsed["center"], "date": parsed["date"]}, {"$set": doc}, upsert=True)
    return {"success": True, "center": parsed["center"], "date": parsed["date"],
            "conductores": len(parsed["drivers"]), "totales": parsed["totals"]}


# Objetivos del scorecard (umbrales del tier) — los pone el usuario a mano.
# Valores por defecto orientativos; cada DSP/centro ajusta los suyos.
# Umbrales del tier Fantastic segun las guias publicas de scorecard DSP (2026).
# Amazon fija DCR y DNR a nivel de ESTACION, asi que son editables por centro
# (/scorecard/targets): esto es el punto de partida, no un dogma.
# Antes estaban en dcr 98,5 / dnr 1500 / pod 97,5 / cc 95, mas blandos que los
# reales: un DSP al 98,6 % de DCR veia "en objetivo" sin tener Fantastic.
_DEFAULT_TARGETS = {"dcr": 99.0, "dnr_dpmo": 950, "pod": 97.0, "cc": 98.0,
                    "rts_pct": 1.5, "fdds": 98.5}

# Copia inmutable de la referencia oficial. Se devuelve junto a los objetivos
# configurados para poder avisar cuando el objetivo propio es MAS BLANDO que el
# de Amazon: el cliente puede querer su propia vara, pero no por accidente.
_TARGETS_FANTASTIC = {"dcr": 99.0, "dnr_dpmo": 950, "pod": 97.0, "cc": 98.0}


@api_router.get("/scorecard/targets")
async def get_scorecard_targets(center: Optional[str] = None, _=Depends(require_admin)):
    """Objetivos (umbrales) del scorecard que el usuario define a mano."""
    doc = await db.scorecard_targets.find_one(
        {"center": center or "GLOBAL"}, {"_id": 0}) if center else None
    if not doc:
        doc = await db.scorecard_targets.find_one({"center": "GLOBAL"}, {"_id": 0})
    targets = dict(_DEFAULT_TARGETS)
    if doc:
        for k in _DEFAULT_TARGETS:
            if doc.get(k) is not None:
                targets[k] = doc[k]
    return {"center": center or "GLOBAL", "targets": targets, "default": _DEFAULT_TARGETS}


@api_router.post("/scorecard/targets")
async def set_scorecard_targets(data: dict = Body(...), _=Depends(require_admin)):
    """body: {center?, dcr, dnr_dpmo, pod, cc, rts_pct, fdds} — los que envíes."""
    center = data.get("center") or "GLOBAL"
    upd = {"center": center}
    for k in _DEFAULT_TARGETS:
        if data.get(k) is not None:
            # Antes un valor no parseable se tiraba en silencio: la pantalla
            # decia "guardado" y el objetivo seguia como estaba.
            upd[k] = _decimal(data[k], k, minimo=0)
    upd["updated_at"] = datetime.now(timezone.utc).isoformat()
    await db.scorecard_targets.update_one({"center": center}, {"$set": upd}, upsert=True)
    return {"success": True, "center": center}


def _sun_sat_week(date_iso: str):
    """Devuelve (domingo, sábado) de la semana scorecard que contiene la fecha."""
    d = datetime.strptime(date_iso, "%Y-%m-%d")
    # weekday(): lunes=0 … domingo=6. Queremos retroceder al domingo anterior.
    back = (d.weekday() + 1) % 7   # domingo->0, lunes->1, … sábado->6
    sun = d - timedelta(days=back)
    sat = sun + timedelta(days=6)
    return sun.strftime("%Y-%m-%d"), sat.strftime("%Y-%m-%d")


@api_router.get("/scorecard/week-range")
async def scorecard_week_range(date: Optional[str] = None, _=Depends(require_admin)):
    """Rango dom-sáb de la semana scorecard. Si no se pasa fecha, usa el último
    día con dato disponible (hoy-2 por el desfase de Cortex)."""
    if not date:
        date = (datetime.now(timezone.utc) - timedelta(days=2)).strftime("%Y-%m-%d")
    sun, sat = _sun_sat_week(date)
    return {"desde": sun, "hasta": sat, "data_hasta": date}


@api_router.get("/metrics/daily-week")
async def daily_week(center: str, desde: str, hasta: str, _=Depends(require_admin)):
    """Acumulado de la semana (por centro): fallos por conductor, totales,
    motivos de POD y los conductores que más arrastran el scorecard."""
    docs = await db.daily_dsp.find(
        {"center": center, "date": {"$gte": desde, "$lte": hasta}}, {"_id": 0}
    ).sort("date", 1).to_list(40)

    # nombres por transporter_id
    drv_docs = await db.drivers.find(
        {"driver_id": {"$ne": None}}, {"_id": 0, "name": 1, "driver_id": 1}).to_list(2000)
    name_by_tid = {(d.get("driver_id") or "").upper(): d.get("name") for d in drv_docs}

    by_driver = {}
    totals = {"rts": 0, "dnr": 0, "pod": 0, "cc": 0}
    pod_reasons, cc_reasons = {}, {}
    days = []
    for doc in docs:
        days.append(doc["date"])
        for k in totals:
            totals[k] += doc.get("totals", {}).get(k, 0)
        for d in doc.get("drivers", []):
            tid = (d.get("transporter_id") or "").upper()
            e = by_driver.setdefault(tid, {"transporter_id": tid,
                "name": name_by_tid.get(tid), "rts": 0, "dnr": 0, "pod": 0, "cc": 0})
            for k in ("rts", "dnr", "pod", "cc"):
                e[k] += d.get(k, 0)
        for r, n in (doc.get("pod_reasons") or {}).items():
            pod_reasons[r] = pod_reasons.get(r, 0) + n
        for r, n in (doc.get("cc_reasons") or {}).items():
            cc_reasons[r] = cc_reasons.get(r, 0) + n

    ranking = sorted(by_driver.values(),
                     key=lambda e: -(e["pod"] * 2 + e["dnr"] * 3 + e["rts"] + e["cc"]))
    top_pod = sorted(pod_reasons.items(), key=lambda x: -x[1])
    return {"center": center, "dias": days, "totals": totals,
            "ranking": ranking, "pod_reasons": top_pod,
            "cc_reasons": sorted(cc_reasons.items(), key=lambda x: -x[1])}


