def _gemini_client_plantilla():
    """Construye cliente Gemini reutilizando el mismo patrón que el resto del backend."""
    from google import genai as genai_sdk
    gemini_key = os.environ.get("GEMINI_API_KEY", "")
    use_vertex = os.environ.get("USE_VERTEX_AI", "").lower() in ("1", "true", "yes")
    if use_vertex:
        vertex_project  = os.environ.get("GCP_PROJECT", "")
        vertex_location = os.environ.get("GCP_LOCATION", "us-central1")
        sa_json = os.environ.get("GCP_SERVICE_ACCOUNT_JSON", "")
        if sa_json:
            from google.oauth2 import service_account
            import base64 as _b64
            sa_clean = sa_json.strip()
            if not sa_clean.startswith("{"):
                try:
                    sa_clean = _b64.b64decode(sa_clean).decode("utf-8")
                except Exception:
                    pass
            creds_info = json.loads(sa_clean)
            credentials = service_account.Credentials.from_service_account_info(
                creds_info, scopes=["https://www.googleapis.com/auth/cloud-platform"]
            )
            return genai_sdk.Client(
                vertexai=True, project=vertex_project,
                location=vertex_location, credentials=credentials
            )
        return genai_sdk.Client(vertexai=True, project=vertex_project, location=vertex_location)
    if not gemini_key:
        raise HTTPException(503, "GEMINI_API_KEY no configurada")
    return genai_sdk.Client(api_key=gemini_key)


def _mime_type(data: bytes) -> str:
    if data[:4] == b"\x89PNG":
        return "image/png"
    return "image/jpeg"


def _calc_horas(h_salida: str | None) -> tuple[str, str]:
    """Normaliza la hora que muestra Cortex y calcula llegada/bajada.

    h_salida ya llega normalizada desde Cortex (11:32 → 11:20).
    """
    if not h_salida:
        return "", ""
    from datetime import datetime as _dt, timedelta as _td
    for fmt in ("%H:%M", "%H.%M", "%I:%M %p", "%I:%M%p"):
        try:
            t = _dt.strptime(h_salida.strip(), fmt)
            bajada  = (_dt.combine(_dt.today(), t.time()) - _td(minutes=10)).strftime("%H:%M")
            llegada = (_dt.combine(_dt.today(), t.time()) - _td(minutes=30)).strftime("%H:%M")
            return llegada, bajada
        except ValueError:
            continue
    return "", ""


# Las olas salen cada 20 minutos y SIEMPRE en punto: xx:00, xx:20, xx:40.
# Lo dijo Mery el 03-09-2026 y es la regla de la nave.
_OLA_MINUTOS = 20


def _normalizar_hora_cortex(hora: str | None) -> str:
    """La hora de OLA a partir de la que enseña Cortex.

    Cortex muestra la hora unos minutos DESPUES de la ola. Antes se restaban 12
    minutos fijos, y eso solo acierta cuando el desfase es exactamente 12: con
    otro cualquiera la hora cae fuera de la rejilla y la plantilla sale mal. En
    una plantilla real de DGA1 (01-09-2026) 8 de 18 filas tenian horas del tipo
    11:50, que no existe como ola, y Mery las corregia a mano una por una.

    Se baja al escalon de 20 minutos, que es lo mismo que restar el desfase real
    sea cual sea (mientras este entre 0 y 20). Y NO CAMBIA NADA de lo que ya
    salia bien: si `hora - 12` caia en la rejilla, entonces los minutos eran 12
    y bajar al escalon da exactamente lo mismo. Probado en `test_plantilla_hora`.
    """
    if not hora:
        return ""
    from datetime import datetime as _dt
    for fmt in ("%H:%M", "%H.%M", "%I:%M %p", "%I:%M%p"):
        try:
            t = _dt.strptime(str(hora).strip(), fmt)
            return t.replace(minute=(t.minute // _OLA_MINUTOS) * _OLA_MINUTOS).strftime("%H:%M")
        except ValueError:
            pass
    return ""


def _build_plantilla_excel(rows: list, red_routes: set, pink_furgos: set, week_num, fecha_str: str, yellow_routes: set = None, marked_conductors: set = None, hide_nave_yard: bool = False) -> bytes:
    import openpyxl
    from openpyxl.styles import PatternFill, Font, Alignment, Border, Side
    from openpyxl.utils import get_column_letter
    from datetime import datetime as _dt
    import io

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "Plantilla Turno"

    # Colores exactos de la plantilla de referencia
    C_TITLE_BG   = "F2F2F2"   # fila título: gris muy claro
    C_TITLE_FG   = "000000"
    C_HEADER_BG  = "FFD966"   # cabeceras columnas: amarillo
    C_HEADER_FG  = "000000"   # texto negro
    C_WHITE      = "FFFFFF"   # fila normal
    C_BLUE       = "BDD7EE"   # fila ola tardía (H.WAVE >= 12:20)
    C_RED_BG     = "FF0000"   # fila "no vino"
    C_RED_FG     = "FFFFFF"
    C_PINK       = "F4CCCC"   # celda FURGO especial
    C_BORDER     = "BFBFBF"

    def fill(hex_color):
        return PatternFill("solid", fgColor=hex_color)

    def brd():
        s = Side(style="thin", color=C_BORDER)
        return Border(left=s, right=s, top=s, bottom=s)

    ca = Alignment(horizontal="center", vertical="center")
    la = Alignment(horizontal="left",   vertical="center")

    # ── Fila 2: cabeceras (nave/yard opcionales — p.ej. OGA5 no las usa) ──
    col_defs = [
        ("RUTA",               13),
        ("CONDUCTOR",          34),
        ("MOVIL",               9),
        ("FURGO",              12),
    ]
    if not hide_nave_yard:
        col_defs += [("H. LLEGADA A NAVE", 18), ("H. BAJADA AL YARD", 18)]
    col_defs += [("H. WAVE", 11), ("OBSERVACIONES", 32)]
    ncols = len(col_defs)

    # ── Fila 1: WEEK xx (izq) · fecha (der) ──
    left_end = 4 if not hide_nave_yard else 3
    ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=left_end)
    ws.merge_cells(start_row=1, start_column=left_end + 1, end_row=1, end_column=ncols)
    for cell, val, align in [
        (ws.cell(row=1, column=1),            f"WEEK {week_num}", la),
        (ws.cell(row=1, column=left_end + 1), fecha_str,          ca),
    ]:
        cell.value = val
        cell.fill  = fill(C_TITLE_BG)
        cell.font  = Font(bold=True, color=C_TITLE_FG, size=11)
        cell.alignment = align
        cell.border = brd()
    ws.row_dimensions[1].height = 22
    for i, (h, w) in enumerate(col_defs, start=1):
        cell = ws.cell(row=2, column=i, value=h)
        cell.fill  = fill(C_HEADER_BG)
        cell.font  = Font(bold=True, color=C_HEADER_FG, size=9)
        cell.alignment = ca
        cell.border = brd()
        ws.column_dimensions[get_column_letter(i)].width = w
    ws.row_dimensions[2].height = 21

    C_YELLOW      = "FFF2CC"   # amarillo clarito — marca manual
    C_MARK        = "FCE4D6"   # naranja clarito — conductor marcado (sin batch, etc.)
    C_MARK_FG     = "7B3F00"
    # Paleta de pasteles para distinguir olas — máx 6 waves distintas
    WAVE_PALETTE  = ["BDD7EE", "C6EFCE", "FFEB9C", "FCE4D6", "E2EFDA", "EAD1DC"]
    _yellow_routes     = {r.upper() for r in (yellow_routes or [])}
    _marked_conductors = {c.upper() for c in (marked_conductors or [])}

    # Mapear cada hora de wave a un color (ordenadas cronológicamente)
    _wave_times = sorted(set(
        (row.get("h_salida") or "").strip()
        for row in rows if (row.get("h_salida") or "").strip()
    ))
    _wave_color = {wt: WAVE_PALETTE[i % len(WAVE_PALETTE)] for i, wt in enumerate(_wave_times)}

    # ── Filas de datos ──
    for idx, row in enumerate(rows):
        r         = idx + 3
        ruta      = row.get("ruta")          or ""
        conductor = row.get("conductor")     or ""
        movil     = row.get("movil")         or ""
        furgo     = row.get("furgo")         or ""
        h_llegada = row.get("h_llegada")     or ""
        h_bajada  = row.get("h_bajada")      or ""
        h_wave    = row.get("h_salida") or row.get("h_wave") or ""
        obs       = row.get("observaciones") or ""

        row_key   = ruta.upper() if ruta.strip() else conductor.upper()
        is_red    = row_key in red_routes
        is_yellow = row_key in _yellow_routes

        # Ola tardía: h_llegada >= 11:50 (solo si no tiene otra marca)
        is_blue = False
        if not is_red and not is_yellow and h_llegada:
            try:
                t = _dt.strptime(h_llegada.strip(), "%H:%M").time()
                is_blue = t >= _dt.strptime("11:50", "%H:%M").time()
            except ValueError:
                pass

        if is_red:
            row_bg, row_fg = C_RED_BG, C_RED_FG
        elif is_yellow:
            row_bg, row_fg = C_YELLOW, "000000"
        elif is_blue:
            row_bg, row_fg = C_BLUE, "000000"
        else:
            row_bg, row_fg = C_WHITE, "000000"

        is_pink_furgo   = furgo.upper() in {f.upper() for f in pink_furgos}
        is_marked_cond  = conductor.upper() in _marked_conductors
        wave_time_color = _wave_color.get(h_wave.strip(), None) if h_wave else None

        if hide_nave_yard:
            cells_vals = [ruta, conductor, movil, furgo, h_wave, obs]
            wave_cols = (5,)
        else:
            cells_vals = [ruta, conductor, movil, furgo, h_llegada, h_bajada, h_wave, obs]
            wave_cols = (5, 6, 7)
        obs_col = len(cells_vals)
        for ci, val in enumerate(cells_vals, start=1):
            cell = ws.cell(row=r, column=ci, value=val)
            if ci == 4 and is_pink_furgo and not is_red:
                # FURGO especial — rosa
                cell.fill = fill(C_PINK)
                cell.font = Font(color="000000", size=9)
            elif ci == 2 and is_marked_cond and not is_red:
                # Conductor marcado — naranja clarito
                cell.fill = fill(C_MARK)
                cell.font = Font(color=C_MARK_FG, size=9, bold=True)
            elif ci in wave_cols and wave_time_color and not is_red and not is_yellow:
                # Hora de ola — color de la wave correspondiente
                cell.fill = fill(wave_time_color)
                cell.font = Font(color="000000", size=9)
            else:
                cell.fill = fill(row_bg)
                cell.font = Font(color=row_fg, size=9, bold=(ci == 1))
            cell.alignment = ca if ci not in (2, obs_col) else la
            cell.border = brd()
        ws.row_dimensions[r].height = 16

    ws.freeze_panes = "A3"
    buf = io.BytesIO()
    wb.save(buf)
    return buf.getvalue()


def _normalize_name(name: str) -> str:
    """Mayúsculas, sin tildes, sin puntuación ni puntos suspensivos."""
    import unicodedata, re
    s = unicodedata.normalize("NFD", name.upper())
    s = "".join(c for c in s if unicodedata.category(c) != "Mn")
    s = re.sub(r"[^A-Z0-9 ]", " ", s)  # quita puntos, comas, etc.
    return s


def _name_tokens(name: str) -> list:
    """Tokens de palabras >= 3 letras, ordenados por longitud desc."""
    return sorted([w for w in _normalize_name(name).split() if len(w) >= 3], key=len, reverse=True)


def _match_score(name_a: str, name_b: str) -> float:
    """
    Score entre dos nombres. Coincidencia exacta = 1.0, prefijo (>=4 chars) = 0.8.
    Maneja nombres truncados con '...' porque _normalize_name ya elimina los puntos.
    """
    tokens_a = _name_tokens(name_a)
    tokens_b = _name_tokens(name_b)
    score = 0.0
    used_b = set()
    for ta in tokens_a:
        for i, tb in enumerate(tokens_b):
            if i in used_b:
                continue
            if ta == tb:
                score += 1.0
                used_b.add(i)
                break
            short, long_ = (ta, tb) if len(ta) <= len(tb) else (tb, ta)
            if len(short) >= 4 and long_.startswith(short):
                score += 0.8
                used_b.add(i)
                break
    return score


def _is_transient_gemini(err_str: str) -> bool:
    """503/500/UNAVAILABLE/overloaded/deadline: el modelo está saturado o lento,
    no es un problema de cuota. Conviene saltar a otro modelo o reintentar."""
    e = err_str.lower()
    return any(k in e for k in ("503", "500", "unavailable", "overloaded",
                                "high demand", "deadline", "timeout", "internal"))


async def _gemini_json_call(client, model_name: str, contents: list) -> dict:
    """Llamada a Gemini que devuelve JSON, resistente a cuota y saturación.
    Cadena de respaldo con dos motivos de salto:
      · cuota DIARIA agotada (429 per-day) → veta ese modelo y pasa al siguiente.
      · saturación/lentitud (503/500/UNAVAILABLE) → pasa al siguiente al instante.
    flash-lite suele estar menos saturado y responde rápido."""
    from google.genai import types as genai_types
    # thinking_budget=0: leer/parsear es factual, no necesita razonamiento largo.
    try:
        cfg = genai_types.GenerateContentConfig(
            temperature=0.0,
            thinking_config=genai_types.ThinkingConfig(thinking_budget=0))
    except Exception:
        cfg = genai_types.GenerateContentConfig(temperature=0.0)
    chain = [model_name, "gemini-2.5-flash-lite", "gemini-flash-latest", "gemini-flash-lite-latest"]
    seen, models = set(), []
    for m in chain:
        if m and m not in seen:
            seen.add(m); models.append(m)
    last_err = None
    for attempt in range(2):  # 2ª vuelta por si TODOS estaban saturados un instante
        for m in models:
            if _is_daily_exhausted(m):
                continue
            try:
                resp = await asyncio.wait_for(
                    asyncio.to_thread(lambda mm=m: client.models.generate_content(
                        model=mm, contents=contents, config=cfg)),
                    timeout=45)
                return json.loads(_strip_markdown_json((resp.text or "").strip()))
            except json.JSONDecodeError:
                raise
            except Exception as e:
                last_err = e
                es = str(e)
                if "429" in es and _is_perday_429(es):
                    _mark_daily_exhausted(m)
                continue  # 429/503/lento/otros → siguiente modelo
        if attempt == 0:
            await asyncio.sleep(2)
    raise last_err or RuntimeError("Gemini no disponible ahora mismo (saturación/cuota)")


async def _gemini_extract(client, model_name: str, prompt: str, img_bytes: bytes) -> dict:
    from google.genai import types as genai_types
    part = genai_types.Part.from_bytes(data=img_bytes, mime_type=_mime_type(img_bytes))
    return await _gemini_json_call(client, model_name, [prompt, part])


async def _gemini_extract_text(client, model_name: str, prompt: str, text: str) -> dict:
    """Igual que _gemini_extract pero desde TEXTO pegado en vez de captura."""
    full = (prompt + "\n\n=== EN VEZ DE UNA IMAGEN, ANALIZA ESTE TEXTO PEGADO "
            "(mismas reglas y mismo JSON de salida) ===\n" + (text or "").strip()[:20000])
    return await _gemini_json_call(client, model_name, [full])


# ── Paso 1: extraer datos con Gemini, devuelve JSON para preview ──
@app.post("/api/tools/plantilla-extraer", dependencies=[Depends(require_admin)])
async def plantilla_extraer(request: Request):
    # Lectura en crudo del multipart: acepta imágenes y/o texto sin que la
    # validación de FastAPI rechace combinaciones (imagen sola, texto solo, mezcla).
    form = await request.form()

    async def _read_files(field):
        out = []
        for f in form.getlist(field):
            if hasattr(f, "read"):
                b = await f.read()
                if b:
                    out.append(b)
        return out

    plat_imgs   = await _read_files("plataforma")
    cortex_imgs = await _read_files("cortex")
    plat_txt    = (str(form.get("plataforma_texto") or "")).strip()
    cortex_txt  = (str(form.get("cortex_texto") or "")).strip()

    if not plat_imgs and not plat_txt:
        raise HTTPException(400, "Aporta las furgonetas de plataforma: sube una captura o pega el texto.")

    client     = _gemini_client_plantilla()
    model_name = os.environ.get("GEMINI_MODEL", "gemini-2.5-flash")

    # Cada fuente (imagen o texto) es una tarea. Cortex primero, plataforma después.
    cortex_tasks = [_gemini_extract(client, model_name, _PROMPT_CORTEX, b) for b in cortex_imgs]
    if cortex_txt:
        cortex_tasks.append(_gemini_extract_text(client, model_name, _PROMPT_CORTEX, cortex_txt))
    plat_tasks = [_gemini_extract(client, model_name, _PROMPT_PLATAFORMA, b) for b in plat_imgs]
    if plat_txt:
        plat_tasks.append(_gemini_extract_text(client, model_name, _PROMPT_PLATAFORMA, plat_txt))

    # return_exceptions: que un fallo puntual en UNA fuente no tumbe todo el proceso.
    all_results = await asyncio.gather(*(cortex_tasks + plat_tasks), return_exceptions=True)
    clean, n_fail = [], 0
    for r in all_results:
        if isinstance(r, Exception):
            n_fail += 1
            logger.warning(f"plantilla_extraer: una fuente falló: {r}")
            clean.append({})
        else:
            clean.append(r)
    if n_fail and n_fail == len(all_results):
        raise HTTPException(503, "La IA no está disponible ahora mismo (saturación/cuota). Inténtalo en un minuto.")

    nc = len(cortex_tasks)
    cortex_results = clean[:nc]
    plat_results   = clean[nc:]

    from datetime import date as _date

    week_num  = _date.today().isocalendar()[1]
    fecha_str = _date.today().strftime("%d/%m/%Y")

    # Combinar datos Cortex (dedup por ruta)
    rutas_map: dict = {}
    for cd in cortex_results:
        if cd.get("week"):
            week_num = cd["week"]
        if cd.get("date"):
            fecha_str = cd["date"]
        for r in cd.get("rutas", []):
            key = (r.get("ruta") or "").strip()
            if key and key not in rutas_map:
                rutas_map[key] = r

    # Combinar datos plataforma (dedup por conductor)
    asignaciones: list = []
    seen_conductores: set = set()
    for pd in plat_results:
        for a in pd.get("asignaciones", []):
            nombre = _normalize_name(a.get("conductor") or "")
            if nombre and nombre not in seen_conductores:
                seen_conductores.add(nombre)
                asignaciones.append(a)

    rows_out = []

    if rutas_map:
        # MODO COMPLETO: Cortex + Plataforma → cruce por nombre
        for ruta_key in sorted(rutas_map):
            ruta_row  = rutas_map[ruta_key]
            conductor = ruta_row.get("conductor") or ""
            # Cortex adelanta doce minutos la hora visible; la plantilla trabaja
            # con la hora real en intervalos de diez minutos.
            h_salida  = _normalizar_hora_cortex(ruta_row.get("h_salida"))

            furgo = ""
            movil = ""
            best_score = 0.0
            best_asig  = None
            for asig in asignaciones:
                sc = _match_score(conductor, asig.get("conductor") or "")
                if sc > best_score:
                    best_score = sc
                    best_asig  = asig

            if best_asig and best_score >= 0.8:
                furgo = (best_asig.get("furgo") or "").replace(" ", "")
                movil = best_asig.get("movil") or ""
                # Complementar: el nombre COMPLETO viene de plataforma (Cortex lo
                # muestra truncado). Solo si el de plataforma es más largo/completo.
                plat_name = (best_asig.get("conductor") or "").strip()
                if plat_name and len(plat_name) >= len(conductor.replace(".", "").strip()):
                    conductor = plat_name

            h_llegada, h_bajada = _calc_horas(h_salida)
            rows_out.append({
                "ruta":          ruta_key,
                "conductor":     conductor,
                "movil":         movil,
                "furgo":         furgo,
                "h_salida":      h_salida,
                "h_bajada":      h_bajada,
                "h_llegada":     h_llegada,
                "observaciones": "",
            })
    else:
        # MODO SOLO PLATAFORMA: una fila por conductor, ruta vacía para rellenar a mano
        for asig in asignaciones:
            rows_out.append({
                "ruta":          "",
                "conductor":     asig.get("conductor") or "",
                "movil":         asig.get("movil") or "",
                "furgo":         (asig.get("furgo") or "").replace(" ", ""),
                "h_salida":      "",
                "h_bajada":      "",
                "h_llegada":     "",
                "observaciones": "",
            })

    return {"week": week_num, "date": fecha_str, "rows": rows_out}


# ── Paso 2: generar Excel con rutas rojas elegidas por el usuario ──
_HORA_RE = re.compile(r"^([01]?\d|2[0-3]):[0-5]\d$")


def _plantilla_validar_filas(rows: list, conductores: list, matriculas: dict, rutas_cortex: dict) -> list:
    """Que cada fila de la plantilla cuadre con lo que la empresa YA sabe.

    La plantilla sale de leer capturas con la IA, y de vez en cuando se cuela
    una hora imposible, un nombre mal leido o una matricula que no existe. Eso
    no se puede impedir en la lectura; se puede CAZAR antes de que salga la
    plantilla, comparando con tres cosas que ya son verdad en la base:
      · los conductores de la empresa (nombre normalizado y por tokens),
      · las furgonetas de la flota (matricula normalizada),
      · lo que Cortex dice de HOY (ruta -> conductor), si la extension ya lo
        capturo: es la fuente sin OCR y manda cuando discrepa.
    Devuelve avisos con sugerencia; no cambia nada solo. Pura, sin base de
    datos: `test_plantilla_validar.py`.

    `conductores`: [{"name", "transporter_id"}]; `matriculas`: {normalizada:
    original}; `rutas_cortex`: {ruta: nombre del conductor segun Cortex}.
    """
    avisos = []
    vistos_c: dict = {}
    vistos_f: dict = {}
    nombres_norm = [(c.get("name") or "", _normalize_name(c.get("name") or "").strip()) for c in conductores if c.get("name")]
    for i, r in enumerate(rows or []):
        if not isinstance(r, dict):
            continue
        conductor = (r.get("conductor") or "").strip()
        ruta = (r.get("ruta") or "").strip()
        furgo = _matricula_norm(r.get("furgo"))
        h_salida = (r.get("h_salida") or "").strip()

        # 1. La ruta la lleva quien dice Cortex, no quien leyo la IA.
        if ruta and rutas_cortex.get(ruta) and conductor:
            if _match_score(conductor, rutas_cortex[ruta]) < 0.8:
                avisos.append({"fila": i, "campo": "conductor", "tipo": "ruta_cortex",
                               "texto": "Cortex dice que la %s la lleva %s" % (ruta, rutas_cortex[ruta]),
                               "sugerencia": rutas_cortex[ruta]})
        # 2. El nombre existe en la empresa (o se parece a uno).
        if conductor:
            n = _normalize_name(conductor).strip()
            exacto = any(n == nn for _, nn in nombres_norm)
            if not exacto:
                mejor, mejor_sc = None, 0.0
                for original, _ in nombres_norm:
                    sc = _match_score(conductor, original)
                    if sc > mejor_sc:
                        mejor, mejor_sc = original, sc
                if mejor and mejor_sc >= 0.8:
                    if _normalize_name(mejor).strip() != n:
                        avisos.append({"fila": i, "campo": "conductor", "tipo": "nombre_parecido",
                                       "texto": "En la empresa figura como %s" % mejor,
                                       "sugerencia": mejor})
                else:
                    avisos.append({"fila": i, "campo": "conductor", "tipo": "nombre_desconocido",
                                   "texto": "No hay ningún conductor con ese nombre", "sugerencia": None})
            if n in vistos_c:
                avisos.append({"fila": i, "campo": "conductor", "tipo": "repetido",
                               "texto": "Ya está en la fila %d" % (vistos_c[n] + 1), "sugerencia": None})
            else:
                vistos_c[n] = i
        # 3. La matricula existe en la flota (o se parece a una).
        if furgo:
            if furgo not in matriculas:
                import difflib
                cerca = difflib.get_close_matches(furgo, list(matriculas), n=1, cutoff=0.75)
                avisos.append({"fila": i, "campo": "furgo", "tipo": "matricula_desconocida",
                               "texto": "Esa matrícula no está en la flota",
                               "sugerencia": matriculas[cerca[0]] if cerca else None})
            if furgo in vistos_f:
                avisos.append({"fila": i, "campo": "furgo", "tipo": "repetido",
                               "texto": "Ya va en la fila %d" % (vistos_f[furgo] + 1), "sugerencia": None})
            else:
                vistos_f[furgo] = i
        # 4. Horas: formato, rango de una ola de reparto y coherencia con salida.
        if h_salida:
            if not _HORA_RE.match(h_salida):
                avisos.append({"fila": i, "campo": "h_salida", "tipo": "hora_invalida",
                               "texto": "La hora no tiene forma de hora (HH:MM)", "sugerencia": None})
            else:
                hh = int(h_salida.split(":")[0])
                if hh < 5 or hh > 16:
                    avisos.append({"fila": i, "campo": "h_salida", "tipo": "hora_rara",
                                   "texto": "Una salida a las %s no es de ninguna ola" % h_salida,
                                   "sugerencia": None})
                # Solo lo IMPOSIBLE: llegada a nave y bajada al yard van antes de la
                # salida, a menos de hora y media, y la llegada antes que la bajada.
                # Medido en 151 filas reales: el 67 % usa -30/-10, pero DGA1 usa
                # -40/-20 a proposito; avisar de eso en cada fila seria un aviso
                # que grita en falso y deja de leerse. Lo que si se vio son 42
                # filas con la bajada DESPUES de la salida: eso si es un error.
                llegada_std, bajada_std = _calc_horas(h_salida)
                sm = int(h_salida.split(":")[0]) * 60 + int(h_salida.split(":")[1])
                def _min(v):
                    return int(v.split(":")[0]) * 60 + int(v.split(":")[1])
                lleg = (r.get("h_llegada") or "").strip()
                baj = (r.get("h_bajada") or "").strip()
                for campo, val, esperado in (("h_llegada", lleg, llegada_std), ("h_bajada", baj, bajada_std)):
                    if val and _HORA_RE.match(val):
                        vm = _min(val)
                        if vm >= sm or sm - vm > 90:
                            avisos.append({"fila": i, "campo": campo, "tipo": "hora_incoherente",
                                           "texto": "Tiene que ser antes de la salida (%s) y a menos de hora y media" % h_salida,
                                           "sugerencia": esperado})
                if lleg and baj and _HORA_RE.match(lleg) and _HORA_RE.match(baj) and _min(lleg) >= _min(baj):
                    avisos.append({"fila": i, "campo": "h_llegada", "tipo": "hora_incoherente",
                                   "texto": "La llegada a nave va después de la bajada al yard",
                                   "sugerencia": llegada_std})
        elif ruta:
            avisos.append({"fila": i, "campo": "h_salida", "tipo": "hora_falta",
                           "texto": "La ruta no tiene hora de salida", "sugerencia": None})
    return avisos


@app.post("/api/tools/plantilla-validar", dependencies=[Depends(require_admin)])
async def plantilla_validar(data: dict = Body(...), user: dict = Depends(require_admin)):
    """Avisos de la plantilla contra la empresa y contra Cortex, con sugerencia."""
    rows = data.get("rows") or []
    center = (data.get("center") or "").strip()
    fecha = (data.get("date") or "").strip()
    # dd/mm/aaaa -> aaaa-mm-dd, que es como Cortex guarda el dia.
    dia = fecha
    m = re.match(r"^(\d{2})/(\d{2})/(\d{4})$", fecha)
    if m:
        dia = "%s-%s-%s" % (m.group(3), m.group(2), m.group(1))
    fc = _filtro_centro(user, center) if center and center != "Todos" else {}
    conductores = await db.drivers.find(
        {"active": {"$ne": False}, **fc}, {"_id": 0, "name": 1, "transporter_id": 1}).to_list(2000)
    matriculas = {}
    async for v in db.vehicles.find({"status": {"$nin": ["deleted", "baja"]}, **fc},
                                    {"_id": 0, "license_plate": 1}):
        n = _matricula_norm(v.get("license_plate"))
        if n:
            matriculas[n] = v.get("license_plate")
    rutas_cortex: dict = {}
    if dia:
        # Hay un resumen POR ESTACION y dia: se juntan todos, que la plantilla
        # de DGA1 no se compare con las rutas de OGA5.
        async for res in db.cortex_resumen.find({"dia": dia}, {"_id": 0, "rutas": 1, "gente": 1}):
            nombres = {g.get("transporterId"): g.get("nombre") for g in (res.get("gente") or []) if g.get("nombre")}
            for r in res.get("rutas") or []:
                nom = nombres.get(r.get("transporterId"))
                if r.get("routeCode") and nom:
                    rutas_cortex[r["routeCode"]] = nom
    avisos = _plantilla_validar_filas(rows, conductores, matriculas, rutas_cortex)
    return {"avisos": avisos, "con_cortex": bool(rutas_cortex), "dia": dia,
            "resumen": {"filas": len(rows), "con_aviso": len({a["fila"] for a in avisos})}}


@app.post("/api/tools/plantilla-excel", dependencies=[Depends(require_admin)])
async def plantilla_excel(body: dict = Body(...), admin=Depends(require_admin)):
    from datetime import date as _date

    rows               = body.get("rows", [])
    red_routes         = {r.upper() for r in body.get("red_routes",         [])}
    pink_furgos        = {f.upper() for f in body.get("pink_furgos",        [])}
    yellow_routes      = {r.upper() for r in body.get("yellow_routes",      [])}
    marked_conductors  = {c.upper() for c in body.get("marked_conductors",  [])}
    week_num           = body.get("week")  or _date.today().isocalendar()[1]
    fecha_str          = body.get("date")  or _date.today().strftime("%d/%m/%Y")
    save_to_hist       = body.get("save", False)
    center             = body.get("center", "")

    # Verificar acceso al centro antes de guardar en historial
    if center and center != "Todos":
        allowed = admin.get("allowed_centers") or []
        if allowed and center not in allowed:
            raise HTTPException(403, "Sin acceso a este centro")

    import io
    hide_nave_yard = bool(body.get("hide_nave_yard"))
    xlsx = _build_plantilla_excel(rows, red_routes, pink_furgos, week_num, fecha_str, yellow_routes, marked_conductors, hide_nave_yard)
    # Sanitizar fecha para uso seguro en nombre de archivo y header HTTP
    safe_fecha = re.sub(r'[^a-zA-Z0-9_\-]', '-', fecha_str)
    safe_week  = re.sub(r'[^a-zA-Z0-9_\-]', '-', str(week_num))
    filename = f"plantilla_turno_w{safe_week}_{safe_fecha}.xlsx"

    # Guardar en historial si se pide y hay centro especificado
    if save_to_hist and center and center != "Todos":
        try:
            from uuid import uuid4 as _uuid4
            r2 = get_r2()
            if r2:
                r2_key = f"plantillas/{center}/{filename}"
                r2.put_object(
                    Bucket=R2_BUCKET, Key=r2_key, Body=xlsx,
                    ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                )
                meta = {
                    "id": str(_uuid4()),
                    "center": center,
                    "date": fecha_str,
                    "week": str(week_num),
                    "r2_key": r2_key,
                    "filename": filename,
                    "uploaded_at": datetime.now(timezone.utc).isoformat(),
                }
                await db.plantillas_diarias.insert_one(meta)
        except Exception as _e:
            logger.warning(f"plantilla_excel: no se pudo guardar historial: {_e}")

    return StreamingResponse(
        io.BytesIO(xlsx),
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f"attachment; filename=\"{filename}\""},
    )


# ── Borradores compartidos de plantilla (edición simultánea) ──
def _plantilla_shared_payload(doc: dict) -> dict:
    """Respuesta pública, sin ObjectId interno de Mongo."""
    return {k: doc.get(k) for k in (
        "id", "center", "state", "revision", "updated_at", "updated_by"
    )}


@app.post("/api/tools/plantilla-compartida", dependencies=[Depends(require_admin)])
async def crear_plantilla_compartida(body: dict = Body(...), admin=Depends(require_admin)):
    center = str(body.get("center") or "").strip()
    if not center or center == "Todos":
        raise HTTPException(400, "Selecciona un centro antes de compartir una plantilla.")
    allowed = admin.get("allowed_centers") or []
    if allowed and center not in allowed:
        raise HTTPException(403, "Sin acceso a este centro")
    state = body.get("state") or {}
    if not isinstance(state, dict) or not isinstance(state.get("rows"), list):
        raise HTTPException(400, "Borrador de plantilla inválido.")
    now = datetime.now(timezone.utc).isoformat()
    doc = {"id": str(uuid.uuid4()), "center": center, "state": state,
           "revision": 1, "updated_at": now, "updated_by": admin.get("name") or "Usuario"}
    await db.plantillas_compartidas.insert_one(doc)
    return _plantilla_shared_payload(doc)


@app.get("/api/tools/plantilla-compartida/{draft_id}", dependencies=[Depends(require_admin)])
async def leer_plantilla_compartida(draft_id: str, admin=Depends(require_admin)):
    doc = await db.plantillas_compartidas.find_one({"id": draft_id}, {"_id": 0})
    if not doc:
        raise HTTPException(404, "La plantilla compartida ya no existe.")
    allowed = admin.get("allowed_centers") or []
    if allowed and doc.get("center") not in allowed:
        raise HTTPException(403, "Sin acceso a este centro")
    return _plantilla_shared_payload(doc)


@app.get("/api/tools/plantilla-compartida", dependencies=[Depends(require_admin)])
async def plantilla_compartida_activa(center: str, admin=Depends(require_admin)):
    """Devuelve el último borrador reciente del centro para que otro equipo se una."""
    allowed = admin.get("allowed_centers") or []
    if allowed and center not in allowed:
        raise HTTPException(403, "Sin acceso a este centro")
    cutoff = (datetime.now(timezone.utc) - timedelta(hours=18)).isoformat()
    doc = await db.plantillas_compartidas.find_one(
        {"center": center, "updated_at": {"$gte": cutoff}}, {"_id": 0}, sort=[("updated_at", -1)])
    return _plantilla_shared_payload(doc) if doc else {"id": None}


@app.delete("/api/tools/plantilla-compartida/{draft_id}", dependencies=[Depends(require_admin)])
async def cerrar_plantilla_compartida(draft_id: str, admin=Depends(require_admin)):
    """Cierra el borrador compartido del centro ("Nueva plantilla"): lo borra para
    TODOS los dispositivos. Sin esto, el auto-join re-enganchaba al borrador viejo
    y el botón de crear una nueva parecía no funcionar."""
    doc = await db.plantillas_compartidas.find_one({"id": draft_id}, {"_id": 0})
    if not doc:
        return {"ok": True}  # ya no existe: objetivo cumplido
    allowed = admin.get("allowed_centers") or []
    if allowed and doc.get("center") not in allowed:
        raise HTTPException(403, "Sin acceso a este centro")
    # Borra todos los borradores del centro (evita que resucite uno anterior <18h)
    await db.plantillas_compartidas.delete_many({"center": doc["center"]})
    return {"ok": True}


@app.put("/api/tools/plantilla-compartida/{draft_id}", dependencies=[Depends(require_admin)])
async def guardar_plantilla_compartida(draft_id: str, body: dict = Body(...), admin=Depends(require_admin)):
    """YA NO SE GUARDA LA HOJA ENTERA. Nunca. Ni con la revision al dia.

    Esta era la puerta por la que se borraba el trabajo de la otra persona
    (Mery y Judit). El control de version no bastaba: guardar UNA celda devuelve
    la revision nueva y el cliente se la queda sin recargar los datos, asi que
    su siguiente guardado completo pasaba la comprobacion y pisaba lo de la otra
    con un HTTP 200 limpio. Reproducido contra produccion el 04-09-2026.

    Se deja la ruta a proposito, en vez de borrarla: un despliegue no cierra el
    navegador de nadie, y la pantalla que Mery tenga abierta desde por la manana
    seguira mandando esto durante horas. Con un 409 esa pestana hace lo que ya
    sabe hacer —recargar la hoja del servidor— y como mucho pierde SU ultimo
    clic, nunca el trabajo de la otra. Cada cambio va ahora por su operacion:
    `/celda`, `/marca`, `/fila`, `/meta` y `/horas`.
    """
    doc = await db.plantillas_compartidas.find_one({"id": draft_id}, {"_id": 0})
    if not doc:
        raise HTTPException(404, "La plantilla compartida ya no existe.")
    allowed = admin.get("allowed_centers") or []
    if allowed and doc.get("center") not in allowed:
        raise HTTPException(403, "Sin acceso a este centro")
    raise HTTPException(409, detail={
        "message": "Recarga la pagina (F5): esta pantalla es de una version anterior "
                   "y guardaba la plantilla entera, que es lo que borraba el trabajo "
                   "de la otra persona.",
        "draft": _plantilla_shared_payload(doc)})


# ── Historial de plantillas ──
# Campos de una fila de la plantilla que se pueden tocar celda a celda.
_PLANTILLA_CELDAS = ("ruta", "conductor", "movil", "furgo",
                     "h_salida", "h_bajada", "h_llegada", "observaciones")


@api_router.patch("/tools/plantilla-compartida/{draft_id}/celda")
async def plantilla_compartida_celda(draft_id: str, body: dict = Body(...), admin=Depends(require_admin)):
    """Cambia UNA celda de la plantilla compartida.

    EL PORQUE (Mery y Judit, 03-09-2026): «si una esta escribiendo y la otra
    escribe se borra todo lo anterior». Pasaba porque cada una guardaba la HOJA
    ENTERA: la ultima en guardar pisaba las celdas de la otra, y el refresco de
    cada 2,5 s sustituia la hoja completa incluso mientras se escribia.
    Guardando celda a celda, dos personas solo pueden chocar si tocan LA MISMA
    celda; en cualquier otro caso los dos cambios conviven.

    Aqui NO se comprueba la revision a proposito: en una celda el ultimo cambio
    es el bueno. Lo que se comprueba es que la fila siga siendo la misma
    (`ruta_ref`), porque si alguien anadio o quito filas los indices bailan y el
    cambio caeria en la fila equivocada — eso si seria un dato falso.
    """
    fila = body.get("fila")
    campo = body.get("campo")
    if not isinstance(fila, int) or fila < 0 or campo not in _PLANTILLA_CELDAS:
        raise HTTPException(400, "Fila o campo no validos")
    valor = str(body.get("valor") or "")[:300]
    ruta_ref = body.get("ruta_ref")
    filtro: dict = {"id": draft_id, "state.rows.%d" % fila: {"$exists": True}}
    if isinstance(ruta_ref, str):
        filtro["state.rows.%d.ruta" % fila] = ruta_ref
    ahora = datetime.now(timezone.utc).isoformat()
    r = await db.plantillas_compartidas.update_one(
        filtro,
        {"$set": {"state.rows.%d.%s" % (fila, campo): valor,
                  "updated_at": ahora, "updated_by": admin.get("name") or "Usuario"},
         "$inc": {"revision": 1}})
    if not r.matched_count:
        doc = await db.plantillas_compartidas.find_one({"id": draft_id}, {"_id": 0})
        if not doc:
            raise HTTPException(404, "Esa plantilla ya no existe")
        # La fila se movio: el cliente se recarga y vuelve a intentarlo.
        raise HTTPException(409, detail={"message": "Las filas han cambiado, se recarga la plantilla.",
                                         "draft": _plantilla_shared_payload(doc)})
    doc = await db.plantillas_compartidas.find_one({"id": draft_id}, {"_id": 0})
    return _plantilla_shared_payload(doc)


# ── LO QUE NO ES UNA CELDA TAMBIEN TIENE QUE VIAJAR SOLO ──────────────────────
# Mery, 04-09-2026: «lo de las horas si, lo de hacer cambios las dos a la vez
# no». Y tenia razon. El arreglo del 03-09 solo cubrio ESCRIBIR en una celda;
# todo lo demas de esta pantalla —marcar una ruta en rojo o amarillo, una furgo
# en rosa, un conductor, anadir o quitar una fila, pegar las horas en todas—
# seguia guardando la HOJA ENTERA.
#
# Y el control de version no salvaba nada, por un motivo que no se ve leyendo el
# codigo: el guardado de UNA celda devuelve la revision nueva y el cliente se la
# queda, pero NO recarga la hoja. Asi que despues de escribir su propia celda,
# el cliente tiene la revision al dia y los datos viejos: su siguiente guardado
# completo pasa la comprobacion y pisa a la otra persona con un 200 limpio.
#
# Reproducido contra produccion el 04-09-2026, en este orden exacto:
#   1. Mery escribe en la fila 0        -> revision 2
#   2. Judit escribe en la fila 1       -> revision 3 (Judit se queda con la 3)
#   3. Judit marca una ruta en rojo     -> PUT de la hoja entera con revision 3
#   4. la fila 0 vuelve a estar VACIA, con HTTP 200 y sin ningun aviso
#
# Por eso cada cosa tiene aqui su propia operacion, y todas son de las que no
# pueden pisarse: conjuntos con $addToSet/$pull, filas con $push, y campos
# sueltos con $set. La hoja entera solo se manda al CREAR el borrador.
_PLANTILLA_MARCAS = ("red_routes", "yellow_routes", "pink_furgos", "marked_conductors")
_PLANTILLA_HORAS = ("h_salida", "h_bajada", "h_llegada")
_PLANTILLA_META = ("week", "date")
_PLANTILLA_MAX_FILAS = 300


async def _plantilla_doc(draft_id: str, admin: dict) -> dict:
    doc = await db.plantillas_compartidas.find_one({"id": draft_id}, {"_id": 0})
    if not doc:
        raise HTTPException(404, "Esa plantilla ya no existe")
    permitidos = admin.get("allowed_centers") or []
    if permitidos and doc.get("center") not in permitidos:
        raise HTTPException(403, "Sin acceso a este centro")
    return doc


async def _plantilla_tocada(draft_id: str, cambios: dict, admin: dict, extra: dict = None) -> dict:
    """Aplica un cambio pequeno y devuelve la plantilla ya guardada."""
    orden = {"$set": {**cambios,
                      "updated_at": datetime.now(timezone.utc).isoformat(),
                      "updated_by": admin.get("name") or "Usuario"},
             "$inc": {"revision": 1}}
    if extra:
        orden.update(extra)
    await db.plantillas_compartidas.update_one({"id": draft_id}, orden)
    doc = await db.plantillas_compartidas.find_one({"id": draft_id}, {"_id": 0})
    return _plantilla_shared_payload(doc or {})


@api_router.patch("/tools/plantilla-compartida/{draft_id}/marca")
async def plantilla_compartida_marca(draft_id: str, body: dict = Body(...),
                                     admin=Depends(require_admin)):
    """Pone o quita UNA marca de color. `$addToSet`/`$pull`, nunca la lista entera.

    Dos personas marcando cosas distintas no pueden pisarse, y marcar dos veces
    lo mismo tampoco rompe nada: es justo lo que dan estas dos operaciones.
    """
    await _plantilla_doc(draft_id, admin)
    tipo = str(body.get("tipo") or "")
    if tipo not in _PLANTILLA_MARCAS:
        raise HTTPException(400, "Marca desconocida")
    valor = str(body.get("valor") or "").strip()[:120]
    if not valor:
        raise HTTPException(400, "Falta que marcar")
    campo = "state.%s" % tipo
    ahora = datetime.now(timezone.utc).isoformat()
    op = "$addToSet" if body.get("activo") else "$pull"
    await db.plantillas_compartidas.update_one(
        {"id": draft_id},
        {op: {campo: valor},
         "$set": {"updated_at": ahora, "updated_by": admin.get("name") or "Usuario"},
         "$inc": {"revision": 1}})
    doc = await db.plantillas_compartidas.find_one({"id": draft_id}, {"_id": 0})
    return _plantilla_shared_payload(doc or {})


@api_router.post("/tools/plantilla-compartida/{draft_id}/fila")
async def plantilla_compartida_anadir_fila(draft_id: str, admin=Depends(require_admin)):
    """Anade una fila vacia al final. Con `$push`: si las dos anaden, salen dos."""
    doc = await _plantilla_doc(draft_id, admin)
    if len((doc.get("state") or {}).get("rows") or []) >= _PLANTILLA_MAX_FILAS:
        raise HTTPException(400, "Esta plantilla ya tiene demasiadas filas")
    vacia = {c: "" for c in _PLANTILLA_CELDAS}
    return await _plantilla_tocada(draft_id, {}, admin, {"$push": {"state.rows": vacia}})


@api_router.delete("/tools/plantilla-compartida/{draft_id}/fila/{fila}")
async def plantilla_compartida_quitar_fila(draft_id: str, fila: int, ruta_ref: str = "",
                                           admin=Depends(require_admin)):
    """Quita una fila. Comprueba que sigue siendo LA MISMA antes de tocarla.

    Sin `ruta_ref`, si la otra persona anadio o quito filas entre medias, los
    indices bailan y se borraria la fila equivocada: un dato falso, que es peor
    que un error.
    """
    doc = await _plantilla_doc(draft_id, admin)
    filas = list((doc.get("state") or {}).get("rows") or [])
    if fila < 0 or fila >= len(filas):
        raise HTTPException(409, "Esa fila ya no existe")
    if ruta_ref and str(filas[fila].get("ruta") or "") != ruta_ref:
        raise HTTPException(409, "Las filas han cambiado, se recarga la plantilla")
    del filas[fila]
    return await _plantilla_tocada(draft_id, {"state.rows": filas}, admin)


@api_router.patch("/tools/plantilla-compartida/{draft_id}/meta")
async def plantilla_compartida_meta(draft_id: str, body: dict = Body(...),
                                    admin=Depends(require_admin)):
    """La semana y la fecha de la cabecera, cada una por su lado."""
    await _plantilla_doc(draft_id, admin)
    cambios = {"state.%s" % k: str(body.get(k) or "")[:40]
               for k in _PLANTILLA_META if k in body}
    if not cambios:
        raise HTTPException(400, "Nada que cambiar")
    return await _plantilla_tocada(draft_id, cambios, admin)


@api_router.patch("/tools/plantilla-compartida/{draft_id}/horas")
async def plantilla_compartida_horas(draft_id: str, body: dict = Body(...),
                                     admin=Depends(require_admin)):
    """Pega las mismas horas en TODAS las filas, sin tocar el resto de campos.

    Es el unico cambio que toca muchas filas de golpe, y aun asi solo escribe
    las tres horas: lo que haya escrito la otra persona en conductor, movil o
    furgo se queda como esta.
    """
    doc = await _plantilla_doc(draft_id, admin)
    filas = (doc.get("state") or {}).get("rows") or []
    horas = {h: str(body.get(h) or "")[:20] for h in _PLANTILLA_HORAS if body.get(h)}
    if not horas:
        raise HTTPException(400, "No hay horas que pegar")
    cambios = {}
    for i in range(len(filas)):
        for h, v in horas.items():
            cambios["state.rows.%d.%s" % (i, h)] = v
    return await _plantilla_tocada(draft_id, cambios, admin)


@api_router.get("/plantillas")
async def list_plantillas(center: str = None, admin=Depends(require_admin)):
    allowed = admin.get("allowed_centers") or []
    query: dict = {}
    if center and center != "Todos":
        if allowed and center not in allowed:
            raise HTTPException(403, "Sin acceso a este centro")
        query["center"] = center
    elif allowed:
        query["center"] = {"$in": allowed}
    docs = await db.plantillas_diarias.find(query).sort("uploaded_at", -1).to_list(500)
    for d in docs:
        d.pop("_id", None)
    return docs


@api_router.get("/plantillas/{plantilla_id}/download")
async def download_plantilla(plantilla_id: str, _=Depends(require_admin)):
    doc = await db.plantillas_diarias.find_one({"id": plantilla_id})
    if not doc:
        raise HTTPException(404, "Plantilla no encontrada")
    r2 = get_r2()
    if not r2:
        raise HTTPException(503, "R2 no disponible")
    try:
        obj = r2.get_object(Bucket=R2_BUCKET, Key=doc["r2_key"])
        content = obj["Body"].read()
    except Exception as e:
        raise HTTPException(500, f"Error al recuperar el archivo: {e}")
    import io
    return StreamingResponse(
        io.BytesIO(content),
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f"attachment; filename=\"{doc['filename']}\""},
    )


@api_router.delete("/plantillas/{plantilla_id}")
async def delete_plantilla(plantilla_id: str, _=Depends(require_admin)):
    doc = await db.plantillas_diarias.find_one({"id": plantilla_id})
    if not doc:
        raise HTTPException(404, "Plantilla no encontrada")
    try:
        r2 = get_r2()
        if r2:
            r2.delete_object(Bucket=R2_BUCKET, Key=doc["r2_key"])
    except Exception as _e:
        logger.warning(f"delete_plantilla R2 error: {_e}")
    await db.plantillas_diarias.delete_one({"id": plantilla_id})
    return {"success": True}


# =========================
# MONETIZACIÓN — reservas de plaza fundador (página de planes) y ofertas
# patrocinadas del portal conductor. Ambas viven en global_db (negocio de la
# plataforma, no de un tenant) y notifican por Telegram al owner.
# =========================

FOUNDER_TOTAL_SLOTS = 10


class FounderReserve(BaseModel):
    name: str
    email: str
    phone: str = ""
    fleet_size: str = ""


@api_router.get("/founder/slots")
async def founder_slots():
    """Público: plazas fundador restantes. Contador real, no marketing falso."""
    used = await global_db.founder_reservations.count_documents({})
    return {"total": FOUNDER_TOTAL_SLOTS, "left": max(0, FOUNDER_TOTAL_SLOTS - used)}


@api_router.post("/founder/reserve")
async def founder_reserve(data: FounderReserve, request: Request):
    """Público: reserva una plaza fundador sin pago. El owner cierra la venta
    en persona (Telegram avisa al momento con los datos de contacto)."""
    _rl_public_action(f"founder:{_rl_key_ip(request)}", max_count=3, window_s=3600,
                      detail="Demasiadas reservas desde esta conexión")
    name = data.name.strip()[:80]
    email = data.email.strip().lower()[:120]
    if not name or "@" not in email or "." not in email.split("@")[-1]:
        raise HTTPException(400, "Nombre y email válidos son obligatorios")
    if await global_db.founder_reservations.find_one({"email": email}):
        return {"success": True, "already": True}
    used = await global_db.founder_reservations.count_documents({})
    if used >= FOUNDER_TOTAL_SLOTS:
        raise HTTPException(409, "No quedan plazas fundador")
    await global_db.founder_reservations.insert_one({
        "id": str(uuid.uuid4()), "name": name, "email": email,
        "phone": data.phone.strip()[:40], "fleet_size": data.fleet_size.strip()[:40],
        "status": "pending", "created_at": datetime.now(timezone.utc).isoformat(),
    })
    await send_telegram_alert(
        "💰 RESERVA FUNDADOR — llámale hoy",
        f"👤 {name}\n📧 {email}\n📞 {data.phone or '—'}\n🚐 Flota: {data.fleet_size or '—'}\n"
        f"Plazas restantes: {FOUNDER_TOTAL_SLOTS - used - 1}/{FOUNDER_TOTAL_SLOTS}",
        severity="critico",
    )
    return {"success": True, "left": FOUNDER_TOTAL_SLOTS - used - 1}


# Oferta por defecto del portal conductor mientras no haya patrocinadores:
# bucle de crecimiento (el conductor recomienda FlotaDSP a su jefe).
_DEFAULT_DRIVER_OFFER = {
    "id": "ref-flotadsp",
    "emoji": "🎁",
    "title": "¿Conoces otro DSP que sufra con las furgonetas?",
    "description": "Recomiéndale FlotaDSP: inspecciones con IA en 30 segundos, como las tuyas.",
    "cta": "Ver cómo funciona",
    "url": "https://flotadsp.com/?utm_source=driver-portal&utm_medium=referral",
}


class DriverOfferIn(BaseModel):
    title: str
    description: str = ""
    cta: str = ""
    url: str
    emoji: str = "🎁"
    active: bool = True


_vistas_contadas: dict = {}


def _ya_contado(clave: str, ventana_s: int = 3600) -> bool:
    """¿Ya contamos este evento para esta clave hace poco?

    Las metricas de las ofertas se venden a un anunciante: si cualquiera puede
    inflarlas recargando la pagina, el numero no vale nada. Se cuenta una vez
    por IP y hora. En memoria a proposito (aproximado y barato); si la maquina
    reinicia, se vuelve a contar: preferible a una coleccion nueva.
    """
    ahora = datetime.now(timezone.utc).timestamp()
    if len(_vistas_contadas) > 5000:            # poda: no crecer sin limite
        for k in [k for k, t in _vistas_contadas.items() if ahora - t > ventana_s]:
            _vistas_contadas.pop(k, None)
    visto = _vistas_contadas.get(clave, 0)
    if ahora - visto < ventana_s:
        return True
    _vistas_contadas[clave] = ahora
    return False


@api_router.get("/driver-offers")
async def list_driver_offers(request: Request):
    """Público (portal conductor): ofertas patrocinadas activas.
    Cuenta impresiones para poder vender el espacio con métricas reales."""
    docs = await global_db.driver_offers.find(
        {"active": True}, {"_id": 0}).sort("created_at", -1).to_list(4)
    if docs:
        # Una impresion por IP y hora: si no, bastaba con recargar en bucle
        # para inflar el numero que le ensenamos al anunciante.
        if not _ya_contado(f"vista:{_rl_key_ip(request)}"):
            await global_db.driver_offers.update_many(
                {"id": {"$in": [d["id"] for d in docs]}}, {"$inc": {"views": 1}})
        return {"offers": docs}
    return {"offers": [_DEFAULT_DRIVER_OFFER]}


@api_router.post("/driver-offers/{offer_id}/click")
async def click_driver_offer(offer_id: str, request: Request):
    """Público: registra un clic en una oferta (métrica de venta del espacio)."""
    _rl_public_action(f"offer:{_rl_key_ip(request)}", max_count=30, window_s=600)
    # SIN upsert: antes, un id inventado creaba un documento nuevo en la BD
    # global, asi que cualquiera podia llenarla de basura desde fuera.
    # Un clic sobre algo que no existe simplemente no se cuenta.
    if _ya_contado(f"clic:{_rl_key_ip(request)}:{offer_id[:64]}", ventana_s=60):
        return {"success": True}
    await global_db.driver_offers.update_one(
        {"id": offer_id[:64]}, {"$inc": {"clicks": 1}})
    return {"success": True}


@api_router.get("/admin/driver-offers")
async def admin_list_driver_offers(_=Depends(require_superadmin)):
    """Super-admin: todas las ofertas con sus métricas (views/clicks)."""
    docs = await global_db.driver_offers.find({}, {"_id": 0}).sort("created_at", -1).to_list(50)
    return {"offers": docs}


@api_router.get("/admin/founder-reservations")
async def admin_list_founder_reservations(_=Depends(require_superadmin)):
    """Super-admin: reservas de plaza fundador (para cerrarlas por teléfono)."""
    docs = await global_db.founder_reservations.find({}, {"_id": 0}).sort("created_at", -1).to_list(50)
    return {"reservations": docs, "total_slots": FOUNDER_TOTAL_SLOTS}


@api_router.post("/admin/driver-offers")
async def admin_create_driver_offer(data: DriverOfferIn, _=Depends(require_superadmin)):
    url = data.url.strip()
    if not url.startswith("https://"):
        raise HTTPException(400, "La URL de la oferta debe empezar por https://")
    doc = {
        "id": str(uuid.uuid4()), "title": data.title.strip()[:120],
        "description": data.description.strip()[:240], "cta": data.cta.strip()[:60],
        "url": url[:300], "emoji": data.emoji.strip()[:8] or "🎁",
        "active": data.active, "views": 0, "clicks": 0,
        "created_at": datetime.now(timezone.utc).isoformat(),
    }
    await global_db.driver_offers.insert_one(dict(doc))
    doc.pop("_id", None)
    return {"success": True, "offer": doc}


@api_router.patch("/admin/driver-offers/{offer_id}")
async def admin_toggle_driver_offer(offer_id: str, data: dict, _=Depends(require_superadmin)):
    """Solo permite activar/desactivar (whitelist de 1 campo a propósito)."""
    if "active" not in data:
        raise HTTPException(400, "Falta el campo active")
    r = await global_db.driver_offers.update_one(
        {"id": offer_id}, {"$set": {"active": bool(data["active"])}})
    if not r.matched_count:
        raise HTTPException(404, "Oferta no encontrada")
    return {"success": True}


@api_router.delete("/admin/driver-offers/{offer_id}")
async def admin_delete_driver_offer(offer_id: str, _=Depends(require_superadmin)):
    await global_db.driver_offers.delete_one({"id": offer_id})
    return {"success": True}


# =========================================================================
# PACKAGE INTELLIGENCE CENTER (Cortex) — investigación de incidencias de paquetes
# =========================================================================
# La extensión de navegador intercepta el JSON real de Cortex (route-summaries /
# route-details) usando la sesión ya autenticada del usuario y lo envía aquí
# normalizado. El backend reconstruye el histórico (solo cambios de estado),
# el timeline por paquete, aplica reglas de transición, prioriza y genera la
# ficha del investigador. Datos aislados por org (colecciones en la BD tenant).

_CORTEX_STATES = {
    # crudo (Cortex/es) → canónico
    "loaded": "LOADED", "out_for_delivery": "LOADED", "on_road": "LOADED", "en_route": "LOADED",
    "in_transit": "LOADED",
    # PICKED_UP NO ES "CARGADO PARA ENTREGAR". Es una RECOGIDA que el conductor
    # ya ha subido a la furgoneta y trae de vuelta a la nave. Traducirlo a
    # LOADED lo metia en el mismo saco que un paquete sin entregar, y el cuadre
    # del debrief lo reclamaba como si le faltara por repartir.
    # Medido el 27-08-2026 sobre el dia completo de OGA5: de los 281 paquetes
    # que figuraban LOADED, los 281 tenian `PICKED_UP` como evento vigente y
    # los 281 venian de un `PENDING_PICKUP` previo. Ni uno solo era reparto.
    # Cortex decia 104 pendientes y la app 320: esa era la diferencia.
    # Se guarda con el nombre que usa Cortex, sin inventar ninguno.
    "picked_up": "PICKED_UP",
    # Y NOT_DELIVERED es lo contrario de DELIVERED, no un matiz. Sin esta
    # entrada caia en el emparejador por texto, donde "delivered" es subcadena
    # de "not_delivered", y 7 paquetes de hoy figuraban ENTREGADOS diciendo
    # Cortex que no se entregaron. Un falso positivo que ademas inflaba el DCR.
    "not_delivered": "NOT_DELIVERED", "undelivered": "NOT_DELIVERED",
    # taskState reales de Cortex que significan "aún por hacer / en la furgoneta"
    "not_started": "LOADED", "not_attempted": "LOADED", "assigned": "LOADED",
    "pending": "LOADED", "ready": "LOADED", "incomplete": "LOADED", "in_progress": "LOADED",
    "reattemptable": "ATTEMPTED",
    "arrived": "ARRIVED", "arrived_at_stop": "ARRIVED", "at_stop": "ARRIVED",
    "attempted": "ATTEMPTED", "delivery_attempted": "ATTEMPTED", "attempt": "ATTEMPTED",
    "rejected": "ATTEMPTED", "business_closed": "ATTEMPTED", "unable_to_access": "ATTEMPTED",
    "missing": "MISSING", "not_on_van": "MISSING", "not_found": "MISSING",
    "delivered": "DELIVERED", "completed": "DELIVERED",
    "recovered": "RECOVERED", "rescued": "RECOVERED",
    "returned": "RETURNED", "returned_to_station": "RETURNED", "rts": "RETURNED",
    "lost": "LOST",
    "uncollected": "UNCOLLECTED", "pickup_failed": "UNCOLLECTED",
}
# palabras clave (texto libre en español) → canónico, por si llega evidencia de texto
_CORTEX_STATE_TEXT = [
    ("MISSING", ("falta", "perdido", "missing", "no está en la furgoneta")),
    ("RECOVERED", ("recuperado", "recovered")),
    ("RETURNED", ("devuelto a la estación", "devuelto", "returned")),
    ("LOST", ("lost", "extraviado definit")),
    ("ATTEMPTED", ("se ha intentado", "no se ha podido entregar", "no se puede entregar", "intento de entrega")),
    ("UNCOLLECTED", ("no se ha podido recoger", "recogida pendiente")),
    ("DELIVERED", ("entregado", "buzón", "puerta principal", "recibido", "delivered")),
    ("ARRIVED", ("en la parada", "llegada a la parada", "arrived")),
    ("LOADED", ("cargado", "en ruta", "loaded")),
]
_CORTEX_ORDER = {s: i for i, s in enumerate(
    ["LOADED", "ARRIVED", "ATTEMPTED", "MISSING", "RECOVERED", "DELIVERED", "RETURNED", "LOST",
     "UNCOLLECTED", "OBSERVED"])}


def _cortex_canon_state(raw) -> str:
    if not raw:
        return "OBSERVED"
    s = str(raw).strip().lower().replace(" ", "_").replace("-", "_")
    if s.upper() in _CORTEX_ORDER:
        return s.upper()
    if s in _CORTEX_STATES:
        return _CORTEX_STATES[s]
    low = str(raw).strip().lower()
    # NEGACION: "not_delivered" contiene "delivered", y por subcadena se
    # convertia en DELIVERED — exactamente al reves de lo que dice Cortex.
    # Cualquier codigo desconocido que empiece por una negacion NO pasa por el
    # emparejador por texto: se devuelve tal cual y se ve que no lo conocemos,
    # que es infinitamente mejor que afirmar lo contrario de la verdad.
    # Solo sobre CODIGOS (sin espacios). El texto libre en espanol empieza por
    # "no se ha podido entregar", que es una frase que el emparejador SI debe
    # reconocer; bloquearla la dejaba sin clasificar. Probado con los dos casos.
    _negado = (" " not in low) and re.match(r"^(not|non|un|no)[_-]", low) is not None
    if not _negado:
        for canon, kws in _CORTEX_STATE_TEXT:
            if any(k in low for k in kws):
                return canon
    # No reconocido: si parece un código de estado (letras/underscore), lo
    # mostramos tal cual (verdad de Cortex) en vez de "OBSERVED" genérico.
    if re.fullmatch(r"[A-Za-z_]{2,28}", s):
        return s.upper()
    return "OBSERVED"


def _cx_estado_vigente(timeline: list):
    """(estado, hora) del evento MAS RECIENTE POR HORA de un timeline.

    No vale coger el ultimo del array: el timeline se llena con `$push` y
    Cortex manda eventos historicos con su propia hora, asi que el orden del
    array es el de llegada, no el de los hechos.

    EMPATES. Cuando dos eventos comparten el segundo exacto —pasa una vez
    cada tres dias, medido— gana el mas informativo para quien esta en la
    nave: si Cortex dice que el paquete no aparece, eso es lo que hay que
    atender aunque llegue empatado con un "se intento".
    """
    if not timeline:
        return None, None
    mejor, mejor_at = None, None
    for e in timeline:
        at = _cortex_parse_dt(e.get("at"))
        if at is None:
            continue
        if mejor_at is None or at > mejor_at:
            mejor, mejor_at = e, at
        elif at == mejor_at and mejor is not None:
            orden = {"MISSING": 3, "DELIVERED": 2, "BACK_TO_ORIGIN": 1}
            if orden.get(e.get("state"), 0) > orden.get(mejor.get("state"), 0):
                mejor = e
    return (mejor or {}).get("state"), mejor_at


def _cortex_parse_dt(v):
    if not v:
        return None
    try:
        s = str(v).replace("Z", "+00:00")
        d = datetime.fromisoformat(s)
        return d if d.tzinfo else d.replace(tzinfo=timezone.utc)
    except Exception:
        try:
            return datetime.fromtimestamp(float(v) / (1000 if float(v) > 1e12 else 1), tz=timezone.utc)
        except Exception:
            return None


def _cortex_ingest_org(request: Request) -> str:
    """Autentica la extensión por su token de ingesta y fija la BD del DSP.
    Devuelve el org_id. El token es un JWT de larga duración con scope propio."""
    token = request.headers.get("x-ingest-token") or request.query_params.get("ingest_token", "")
    if not token:
        raise HTTPException(status_code=401, detail="Falta el token de ingesta (X-Ingest-Token).")
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[JWT_ALGORITHM])
    except Exception:
        raise HTTPException(status_code=401, detail="Token de ingesta inválido o caducado.")
    if payload.get("scope") != "cortex_ingest":
        raise HTTPException(status_code=403, detail="Token sin permiso de ingesta.")
    # Sin `db_name` NO se escribe. Un token viejo sin ese campo caeria en la BD
    # por defecto y mezclaria los datos de dos empresas: mejor que falle y se
    # regenere la llave, que se nota enseguida.
    if not payload.get("db_name"):
        raise HTTPException(
            status_code=403,
            detail="Esta llave es de una versión anterior y no identifica la empresa. "
                   "Vuelve a copiarla desde Cortex IA en la aplicación.")
    set_current_org_db(payload["db_name"])
    return payload.get("org_id", "")


def _cortex_evaluate(pkg: dict) -> dict:
    """Motor de reglas: prioridad + ficha del investigador a partir del timeline.
    Determinista y sin IA generativa: es un peritaje de secuencia de estados."""
    tl = pkg.get("timeline") or []
    seq = [e.get("state") for e in tl]
    state = pkg.get("state") or (seq[-1] if seq else "OBSERVED")
    now = datetime.now(timezone.utc)

    def _at(i):
        return _cortex_parse_dt(tl[i].get("at")) if 0 <= i < len(tl) else None

    def _mins_since(dt):
        return int((now - dt).total_seconds() // 60) if dt else None

    # ¿Hubo Attempted inmediatamente antes de un Missing?
    attempted_before_missing = False
    idx_missing = next((i for i, s in enumerate(seq) if s == "MISSING"), None)
    if idx_missing is not None:
        prev = [s for s in seq[:idx_missing] if s in ("ATTEMPTED", "ARRIVED", "LOADED")]
        attempted_before_missing = bool(prev) and prev[-1] == "ATTEMPTED"
    # ¿Se llegó a ver en la furgoneta antes del Missing? Si no, es "falta en
    # carga": nunca subió a la ruta y no tiene sentido buscarlo en el vehículo.
    never_on_van = idx_missing is not None and not any(
        s in ("LOADED", "ARRIVED", "ATTEMPTED") for s in seq[:idx_missing])

    missing_at = _at(idx_missing) if idx_missing is not None else None
    mins_missing = _mins_since(missing_at)

    priority, reason = "low", ""
    if state in ("RECOVERED", "DELIVERED"):
        priority = "low"
        reason = "Resuelto" if state == "DELIVERED" else "Recuperado"
    elif state == "LOST":
        priority, reason = "critical", "Paquete dado por perdido (Lost)."
    elif state == "MISSING" and attempted_before_missing:
        priority, reason = "critical", "Transición Attempted → Missing: probablemente estaba en la furgoneta."
    elif state == "MISSING" and never_on_van:
        priority, reason = "medium", "Falta en carga: nunca se escaneó en la furgoneta."
    elif state == "MISSING" and mins_missing is not None and mins_missing >= 15:
        priority, reason = "high", f"Missing desde hace {mins_missing} min sin resolver."
    elif state == "MISSING":
        priority, reason = "high", "Missing reciente sin resolver."
    elif state == "ATTEMPTED":
        priority, reason = "medium", "Intento de entrega sin resolver."

    # Ficha del investigador (recomendación)
    investigator = None
    if state in ("MISSING", "LOST"):
        container = pkg.get("container_id")
        rec_type, confidence, text = "review", 0.6, ""
        if attempted_before_missing:
            rec_type, confidence = "vehicle_or_tote", 0.9
            att_at = _at(seq.index("ATTEMPTED")) if "ATTEMPTED" in seq else None
            gap = None
            if att_at and missing_at:
                gap = int((missing_at - att_at).total_seconds() // 60)
            text = (f"El paquete tuvo un Attempted{f' {gap} minutos' if gap else ''} antes del Missing. "
                    "Es muy probable que estuviera físicamente en la furgoneta. "
                    + (f"Revisa el contenedor {container}." if container else "Revisa el tote del stop u organización de la furgoneta."))
        elif seq and seq[0] == "LOADED" and "ATTEMPTED" not in seq and "ARRIVED" not in seq:
            rec_type, confidence = "loaded_never_attempted", 0.75
            text = ("El paquete se cargó pero nunca se intentó entregar ni llegó a la parada. "
                    "Puede seguir en la furgoneta o no haberse escaneado correctamente al cargar. "
                    + (f"Revisa el contenedor {container}." if container else "Revisa la carga y el tote."))
        elif never_on_van:
            rec_type, confidence = "missing_at_load", 0.8
            text = ("Falta en carga: el paquete nunca se escaneó en la furgoneta (ni Loaded, ni Arrived, "
                    "ni Attempted). Lo más probable es que no saliera de la estación: reclámalo como falta "
                    "en carga y no pierdas tiempo buscándolo en el vehículo.")
        else:
            text = ("Missing sin un Attempted previo claro. Revisa el último escaneo del paquete y "
                    "el tote del stop antes de darlo por perdido.")
        investigator = {
            "type": rec_type, "confidence": confidence, "text": text,
            "container": container, "mins_since_missing": mins_missing,
        }

    return {"priority": priority, "reason": reason,
            "attempted_before_missing": attempted_before_missing,
            "investigator": investigator}


def _cortex_addr_str(v):
    """Direccion SIEMPRE como texto.

    Cortex la manda de dos formas: texto en route-details, pero un OBJETO en el
    informe de faltas ({address1, city, geocode, customerName, ...}). Al guardar
    el objeto tal cual, React reventaba al pintarlo (error #31) y la pantalla de
    Paquetes se caia al abrir un missing.

    Ademas nos quedamos SOLO con el punto de entrega: customerName y
    customerPhone son datos personales del cliente final que no necesitamos
    para investigar un paquete, asi que no entran en nuestra base de datos.
    """
    if not v:
        return None
    if isinstance(v, str):
        return v.strip() or None
    if isinstance(v, dict):
        cp_city = " ".join(str(x).strip() for x in (v.get("postalCode"), v.get("city")) if x)
        parts = [v.get("address1"), v.get("address2"), v.get("address3"), cp_city]
        out = ", ".join(str(x).strip() for x in parts if x and str(x).strip().lower() not in ("", "none"))
        return out or None
    return str(v)


def _cortex_evento_doc(ev: dict, tba: str) -> dict:
    """Evento de Cortex con fecha de caducidad (90 dias).

    El indice TTL necesita un campo de tipo fecha REAL, no una cadena ISO:
    por eso expira_en se guarda como datetime y no pasa por serialize_doc.
    """
    doc = serialize_doc({"id": str(uuid.uuid4()), **ev, "tba": tba})
    doc["expira_en"] = datetime.now(timezone.utc) + timedelta(days=90)
    return doc


async def _cortex_apply_observation(obs: dict, captured_at) -> str:
    """Aplica una observación canónica: crea o actualiza el paquete guardando
    solo los cambios de estado en el histórico. Devuelve 'new'|'changed'|'same'."""
    tba = (obs.get("tba") or obs.get("package_id") or "").strip().upper()
    if not tba:
        return "same"
    # ¿Trae ESTADO esta observación, o sólo datos de relleno?
    # El informe de faltas (packagesByStatus) es la única fuente con la
    # DIRECCIÓN en texto, pero no trae estado de entrega: su `packageStatus` es
    # un objeto y su `reasonCode` es un motivo, no un estado. Sin esta
    # distinción, `_cortex_canon_state(None)` devuelve 'OBSERVED' y esa fuente
    # pisaría el estado bueno — un paquete DELIVERED por route-details pasaría a
    # OBSERVED sólo por venir en el informe. Con 757 entregados hoy, eso es
    # falsear la operación entera.
    _state_raw = obs.get("state") or obs.get("raw_state") or obs.get("taskState")
    sin_estado = not (isinstance(_state_raw, str) and _state_raw.strip())
    state = _cortex_canon_state(_state_raw)

    # EXCEPCIÓN: "falta el paquete" SÍ es un estado.
    #
    # El informe de faltas no trae `taskState` —por eso se le trata como fuente
    # sin estado, para que no pise el DELIVERED que sí sabe route-details—, pero
    # su `reasonCode: OBJECT_MISSING` no es un matiz: es Cortex diciendo
    # literalmente que el paquete falta, y es la ÚNICA fuente que lo dice. Sin
    # esta excepción, un paquete que Cortex marca "Falta el paquete" no aparecía
    # nunca como MISSING en el panel (pasó el 15/08 con ES2586309005: visible en
    # Cortex, ausente aquí).
    #
    # Sólo estos códigos, y sólo hacia MISSING: es un estado terminal que ya
    # tenía prioridad sobre el resumido de route-details ("un Missing explícito
    # es evidencia más fuerte"), así que no puede degradar nada.
    _ctx = str(obs.get("state_context") or "").strip().upper().replace(" ", "_").replace("-", "_")
    if sin_estado and _ctx in ("OBJECT_MISSING", "PACKAGE_MISSING", "MISSING"):
        state = "MISSING"
        sin_estado = False
    observed_at = _cortex_parse_dt(obs.get("observed_at")) or _cortex_parse_dt(captured_at) or datetime.now(timezone.utc)
    ev = {
        "state": state, "at": observed_at.isoformat(),
        "raw": (obs.get("raw_state") or obs.get("taskState") or "")[:80],
        "context": (str(obs.get("state_context") or "")[:80]) or None,
        "stop_id": obs.get("stop_id"), "container_id": obs.get("container_id"),
    }
    # Centro/estación: serviceAreaId es la clave dura; el centro (OGA5/DGA1) es la
    # etiqueta legible. Guardamos el mapa estación→centro para resolver los que
    # lleguen sin etiqueta (informe de faltas) o los antiguos.
    said = str(obs.get("service_area_id") or "").strip() or None
    center = str(obs.get("center") or "").strip().upper() or None
    station_code = str(obs.get("station_code") or "").strip() or None
    st_doc = None
    if said:
        st_doc = await db.cortex_stations.find_one(
            {"service_area_id": said}, {"_id": 0, "center": 1, "manual": 1})
    if said and (center or station_code):
        try:
            setd = {}
            # La asignación MANUAL del panel manda SIEMPRE: la etiqueta que la
            # extensión lee de la UI de Cortex puede venir mezclada y antes
            # pisaba el mapeo manual a cada captura ("reetiquetado no funciona").
            if center and not (st_doc or {}).get("manual"):
                setd["center"] = center
            if station_code:
                setd["station_code"] = station_code
            if setd:
                await db.cortex_stations.update_one(
                    {"service_area_id": said}, {"$set": setd}, upsert=True)
        except Exception:
            pass
    # Resolver el centro del paquete: el mapeo manual de la estación gana a la
    # etiqueta de la captura; sin mapeo, la etiqueta rellena el hueco.
    if st_doc and st_doc.get("center") and (st_doc.get("manual") or not center):
        center = st_doc["center"]
    ident = {
        "reference_id": obs.get("reference_id"),
        "route_code": obs.get("route_code") or obs.get("route_id"),
        "route_id": obs.get("route_id"),
        "service_area_id": said, "center": center,
        "driver_name": obs.get("driver_name"), "driver_id": obs.get("driver_id"),
        "stop_id": obs.get("stop_id"),
        "stop_address": _cortex_addr_str(obs.get("stop_address") or obs.get("address")),
        "container_id": obs.get("container_id"), "station": obs.get("station"),
        "lat": obs.get("lat"), "lng": obs.get("lng"),
        # Destino (geocode de la direccion), distinto del ultimo escaneo. Lo
        # manda la extension 2.22+; nulo no pisa lo conocido (regla de abajo).
        "dest_lat": obs.get("dest_lat"), "dest_lng": obs.get("dest_lng"),
    }
    # Las fuentes se COMPLEMENTAN: el informe de faltas no trae conductor pero
    # route-details sí. Un campo null/"" de una fuente pobre NUNCA pisa el dato
    # ya conocido de otra fuente más rica.
    ident = {k: v for k, v in ident.items() if v not in (None, "")}
    common = {"tba": tba, "state": state, "updated_at": observed_at.isoformat(), **ident}
    # Caducidad a 90 dias, igual que cortex_events. Sin esto la coleccion crecia
    # sin techo: medido, 3.309 docs/dia = 77 MB/mes. Se reescribe en cada
    # captura a proposito, asi el reloj se reinicia mientras el paquete siga
    # vivo y solo caduca lo que lleva 90 dias sin verse.
    # Va como datetime (no ISO): el indice TTL de Mongo solo entiende fechas.
    common["expira_en"] = datetime.now(timezone.utc) + timedelta(days=90)
    # CUANDO LO VIMOS NOSOTROS, que no es cuando paso en Cortex.
    # No habia forma de distinguir un paquete que sigue de verdad en la
    # furgoneta de otro cuya ruta llevabamos dos horas sin bajar: `updated_at`
    # y `first_seen` son la hora del EVENTO en Cortex, y una ruta terminada a
    # las 19:00 no vuelve a moverla aunque la pidamos cincuenta veces. Con eso
    # me equivoque yo mismo diagnosticando: mirando `updated_at` parecia que el
    # barrido estaba muerto y estaba funcionando. Sin este campo, "esta al dia"
    # no se puede ni preguntar.
    common["seen_at"] = datetime.now(timezone.utc).isoformat()
    # Día de servicio (el que el usuario tiene seleccionado en Cortex). Se guarda
    # una sola vez y no se pisa con null: cada paquete pertenece a un día.
    service_day = str(obs.get("service_day") or "").strip()[:10]
    if service_day:
        common["service_day"] = service_day
    pkg = await db.cortex_packages.find_one({"tba": tba}, {"_id": 0})

    # ¿ES ESTE EVENTO EL MAS RECIENTE QUE CONOCEMOS?
    # Se decide aqui, una sola vez, porque hay cuatro caminos distintos mas
    # abajo que escriben `common` y todos tienen el mismo problema: si el
    # evento es viejo, ni su estado ni su hora pueden mandar.
    _ult_estado, _ult_at = _cx_estado_vigente((pkg or {}).get("timeline") or [])
    _es_el_mas_nuevo = _ult_at is None or observed_at >= _ult_at
    if not _es_el_mas_nuevo:
        # `updated_at` es "cuando lo vimos por ultima vez" y NO puede
        # retroceder: es lo que alimenta la regla del hueco del cuadre del
        # debrief, y un paquete con la hora echada atras parece llevar horas
        # sin observarse y cambia de cajon sin que haya pasado nada.
        common.pop("updated_at", None)

    # UNA FUENTE SIN ESTADO NO CREA PAQUETES, SÓLO COMPLETA LOS QUE YA HAY.
    #
    # El informe de faltas (packagesByStatus) es de donde sale la DIRECCIÓN, y
    # se pide con la fecha de HOY. Pero devuelve también paquetes que arrastran
    # de días anteriores —los "se puede volver a intentar" siguen ahí hasta que
    # se entregan—, y no trae estado ni día propio. Si con eso se crearan
    # paquetes, entrarían como del día de hoy y el contador de "rastreados"
    # subiría por encima de los que salieron de verdad a ruta: un número
    # inflado, que en una pantalla de operación es peor que no tener el dato.
    #
    # Quien decide qué paquetes son de hoy es route-details, que sí trae día y
    # estado. El informe sólo aporta la dirección de los que ya conocemos.
    if not pkg and sin_estado:
        return "same"

    if not pkg:
        # Sembrar timeline con recentTaskEvents si vienen, más el estado actual
        seed = []
        for e in (obs.get("events") or []):
            st = _cortex_canon_state(e.get("state") or e.get("raw"))
            at = _cortex_parse_dt(e.get("at") or e.get("time"))
            if at:
                seed.append({"state": st, "at": at.isoformat(), "raw": (e.get("raw") or "")[:80]})
        seed.sort(key=lambda e: e["at"])
        if not seed or seed[-1]["state"] != state:
            seed.append(ev)
        doc = {**common, "id": str(uuid.uuid4()), "first_seen": observed_at.isoformat(),
               "captures_n": 1, "timeline": seed}
        doc.setdefault("reference_id", tba)
        evalr = _cortex_evaluate(doc)
        doc.update({"priority": evalr["priority"], "reason": evalr["reason"]})
        await db.cortex_packages.insert_one(serialize_doc(doc))
        await db.cortex_events.insert_one(_cortex_evento_doc(ev, tba))
        return "new"

    # Fuente SIN estado sobre un paquete que ya existe: enriquece y calla.
    # Se guardan sus datos buenos (la dirección, sobre todo) y no se toca ni el
    # estado ni el timeline, que los sabe mejor route-details.
    if sin_estado:

        # NI EL ESTADO NI EL DÍA. El informe de faltas devuelve los paquetes que
        # siguen pendientes de reintento, y esos ARRASTRAN de días anteriores;
        # como se pide con la fecha de hoy, todos vienen etiquetados como de
        # hoy. Dejar que eso pisara `service_day` reescribía el pasado: el 11 de
        # agosto pasó de 10.491 paquetes a 5.783 en una tarde, porque los que
        # seguían reintentándose se mudaban al día de hoy. Un histórico que
        # cambia solo no vale para nada, y menos delante de Amazon.
        #
        # `first_seen` tampoco se toca: es la fecha en que el paquete apareció
        # por primera vez y es lo único que permite reconstruir a qué día
        # pertenece si algo se tuerce.
        enriquecer = {k: v for k, v in common.items()
                      if k not in ("state", "service_day", "first_seen")}
        # El contexto (el motivo: ADDRESS_NOT_FOUND) sí se anota en el ÚLTIMO
        # evento si aún no lo tenía: es justo el dato que dice por qué falló.
        ctx = ev.get("context")
        tl = pkg.get("timeline") or []
        if ctx and tl and not tl[-1].get("context"):
            tl[-1]["context"] = ctx
            enriquecer["timeline"] = tl
        await db.cortex_packages.update_one(
            {"tba": tba}, {"$set": enriquecer, "$inc": {"captures_n": 1}})
        return "same"

    # ── UN EVENTO QUE YA ESTA NO SE VUELVE A GUARDAR ─────────────────────────
    # El timeline hacia PING-PONG y crecia sin tope. Cortex reenvia sus eventos
    # historicos en cada respuesta; la unica guarda que habia comparaba con el
    # ULTIMO del array, asi que dos eventos alternandose se colaban los dos, una
    # y otra vez: medido el 27-08, 658 eventos duplicados en un dia y un paquete
    # con 88 entradas para 2 eventos reales, mas una fila basura en
    # `cortex_events` por cada repeticion.
    # La identidad de un evento es (estado, hora, crudo, contexto): si eso ya
    # esta guardado, no es informacion nueva.
    def _ya_guardado(tl, e):
        clave = (e.get("state"), str(e.get("at")), str(e.get("raw") or ""),
                 str(e.get("context") or ""))
        return any((x.get("state"), str(x.get("at")), str(x.get("raw") or ""),
                    str(x.get("context") or "")) == clave for x in tl)

    _repetido = _ya_guardado(pkg.get("timeline") or [], ev)

    last = (pkg.get("timeline") or [{}])[-1]
    if last.get("state") == state:
        await db.cortex_packages.update_one({"tba": tba}, {"$set": common, "$inc": {"captures_n": 1}})
        return "same"
    # Un Missing explícito es evidencia más fuerte que el taskState resumido de
    # route-details. Cortex puede seguir devolviendo "attempted" durante un
    # tiempo aunque el informe de faltas ya haya marcado el paquete como Missing.
    # Nunca lo rebajamos de forma silenciosa; solo un estado terminal/resuelto
    # posterior puede cerrar el Missing.
    if pkg.get("state") in ("MISSING", "LOST") and state in ("LOADED", "ARRIVED", "ATTEMPTED", "OBSERVED"):
        meta = {k: v for k, v in common.items() if k not in ("state", "updated_at") and v not in (None, "")}
        await db.cortex_packages.update_one(
            {"tba": tba}, {"$set": meta, "$inc": {"captures_n": 1}} if meta else {"$inc": {"captures_n": 1}})
        return "same"
    # Una observación SIN estado (OBSERVED) nunca degrada un estado real ya
    # conocido: solo refresca metadatos (ruta, conductor, dirección…).
    if state == "OBSERVED" and last.get("state") not in (None, "", "OBSERVED"):
        meta = {k: v for k, v in common.items() if k not in ("state", "updated_at") and v not in (None, "")}
        await db.cortex_packages.update_one(
            {"tba": tba}, {"$set": meta, "$inc": {"captures_n": 1}} if meta else {"$inc": {"captures_n": 1}})
        return "same"
    # ── UN EVENTO VIEJO NO PUEDE CAMBIAR EL ESTADO ───────────────────────────
    # Cortex manda `recentTaskEvents` con su propia hora: una captura de las
    # 15:00 puede traer un evento de las 10:51. Al hacer `$push` ese evento
    # queda el ultimo del array y, con la logica anterior, pasaba a ser el
    # estado actual — pisando un DELIVERED de las 11:36. Medido: 24 paquetes
    # entregados en tres dias que el cuadre reclamaba al conductor.
    #
    # El evento se guarda igual en el historico (es informacion buena), pero
    # el estado solo se mueve si el evento es el mas reciente que conocemos.
    if not _es_el_mas_nuevo:
        # Al historico si; al estado no. Y los metadatos tambien, que un
        # evento viejo puede traer la direccion que faltaba.
        meta = {k: v for k, v in common.items()
                if k not in ("state", "updated_at") and v not in (None, "")}
        upd = {"$set": meta, "$inc": {"captures_n": 1}}
        if not _repetido:
            upd["$push"] = {"timeline": ev}
        await db.cortex_packages.update_one({"tba": tba}, upd)
        if not _repetido:
            await db.cortex_events.insert_one(_cortex_evento_doc(ev, tba))
        return "same"

    # Cambio de estado real → histórico + timeline
    doc = {**pkg, **common, "timeline": (pkg.get("timeline") or []) + [ev]}
    evalr = _cortex_evaluate(doc)
    upd = {"$set": {**common, "priority": evalr["priority"], "reason": evalr["reason"]},
           "$inc": {"captures_n": 1}}
    if not _repetido:
        upd["$push"] = {"timeline": ev}
    await db.cortex_packages.update_one({"tba": tba}, upd)
    if not _repetido:
        await db.cortex_events.insert_one(_cortex_evento_doc(ev, tba))
    return "changed"


# =========================================================================
# CALIDAD DE ENTREGA EN VIVO — el scorecard antes de que Amazon lo publique
# =========================================================================
# Ver docs/CALIDAD_EN_VIVO.md para el porque de cada decision. Resumen:
# Cortex entra solo y en el dia; el scorecard oficial llega 6 dias tarde.

# Entregado bien.
_CX_OK = ("DELIVERED",)

# Todavia en juego: el paquete esta en la furgoneta o de camino. NO es un fallo,
# es una jornada sin terminar. Si esto pesa mucho en un dia, ese dia no puntua.
# PICKED_UP entra aqui y no en "fallo": es un paquete cargado en la furgoneta y
# en reparto, no una entrega que salio mal. Sin esto, medio dia de trabajo
# normal contaria como miles de fallos y hundiria el DCR en vivo.
_CX_EN_VUELO = ("LOADED", "PICKED_UP", "YOU_ARE_NEXT", "ARRIVED", "OBSERVED",
                "NONE", "PENDING_PICKUP")

# Nunca salio a reparto: no se despacho, luego no entra en el denominador del
# DCR. Meterlo seria castigar al conductor por un paquete que no llego a tocar.
_CX_NO_DESPACHADO = ("UNCOLLECTED", "NOT_READY", "TR_CANCELLED")

# Cualquier otro estado al cierre del dia es un fallo de entrega imputable:
# BACK_TO_ORIGIN, CUSTOMER_UNAVAILABLE, ATTEMPTED, MISSING, DAMAGED,
# ADDRESS_NOT_FOUND, LOCKER_ISSUE.

# Porcentaje de paquetes en vuelo por encima del cual un dia se considera
# incompleto y no puntua. Medido: dias cerrados 0,00-0,02 %; dia en curso 20 %.
_CX_UMBRAL_EN_VUELO = 2.0


def _cx_categoria_stage():
    """Clasifica cada paquete en ok / vuelo / nodesp / fallo dentro de Mongo.

    Se hace en el servidor de base de datos a proposito: son ~100.000 documentos
    por mes y traerselos a Python para contarlos tarda segundos y se come la RAM
    del contenedor. Asi el trabajo lo hace el indice.
    """
    return {"$switch": {"branches": [
        {"case": {"$in": ["$state", list(_CX_OK)]}, "then": "ok"},
        {"case": {"$in": ["$state", list(_CX_EN_VUELO)]}, "then": "vuelo"},
        {"case": {"$in": ["$state", list(_CX_NO_DESPACHADO)]}, "then": "nodesp"},
    ], "default": "fallo"}}


async def _cx_bruto(desde: str, hasta: str, center: str = ""):
    """Conteos por (dia, conductor) en UNA sola consulta agregada."""
    match = {"service_day": {"$gte": desde, "$lte": hasta}}
    if center:
        # center viene sucio en la BD ('OGA5', 'OGA5 ', 'AMZL OGA5 ...'): regex.
        match["center"] = {"$regex": re.escape(center.strip()), "$options": "i"}
    cur = db.cortex_packages.aggregate([
        {"$match": match},
        # La categoria se calcula UNA vez por documento. Ponerla dentro de cada
        # $sum obliga a Mongo a evaluar el $switch cuatro veces por paquete:
        # sobre ~52.000 documentos de una semana eso son 156.000 evaluaciones
        # de mas por consulta, y se nota.
        {"$addFields": {"_cat": _cx_categoria_stage()}},
        {"$group": {
            "_id": {"dia": "$service_day", "cond": "$driver_id"},
            "ok": {"$sum": {"$cond": [{"$eq": ["$_cat", "ok"]}, 1, 0]}},
            "vuelo": {"$sum": {"$cond": [{"$eq": ["$_cat", "vuelo"]}, 1, 0]}},
            "nodesp": {"$sum": {"$cond": [{"$eq": ["$_cat", "nodesp"]}, 1, 0]}},
            "fallo": {"$sum": {"$cond": [{"$eq": ["$_cat", "fallo"]}, 1, 0]}},
            "rts": {"$sum": {"$cond": [{"$eq": ["$state", "BACK_TO_ORIGIN"]}, 1, 0]}},
        }},
    ], allowDiskUse=True)
    return await cur.to_list(20000)


def _cx_dias(bruto: list) -> dict:
    """Estado de cada dia: cerrado (puntua) o en curso (solo progreso)."""
    dias = {}
    for r in bruto:
        # .get y no [...]: $group OMITE la clave cuando el campo no existe en el
        # documento, no la pone a null. Un paquete sin service_day no se puede
        # imputar a ningun dia, asi que se descarta en vez de tumbar la pantalla.
        dia = r["_id"].get("dia")
        if not dia:
            continue
        d = dias.setdefault(dia, {"ok": 0, "vuelo": 0, "nodesp": 0, "fallo": 0})
        for k in ("ok", "vuelo", "nodesp", "fallo"):
            d[k] += r[k]
    for dia, d in dias.items():
        total = d["ok"] + d["vuelo"] + d["nodesp"] + d["fallo"]
        d["total"] = total
        d["en_vuelo_pct"] = round(d["vuelo"] / total * 100, 2) if total else 0.0
        d["cerrado"] = total > 0 and d["en_vuelo_pct"] <= _CX_UMBRAL_EN_VUELO
    return dias


def _cx_tasas(ok: int, fallo: int, rts: int) -> dict:
    """DCR y RTS a partir de los despachados. Sin despachados no hay tasa.

    Devolver 100 % cuando no hay datos seria el peor falso positivo posible:
    un centro sin actividad se veria perfecto. Se devuelve None y la pantalla
    dice 'sin datos'.
    """
    desp = ok + fallo
    if desp <= 0:
        return {"despachados": 0, "entregados": ok, "fallos": fallo, "rts": rts,
                "dcr": None, "rts_pct": None}
    return {"despachados": desp, "entregados": ok, "fallos": fallo, "rts": rts,
            "dcr": round(ok / desp * 100, 2), "rts_pct": round(rts / desp * 100, 2)}


async def _cx_nombres(ids: set) -> dict:
    """ID de Amazon -> nombre. Primero la ficha; si no, el historico de rutas.

    Medido en produccion: 84 de 127 IDs de Cortex ya cruzan con una ficha por
    drivers.driver_id, y route_history rescata unos cuantos mas porque guarda
    el par (transporter_id, driver_name) tal cual lo da Amazon.
    """
    if not ids:
        return {}
    # ── EL MISMO ID VIVE EN DOS CAMPOS DE LA FICHA ───────────────────────────
    # La ficha tiene "ID Amazon" (`driver_id`) y "Transporter ID (Cortex)"
    # (`transporter_id`), y son lo mismo: al dar de alta se rellenaba uno u
    # otro segun el dia. Medido el 29-08-2026 sobre 213 fichas:
    #     92 con los dos y coincidiendo · 32 solo en `driver_id`
    #     19 solo en `transporter_id`   ·  0 con los dos DISTINTOS
    # Ese cero es lo que hace seguro tratarlos como uno solo: nunca se
    # contradicen.
    #
    # Buscando por un campo solo, media plantilla no cruzaba: los 19 salian
    # "SIN FICHA" en el debrief y los 32 en la pantalla de IDs sin ficha — el
    # mismo fallo visto desde los dos lados.
    mapa = {}
    async for d in db.drivers.find(
            {"$or": [{"driver_id": {"$in": list(ids)}},
                     {"transporter_id": {"$in": list(ids)}}]},
            {"_id": 0, "id": 1, "name": 1, "driver_id": 1, "transporter_id": 1, "active": 1}):
        ficha = {"nombre": d.get("name"), "ficha_id": d.get("id"),
                 "activo": d.get("active", True), "origen": "ficha"}
        for campo in ("driver_id", "transporter_id"):
            v = (d.get(campo) or "").strip()
            if v in ids:
                mapa[v] = ficha
    faltan = ids - set(mapa)
    if faltan:
        async for r in db.route_history.find({"transporter_id": {"$in": list(faltan)}},
                                             {"_id": 0, "transporter_id": 1, "driver_name": 1}):
            if r.get("driver_name") and r["transporter_id"] not in mapa:
                mapa[r["transporter_id"]] = {"nombre": r["driver_name"], "ficha_id": None,
                                             "activo": True, "origen": "historico"}
    return mapa


# Volumen minimo para que un conductor entre en el ranking de impacto. Con 20
# paquetes, un solo fallo son 5 puntos de tasa: seria senalar a alguien por
# ruido estadistico. Por debajo de _CX_MUESTRA_FIABLE se marca 'muestra corta'.
_CX_MINIMO_RANKING = 40
_CX_MUESTRA_FIABLE = 120


def _cx_impacto(conductores: list, tasa_fallo_flota: float) -> list:
    """Exceso de fallos de cada conductor sobre lo que haria la media con SUS
    paquetes. Es lo unico que se le puede imputar de verdad.

    Un conductor con 900 paquetes y 9 fallos (1 %) y otro con 200 y 6 (3 %)
    tienen tasas muy distintas, pero si la media de flota es el 1 %, el primero
    no sobra nada y el segundo sobra 4 fallos. Ordenar por tasa castigaria al
    de poco volumen; ordenar por exceso senala al que de verdad cuesta dinero.
    """
    out = []
    for c in conductores:
        desp = c["despachados"]
        if desp < _CX_MINIMO_RANKING:
            continue
        esperados = desp * tasa_fallo_flota
        exceso = c["fallos"] - esperados
        if exceso <= 0:
            continue
        out.append({**c, "fallos_esperados": round(esperados, 1),
                    "exceso": round(exceso, 1),
                    "muestra_corta": desp < _CX_MUESTRA_FIABLE})
    return sorted(out, key=lambda x: x["exceso"], reverse=True)


# ═══════════════════════════════════════════════════════════════════════════
# DONDE SE DEJA CADA PAQUETE  (metrica PROPIA, NO el DSC DPMO de Amazon)
#
# CORRECCION 2026-08-07: este bloque se llamo "DSC" y se presento como si
# midiera el Delivery Success Conditions DPMO de Amazon. ESO ERA FALSO y estuvo
# desplegado. Extraidos los 17 valores reales de DSC DPMO de los scorecards
# (por coordenadas fisicas del PDF, no por orden de texto): van de 598 a 1712
# DPMO, o sea del 0,06 % al 0,17 % de los paquetes. Esta metrica marca un
# 8,31 % = 83.100 DPMO. Noventa veces mas. No pueden ser lo mismo: si Amazon
# contase "dejar en el jardin" como defecto DSC, el DPMO seria de decenas de
# miles. La metrica sigue siendo util y real, pero es NUESTRA, no la de Amazon.
#
# Por que esto y no otra cosa: en las 17 scorecards reales de OGA5 (semanas 12
# a 31 de 2026), "Delivery Success Conditions (DSC) DPMO" sale como area de
# foco en 14, y es la numero 1 en 12 de ellas. Es LA metrica que le cuesta el
# tier a este DSP, muy por encima del WHC (5 semanas) o del DCR (1).
#
# De donde salen los datos: del propio `timeline` de cortex_packages, campo
# `context` del ultimo evento DELIVERED. NO hace falta cruzar con
# cortex_events. Medido en produccion sobre 48 136 entregas de 7 dias:
# 602 ms el desglose por conductor y 297 ms la distribucion, contra 6 974 ms
# del mismo calculo con $lookup (y sin indice, directamente expiraba).
#
# LO QUE ESTO NO ES: no es el DPMO de Amazon. Amazon no publica que
# ubicaciones penaliza ni con que peso, y no me lo invento. Lo que se mide es
# un HECHO comprobable — donde deja los paquetes cada conductor — y el exceso
# de cada uno sobre lo que haria la media de la flota con SUS entregas.
_DSC_EN_MANO = ("DELIVERED_TO_HOUSEHOLD_MEMBER", "DELIVERED_TO_CUSTOMER",
                "DELIVERED_TO_RECEPTIONIST", "DELIVERED_TO_MAIL_ROOM_CLERK")
_DSC_SEGURO = ("DELIVERED_TO_STORE", "DELIVERED_TO_LOCKER",
               "DELIVERED_TO_EVERYWHERE_LOCKER")
# Dejado sin nadie delante. Medido en produccion: 8,31 % de la flota, pero de
# 1,3 % a 21,8 % segun el conductor, con muestras de cientos de entregas.
_DSC_RIESGO = ("DELIVERED_TO_GARDEN", "DELIVERED_TO_NEIGHBOR", "DELIVERED_TO_SHED",
               "DELIVERED_TO_GARAGE", "DELIVERED_TO_REAR_DOOR",
               "DELIVERED_TO_MAIL_SLOT", "DELIVERED_TO_SAFE_LOCATION")

_DSC_ETIQUETA = {
    "DELIVERED_TO_HOUSEHOLD_MEMBER": "En mano", "DELIVERED_TO_CUSTOMER": "Al cliente",
    "DELIVERED_TO_RECEPTIONIST": "Recepción", "DELIVERED_TO_MAIL_ROOM_CLERK": "Conserjería",
    "DELIVERED_TO_STORE": "Punto de recogida", "DELIVERED_TO_LOCKER": "Locker",
    "DELIVERED_TO_EVERYWHERE_LOCKER": "Locker externo", "DELIVERED_TO_DOORSTEP": "En la puerta",
    "DELIVERED_TO_GARDEN": "Jardín", "DELIVERED_TO_NEIGHBOR": "Vecino",
    "DELIVERED_TO_SHED": "Cobertizo", "DELIVERED_TO_GARAGE": "Garaje",
    "DELIVERED_TO_REAR_DOOR": "Puerta trasera", "DELIVERED_TO_MAIL_SLOT": "Buzón",
    "DELIVERED_TO_SAFE_LOCATION": "Lugar seguro", "NONE": "Sin registrar",
}

# Minimo de entregas para aparecer en el ranking. Con menos, un porcentaje no
# significa nada y senalar a alguien seria un falso positivo.
# Causas por las que un paquete vuelve a la estacion. La accion es lo que
# cambia: sin ella el dato es una queja, no una herramienta.
_DSC_CAUSA = {
    "CUSTOMER_UNAVAILABLE": "Cliente ausente", "BUSINESS_CLOSED": "Comercio cerrado",
    "ADDRESS_NOT_FOUND": "Dirección no encontrada", "NONE": "Sin causa registrada",
    "RESCHEDULED_BY_CUSTOMER": "Reprogramado por el cliente",
    "NO_ITEMS_DELIVERED": "Nada entregado en la parada",
    "INACCESSIBLE_DELIVERY_LOCATION": "Acceso imposible",
    "OBJECT_MISSING": "Paquete no encontrado", "TR_CANCELLED": "Cancelado",
    "LOCKER_ISSUE": "Problema con el locker", "DAMAGED": "Dañado",
    "BAD_WEATHER": "Meteorología", "OTP_NOT_AVAILABLE": "Sin código OTP",
    "SELF_SERVICE_RETURN": "Devolución del cliente",
}
_DSC_ACCION = {
    "BUSINESS_CLOSED": "Orden de ruta: mover esas paradas fuera del cierre comercial",
    "ADDRESS_NOT_FOUND": "Libreta de portales: apuntar cómo se llega",
    "INACCESSIBLE_DELIVERY_LOCATION": "Libreta de portales: anotar el acceso",
    "OBJECT_MISSING": "Carga: el paquete no iba en la furgoneta",
    "NONE": "Formación: el conductor no marcó el motivo",
}

_DSC_MINIMO = 80
_DSC_MUESTRA_FIABLE = 250


def _dsc_base(desde: str) -> list:
    """Etapas comunes: saca de cada paquete entregado DONDE se dejo."""
    return [
        {"$match": {"service_day": {"$gte": desde}, "state": "DELIVERED",
                    "driver_id": {"$nin": [None, ""]}}},
        # El ultimo DELIVERED del timeline: un paquete puede tener varios
        # eventos y el que cuenta es el que cerro la entrega.
        {"$addFields": {"_e": {"$last": {"$filter": {
            "input": {"$ifNull": ["$timeline", []]}, "as": "t",
            "cond": {"$eq": ["$$t.state", "DELIVERED"]}}}}}},
        {"$addFields": {"ctx": {"$ifNull": ["$_e.context", "NONE"]}, "rw": "$_e.raw"}},
    ]


# ═══════════════════════════════════════════════════════════════════════════
# DIRECCIONES QUE DAN PROBLEMAS
# ═══════════════════════════════════════════════════════════════════════════
# EL HALLAZGO QUE LO MOTIVA. Medido sobre 90 dias: 2.154 paquetes fallados, y
# de las 454 direcciones distintas que fallan, DOCE acumulan 93 paquetes. Una
# sola —reparalotodo.net, Avenida Ferrol 40— falla 9 veces y las 9 por el mismo
# motivo: INACCESSIBLE_DELIVERY_LOCATION. Nadie lo habia mirado nunca porque el
# fallo se ve paquete a paquete, y paquete a paquete no se repite: se repite la
# DIRECCION.
#
# Y ahi esta el negocio: arreglar una direccion UNA vez —una nota de acceso, un
# telefono, un horario— se lleva por delante todos sus fallos futuros. Los
# motivos mas gordos son accionables:
#   BUSINESS_CLOSED  438 (20%) -> un negocio con horario; si siempre llegamos
#                                 despues de que cierre, es orden de ruta.
#   ADDRESS_NOT_FOUND 216 (10%) -> la direccion esta mal o el portal no se ve.
#   INACCESSIBLE      73  (3%)  -> hay una barrera, un codigo, un acceso.
# CUSTOMER_UNAVAILABLE (21%) es el mayor pero el menos accionable, y por eso NO
# manda en la ordenacion: ordenar por volumen bruto pondria arriba justo lo que
# no se puede arreglar.

# Motivos sobre los que se puede hacer algo, con su peso. Lo que no esta aqui
# cuenta como 1: no se ignora, pero tampoco sube a nadie al principio.
_DIR_ACCIONABLE = {
    "BUSINESS_CLOSED": 3.0,
    "ADDRESS_NOT_FOUND": 3.0,
    "INACCESSIBLE_DELIVERY_LOCATION": 3.0,
    "NO_SECURE_LOCATION": 2.0,
    "LOCKER_ISSUE": 2.0,
    "CUSTOMER_UNAVAILABLE": 0.5,
    "RESCHEDULED_BY_CUSTOMER": 0.3,
    "TR_CANCELLED": 0.2,
}
_DIR_MIN_FALLOS = 2
COLECCION_DIR_NOTAS = "direcciones_notas"


def _dir_clave(direccion: str) -> str:
    """Misma direccion escrita de seis maneras = una sola clave.

    Vienen del sistema de Amazon sin normalizar: 'Rua Isaac Peral, 14' y 'RUA
    ISAAC PERAL 14, BAJO' son el mismo portal. Sin esto cada variante cuenta
    por separado y NINGUNA llega al minimo: el problema existe y no lo ve nadie.
    """
    s = unicodedata.normalize("NFKD", str(direccion or "")).encode("ascii", "ignore").decode()
    s = s.lower()
    s = re.sub(r"\b(bajo|baixo|piso|puerta|pta|esc|escalera|izq|dcha|izquierda|derecha)\b", " ", s)
    s = re.sub(r"[^a-z0-9]+", " ", s)
    # Letra pegada a numero = numero suelto. 'n°43' y 'n 43' son el mismo portal:
    # el simbolo de grado desaparece al quitar acentos y deja 'n43', que sin
    # esto cuenta como una direccion distinta. Salio en 'Calle Campanario
    # n°43', que esta en produccion.
    s = re.sub(r"(?<=[a-z])(?=\d)", " ", s)
    s = re.sub(r"(?<=\d)(?=[a-z])", " ", s)
    return re.sub(r"\s+", " ", s).strip()


def _dir_sugerencia(motivos: dict, horas: list) -> Optional[str]:
    """Que hacer con esta direccion, deducido del patron. None si no hay patron.

    NO se inventa una sugerencia para todo. Solo sale cuando el motivo manda
    de verdad (la mitad de los fallos o mas) y, cuando la hora importa, cuando
    hay horas suficientes para ver un patron. Una sugerencia para cada
    direccion seria ruido, y ruido en el sitio donde alguien va a tomar una
    decision es peor que un hueco vacio.

    LO DEL HORARIO SALE DE LOS DATOS, no de una intuicion. Medido sobre 90
    dias: BUSINESS_CLOSED tiene hora media 15:24 y su pico a las 17:00 con 79
    fallos, cuando a esa hora solo se entrega el 9% del volumen del dia. O sea
    que entregar en negocios por la tarde falla mucho mas de lo que le tocaria.
    """
    if not motivos:
        return None
    total = sum(motivos.values())
    dom, n = max(motivos.items(), key=lambda x: x[1])
    if n < max(2, total * 0.5):
        return None

    if dom == "BUSINESS_CLOSED":
        if len(horas) >= 2:
            media = sum(horas) / len(horas)
            if media >= 14.5:
                return ("Negocio cerrado %d veces, casi siempre por la tarde "
                        "(sobre las %02d:00). Ponla antes de comer." % (n, round(media)))
            return ("Negocio cerrado %d veces, y ya se intenta por la mañana: "
                    "hace falta el horario o un teléfono." % n)
        return "Negocio cerrado %d veces. Apunta su horario." % n

    if dom == "ADDRESS_NOT_FOUND":
        return ("No se encuentra %d veces. La dirección está mal o el portal no se ve: "
                "hace falta una referencia (al lado de qué, qué color)." % n)

    if dom == "INACCESSIBLE_DELIVERY_LOCATION":
        return ("No se puede acceder %d veces. Suele ser una barrera, un código o una "
                "entrada por otro lado: apunta cómo se entra." % n)

    if dom == "NO_SECURE_LOCATION":
        return "Sin sitio donde dejarlo %d veces. Mira si hay un vecino o un comercio." % n

    if dom == "CUSTOMER_UNAVAILABLE" and n >= 4:
        # Con muchos intentos fallidos ya no es mala suerte, pero tampoco es
        # culpa del reparto: lo unico honesto es sugerir hablar con la persona.
        return ("Cliente ausente %d veces: no se arregla repartiendo mejor. "
                "Un teléfono o una indicación de dónde dejarlo sí." % n)

    return None


COLECCION_DIR_HIST = "direcciones_historico"


async def consolidar_direcciones() -> dict:
    """Guarda el recuento de fallos por direccion ANTES de que Cortex los borre.

    POR QUE HACE FALTA. `cortex_packages` tiene TTL y hoy solo llega hasta el
    1 de julio: 60 dias. Sin esto, una direccion que fallo cuatro veces en mayo
    desaparece, y el analisis empieza de cero cada dos meses en vez de mejorar.
    Justo al reves de lo que tiene que pasar.

    Lo que se guarda es DIMINUTO —un documento por direccion con contadores— y
    no un duplicado de los paquetes: en un Atlas M0 de 512 MB eso importa. Hoy
    serian del orden de 450 documentos.

    ES IDEMPOTENTE por dia. Se guarda que dias ya estan contados y no se vuelven
    a sumar: correrlo dos veces no duplica nada. Sin eso, un reintento tras un
    fallo doblaria los contadores y las direcciones "peores" serian las que
    tuvieron la mala suerte de estar en el reintento.
    """
    ya = set()
    doc = await db.app_meta.find_one({"_id": "dirs_consolidadas"}, {"_id": 0})
    if doc:
        ya = set(doc.get("dias") or [])

    # Solo dias CERRADOS: el de hoy sigue moviendose.
    hoy = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    cur = db.cortex_packages.aggregate([
        {"$match": {"service_day": {"$lt": hoy},
                    "state": {"$nin": list(_CX_OK) + list(_CX_EN_VUELO) + list(_CX_NO_DESPACHADO)}}},
        {"$group": {"_id": "$service_day"}}])
    dias = sorted({r["_id"] async for r in cur if r["_id"] and r["_id"] not in ya})
    if not dias:
        return {"dias": 0, "direcciones": 0}

    tocadas: dict = {}
    async for p in db.cortex_packages.find(
            {"service_day": {"$in": dias},
             "state": {"$nin": list(_CX_OK) + list(_CX_EN_VUELO) + list(_CX_NO_DESPACHADO)}},
            {"_id": 0, "stop_address": 1, "state": 1, "timeline": 1, "service_day": 1}):
        dirtxt = (p.get("stop_address") or "").strip()
        k = _dir_clave(dirtxt)
        if not k or len(k) < 8:
            continue
        ctx = None
        hora = None
        for e in reversed(p.get("timeline") or []):
            if e.get("state") == p.get("state"):
                ctx = e.get("context")
                if e.get("at"):
                    try:
                        hora = (int(str(e["at"])[11:13]) + 2) % 24
                    except Exception:                        # noqa: BLE001
                        pass
                break
        g = tocadas.setdefault(k, {"n": 0, "motivos": {}, "horas": [], "texto": dirtxt,
                                   "ultimo": p.get("service_day")})
        g["n"] += 1
        m = str(ctx or "SIN_MOTIVO")
        g["motivos"][m] = g["motivos"].get(m, 0) + 1
        if hora is not None:
            g["horas"].append(hora)
        if len(dirtxt) > len(g["texto"]):
            g["texto"] = dirtxt
        if (p.get("service_day") or "") > (g["ultimo"] or ""):
            g["ultimo"] = p["service_day"]

    for k, g in tocadas.items():
        inc = {"n": g["n"]}
        for m, v in g["motivos"].items():
            # El punto no vale como clave de campo en Mongo, y un motivo raro
            # con un punto tumbaria el update entero.
            inc["motivos.%s" % re.sub(r"[.$]", "_", m)] = v
        await db[COLECCION_DIR_HIST].update_one(
            {"_id": k},
            {"$inc": inc,
             "$set": {"texto": g["texto"], "ultimo": g["ultimo"],
                      "at": datetime.now(timezone.utc).isoformat()},
             "$push": {"horas": {"$each": g["horas"][:40], "$slice": -200}}},
            upsert=True)

    # La lista de dias ya contados se recorta: con el TTL de Cortex, un dia de
    # hace un ano no puede volver a aparecer y guardarlo no sirve de nada.
    nuevos = sorted(ya | set(dias))[-400:]
    await db.app_meta.update_one({"_id": "dirs_consolidadas"},
                                 {"$set": {"dias": nuevos,
                                           "at": datetime.now(timezone.utc).isoformat()}},
                                 upsert=True)
    logger.info("Direcciones consolidadas: %d días, %d direcciones", len(dias), len(tocadas))
    return {"dias": len(dias), "direcciones": len(tocadas)}


@api_router.post("/cortex/direcciones-problema/consolidar")
async def disparar_consolidar_direcciones(_=Depends(require_admin)):
    """Consolida ahora, sin esperar a su hora."""
    return await consolidar_direcciones()


@api_router.get("/cortex/direcciones-problema")
async def direcciones_problema(dias: int = 90, center: str = "", _=Depends(require_admin)):
    """Las direcciones que fallan una y otra vez, con su motivo y su nota."""
    desde = (datetime.now(timezone.utc) - timedelta(days=max(7, min(dias, 365)))).strftime("%Y-%m-%d")
    q = {"service_day": {"$gte": desde},
         "state": {"$nin": list(_CX_OK) + list(_CX_EN_VUELO) + list(_CX_NO_DESPACHADO)}}
    if center and center not in ("Todos", "todos"):
        q["center"] = {"$regex": re.escape(center.strip()), "$options": "i"}

    grupos = {}
    async for p in db.cortex_packages.find(
            q, {"_id": 0, "stop_address": 1, "state": 1, "service_day": 1,
                "timeline": 1, "lat": 1, "lng": 1, "route_code": 1}):
        dirtxt = (p.get("stop_address") or "").strip()
        if not dirtxt:
            continue
        k = _dir_clave(dirtxt)
        if not k or len(k) < 8:
            continue
        # El `context` del ultimo evento del estado vigente es el motivo real
        # que da Amazon; el estado a secas dice que fallo, no por que.
        ctx = None
        for e in reversed(p.get("timeline") or []):
            if e.get("state") == p.get("state"):
                ctx = e.get("context")
                break
        g = grupos.setdefault(k, {"texto": dirtxt, "n": 0, "motivos": {}, "dias": set(),
                                  "rutas": set(), "lat": None, "lng": None, "horas": []})
        # La hora del fallo, en hora local. Es lo que permite distinguir "el
        # negocio esta cerrado" de "llegamos cuando ya habia cerrado".
        for e in reversed(p.get("timeline") or []):
            if e.get("state") == p.get("state") and e.get("at"):
                try:
                    g["horas"].append((int(str(e["at"])[11:13]) + 2) % 24)
                except Exception:                            # noqa: BLE001
                    pass
                break
        g["n"] += 1
        m = str(ctx or "SIN_MOTIVO")
        g["motivos"][m] = g["motivos"].get(m, 0) + 1
        g["dias"].add(p.get("service_day"))
        if p.get("route_code"):
            g["rutas"].add(p["route_code"])
        if g["lat"] is None and p.get("lat"):
            g["lat"], g["lng"] = p.get("lat"), p.get("lng")
        if len(dirtxt) > len(g["texto"]):
            g["texto"] = dirtxt

    notas = {n["clave"]: n async for n in db[COLECCION_DIR_NOTAS].find({}, {"_id": 0})}

    # SE SUMA LO QUE YA NO ESTA EN CORTEX. Sus paquetes tienen TTL y hoy solo
    # llegan 60 dias atras; sin esto, una direccion que fallo cuatro veces en
    # mayo desaparece y el analisis empieza de cero cada dos meses en vez de
    # mejorar. `consolidar_direcciones()` lo va guardando cada tarde.
    async for h in db[COLECCION_DIR_HIST].find({}):
        k = h.get("_id")
        if not k:
            continue
        g = grupos.setdefault(k, {"texto": h.get("texto") or k, "n": 0, "motivos": {},
                                  "dias": set(), "rutas": set(), "lat": None,
                                  "lng": None, "horas": []})
        # Solo se suma lo ANTERIOR a la ventana que ya trae Cortex: los dias
        # que estan en las dos partes se contarian dos veces.
        if (h.get("ultimo") or "") < desde:
            g["n"] += int(h.get("n") or 0)
            for m, v in (h.get("motivos") or {}).items():
                g["motivos"][m] = g["motivos"].get(m, 0) + int(v or 0)
            g["horas"].extend(h.get("horas") or [])
            g["historico"] = True

    out = []
    for k, g in grupos.items():
        if g["n"] < _DIR_MIN_FALLOS:
            continue
        dom = max(g["motivos"].items(), key=lambda x: x[1])
        prioridad = round(sum(_DIR_ACCIONABLE.get(m, 1.0) * n for m, n in g["motivos"].items()), 1)
        nota = notas.get(k) or {}
        out.append({
            "clave": k,
            "direccion": g["texto"],
            "fallos": g["n"],
            "dias_distintos": len(g["dias"]),
            "rutas": sorted(g["rutas"])[:6],
            "motivo_principal": dom[0],
            "motivo_n": dom[1],
            "motivos": dict(sorted(g["motivos"].items(), key=lambda x: -x[1])),
            "prioridad": prioridad,
            "accionable": prioridad >= g["n"] * 1.5,
            "lat": g["lat"], "lng": g["lng"],
            "nota": nota.get("nota"),
            "nota_por": nota.get("por"),
            "nota_en": nota.get("en"),
            # Que hacer, deducido del patron. Sale vacia si no hay patron: una
            # sugerencia para cada direccion seria ruido justo donde alguien va
            # a decidir algo.
            "sugerencia": _dir_sugerencia(g["motivos"], g["horas"]),
            "hora_media": (round(sum(g["horas"]) / len(g["horas"]), 1)
                           if g["horas"] else None),
        })
    out.sort(key=lambda x: (-x["prioridad"], -x["fallos"]))
    return {
        "direcciones": out[:150],
        "total": len(out),
        "paquetes_en_juego": sum(x["fallos"] for x in out),
        "con_nota": sum(1 for x in out if x.get("nota")),
        "desde": desde,
    }


@api_router.post("/cortex/direcciones-problema/nota")
async def guardar_nota_direccion(data: dict = Body(...), user: dict = Depends(require_admin)):
    """La nota de esa direccion: como entrar, a que hora, a quien llamar.

    Es lo unico que convierte esta pantalla en algo util. Ver la lista de
    direcciones que fallan sin poder dejar escrito el porque no arregla nada:
    quien lo averigua hoy no es quien reparte manana.
    """
    clave = _dir_clave(str(data.get("clave") or data.get("direccion") or ""))
    if not clave:
        raise HTTPException(400, "Falta la dirección")
    nota = str(data.get("nota") or "").strip()[:600]
    quien = user.get("name") or user.get("username") or "oficina"
    if not nota:
        await db[COLECCION_DIR_NOTAS].delete_one({"clave": clave})
        return {"ok": True, "borrada": True}
    await db[COLECCION_DIR_NOTAS].update_one(
        {"clave": clave},
        {"$set": {"clave": clave, "nota": nota, "por": quien,
                  "en": datetime.now(timezone.utc).isoformat(),
                  "direccion": str(data.get("direccion") or "")[:300]}},
        upsert=True)
    return {"ok": True, "nota": nota}


@api_router.get("/cortex/dsc")
async def cortex_dsc(dias: int = 7, _=Depends(require_admin)):
    """Dónde deja los paquetes cada conductor y quién se sale de la media."""
    dias = max(1, min(int(dias or 7), 30))
    desde = (datetime.now(timezone.utc) - timedelta(days=dias)).strftime("%Y-%m-%d")
    base = _dsc_base(desde)

    # Motor es async: aggregate() devuelve un cursor que hay que recorrer con
    # await/to_list. Un list() a secas revienta con
    # "AsyncIOMotorLatentCommandCursor object is not iterable".
    # El length va holgado y explicito: son ~20 contextos y ~120 conductores,
    # pero un to_list sin tope corta EN SILENCIO (ya paso con los backups).
    reparto = await db.cortex_packages.aggregate(
        base + [{"$group": {"_id": "$ctx", "n": {"$sum": 1}}}, {"$sort": {"n": -1}}],
        maxTimeMS=25000).to_list(length=200)
    total = sum(r["n"] for r in reparto)
    if not total:
        return {"dias": dias, "desde": desde, "total": 0, "reparto": [],
                "conductores": [], "flota": None}

    riesgo_tot = sum(r["n"] for r in reparto if r["_id"] in _DSC_RIESGO)
    tasa_flota = riesgo_tot / total

    crudo = await db.cortex_packages.aggregate(base + [
        {"$group": {"_id": "$driver_id", "n": {"$sum": 1},
                    "riesgo": {"$sum": {"$cond": [{"$in": ["$ctx", list(_DSC_RIESGO)]}, 1, 0]}},
                    "mano": {"$sum": {"$cond": [{"$in": ["$ctx", list(_DSC_EN_MANO)]}, 1, 0]}},
                    # Marcado como entregado pero con el evento crudo diciendo
                    # lo contrario. Es una contradiccion del propio dato, no una
                    # interpretacion mia: por eso se puede afirmar.
                    "contradicciones": {"$sum": {"$cond": [{"$eq": ["$rw", "NOT_DELIVERED"]}, 1, 0]}}}},
    ], maxTimeMS=25000).to_list(length=2000)

    nombres = await _cx_nombres({r["_id"] for r in crudo if r.get("_id")})
    conductores = []
    for r in crudo:
        n = r["n"]
        if n < _DSC_MINIMO:
            continue
        esperado = n * tasa_flota
        exceso = r["riesgo"] - esperado
        # _cx_nombres devuelve un DICT por conductor (nombre/ficha_id/activo/
        # origen), no una cadena. Usarlo tal cual metia el objeto entero en el
        # campo `nombre` y la pantalla habria pintado [object Object].
        info = nombres.get(r["_id"]) or {}
        conductores.append({
            "driver_id": r["_id"],
            "nombre": info.get("nombre") or "Sin emparejar",
            # Para enlazar con la ficha real: sin esto la tabla es un callejon
            # sin salida y no sirve para actuar, que es de lo que se trata.
            "ficha_id": info.get("ficha_id"),
            "activo": info.get("activo", True),
            "entregas": n,
            "riesgo": r["riesgo"],
            "en_mano": r["mano"],
            "pct_riesgo": round(r["riesgo"] / n * 100, 1),
            "pct_mano": round(r["mano"] / n * 100, 1),
            "esperado": round(esperado, 1),
            # Solo el exceso es imputable: un conductor con 700 entregas y un
            # 9 % no sobra nada si la flota va al 8,3 %; otro con 200 y un 20 %
            # sobra 23 paquetes. Ordenar por tasa bruta castigaria al de poco
            # volumen, que es justo el falso positivo que hay que evitar.
            "exceso": round(exceso, 1),
            "contradicciones": r["contradicciones"],
            "muestra_corta": n < _DSC_MUESTRA_FIABLE,
        })
    conductores.sort(key=lambda c: c["exceso"], reverse=True)

    # ── Los que vuelven a la estacion, POR CAUSA ────────────────────────
    # El motor de calidad ya los cuenta, pero solo como "fallo". Sin la causa
    # no se puede actuar: no es lo mismo un cliente ausente (nada que hacer)
    # que un comercio cerrado (orden de ruta) o una direccion no encontrada
    # (libreta de portales). Medido en 14 dias: 767 retornos, y el 44 % de los
    # BUSINESS_CLOSED cae entre las 14 y las 16 h — el cierre comercial
    # espanol. Eso se arregla planificando, no rinendo a nadie.
    ret_base = [
        {"$match": {"service_day": {"$gte": desde},
                    "state": {"$in": ["BACK_TO_ORIGIN", "ATTEMPTED", "CUSTOMER_UNAVAILABLE",
                                      "ADDRESS_NOT_FOUND", "REJECTED"]}}},
        {"$addFields": {"_r": {"$last": {"$filter": {
            "input": {"$ifNull": ["$timeline", []]}, "as": "t",
            "cond": {"$in": ["$$t.state", ["BACK_TO_ORIGIN", "ATTEMPTED"]]}}}}}},
        {"$addFields": {"rctx": {"$ifNull": ["$_r.context", "NONE"]}, "rat": "$_r.at"}},
    ]
    causas = await db.cortex_packages.aggregate(ret_base + [
        {"$group": {"_id": "$rctx", "n": {"$sum": 1}}}, {"$sort": {"n": -1}},
    ], maxTimeMS=25000).to_list(length=60)
    # Reparto horario del comercio cerrado: la unica causa con patron de hora.
    horas = await db.cortex_packages.aggregate(ret_base + [
        {"$match": {"rctx": "BUSINESS_CLOSED", "rat": {"$type": "string"}}},
        {"$group": {"_id": {"$substr": ["$rat", 11, 2]}, "n": {"$sum": 1}}},
        {"$sort": {"_id": 1}},
    ], maxTimeMS=25000).to_list(length=30)
    ret_total = sum(c["n"] for c in causas)
    cerrado = next((c["n"] for c in causas if c["_id"] == "BUSINESS_CLOSED"), 0)
    # Cuantos caen en la franja de cierre comercial (14:00-16:59).
    en_siesta = sum(h["n"] for h in horas if h["_id"] in ("14", "15", "16"))

    return {
        "dias": dias, "desde": desde, "total": total,
        "retornos": {
            "total": ret_total,
            "causas": [{"ctx": c["_id"],
                        "etiqueta": _DSC_CAUSA.get(c["_id"], c["_id"].replace("_", " ").title()),
                        "n": c["n"], "pct": round(c["n"] / max(1, ret_total) * 100, 1),
                        "accion": _DSC_ACCION.get(c["_id"], "")} for c in causas if c["n"]],
            "cerrado": cerrado,
            "cerrado_horas": [{"h": h["_id"], "n": h["n"]} for h in horas],
            "cerrado_en_siesta": en_siesta,
            "cerrado_pct_siesta": round(en_siesta / cerrado * 100) if cerrado else 0,
        },
        "flota": {
            "riesgo": riesgo_tot,
            "pct_riesgo": round(tasa_flota * 100, 2),
            "pct_mano": round(sum(r["n"] for r in reparto if r["_id"] in _DSC_EN_MANO) / total * 100, 1),
            "sin_registrar": sum(r["n"] for r in reparto if r["_id"] == "NONE"),
            "contradicciones": sum(c["contradicciones"] for c in conductores),
            # Cuantas entregas habria que mover para que la flota baje 1 punto.
            "por_punto": max(1, round(total / 100)),
        },
        "reparto": [{
            "ctx": r["_id"],
            "etiqueta": _DSC_ETIQUETA.get(r["_id"], r["_id"].replace("DELIVERED_TO_", "").title()),
            "n": r["n"], "pct": round(r["n"] / total * 100, 2),
            "grupo": ("riesgo" if r["_id"] in _DSC_RIESGO else
                      "mano" if r["_id"] in _DSC_EN_MANO else
                      "seguro" if r["_id"] in _DSC_SEGURO else "otro"),
        } for r in reparto if r["n"]],
        "conductores": conductores[:40],
        "minimo_entregas": _DSC_MINIMO,
    }


def _parecido(a: str, b: str) -> float:
    """Parecido entre dos nombres, 0..1, por palabras compartidas.

    Nada de distancia de edicion: los nombres vienen con el orden cambiado
    ("APELLIDO NOMBRE" vs "Nombre Apellido") y con tildes puestas o quitadas,
    y ahi comparar cadenas enteras falla. Contar palabras en comun aguanta el
    reordenado, que es el caso real.
    """
    pa = {w for w in _norm_texto(a).split() if len(w) > 2}
    pb = {w for w in _norm_texto(b).split() if len(w) > 2}
    if not pa or not pb:
        return 0.0
    return len(pa & pb) / min(len(pa), len(pb))


@api_router.get("/cortex/emparejar")
async def cortex_emparejar(dias: int = 30, _=Depends(require_admin)):
    """IDs de Amazon que reparten sin ficha, con la ficha que probablemente son."""
    dias = max(7, min(int(dias or 30), 120))
    desde = (datetime.now(timezone.utc) - timedelta(days=dias)).strftime("%Y-%m-%d")

    cur = db.cortex_packages.aggregate([
        {"$match": {"service_day": {"$gte": desde}, "driver_id": {"$nin": [None, ""]}}},
        {"$group": {"_id": "$driver_id", "paquetes": {"$sum": 1},
                    "ultimo": {"$max": "$service_day"},
                    "centro": {"$first": "$center"}}},
        {"$sort": {"paquetes": -1}},
    ], allowDiskUse=True)
    activos = await cur.to_list(2000)
    ids = {a["_id"] for a in activos}

    # Los que YA tienen ficha se descartan: aqui solo interesa lo que falta.
    con_ficha = set()
    async for dv in db.drivers.find({"driver_id": {"$in": list(ids)}}, {"_id": 0, "driver_id": 1}):
        con_ficha.add(dv["driver_id"])

    # Nombre que Amazon dio en el historico de rutas, si lo hay.
    historico = {}
    async for r in db.route_history.find({"transporter_id": {"$in": list(ids - con_ficha)}},
                                         {"_id": 0, "transporter_id": 1, "driver_name": 1}):
        if r.get("driver_name"):
            historico.setdefault(r["transporter_id"], r["driver_name"])

    # Fichas que aun no tienen ID asignado: son las candidatas.
    libres = await db.drivers.find(
        {"$or": [{"driver_id": {"$in": [None, ""]}}, {"driver_id": {"$exists": False}}]},
        {"_id": 0, "id": 1, "name": 1, "center": 1, "active": 1}).to_list(500)

    pendientes = []
    for a in activos:
        did = a["_id"]
        if did in con_ficha:
            continue
        nombre = historico.get(did)
        sug = []
        if nombre:
            for f in libres:
                p = _parecido(nombre, f.get("name") or "")
                if p >= 0.5:
                    sug.append({"ficha_id": f["id"], "nombre": f.get("name"),
                                "centro": f.get("center"), "parecido": round(p, 2)})
            sug.sort(key=lambda x: x["parecido"], reverse=True)
        pendientes.append({
            "driver_id": did, "paquetes": a["paquetes"], "ultimo_dia": a["ultimo"],
            "centro": (a.get("centro") or "").strip(),
            "nombre_historico": nombre, "sugerencias": sug[:3],
        })

    return {
        "pendientes": pendientes,
        "libres": sorted(libres, key=lambda f: (f.get("name") or "")),
        "resumen": {
            "activos": len(activos), "con_ficha": len(con_ficha),
            "sin_ficha": len(pendientes),
            "con_nombre_conocido": sum(1 for p in pendientes if p["nombre_historico"]),
            "paquetes_sin_atribuir": sum(p["paquetes"] for p in pendientes),
        },
    }


# =========================================================================
# WHC — WORKING HOURS COMPLIANCE
# Ver docs/WHC.md: que se puede afirmar de estos datos y que no.
# =========================================================================

# OJO: las 55 h de ciclo 1 son el limite CONTRACTUAL/LEGAL del DSP, NO el
# umbral de WHC de Amazon. Comprobado con la Semana 31 de OGA5: XAQUIN
# RIVADULLA trabajo 56h 30m y su fila del scorecard dice "Weekly Limit
# Exceeded = NO". El umbral de Amazon es MAYOR de 56h 30m y no lo publica.
# Marcar 56h30m como incumplimiento de Amazon seria un falso positivo.
_WHC_LIMITE_PROPIO = 55 * 60          # el tuyo, editable en pantalla
_WHC_SUELO_AMAZON_OBSERVADO = 56 * 60 + 30   # visto cumpliendo, luego el real es mayor

# Cuando queda menos de esto para TU limite, se avisa.
_WHC_MARGEN_AVISO_PROPIO = 3 * 60

# Aviso cuando queda menos de esto para el limite.
_WHC_MARGEN_AVISO = 3 * 60

# Duracion de bloque a partir de la cual se marca RIESGO diario (nunca
# incumplimiento). 10 h es la referencia de una ruta estandar mas dos horas.
_WHC_BLOQUE_RIESGO = 10 * 60
# Límite duro de jornada de la DSP: un bloque de 11 h o más se cuenta como
# incumplimiento propio. Es TU norma, no la de Amazon — Amazon ha dejado pasar
# bloques de 11 h 44 m sin excepción. Por eso alimenta el "WHC propio" y NO el
# porcentaje que publicará Amazon, que se calcula con sus excepciones.
_WHC_BLOQUE_LIMITE = 11 * 60
# Duracion implicita de un bloque sin hora de fin. Medida en el propio plan:
# 8 h 59 m – 9 h 14 m, una ruta estandar. Solo se usa para reconstruir el total
# de un conductor cuyo pegado no trajo la linea de horas, y queda marcado.
_WHC_BLOQUE_IMPLICITO = 9 * 60
# Ritmo: la semana son 6 bloques de ~9 h. A mitad de semana lo que importa no es
# el total (todavia bajo) sino si vas por encima de lo que te tocaria a estas
# alturas: el miercoles llevas 4 dias, o sea 4 bloques y 36 h como maximo.
_WHC_BLOQUES_SEMANA = 6
_WHC_DIAS = ["dom", "lun", "mar", "mié", "mie", "jue", "vie", "sáb", "sab"]


def _whc_dias_del_plan(texto: str):
    """Días que trae la cabecera del pegado ("dom., ago. 02"). Devuelve cuántos
    de esos días YA HAN PASADO (incluido hoy). Si no hay cabecera, se cae al día
    de la semana de hoy, contando el domingo como día 1."""
    from datetime import date
    meses = {"ene": 1, "feb": 2, "mar": 3, "abr": 4, "may": 5, "jun": 6,
             "jul": 7, "ago": 8, "sep": 9, "oct": 10, "nov": 11, "dic": 12}
    hoy = datetime.now(timezone.utc).date()
    fechas = []
    for l in (texto or "").split("\n"):
        m = re.match(r"^\s*(%s)\.?,?\s+([a-zé]{3})\.?\s+(\d{1,2})\s*$"
                     % "|".join(_WHC_DIAS), l.strip(), re.I)
        if m:
            mes = meses.get(m.group(2)[:3].lower())
            if mes:
                try:
                    fechas.append(date(hoy.year, mes, int(m.group(3))))
                except ValueError:
                    pass
    if fechas:
        pasados = sum(1 for f in sorted(set(fechas)) if f <= hoy)
        return max(1, min(pasados or len(fechas), 7)), True
    # Sin cabecera: domingo = 1 … sábado = 7
    return ((hoy.weekday() + 1) % 7) + 1, False

# ── Cortes de tier del WHC ────────────────────────────────────────────────
# Medidos sobre 17 scorecards REALES de OGA5 (semanas 12 a 31 de 2026), no
# publicados por Amazon. En las 17 semanas la formula
# (conductores - excepciones) / conductores reproduce al decimal el
# porcentaje impreso, incluido el caso extremo de la S28: 12 excepciones de
# 65 conductores = 81,5 %, y el PDF pone 81,5 %.
#
#   100 %            -> Fantastic   11 semanas, TODAS con 0 excepciones
#   97,1 % .. 98,2 % -> Great        5 semanas, con 1 o 2 excepciones
#   81,5 %           -> Poor         1 semana, con 12 excepciones
#
# Entre 98,2 y 100, y entre 81,5 y 97,1, NO hay ni un solo dato observado.
# Devolver un tier ahi seria inventarselo: se devuelve None y la pantalla
# dice que no se sabe. Preferimos "no lo se" a un tier falso.
#
# El hallazgo que de verdad importa para un DSP: en 17 semanas no hay ni una
# sola con Fantastic y alguna excepcion. UNA excepcion te quita el Fantastic.
_WHC_TIER_OBSERVADO = (
    (100.0, 100.0, "Fantastic"),
    (97.1, 98.2, "Great"),
    (81.5, 81.5, "Poor"),
)


def _whc_tier(pct):
    """Tier del WHC solo si los scorecards reales lo respaldan; si no, None."""
    if pct is None:
        return None
    for lo, hi, tier in _WHC_TIER_OBSERVADO:
        if lo - 0.05 <= pct <= hi + 0.05:
            return tier
    return None


def _whc_minutos(txt: str):
    """'11:34am' / '11 AM' / '12:30' -> minutos desde medianoche. None si no cuela."""
    t = (txt or "").strip().lower().replace(" ", "").replace(".", "")
    m = re.match(r"^(\d{1,2}):(\d{2})(am|pm)?$", t) or re.match(r"^(\d{1,2})(am|pm)$", t)
    if not m:
        return None
    g = m.groups()
    h = int(g[0])
    mi = int(g[1]) if len(g) > 2 and g[1] and g[1].isdigit() else 0
    ap = g[-1]
    if ap == "pm" and h != 12:
        h += 12
    if ap == "am" and h == 12:
        h = 0
    if h > 23 or mi > 59:
        return None
    return h * 60 + mi


def _whc_dur(txt: str) -> int:
    """'53h 34m' -> minutos."""
    h = re.search(r"(\d+)\s*h", txt or "")
    m = re.search(r"(\d+)\s*m", txt or "")
    return (int(h.group(1)) if h else 0) * 60 + (int(m.group(1)) if m else 0)


# Tipos de bloque que el portal escribe debajo de la hora.
_WHC_TIPOS = ("standard parcel", "nursery route", "dsp initiated work",
              "cycle 1", "cycle 2", "sameday", "multi-use")


def _whc_parsear(texto: str) -> list:
    """Convierte el pegado del plan semanal en conductores con sus bloques.

    Formato del portal (validado con 61 conductores de la Semana 31):
        NOMBRE
        Estandar
        53h 34m / 54h 45m        <- trabajado / planificado
        10:35am - 9:05pm
        Standard Parcel
        11 AM                    <- bloque SIN hora de fin (si le sigue un tipo)
        Standard Parcel
        ...

    Reglas deducidas y comprobadas:
      · 'HH:MMam - HH:MMpm' + tipo -> bloque con horas conocidas
      · hora suelta + tipo         -> bloque REAL cuya hora de fin no aparece.
        Su duracion implicita medida es 8h59m-9h14m: una ruta estandar.
      · hora suelta sin tipo       -> dia vacio, no cuenta
    """
    lineas = [l.strip() for l in (texto or "").replace("\r", "").split("\n")]
    out, actual = [], None
    i = 0
    while i < len(lineas):
        l = lineas[i]
        if not l:
            i += 1
            continue
        # "53h 34m / 54h 45m"  ·  "45h 54m / ⚠ 45h"  ·  "9h 15m / 9h"  ·  "/"
        #
        # OJO: el portal mete un ICONO DE AVISO entre la barra y el limite
        # cuando el conductor va justo ("45h 54m / ⚠ 45h"). El regex anterior
        # exigia que tras la barra viniera ya el numero, asi que esas lineas NO
        # casaban: el total se quedaba en 0, el conductor salia con "0h 00m" con
        # sus bloques a la vista y ademas se caia del denominador del WHC.
        # Por eso se toleran caracteres no numericos a ambos lados de la barra.
        mt = re.match(r"^\D*?(\d+\s*h(?:\s*\d+\s*m)?)\s*/\s*\D*?(\d+\s*h(?:\s*\d+\s*m)?)\s*$", l)
        if mt and actual:
            actual["trabajado"] = _whc_dur(mt.group(1))
            actual["planificado"] = _whc_dur(mt.group(2))
            actual["trabajado_origen"] = "portal"
            i += 1
            continue
        # Solo el trabajado, sin limite detras: "45h 54m /"
        ms = re.match(r"^\D*?(\d+\s*h(?:\s*\d+\s*m)?)\s*/\s*$", l)
        if ms and actual:
            actual["trabajado"] = _whc_dur(ms.group(1))
            actual["trabajado_origen"] = "portal"
            i += 1
            continue
        # Rango con horas: "10:35am - 9:05pm"
        mr = re.match(r"^(\d{1,2}:\d{2}\s*[ap]m?)\s*[-–]\s*(\d{1,2}:\d{2}\s*[ap]m?)$", l, re.I)
        if mr and actual:
            a, z = _whc_minutos(mr.group(1)), _whc_minutos(mr.group(2))
            if a is not None and z is not None:
                if z < a:
                    z += 1440
                tipo = lineas[i + 1] if i + 1 < len(lineas) else ""
                actual["bloques"].append({"inicio": mr.group(1), "fin": mr.group(2),
                                          "minutos": z - a, "tipo": tipo[:40], "estimado": False})
            i += 1
            continue
        # "10:45am - en curso": el conductor ESTA TRABAJANDO AHORA MISMO. Es un
        # bloque real sin hora de fin todavia. Tirarlo era el motivo de que el
        # total del portal no cuadrase con la suma de bloques: la diferencia
        # medida en el pegado real era de +8 h 58 m, exactamente una ruta.
        mc = re.match(r"^(\d{1,2}:\d{2}\s*[ap]m?)\s*[-–]\s*en\s+curso$", l, re.I)
        if mc and actual:
            tipo = lineas[i + 1] if i + 1 < len(lineas) else ""
            actual["bloques"].append({"inicio": mc.group(1), "fin": None,
                                      "minutos": None, "tipo": tipo[:40],
                                      "estimado": True, "en_curso": True})
            i += 1
            continue
        # Hora suelta: bloque sin fin SOLO si la linea siguiente es un tipo
        if actual and _whc_minutos(l) is not None:
            sig = (lineas[i + 1] if i + 1 < len(lineas) else "").lower()
            if any(t in sig for t in _WHC_TIPOS):
                actual["bloques"].append({"inicio": l, "fin": None, "minutos": None,
                                          "tipo": lineas[i + 1][:40], "estimado": True})
            i += 1
            continue
        # Ruido conocido del pegado
        if l.lower() in ("estandar", "estándar", "standard") or l.startswith("```") or l in ("DGA1", "DGA2", "OGA5"):
            i += 1
            continue
        if any(t in l.lower() for t in _WHC_TIPOS):
            i += 1
            continue
        # Cualquier otra cosa con letras es un nombre nuevo
        if re.search(r"[A-Za-zÁÉÍÓÚÑáéíóúñ]{3}", l) and not re.match(r"^\d", l):
            actual = {"nombre": l[:80], "trabajado": 0, "planificado": 0, "bloques": []}
            out.append(actual)
        i += 1
    return [c for c in out if c["trabajado"] or c["bloques"]]


def _whc_ritmo(c: dict, dia: int, limite_min: int) -> dict:
    """¿Va demasiado rápido para lo que llevamos de semana?

    A mitad de semana el total todavía es bajo y no dice nada. Lo que avisa es
    el RITMO: la semana son 6 bloques de ~9 h, así que el miércoles (día 4) lo
    máximo razonable son 4 bloques = 36 h. Con 37 h ese día, acabar por debajo
    del límite exige recortar en los que quedan.
    """
    bloques_ref = min(dia, _WHC_BLOQUES_SEMANA)
    horas_ref = bloques_ref * _WHC_BLOQUE_IMPLICITO
    exceso = c["trabajado"] - horas_ref
    # Bloques que aún le caben: los que le faltan para 6, pero nunca más que los
    # días que quedan de semana. Sin ese tope, un jueves con 4 bloques proyectaba
    # sólo 1 día más cuando en realidad le quedan 2.
    restantes = max(0, min(_WHC_BLOQUES_SEMANA - len(c["bloques"]), 7 - dia))
    proyeccion = c["trabajado"] + restantes * _WHC_BLOQUE_IMPLICITO
    if limite_min and c["trabajado"] > limite_min:
        estado = "pasado"
    elif limite_min and proyeccion > limite_min:
        estado = "peligro"
    elif exceso > 0:
        estado = "peligro"
    elif exceso > -60:
        estado = "justo"
    else:
        estado = "ok"
    return {"dia_semana": dia, "bloques_ref": bloques_ref, "horas_ref": horas_ref,
            "exceso_ritmo": exceso, "bloques_restantes": restantes,
            "proyeccion": proyeccion,
            "proyeccion_pasa": bool(limite_min and proyeccion > limite_min),
            "estado_ritmo": estado}


def _whc_evaluar(conductores: list, limite_min: int, bloque_limite: int = None,
                 dia: int = None) -> list:
    """Añade a cada conductor su margen semanal y el riesgo diario.

    OJO con la separacion: `supera_semanal` es un HECHO (el total trabajado lo
    da el propio portal). `riesgo_diario` es un AVISO, no un incumplimiento —
    ver el docstring del modulo para el porque.
    """
    out = []
    for c in conductores:
        con_hora = [b["minutos"] for b in c["bloques"] if b["minutos"] is not None]
        sin_hora = sum(1 for b in c["bloques"] if b["minutos"] is None)
        # Cuadre: si la suma de bloques con hora no explica el total, la
        # diferencia son los bloques sin hora de fin. Se reparte entre ellos
        # para poder estimarlos, y se marca como estimado.
        resto = c["trabajado"] - sum(con_hora)
        est = int(resto / sin_hora) if sin_hora and resto > 0 else 0
        origen = c.get("trabajado_origen") or ("portal" if c["trabajado"] else None)
        if not c["trabajado"] and c["bloques"]:
            # Red de seguridad: el portal no dio el total pero SI hay bloques.
            # Dejarlo en 0 seria lo peor de todo — el conductor apareceria como
            # que no ha trabajado, con sus bloques a la vista, y encima se caeria
            # del denominador del WHC. Se reconstruye desde los bloques y se
            # marca el origen para que la pantalla no lo presente como dato del
            # portal. Los bloques sin hora de fin valen la duracion implicita
            # medida en el propio plan (una ruta estandar, ~9 h).
            est = _WHC_BLOQUE_IMPLICITO
            origen = "bloques"
        for b in c["bloques"]:
            if b["minutos"] is None:
                b["minutos"] = est
        if origen == "bloques":
            c["trabajado"] = sum(b["minutos"] or 0 for b in c["bloques"])

        blim = bloque_limite or _WHC_BLOQUE_LIMITE
        largos = [b for b in c["bloques"] if (b["minutos"] or 0) >= _WHC_BLOQUE_RIESGO]
        pasados = [b for b in c["bloques"] if (b["minutos"] or 0) >= blim]
        margen = (limite_min - c["trabajado"]) if limite_min else None
        supera = bool(limite_min and c["trabajado"] > limite_min)
        out.append({
            **c,
            "dias_trabajados": len(c["bloques"]),
            "margen_semanal": margen,
            # OJO con el nombre: es TU limite, no el de Amazon. Amazon no marco
            # excepcion semanal a quien hizo 56h30m.
            "supera_semanal": supera,
            # "portal" = el total lo da Amazon. "bloques" = lo hemos reconstruido
            # porque el pegado no traia el total; la pantalla debe decirlo.
            "trabajado_origen": origen,
            # Tiene un bloque "en curso": esta trabajando AHORA. Es justo lo que
            # hay que saber de alguien que ya se ha pasado o esta al borde.
            "trabajando_ahora": any(b.get("en_curso") for b in c["bloques"]),
            **(_whc_ritmo(c, dia, limite_min) if dia else {}),
            "al_limite": bool(limite_min and 0 <= (margen or 0) <= _WHC_MARGEN_AVISO_PROPIO),
            "riesgo_diario": [{"inicio": b["inicio"], "fin": b["fin"],
                               "minutos": b["minutos"], "estimado": b["estimado"]}
                              for b in largos],
            # Bloques que se pasan de TU limite de jornada (11 h por defecto).
            "bloques_pasados": [{"inicio": b["inicio"], "fin": b["fin"],
                                 "minutos": b["minutos"], "estimado": b["estimado"]}
                                for b in pasados],
            # Incumplimiento segun TUS normas: pasarse de la semana o de la
            # jornada. Esto NO es la excepcion de Amazon, que se calcula sobre lo
            # fichado y sale en su hoja de excepciones.
            "incumple_propio": bool(supera or pasados),
            "cuadra": abs(c["trabajado"] - sum(b["minutos"] or 0 for b in c["bloques"])) <= 10,
        })
    orden = {True: 0, False: 1}
    out.sort(key=lambda c: (orden[c["incumple_propio"]], orden[c["supera_semanal"]],
                            -(c["trabajado"] or 0)))
    return out


@api_router.post("/whc/analizar")
async def whc_analizar(data: dict = Body(...), _=Depends(require_admin)):
    """Analiza el plan semanal pegado del portal y devuelve el estado de WHC."""
    texto = data.get("texto") or ""
    if len(texto.strip()) < 40:
        raise HTTPException(400, "Pega el plan de la semana desde el portal")
    limite = _WHC_LIMITE_PROPIO
    if data.get("limite_horas"):
        limite = int(_decimal(data["limite_horas"], "limite_horas", minimo=0, maximo=100) * 60)
    # Excepciones que Amazon ya reporto esta semana (de la hoja "Drivers With
    # Working Hour Exceptions"). Si no se dan, se asume 0 y el WHC sale al 100 %.
    try:
        excepciones = max(0, int(data.get("excepciones") or 0))
    except (TypeError, ValueError):
        excepciones = 0

    bloque_limite = _WHC_BLOQUE_LIMITE
    if data.get("limite_bloque_horas"):
        bloque_limite = int(_decimal(data["limite_bloque_horas"], "limite_bloque_horas",
                                     minimo=0, maximo=24) * 60)

    dia, dia_del_plan = _whc_dias_del_plan(texto)

    conductores = _whc_parsear(texto)
    if not conductores:
        raise HTTPException(400, "No se ha reconocido ningún conductor en ese texto")
    ev = _whc_evaluar(conductores, limite, bloque_limite, dia)

    # El plan se guarda para no tener que volver a pegarlo cada vez. Se guarda
    # por (centro, semana): una semana nueva no pisa la anterior.
    center = (data.get("center") or "").upper().strip()
    if center and data.get("guardar") is not False:
        sun, _sat = _sun_sat_week((datetime.now(timezone.utc)).strftime("%Y-%m-%d"))
        await db.whc_planes.update_one(
            {"center": center, "week": sun},
            {"$set": {"center": center, "week": sun, "texto": texto[:400000],
                      "limite_horas": round(limite / 60, 2),
                      "limite_bloque_horas": round(bloque_limite / 60, 2),
                      "excepciones": excepciones,
                      "updated_at": datetime.now(timezone.utc).isoformat()}},
            upsert=True)

    # ── WHC: el porcentaje que Amazon publica, calculado igual que ellos ──
    # El scorecard lo define textualmente: "The metric is calculated as % of
    # drivers complying with working hour limits". El denominador son los
    # conductores CON ACTIVIDAD esa semana (los que tienen horas en el plan).
    # Validado: S31 de OGA5, 69 conductores con horas y 2 excepciones ->
    # 67/69 = 97,101 %, que es el 97,1 % impreso en el PDF.
    con_actividad = sum(1 for c in ev if c["trabajado"] > 0)
    whc = None
    if con_actividad:
        cumplen = max(0, con_actividad - excepciones)
        pct = round(cumplen / con_actividad * 100, 1)
        whc = {
            "conductores_con_actividad": con_actividad,
            "excepciones": excepciones,
            "porcentaje": pct,
            # None cuando el porcentaje cae en una zona sin ningun scorecard
            # observado: no nos inventamos el tier.
            "tier": _whc_tier(pct),
            "tier_si_una_mas": _whc_tier(round(max(0, cumplen - 1) / con_actividad * 100, 1)),
            # Lo que de verdad hay que saber: cuanto cuesta UNA sola excepcion.
            # Con 69 conductores son 1,45 puntos, y basta una para dejar de
            # estar al 100 %. El WHC es practicamente todo o nada.
            "coste_por_excepcion": round(100 / con_actividad, 2),
            "porcentaje_si_una_mas": round(max(0, cumplen - 1) / con_actividad * 100, 1),
        }

    # ── WHC PROPIO: el cumplimiento segun TUS normas ──────────────────────────
    # Amazon publica su WHC con SUS excepciones, que no se saben hasta el martes.
    # Esto es otra cosa y va aparte: el % de conductores que cumplen las normas
    # de la DSP (no pasar del limite semanal ni de la jornada). Sirve para actuar
    # HOY, mientras el numero de Amazon todavia no existe.
    whc_propio = None
    if con_actividad:
        activos = [c for c in ev if c["trabajado"] > 0]
        incumplen = [c for c in activos if c["incumple_propio"]]
        por_semanal = [c for c in incumplen if c["supera_semanal"]]
        por_bloque = [c for c in incumplen if c["bloques_pasados"]]
        whc_propio = {
            "conductores": len(activos),
            "incumplen": len(incumplen),
            "por_semanal": len(por_semanal),
            "por_bloque": len(por_bloque),
            "por_ambos": sum(1 for c in incumplen
                             if c["supera_semanal"] and c["bloques_pasados"]),
            # Sin conductores en el cuadrante esto era un 500. Le pasa a toda
            # empresa el primer dia, que es justo cuando peor sienta.
            "porcentaje": (round((len(activos) - len(incumplen)) / len(activos) * 100, 1)
                           if activos else None),
            "limite_semanal_min": limite,
            "limite_bloque_min": bloque_limite,
            "trabajando_ahora": sum(1 for c in incumplen if c["trabajando_ahora"]),
            "quien": [{"nombre": c.get("nombre"), "trabajado": c["trabajado"],
                       "supera_semanal": c["supera_semanal"],
                       "trabajando_ahora": c["trabajando_ahora"],
                       "bloques_pasados": len(c["bloques_pasados"]),
                       "peor_bloque": max((b["minutos"] or 0)
                                          for b in c["bloques_pasados"]) if c["bloques_pasados"] else None}
                      for c in incumplen],
        }

    # ── RITMO DE LA SEMANA ────────────────────────────────────────────────────
    # Lo que sirve un miércoles: quién va por encima del ritmo, no quién ya se
    # pasó (todavía no se ha pasado nadie).
    en_ritmo = [c for c in ev if c["trabajado"] > 0]
    ritmo = {
        "dia_semana": dia,
        "dia_leido_del_plan": dia_del_plan,
        "bloques_ref": min(dia, _WHC_BLOQUES_SEMANA),
        "horas_ref_min": min(dia, _WHC_BLOQUES_SEMANA) * _WHC_BLOQUE_IMPLICITO,
        "pasados": sum(1 for c in en_ritmo if c.get("estado_ritmo") == "pasado"),
        "peligro": sum(1 for c in en_ritmo if c.get("estado_ritmo") == "peligro"),
        "justos": sum(1 for c in en_ritmo if c.get("estado_ritmo") == "justo"),
        "en_ruta_ahora": sum(1 for c in en_ritmo if c["trabajando_ahora"]),
        # Los que hay que mirar HOY: van mal de ritmo, ordenados por exceso, y
        # marcando quién sigue en ruta ahora mismo (a ése aún se le puede cortar).
        "avisos": sorted(
            [{"nombre": c.get("nombre"), "trabajado": c["trabajado"],
              "estado": c.get("estado_ritmo"), "exceso": c.get("exceso_ritmo"),
              "proyeccion": c.get("proyeccion"),
              "proyeccion_pasa": c.get("proyeccion_pasa"),
              "bloques": len(c["bloques"]),
              "bloques_restantes": c.get("bloques_restantes"),
              "trabajando_ahora": c["trabajando_ahora"]}
             for c in en_ritmo if c.get("estado_ritmo") in ("pasado", "peligro", "justo")],
            key=lambda x: (-(x["trabajando_ahora"]), -(x["exceso"] or 0)))[:25],
    }

    return {
        "semana": (data.get("semana") or "")[:40],
        "whc": whc,
        "whc_propio": whc_propio,
        "ritmo": ritmo,
        "limite_min": limite,
        "limite_bloque_min": bloque_limite,
        "limite_es_propio": True,
        "suelo_amazon_observado_min": _WHC_SUELO_AMAZON_OBSERVADO,
        "conductores": ev,
        "resumen": {
            "total": len(ev),
            "superan": sum(1 for c in ev if c["supera_semanal"]),
            "bloque_pasado": sum(1 for c in ev if c["bloques_pasados"]),
            "incumplen_propio": sum(1 for c in ev if c["incumple_propio"]),
            "al_limite": sum(1 for c in ev if c["al_limite"]),
            "con_riesgo_diario": sum(1 for c in ev if c["riesgo_diario"]),
            "no_cuadran": sum(1 for c in ev if not c["cuadra"]),
        },
        # Que la pantalla pueda explicar por que no afirma nada de lo diario.
        "aviso_diario": ("El límite semanal de aquí es EL TUYO, no el de Amazon: "
                         "en la semana 31 un conductor hizo 56 h 30 m y Amazon "
                         "NO marcó excepción semanal, así que su umbral es mayor. "
                         "Y los bloques largos son un aviso de riesgo, no un "
                         "incumplimiento: en semanas con CERO excepciones hay "
                         "bloques de 11 h 44 m, y sin embargo uno de 10 h 05 m sí "
                         "generó excepción. La excepción se calcula sobre lo "
                         "FICHADO, que no está en el plan."),
    }


@api_router.get("/cortex/calidad")
async def cortex_calidad(desde: str = "", hasta: str = "", center: str = "",
                         _=Depends(require_admin)):
    """Calidad de entrega real, calculada desde Cortex, sin subir nada.

    Por defecto la semana scorecard en curso (domingo->sabado, como Amazon).
    Solo puntuan los dias cerrados; el dia en curso va aparte como progreso.
    """
    hoy = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    if not desde or not hasta:
        desde, hasta = _sun_sat_week(hoy)
    for v in (desde, hasta):
        if not re.match(r"^\d{4}-\d{2}-\d{2}$", v):
            raise HTTPException(400, "Fechas en formato AAAA-MM-DD")

    bruto = await _cx_bruto(desde, hasta, center)
    if not bruto:
        return {"desde": desde, "hasta": hasta, "center": center, "hay_datos": False,
                "dias": {}, "total": None, "conductores": [], "impacto": [],
                "en_curso": None, "objetivos": {}, "margen": None}

    dias = _cx_dias(bruto)
    cerrados = {d for d, v in dias.items() if v["cerrado"]}

    # --- agregado de los dias cerrados, por conductor ---
    # OJO: si un paquete no trae driver_id, Mongo NO mete la clave en el _id del
    # $group con valor null: la OMITE. Un r["_id"]["cond"] directo revienta con
    # KeyError. Pasa de verdad: 94 paquetes sin conductor, y 70 de ellos son
    # fallos, asi que tirarlos falsearia el DCR a la baja. Van a SIN_CONDUCTOR.
    # LA FOTO CONGELADA MANDA TAMBIEN AQUI. Este recuento sale del estado de
    # AHORA de cada paquete, y un devuelto el viernes que se re-reparte el
    # lunes deja de ser un fallo del viernes (gotcha 39). Medido el 02-09-2026
    # en la misma pantalla: arriba "DCR de la semana 99,79 % · 34 fallos" y
    # abajo, con la foto, "98,4 % · 347 fallos". El de arriba era el que
    # Amazon nunca veria. Los dias cerrados se sustituyen por su foto cuando
    # la foto vio mas fallos, con la MISMA regla que la scorecard en vivo.
    fotos = {f["fecha"]: f for f in await _cx_dias_reparto(center, desde, hasta)}
    for d in cerrados:
        f = fotos.get(d)
        if f and f.get("congelado"):
            dias[d].update({"ok": f["entregados"], "fallo": f["fallos"],
                            "nodesp": f["no_despachados"], "vuelo": f["en_vuelo"],
                            "total": f["total"], "congelado": True,
                            "rts_foto": int((f.get("por_estado") or {}).get("BACK_TO_ORIGIN", 0))})

    porc, tot = {}, {"ok": 0, "fallo": 0, "rts": 0, "nodesp": 0}
    rts_vivo: dict = {}
    for r in bruto:
        dia = r["_id"].get("dia")
        if dia not in cerrados:
            continue
        cid = r["_id"].get("cond") or "SIN_CONDUCTOR"
        a = porc.setdefault(cid, {"ok": 0, "fallo": 0, "rts": 0, "nodesp": 0})
        for k in ("ok", "fallo", "rts", "nodesp"):
            a[k] += r[k]
        rts_vivo[dia] = rts_vivo.get(dia, 0) + r["rts"]
    # El total de la semana sale de los dias (ya con foto). El reparto por
    # conductor sigue siendo el vivo, que es el unico con nombre: la foto guarda
    # estados, no personas. Por eso los fallos por conductor son un MINIMO.
    for d in cerrados:
        v = dias[d]
        tot["ok"] += v["ok"]
        tot["fallo"] += v["fallo"]
        tot["nodesp"] += v["nodesp"]
        tot["rts"] += v["rts_foto"] if v.get("congelado") else rts_vivo.get(d, 0)

    total = _cx_tasas(tot["ok"], tot["fallo"], tot["rts"])
    total["dias_congelados"] = sum(1 for d in cerrados if dias[d].get("congelado"))
    total["no_despachados"] = tot["nodesp"]
    total["dias_cerrados"] = len(cerrados)
    total["dias_totales"] = len(dias)

    nombres = await _cx_nombres({c for c in porc if c != "SIN_CONDUCTOR"})
    conductores = []
    for cid, a in porc.items():
        n = nombres.get(cid, {})
        conductores.append({
            "driver_id": cid, "nombre": n.get("nombre"), "ficha_id": n.get("ficha_id"),
            "origen_nombre": n.get("origen"), "sin_ficha": cid != "SIN_CONDUCTOR" and not n,
            **_cx_tasas(a["ok"], a["fallo"], a["rts"]),
        })
    conductores.sort(key=lambda c: (c["dcr"] if c["dcr"] is not None else 101))

    tasa_fallo = (tot["fallo"] / (tot["ok"] + tot["fallo"])) if (tot["ok"] + tot["fallo"]) else 0
    impacto = _cx_impacto([c for c in conductores if c["despachados"]], tasa_fallo)

    # --- objetivos y margen que queda ---
    obj = dict(_DEFAULT_TARGETS)
    doc = await db.scorecard_targets.find_one({"center": center or "GLOBAL"}, {"_id": 0}) \
        or await db.scorecard_targets.find_one({"center": "GLOBAL"}, {"_id": 0})
    if doc:
        for k in _DEFAULT_TARGETS:
            if doc.get(k) is not None:
                obj[k] = doc[k]

    margen = None
    if total["despachados"] and len(cerrados):
        # Estimacion del volumen de la semana: media diaria de los dias cerrados
        # por los dias de servicio que tiene la semana. Es una estimacion y se
        # dice que lo es; el margen se recalcula solo cada dia que cierra.
        media_dia = total["despachados"] / len(cerrados)
        # Los dias que faltan por venir cuentan: si no, un martes se preveia una
        # semana de 3 dias y el margen salia por los suelos (alarma falsa justo
        # los dias en que mas se mira la pantalla).
        por_venir = 0
        try:
            d_hoy = datetime.strptime(hoy, "%Y-%m-%d")
            d_fin = datetime.strptime(hasta, "%Y-%m-%d")
            por_venir = max(0, (d_fin - d_hoy).days)
        except ValueError:
            pass
        dias_previstos = max(len(dias) + por_venir, len(cerrados))
        prevision = media_dia * dias_previstos
        max_fallos = prevision * (1 - float(obj["dcr"]) / 100)
        # Los fallos de TODOS los dias del rango, no solo los cerrados: si se
        # permiten 7 dias de fallos hay que contar 7 dias de fallos. Antes se
        # permitian 7 y se contaban 6, y el margen salia inflado en un dia
        # entero — optimista, que es la direccion que hace dano.
        # Un BACK_TO_ORIGIN de hoy ya es un fallo aunque la jornada siga abierta.
        fallos_del_rango = sum(v["fallo"] for v in dias.values())
        margen = {
            "objetivo_dcr": float(obj["dcr"]),
            "fallos_hasta_ahora": fallos_del_rango,
            "fallos_en_dias_cerrados": tot["fallo"],
            "fallos_permitidos": int(max_fallos),
            "margen_restante": int(max_fallos - fallos_del_rango),
            "prevision_paquetes": int(prevision),
            "dias_previstos": dias_previstos,
            "en_objetivo": total["dcr"] is not None and total["dcr"] >= float(obj["dcr"]),
        }

    # --- dia en curso: progreso, NUNCA nota ---
    en_curso = None
    abiertos = sorted(d for d in dias if not dias[d]["cerrado"])
    # Solo es "en curso" si el dia ES hoy. Un dia pasado que quedo sin cerrar no
    # es una jornada en marcha: es un hueco de captura de la extension, y
    # venderlo como "Jornada de hoy · 73 % de avance" es mentir con datos de
    # anteayer. Paso de verdad el 2026-08-04 con el dia 2026-08-02 (25,65 %
    # en vuelo). Los dias incompletos se listan aparte y se dicen como tales.
    if abiertos and abiertos[-1] == hoy:
        d = abiertos[-1]
        v = dias[d]
        en_curso = {"dia": d, "entregados": v["ok"], "en_vuelo": v["vuelo"],
                    "fallos_provisionales": v["fallo"], "total": v["total"],
                    "avance_pct": round(v["ok"] / v["total"] * 100, 1) if v["total"] else 0,
                    "nota": "Jornada sin cerrar: no puntua todavia."}

    return {"desde": desde, "hasta": hasta, "center": center, "hay_datos": True,
            "dias": dias, "total": total, "conductores": conductores,
            "impacto": impacto[:8], "en_curso": en_curso, "objetivos": obj,
            # Dias del rango que no puntuan por captura incompleta. Que se vean:
            # un scorecard calculado sobre datos con huecos hay que poder auditarlo.
            "dias_incompletos": [d for d in abiertos if d != hoy],
            "referencia_fantastic": _TARGETS_FANTASTIC,
            # True si el objetivo configurado es MAS BLANDO que el de Amazon: la
            # pantalla lo avisa en vez de dar por bueno un aprobado que Amazon
            # no daria.
            "objetivo_blando": float(obj["dcr"]) < _TARGETS_FANTASTIC["dcr"],
            "margen": margen,
            "sin_ficha": sorted({c["driver_id"] for c in conductores if c["sin_ficha"]})}


@api_router.get("/cortex/simular")
async def cortex_simular(desde: str = "", hasta: str = "", center: str = "",
                         conductores: str = "", _=Depends(require_admin)):
    """Si estos conductores bajaran a la media de la flota, ¿donde queda el DCR?

    No es una promesa: es aritmetica sobre los paquetes que YA se han repartido.
    Sirve para decidir a quien formar primero con un numero delante, en vez de
    por corazonada.
    """
    ids = [x for x in (conductores or "").split(",") if x.strip()]
    datos = await cortex_calidad(desde=desde, hasta=hasta, center=center)
    if not datos["hay_datos"] or not datos["total"]["despachados"]:
        raise HTTPException(400, "No hay datos suficientes en ese periodo")

    elegidos = [c for c in datos["impacto"] if c["driver_id"] in ids] if ids else datos["impacto"][:3]
    recuperables = sum(c["exceso"] for c in elegidos)
    t = datos["total"]
    dcr_nuevo = round((t["entregados"] + recuperables) / t["despachados"] * 100, 2)
    return {
        "dcr_actual": t["dcr"], "dcr_simulado": dcr_nuevo,
        "ganancia_puntos": round(dcr_nuevo - t["dcr"], 2),
        "paquetes_recuperables": int(round(recuperables)),
        "objetivo": float(datos["objetivos"]["dcr"]),
        "alcanza_objetivo": dcr_nuevo >= float(datos["objetivos"]["dcr"]),
        "conductores": [{"driver_id": c["driver_id"], "nombre": c["nombre"],
                         "exceso": c["exceso"], "dcr": c["dcr"]} for c in elegidos],
    }


# Rejilla de agrupacion de portales. 0,0004 grados de latitud son ~44 m y
# 0,0005 de longitud ~40 m a la latitud de Galicia. Suficiente para que el
# mismo portal caiga siempre en la misma celda pese a la deriva del GPS, y
# bastante fino para no mezclar dos edificios distintos de la misma calle.
_PORTAL_LAT = 0.0004
_PORTAL_LNG = 0.0005

# Estados que cuentan como "fallo en el portal": el conductor LLEGO y no pudo
# entregar. ATTEMPTED entra porque un intento fallido en el mismo sitio dos dias
# distintos es justo la senal que buscamos, aunque el paquete se entregara luego.
#
# UNCOLLECTED esta fuera a proposito: significa que el paquete no se recogio en
# la estacion y nunca subio a la furgoneta. Medido en el peor punto: de 53
# fallos, 34 eran UNCOLLECTED — un problema de carga disfrazado de portal
# imposible. Ademas _CX_NO_DESPACHADO ya lo saca del DCR por lo mismo: contarlo
# aqui como fallo de entrega seria darle dos significados a la misma cosa.
# La senal no se pierde: se cuenta aparte como `no_recogidos`.
_PORTAL_FALLOS = ("BACK_TO_ORIGIN", "CUSTOMER_UNAVAILABLE", "ADDRESS_NOT_FOUND",
                  "ATTEMPTED")
_PORTAL_NO_RECOGIDOS = ("UNCOLLECTED", "NOT_READY")


def _celda(lat, lng):
    """Coordenada -> identificador estable de celda. None si no es un numero."""
    try:
        return "%d:%d" % (round(float(lat) / _PORTAL_LAT), round(float(lng) / _PORTAL_LNG))
    except (TypeError, ValueError):
        return None


def _celda_centro(celda: str):
    a, b = celda.split(":")
    return round(int(a) * _PORTAL_LAT, 6), round(int(b) * _PORTAL_LNG, 6)


def _fusionar_celdas(claves):
    """Agrupa celdas que se tocan (vecindad de 8). Devuelve [[celda, ...], ...].

    Sin esto, un portal justo en el borde de la rejilla aparece dos veces y la
    nota de una mitad no llega al conductor que entra por la otra. Pasa de
    verdad: los dos peores portales de julio eran el mismo, a 16 metros.
    """
    padre = {k: k for k in claves}

    def raiz(x):
        while padre[x] != x:
            padre[x] = padre[padre[x]]
            x = padre[x]
        return x

    def unir(a, b):
        ra, rb = raiz(a), raiz(b)
        if ra != rb:
            padre[rb] = ra

    presentes = set(claves)
    for k in claves:
        a, b = (int(x) for x in k.split(":"))
        for da in (0, 1):
            for dbb in (-1, 0, 1):
                if da == 0 and dbb <= 0:
                    continue          # cada par se visita una sola vez
                v = "%d:%d" % (a + da, b + dbb)
                if v in presentes:
                    unir(k, v)
    grupos = {}
    for k in claves:
        grupos.setdefault(raiz(k), []).append(k)
    return list(grupos.values())


def _stage_celda():
    """Agrupacion por celda dentro de Mongo. lat/lng vienen como TEXTO en los
    documentos de Cortex, asi que hay que convertirlos y descartar los rotos
    sin reventar la consulta ($convert con onError)."""
    num = lambda c: {"$convert": {"input": c, "to": "double", "onError": None, "onNull": None}}
    return [
        {"$addFields": {"_la": num("$lat"), "_ln": num("$lng")}},
        {"$match": {"_la": {"$ne": None}, "_ln": {"$ne": None}}},
        {"$addFields": {"_celda": {"$concat": [
            {"$toString": {"$round": [{"$divide": ["$_la", _PORTAL_LAT]}, 0]}}, ":",
            {"$toString": {"$round": [{"$divide": ["$_ln", _PORTAL_LNG]}, 0]}}]}}},
    ]


@api_router.get("/cortex/portales")
async def cortex_portales(dias: int = 60, center: str = "", minimo_dias: int = 2,
                          _=Depends(require_admin)):
    """Portales que fallan una y otra vez, con la nota que alguien dejo.

    minimo_dias=2 por defecto: un fallo suelto es mala suerte, dos dias
    distintos en el mismo portal es un patron. Con minimo_dias=1 se ve todo.
    """
    dias = max(7, min(int(dias or 60), 365))
    desde = (datetime.now(timezone.utc) - timedelta(days=dias)).strftime("%Y-%m-%d")
    match = {"service_day": {"$gte": desde}, "state": {"$in": list(_PORTAL_FALLOS)}}
    if center:
        match["center"] = {"$regex": re.escape(center.strip()), "$options": "i"}

    cur = db.cortex_packages.aggregate(
        [{"$match": match}] + _stage_celda() + [
            {"$group": {"_id": "$_celda",
                        "fallos": {"$sum": 1},
                        "dias": {"$addToSet": "$service_day"},
                        "estados": {"$addToSet": "$state"},
                        # La dirección que da Amazon. Es la MITAD de la historia:
                        # sirve para contrastarla con lo que dice el mapa en esa
                        # coordenada, que es de donde sale la señal de verdad.
                        "direcciones": {"$addToSet": "$stop_address"},
                        "lat": {"$first": "$_la"}, "lng": {"$first": "$_ln"},
                        "center": {"$first": "$center"},
                        "ultimo": {"$max": "$service_day"}}},
            {"$match": {"$expr": {"$gte": [{"$size": "$dias"}, int(minimo_dias)]}}},
            {"$sort": {"fallos": -1}}, {"$limit": 300},
        ], allowDiskUse=True)
    celdas = await cur.to_list(300)
    if not celdas:
        return {"portales": [], "resumen": {"reincidentes": 0, "fallos": 0}}

    # Entregas correctas en esas mismas celdas: distingue "direccion imposible"
    # de "aqui se entrega bien salvo en un piso concreto". Cambia la accion.
    claves = [c["_id"] for c in celdas]
    cur2 = db.cortex_packages.aggregate(
        [{"$match": {"service_day": {"$gte": desde},
                     "state": {"$in": ["DELIVERED"] + list(_PORTAL_NO_RECOGIDOS)},
                     **({"center": match["center"]} if center else {})}}]
        + _stage_celda() + [
            {"$match": {"_celda": {"$in": claves}}},
            {"$group": {"_id": "$_celda",
                        "ok": {"$sum": {"$cond": [{"$eq": ["$state", "DELIVERED"]}, 1, 0]}},
                        # Se quedaron en la estacion: no es culpa del portal,
                        # pero el DSP quiere saberlo igual.
                        "nr": {"$sum": {"$cond": [{"$eq": ["$state", "DELIVERED"]}, 0, 1]}}}},
        ], allowDiskUse=True)
    _c2 = await cur2.to_list(500)
    ok_por_celda = {r["_id"]: r["ok"] for r in _c2}
    nr_por_celda = {r["_id"]: r["nr"] for r in _c2}

    notas = {n["celda"]: n async for n in db.portales.find({"celda": {"$in": claves}}, {"_id": 0})}
    por_celda = {c["_id"]: c for c in celdas}

    portales = []
    for grupo in _fusionar_celdas(claves):
        trozos = [por_celda[k] for k in grupo]
        dias = set()
        for t in trozos:
            dias.update(t["dias"])
        fallos = sum(t["fallos"] for t in trozos)
        ok = sum(ok_por_celda.get(k, 0) for k in grupo)
        no_recogidos = sum(nr_por_celda.get(k, 0) for k in grupo)
        # La nota del grupo es la de cualquiera de sus celdas: al guardarla se
        # escribe en todas, pero un grupo puede crecer despues (celda nueva con
        # fallos) y entonces solo una la tiene.
        n = next((notas[k] for k in grupo if k in notas), {})
        # La resolución del mapa se guarda por celda igual que la nota: la del
        # grupo es la de cualquiera de sus celdas.
        g = next((notas[k].get("geo") for k in grupo if notas.get(k, {}).get("geo")), None)
        # Dónde está de verdad la dirección (búsqueda por texto en varios
        # buscadores). Es lo que trae la distancia a donde mandaron al conductor.
        gd = next((notas[k].get("geodir") for k in grupo if notas.get(k, {}).get("geodir")), None)
        principal = max(trozos, key=lambda t: t["fallos"])
        # Una celda son ~25 m: puede cubrir más de un portal, y ver DOS
        # direcciones distintas ahí es información, no un error que ocultar.
        dirs = sorted({(d or "").strip() for t in trozos for d in (t.get("direcciones") or []) if (d or "").strip()})
        portales.append({
            "celda": principal["_id"], "celdas": sorted(grupo),
            "lat": principal["lat"], "lng": principal["lng"],
            "center": (principal.get("center") or "").strip(),
            "fallos": fallos, "dias_distintos": len(dias),
            "no_recogidos": no_recogidos,
            "ultimo_fallo": max(t["ultimo"] for t in trozos), "entregas_ok": ok,
            "tasa_fallo": round(fallos / (fallos + ok) * 100, 1) if (fallos + ok) else 100.0,
            "estados": sorted({e for t in trozos for e in t["estados"]}),
            "direcciones": dirs[:3],
            "geo": g, "geodir": gd,
            "nota": n.get("nota"), "nota_autor": n.get("autor"),
            "nota_fecha": n.get("actualizado_en"), "resuelto": bool(n.get("resuelto")),
        })
    portales.sort(key=lambda p: p["fallos"], reverse=True)
    return {"portales": portales,
            "resumen": {"reincidentes": len(portales),
                        "fallos": sum(p["fallos"] for p in portales),
                        "sin_nota": sum(1 for p in portales if not p["nota"])}}


@api_router.post("/cortex/portales")
async def cortex_portal_nota(data: dict = Body(...), user: dict = Depends(require_admin)):
    """Guarda (o borra) la nota de un portal. body: {celda, nota, resuelto?}"""
    celdas = data.get("celdas") or [data.get("celda")]
    celdas = [str(c).strip() for c in celdas if c and re.match(r"^-?\d+:-?\d+$", str(c).strip())]
    if not celdas:
        raise HTTPException(400, "Celda no valida")
    nota = (data.get("nota") or "").strip()[:600]
    if not nota:
        # Borrar la nota NO puede llevarse por delante lo que calculó el mapa,
        # que vive en el mismo documento y lo puso otra acción distinta. Son DOS
        # subdocumentos: `geo` (qué hay en la coordenada) y `geodir` (dónde está
        # la dirección). Mirar sólo `geo` borraba el documento entero de un
        # portal que ya tuviera `geodir`, y con él la dirección encontrada.
        conservar = {"$or": [{"geo": {"$exists": True}}, {"geodir": {"$exists": True}}]}
        await db.portales.update_many(
            {"celda": {"$in": celdas}, **conservar},
            {"$unset": {"nota": "", "autor": "", "actualizado_en": "", "resuelto": "", "grupo": ""}})
        await db.portales.delete_many(
            {"celda": {"$in": celdas}, "geo": {"$exists": False}, "geodir": {"$exists": False}})
        return {"success": True, "borrada": True}
    ahora = datetime.now(timezone.utc).isoformat()
    autor = user.get("name") or user.get("username")
    # Se escribe en todas las celdas del grupo a proposito: asi el conductor la
    # encuentra con una consulta por indice, entre por el lado que entre.
    for c in celdas:
        lat, lng = _celda_centro(c)
        await db.portales.update_one({"celda": c}, {"$set": {
            "celda": c, "lat": lat, "lng": lng, "nota": nota,
            "grupo": celdas, "resuelto": bool(data.get("resuelto")),
            "autor": autor, "actualizado_en": ahora,
        }}, upsert=True)
    return {"success": True, "celdas": len(celdas)}


# 'lugar' es un sitio con nombre propio (As Buceleiras, Malvares), que NO es lo
# mismo que 'zona' —el centro del municipio cuando nadie encontró nada—. Sin
# este escalón, media Galicia rural se guardaba como "no lo sé". Ver el bloque
# PRECISION_LUGAR en geoDireccion.js.
_GEO_PRECISIONES = ("portal", "calle", "lugar", "zona")


@api_router.post("/cortex/portales/geo")
async def cortex_portal_geo(data: dict = Body(...), user: dict = Depends(require_admin)):
    """Guarda lo que el mapa dice que hay en la coordenada de un portal.

    Quién geocodifica y por qué así: lo hace el NAVEGADOR contra Nominatim
    (OpenStreetMap), a petición de una persona y de uno en uno. La política de
    uso de Nominatim prohíbe barridos masivos, y un cron del backend recorriendo
    300 portales sería exactamente eso. Aquí solo se persiste el resultado para
    que se pida UNA vez y lo vean todos, incluido el conductor en su ruta.

    Esto NO es "la dirección correcta". Es una SEGUNDA OPINIÓN sobre la misma
    coordenada, que se guarda junto a la de Amazon para poder contrastarlas. La
    señal útil es el desacuerdo entre las dos, no ninguna de las dos por
    separado. Por eso viaja siempre con su precisión y su fecha.

    Nunca pisa la nota escrita por una persona: va en su propio subdocumento.
    """
    celdas = data.get("celdas") or [data.get("celda")]
    celdas = [str(c).strip() for c in celdas if c and re.match(r"^-?\d+:-?\d+$", str(c).strip())]
    if not celdas:
        raise HTTPException(400, "Celda no valida")

    g = data.get("geo")
    if g is None:
        # Borrar la resolución es legítimo: si el mapa se equivocó, mejor sin
        # dato que con uno malo.
        for c in celdas:
            await db.portales.update_one({"celda": c}, {"$unset": {"geo": ""}})
        return {"success": True, "borrada": True}
    if not isinstance(g, dict):
        raise HTTPException(400, "geo debe ser un objeto")

    precision = str(g.get("precision") or "").strip()
    if precision not in _GEO_PRECISIONES:
        # Sin precisión declarada no se guarda. Una dirección sin saber si es
        # del portal, de la calle o del barrio no se puede usar para nada.
        raise HTTPException(400, f"precision debe ser una de {_GEO_PRECISIONES}")

    geo = {
        "display": str(g.get("display") or "").strip()[:300],
        "calle": str(g.get("calle") or "").strip()[:160],
        "numero": str(g.get("numero") or "").strip()[:20],
        "cp": str(g.get("cp") or "").strip()[:12],
        "municipio": str(g.get("municipio") or "").strip()[:120],
        "precision": precision,
        # Con qué se confirmó. 'dos_fuentes' significa que OpenStreetMap y el
        # callejero oficial del IGN coincidieron en la vía; sin eso no se afirma.
        "fuente": str(g.get("fuente") or "openstreetmap")[:40],
        "acuerdo": str(g.get("acuerdo") or "")[:40],
        "por": user.get("name") or user.get("username"),
        "en": datetime.now(timezone.utc).isoformat(),
    }
    if not geo["display"]:
        raise HTTPException(400, "geo.display vacio")

    for c in celdas:
        lat, lng = _celda_centro(c)
        await db.portales.update_one({"celda": c}, {"$set": {
            "celda": c, "lat": lat, "lng": lng, "geo": geo,
        }}, upsert=True)
    return {"success": True, "celdas": len(celdas), "geo": geo}


@api_router.post("/cortex/portales/geodir")
async def cortex_portal_geodir(data: dict = Body(...), user: dict = Depends(require_admin)):
    """Guarda DÓNDE ESTÁ DE VERDAD la dirección que Amazon dio para este portal.

    Va al revés que /geo. Allí se pregunta qué hay en la coordenada; aquí se
    coge el TEXTO de la dirección y se busca en varios geocodificadores a la
    vez (`lib/geoDireccion.js`). Lo hace el NAVEGADOR: Nominatim responde 403 al
    servidor, así que un cron aquí no podría consultarlo ni aunque quisiera.

    El dato que se guarda y el único que sirve para actuar es `metros_amazon`:
    la distancia entre donde está la dirección y donde mandaron al conductor.

    ── LO QUE ESTE ENDPOINT NO SE CREE ──────────────────────────────────────
    La regla de "dos familias independientes" se vuelve a exigir AQUÍ, no sólo
    en el navegador. Una coordenada equivocada manda a un conductor a otro
    sitio, así que la comprobación tiene que estar en el sitio que escribe en la
    base de datos: un cliente viejo, una pestaña con código antiguo o una
    llamada a mano no pueden colar una dirección sin confirmar.
    """
    celdas = data.get("celdas") or [data.get("celda")]
    celdas = [str(c).strip() for c in celdas if c and re.match(r"^-?\d+:-?\d+$", str(c).strip())]
    if not celdas:
        raise HTTPException(400, "Celda no valida")

    g = data.get("geodir")
    if g is None:
        for c in celdas:
            await db.portales.update_one({"celda": c}, {"$unset": {"geodir": ""}})
        return {"success": True, "borrada": True}
    if not isinstance(g, dict):
        raise HTTPException(400, "geodir debe ser un objeto")

    # Dos familias de datos DISTINTAS. Nominatim y Photon cuentan como una sola
    # (las dos leen OpenStreetMap): que coincidan es la misma opinión repetida,
    # no una confirmación.
    familias = [str(f).strip().lower()[:20] for f in (g.get("familias") or []) if str(f).strip()]
    familias = sorted(set(familias))
    nivel = g.get("precision_acuerdo")
    if len(familias) < 2:
        # EXCEPCIÓN, y sólo una: el callejero OFICIAL (IGN) solo, y únicamente
        # para afirmar la ZONA, nunca el portal. En los pueblos pequeños
        # OpenStreetMap no tiene la calle y no hay segunda fuente posible; sin
        # esta salida el sistema se queda mudo justo donde el conductor más se
        # pierde. El navegador ya ha comprobado antes que el municipio y el
        # nombre de vía que devuelve el IGN son los que se le pidieron — que es
        # lo que caza los dos errores reales que se le vieron (un portal en
        # Guitiriz para una dirección de Lugo, y 'TRAS DO PILAR' por 'Rúa do
        # Vilar').
        #
        # Y la segunda: CONFIRMAR el punto de Amazon no es lo mismo que
        # contradecirle. Decir "está en otro sitio" mueve al conductor y por eso
        # exige dos familias; decir "la coordenada es correcta" no mueve a
        # nadie —sigue yendo donde ya iba— y una sola fuente que caiga encima
        # del punto basta. Medido en las direcciones reales del 15/08: la mitad
        # de los casos son exactamente esto (Photon a 6 m, a 20 m, a 238 m), y
        # exigirles dos familias los dejaba en "no se ha podido confirmar"
        # cuando la respuesta útil era "el fallo no es la coordenada, es el
        # portal: timbre, negocio cerrado, puerta sin número".
        confirma = g.get("veredicto") == "coincide"
        if not (nivel == "zona" and (familias == ["ign"] or confirma)):
            raise HTTPException(400, "hacen falta 2 familias de fuentes distintas")

    try:
        lat = float(g.get("lat"))
        lng = float(g.get("lng"))
    except (TypeError, ValueError):
        raise HTTPException(400, "lat/lng no validas")
    if not (-90 <= lat <= 90 and -180 <= lng <= 180):
        raise HTTPException(400, "lat/lng fuera de rango")

    # La distancia se RECALCULA aquí contra el centro de la celda en vez de
    # creerse la del cliente: es el número que se le enseña al conductor y no
    # puede depender de que la pestaña hiciera bien la cuenta.
    ref_lat, ref_lng = _celda_centro(celdas[0])
    metros = _haversine_km((lat, lng), (ref_lat, ref_lng))
    metros = int(round(metros * 1000)) if metros is not None else None

    precision = str(g.get("precision") or "").strip()
    if precision not in _GEO_PRECISIONES:
        raise HTTPException(400, f"precision debe ser una de {_GEO_PRECISIONES}")

    geodir = {
        "display": str(g.get("display") or "").strip()[:300],
        "lat": lat, "lng": lng,
        "metros_amazon": metros,
        # De qué texto se partió: sin esto no hay forma de revisar despues por
        # qué salió lo que salió.
        "direccion_amazon": str(g.get("direccion_amazon") or "").strip()[:300],
        "familias": familias,
        "fuentes": [str(f).strip()[:20] for f in (g.get("fuentes") or [])][:6],
        "precision": precision,
        # Qué se está afirmando exactamente:
        #   'portal' → DOS fuentes dieron número de portal.
        #   'calle'  → coinciden en la vía, no en el número.
        #   'zona'   → sólo coinciden en el área (<1 km). NO señala un portal;
        #              sirve para avisar de que el punto de Amazon queda fuera.
        # Se guarda tal cual porque el aviso que ve el conductor cambia según
        # esto: mandarle al "portal exacto" cuando sólo se sabe la zona es
        # justo el falso positivo que no puede pasar.
        "precision_acuerdo": (g.get("precision_acuerdo")
                              if g.get("precision_acuerdo") in ("portal", "calle", "zona")
                              else "calle"),
        # Y esto es lo que se le dice a la persona: si el punto de Amazon está
        # BIEN ('coincide') o desplazado. Que esté bien también es una respuesta
        # útil —"la coordenada no es el problema"— y antes no se guardaba.
        "veredicto": (g.get("veredicto")
                      if g.get("veredicto") in ("coincide", "desplazada") else "no_lo_se"),
        "dispersion_m": int(g.get("dispersion_m") or 0),
        "por": user.get("name") or user.get("username"),
        "en": datetime.now(timezone.utc).isoformat(),
    }
    if not geodir["display"]:
        raise HTTPException(400, "geodir.display vacio")

    for c in celdas:
        clat, clng = _celda_centro(c)
        await db.portales.update_one({"celda": c}, {"$set": {
            "celda": c, "lat": clat, "lng": clng, "geodir": geodir,
        }}, upsert=True)
    return {"success": True, "celdas": len(celdas), "geodir": geodir}


@api_router.get("/cortex/geocode")
async def cortex_geocode(q: str, _=Depends(require_admin)):
    """Geocodifica una dirección con Google. CUARTA FAMILIA de fuentes.

    ── POR QUÉ PASA POR AQUÍ Y NO POR EL NAVEGADOR ──────────────────────────
    Dos motivos, y los dos importan:
      · El servicio de geocodificación de Google NO admite CORS: desde el
        navegador no se puede llamar. (Al revés que Nominatim, que sólo funciona
        desde el navegador porque al servidor le responde 403. Cada fuente tiene
        su lado.)
      · Y sobre todo: así la clave vive SÓLO en los secretos de Fly. Metida en
        el navegador estaría a la vista de cualquiera que abra el código.

    ── LO QUE SE MIRA DE LA RESPUESTA ───────────────────────────────────────
    Google contesta SIEMPRE algo. Cuando no encuentra la dirección devuelve el
    centro del municipio, y ése es su resultado peligroso: parece una respuesta
    y no lo es. Pero lo avisa, y hay que hacerle caso:
      · `location_type`: ROOFTOP es el portal exacto; RANGE_INTERPOLATED,
        interpolado sobre el tramo; GEOMETRIC_CENTER y APPROXIMATE, el centro
        de algo (una vía entera o un pueblo).
      · `partial_match: true`: "he entendido sólo una parte de lo que me has
        pedido". Medido con direcciones reales: en 'Calle El Barro 34,
        Pontedeume' devuelve el centro de Pontedeume con las dos señales
        puestas, y en 'Calzada de Santo Antonio 22, A Estrada' acierta el portal
        con ROOFTOP y sin partial_match.

    Aquí no se decide nada: se traduce la respuesta y se declara su precisión.
    Quien decide si dos fuentes coinciden es el navegador, con las mismas reglas
    que aplica a las otras tres.
    """
    clave = os.environ.get("GOOGLE_GEOCODING_KEY", "").strip()
    if not clave:
        raise HTTPException(503, "Google no configurado")
    texto = (q or "").strip()[:300]
    if len(texto) < 5:
        raise HTTPException(400, "consulta demasiado corta")

    try:
        # httpx se importa dentro de la función, como en el resto del fichero:
        # aquí no es un módulo global.
        import httpx as _httpx
        async with _httpx.AsyncClient(timeout=12) as c:
            r = await c.get("https://maps.googleapis.com/maps/api/geocode/json",
                            params={"address": texto, "region": "es",
                                    "language": "es", "key": clave})
        j = r.json()
    except Exception as e:
        logger.warning(f"google geocode: {e}")
        return {"ok": False, "motivo": "sin_respuesta"}

    estado = j.get("status")
    if estado != "OK" or not j.get("results"):
        # ZERO_RESULTS es una respuesta legítima. REQUEST_DENIED / OVER_QUERY_LIMIT
        # son problemas de la cuenta y conviene verlos en el log, no tragárselos.
        if estado not in ("OK", "ZERO_RESULTS"):
            logger.warning(f"google geocode {estado}: {j.get('error_message', '')[:200]}")
        return {"ok": False, "motivo": estado or "sin_datos"}

    res = j["results"][0]
    comp = {t: c.get("long_name") for c in res.get("address_components", []) for t in c.get("types", [])}
    loc = (res.get("geometry") or {}).get("location") or {}
    tipo = (res.get("geometry") or {}).get("location_type") or ""
    parcial = bool(res.get("partial_match"))

    # La precisión se declara por lo que dice Google, nunca por lo que nos
    # convendría. `partial_match` degrada a zona aunque diga ROOFTOP: significa
    # que no ha entendido la dirección entera, y entonces el punto es de otra
    # cosa parecida, no de lo que se pidió.
    if parcial:
        precision = "zona"
    elif tipo == "ROOFTOP":
        precision = "portal"
    elif tipo in ("RANGE_INTERPOLATED", "GEOMETRIC_CENTER"):
        precision = "calle"
    else:
        precision = "zona"

    return {
        "ok": True,
        "lat": loc.get("lat"), "lng": loc.get("lng"),
        "display": res.get("formatted_address"),
        "calle": comp.get("route") or "",
        "numero": comp.get("street_number") or "",
        "cp": comp.get("postal_code") or "",
        "municipio": comp.get("locality") or comp.get("administrative_area_level_3") or "",
        "precision": precision,
        "location_type": tipo,
        "partial": parcial,
    }


# El Nomenclator va en su propio modulo y se importa con red: si el fichero de
# datos faltara en la imagen, el geocodificador tiene que seguir funcionando
# exactamente como antes, no caerse.
try:
    import geo_nomenclator as _nomen
except Exception as _e:  # pragma: no cover
    _nomen = None
    logger.warning(f"Nomenclator no disponible: {_e}")


# ─── RESCATE DE DIRECCIONES: LAS DOS FUENTES QUE EL NAVEGADOR NO PUEDE PEDIR ───
#
# Los cuatro buscadores del panel (Nominatim, Photon, Cartociudad y Google) se
# preguntan desde el navegador. Hay dos más que sólo se pueden preguntar desde
# aquí, y son justo los que salvan el caso difícil:
#
#   · CATASTRO — el registro oficial de direcciones de España. Tiene TODOS los
#     portales, incluidos los pueblos donde OpenStreetMap no tiene ni la calle.
#     Y hace algo que ningún geocodificador hace: buscar por nombre aproximado y
#     devolver el nombre OFICIAL. Amazon manda "Calle belvís de paleo"; en el
#     Catastro no existe ninguna CALLE con ese nombre, existe el LUGAR
#     "LG BELVIS. PALEO". Esa traducción es la que desbloquea el rural gallego,
#     donde las direcciones son lugares y parroquias, no calles con número.
#
#   · OVERPASS — pregunta a OpenStreetMap por la GEOMETRÍA de la vía en vez de
#     por el texto. Encuentra calles que el buscador de Nominatim no encuentra:
#     medido contra 'Calle belvís de paleo, 15175 Carral', Nominatim devuelve
#     CERO resultados y Overpass devuelve los 4 tramos de la vía con sus
#     coordenadas. Sigue siendo OpenStreetMap, así que cuenta como la MISMA
#     familia que Nominatim y Photon: suma alcance, no suma confirmación.
#
# Los dos rechazan al navegador por CORS, y ninguno de los dos rechaza al
# servidor (probado el 2026-08-20 desde la máquina de Fly). Es exactamente al
# revés que Nominatim, que sólo responde al navegador. Por eso la búsqueda vive
# repartida entre los dos sitios: no es una decisión de gusto.
#
# AQUÍ NO SE DECIDE NADA. Igual que /cortex/geocode, esto sólo consulta y
# traduce. Quién coincide con quién y qué se puede afirmar lo sigue decidiendo
# el navegador con las mismas reglas de siempre (dos familias independientes).

_CATASTRO = "https://ovc.catastro.meh.es/OVCServWeb/OVCSWLocalizacionRC"
_OVERPASS = "https://overpass-api.de/api/interpreter"
_UA_GEO = {"User-Agent": "FlotaDSP/1.0 (+https://flotadsp.com)"}

# El Catastro pide la PROVINCIA por su nombre, y de la dirección sólo tenemos el
# código postal. Los dos primeros dígitos la dan sin ambigüedad.
# Ojo: Navarra (31) y las tres vascas (01, 20, 48) tienen catastro foral propio
# y NO están en este servicio. Allí sólo responderán las otras fuentes.
_PROV_POR_CP = {
    "01": "ARABA/ALAVA", "02": "ALBACETE", "03": "ALICANTE", "04": "ALMERIA",
    "05": "AVILA", "06": "BADAJOZ", "07": "BALEARS, ILLES", "08": "BARCELONA",
    "09": "BURGOS", "10": "CACERES", "11": "CADIZ", "12": "CASTELLON",
    "13": "CIUDAD REAL", "14": "CORDOBA", "15": "A CORUÑA", "16": "CUENCA",
    "17": "GIRONA", "18": "GRANADA", "19": "GUADALAJARA", "20": "GIPUZKOA",
    "21": "HUELVA", "22": "HUESCA", "23": "JAEN", "24": "LEON", "25": "LLEIDA",
    "26": "RIOJA, LA", "27": "LUGO", "28": "MADRID", "29": "MALAGA",
    "30": "MURCIA", "31": "NAVARRA", "32": "OURENSE", "33": "ASTURIAS",
    "34": "PALENCIA", "35": "PALMAS, LAS", "36": "PONTEVEDRA",
    "37": "SALAMANCA", "38": "SANTA CRUZ DE TENERIFE", "39": "CANTABRIA",
    "40": "SEGOVIA", "41": "SEVILLA", "42": "SORIA", "43": "TARRAGONA",
    "44": "TERUEL", "45": "TOLEDO", "46": "VALENCIA", "47": "VALLADOLID",
    "48": "BIZKAIA", "49": "ZAMORA", "50": "ZARAGOZA", "51": "CEUTA",
    "52": "MELILLA",
}

# Lo que va delante del nombre y no forma parte de él. Se quita para preguntar,
# porque el Catastro guarda el tipo de vía en un campo aparte y buscar
# "CALLE BELVIS" no encuentra el lugar "BELVIS. PALEO".
#
# El `c/` va en su propia rama y no dentro del grupo con `\b`: detrás de la
# barra no hay frontera de palabra, así que `c/`, la forma más corta y de las
# más frecuentes, no se quitaba nunca. 'C/ Nova 12' se preguntaba tal cual y no
# lo encuentra ningún callejero.
_RE_TIPO_VIA = re.compile(
    r"^(?:c\s*/\s*|(?:calle|rua|rúa|avenida|avda\.?|av\.?|plaza|praza|pza\.?|"
    r"camino|camiño|carretera|ctra\.?|paseo|travesia|travesía|trav\.?|ronda|"
    r"alameda|lugar|lg\.?|urbanizacion|urbanización|urb\.?|poligono|polígono|"
    r"estrada|parque|via|vía|barrio|bº|aldea|parroquia)\b\.?\s*)", re.I)


def _geo_sin_acentos(s: str) -> str:
    # unicodedata se importa dentro, como el resto de importaciones puntuales
    # de este fichero: no es un modulo global aqui.
    import unicodedata
    return "".join(ch for ch in unicodedata.normalize("NFKD", s or "")
                   if not unicodedata.combining(ch))


def _geo_via_limpia(via: str) -> tuple:
    """Separa el nombre de la vía del número de portal.

    'Calle El Barro 34' → ('EL BARRO', '34'). El número va aparte porque el
    Catastro lo pide en su propio parámetro, y porque saber si lo tenemos o no
    es lo que decide después si podemos hablar de portal o sólo de calle.
    """
    t = _RE_TIPO_VIA.sub("", str(via or "").strip())

    # PRIMERO se quitan los pisos, y NO se toman por número de portal. '1ºA' es
    # un primero A, no el portal 1. Confundirlos sería el peor falso positivo de
    # todos: el Catastro devolvería el portal 1 de esa vía con coordenadas
    # exactas y lo daríamos por bueno. Visto en una dirección real de Carral:
    # 'Calle belvís de paleo 1ºA 1ºA' no lleva número de portal por ningún lado.
    t = re.sub(r"[\s,]*\b\d{1,3}\s*[ºª°]\s*[A-Za-z]?\b", " ", t)

    # Lo que queda al final y es un número (con letra opcional: '34', '12 B')
    # sí es el portal.
    m = re.search(r"[\s,]+(\d{1,4})\s*[A-Za-z]?\s*$", " " + t)
    numero = m.group(1) if m else ""
    if m:
        t = (" " + t)[:m.start()]
    return _geo_sin_acentos(t).upper().strip(" ,.-"), numero


def _geo_parecido(a: str, b: str) -> float:
    import difflib
    return difflib.SequenceMatcher(
        None, _geo_sin_acentos(a).upper(), _geo_sin_acentos(b).upper()).ratio()


def _xml_tag(xml: str, tag: str) -> list:
    return re.findall(rf"<{tag}>(.*?)</{tag}>", xml or "", re.S)


async def _geo_pide(c, url, params=None, cuerpo=None, intentos=3):
    """El Catastro se cae a ratos: sin reintento fallan la mitad de las consultas.

    No es una suposición — la primera tanda de pruebas dio ReadError en las tres
    llamadas y la misma consulta funcionó al minuto siguiente. Un fallo de red
    aquí se vería en pantalla como "no encuentro la dirección", que es
    exactamente la respuesta que no queremos dar por un problema nuestro.
    """
    ultimo = None
    for i in range(intentos):
        try:
            if cuerpo is not None:
                return await c.post(url, content=cuerpo.encode("utf-8"))
            return await c.get(url, params=params)
        except Exception as e:
            ultimo = e
            await asyncio.sleep(1.2 * (i + 1))
    raise ultimo


async def _geo_catastro(c, via: str, municipio: str, cp: str) -> Optional[dict]:
    """Catastro: nombre aproximado → vía oficial → portal → coordenadas.

    Tres saltos, y cada uno tiene su motivo:
      1. ConsultaVia   busca por nombre PARCIAL y devuelve los nombres oficiales
                       con su sigla (CL calle, LG lugar, RU rúa, PQ parroquia).
                       Éste es el paso que traduce lo que escribe el cliente a
                       lo que existe en el callejero.
      2. ConsultaNumero con la vía oficial y el número → referencias catastrales.
      3. Consulta_CPMRC referencia → latitud y longitud.
    """
    nombre, numero = _geo_via_limpia(via)
    mun = _geo_sin_acentos(municipio).upper().strip()
    prov = _PROV_POR_CP.get(str(cp or "")[:2], "")
    if not nombre or not mun or not prov:
        return None

    # Se pregunta por el nombre entero y, si no hay suerte, por sus palabras
    # sueltas de mayor a menor. 'BELVIS DE PALEO' no existe; 'BELVIS' sí, y de
    # ahí sale 'LG BELVIS. PALEO'. Sin esta escalera el rural no se resuelve.
    palabras = [p for p in re.split(r"[\s,\.]+", nombre) if len(p) >= 4]
    palabras.sort(key=len, reverse=True)
    intentos = [nombre] + palabras[:2]

    vias = []
    for t in intentos:
        r = await _geo_pide(c, f"{_CATASTRO}/OVCCallejero.asmx/ConsultaVia",
                            {"Provincia": prov, "Municipio": mun,
                             "TipoVia": "", "NombreVia": t})
        vias = list(zip(_xml_tag(r.text, "tv"), _xml_tag(r.text, "nv")))
        if vias:
            break
    if not vias:
        return None

    # Las que más se parecen a lo que pidió el cliente, de mayor a menor. Se
    # prueban VARIAS y no sólo la primera: en Pontedeume, 'EL BARRO' casa mejor
    # con 'LG BARRO', pero esa vía no tiene ni un portal numerado en el Catastro
    # y la consulta se quedaba en nada teniendo al lado 'CL BARRO' con todos sus
    # números. Quedarse con la primera candidata tiraba la respuesta a la basura.
    candidatas = sorted(vias, key=lambda v: -_geo_parecido(nombre, v[1]))
    candidatas = [v for v in candidatas if _geo_parecido(nombre, v[1]) >= 0.45][:3]
    if not candidatas:
        # Se parecen tan poco que serían otra vía. Mejor no decir nada.
        return None

    # EL CATASTRO EXIGE UN NÚMERO. Pedirle la vía entera con Numero="" contesta
    # "EL NÚMERO ES OBLIGATORIO" y devuelve cero, así que la vía existía, se
    # sabía su nombre oficial, y aun así la respuesta era "no lo sé". Y con un
    # número que no existe —'EL BARRO 34' en Pontedeume— contesta "EL NUMERO NO
    # EXISTE" y pasa lo mismo.
    #
    # Por eso, cuando el número pedido no da nada, se tantea con unos pocos
    # portales bajos: cualquiera de ellos sirve para situar la VÍA, que es lo
    # que se está buscando. Lo que NUNCA se hace es presentar ese punto como el
    # portal del cliente: si el número que respondió no es el que se pidió, esto
    # sale marcado como 'calle' y se dice que el número no está confirmado.
    async def _consulta(sig_c, ofi_c, num):
        r = await _geo_pide(c, f"{_CATASTRO}/OVCCallejero.asmx/ConsultaNumero",
                            {"Provincia": prov, "Municipio": mun,
                             "TipoVia": sig_c.strip(), "NomVia": ofi_c,
                             "Numero": num})
        pc1, pc2 = _xml_tag(r.text, "pc1"), _xml_tag(r.text, "pc2")
        nums = [n.strip().lstrip("0") for n in _xml_tag(r.text, "pnp")]
        return [a + b for a, b in zip(pc1, pc2)], nums

    rcs, con_numero, sigla, oficial = [], False, "", ""

    # 1) El número que pidió el cliente, en cada vía candidata.
    if numero:
        for sig_c, ofi_c in candidatas:
            rcs, nums = await _consulta(sig_c, ofi_c, numero)
            if rcs:
                con_numero = numero.lstrip("0") in nums
                sigla, oficial = sig_c, ofi_c
                break

    # 2) Si no, tanteo para situar la vía. Sólo sobre la candidata que más se
    #    parece: probar las tres por cinco números serían quince consultas a un
    #    servicio lento, y la ganancia no lo paga.
    if not rcs:
        sig_c, ofi_c = candidatas[0]
        for sonda in ("1", "2", "3", "5", "10"):
            rcs, _ = await _consulta(sig_c, ofi_c, sonda)
            if rcs:
                con_numero = False   # sitúa la vía, NO el portal del cliente
                sigla, oficial = sig_c, ofi_c
                break
    if not rcs:
        return None

    r = await _geo_pide(c, f"{_CATASTRO}/OVCCoordenadas.asmx/Consulta_CPMRC",
                        {"Provincia": "", "Municipio": "", "SRS": "EPSG:4326",
                         "RC": rcs[0]})
    xs, ys = _xml_tag(r.text, "xcen"), _xml_tag(r.text, "ycen")
    if not xs or not ys:
        return None
    try:
        lng, lat = float(xs[0]), float(ys[0])
    except ValueError:
        return None

    return {
        "fuente": "catastro",
        # MISMA familia que Cartociudad a propósito: los dos son el callejero
        # oficial del Estado y beben de los mismos datos de direcciones. Que
        # coincidan no es una confirmación independiente, es la misma opinión
        # dicha dos veces, y tratarla como confirmación sería el falso positivo
        # más caro de todos: manda a un conductor a una coordenada.
        "familia": "ign",
        "lat": lat, "lng": lng,
        "calle": f"{sigla.strip()} {oficial}".strip()[:160],
        "numero": (numero if con_numero else "")[:20],
        "cp": str(cp or "")[:12],
        "municipio": municipio[:120],
        "display": ((_xml_tag(r.text, "ldt") or [""])[0]).strip()[:300],
        "precision": "portal" if con_numero else "calle",
    }


async def _geo_overpass(c, via: str, municipio: str) -> Optional[dict]:
    """OpenStreetMap preguntado por geometría en vez de por texto.

    Encuentra vías que el buscador de Nominatim no encuentra. El punto que
    devuelve es el centro de los tramos que llevan ese nombre, así que es
    precisión de CALLE y nunca de portal: se declara tal cual.
    """
    nombre, _ = _geo_via_limpia(via)
    mun = str(municipio or "").strip()
    if len(nombre) < 4 or not mun:
        return None
    # La palabra más larga: la que menos se equivoca al abreviar. Se escapan las
    # comillas para que no se pueda inyectar nada en la consulta.
    palabra = max(re.split(r"[\s,\.]+", nombre), key=len).replace('"', "")
    mun_q = mun.replace('"', "")
    if len(palabra) < 4:
        return None

    q = (f'[out:json][timeout:20];'
         f'area["name"~"^{mun_q}$",i]["boundary"="administrative"]->.a;'
         f'way(area.a)["highway"]["name"~"{palabra}",i];out center 60;')
    r = await _geo_pide(c, _OVERPASS, cuerpo=q, intentos=2)
    try:
        elementos = r.json().get("elements", [])
    except Exception:
        return None
    if not elementos:
        return None

    # Puede haber varias vías distintas que contengan la palabra. Se elige el
    # NOMBRE más parecido y se promedian sólo sus tramos: mezclar dos calles
    # distintas daría un punto en mitad de ninguna parte.
    porn = {}
    for e in elementos:
        n = (e.get("tags") or {}).get("name")
        cen = e.get("center") or {}
        if n and cen.get("lat") is not None:
            porn.setdefault(n, []).append((cen["lat"], cen["lon"]))
    if not porn:
        return None
    mejor = max(porn, key=lambda n: _geo_parecido(nombre, n))
    if _geo_parecido(nombre, mejor) < 0.45:
        return None
    puntos = porn[mejor]
    lat = sum(p[0] for p in puntos) / len(puntos)
    lng = sum(p[1] for p in puntos) / len(puntos)

    return {
        "fuente": "overpass",
        # OpenStreetMap otra vez: no confirma a Nominatim ni a Photon.
        "familia": "osm",
        "lat": lat, "lng": lng,
        "calle": str(mejor)[:160], "numero": "", "cp": "",
        "municipio": mun[:120],
        "display": f"{mejor}, {mun}"[:300],
        "precision": "calle",
    }


# ─── APPLE MAPS: LA QUINTA FUENTE ────────────────────────────────────────────
#
# Dani, 03-09-2026: «en direcciones usamos varios motores y aun asi no encuentra
# las geos; el de Apple las encuentra casi todas». Es cierto en el rural gallego,
# donde OSM no tiene la via y Google devuelve el centro del pueblo.
#
# OJO CON LA URL QUE PARECE QUE VALE: `maps.apple.com/frame?center=lat,lng` NO
# geocodifica —solo PINTA un mapa en unas coordenadas que ya tienes—. Para que
# Apple BUSQUE una direccion hace falta su API, y esa pide cuenta de Apple
# Developer: una clave de MapKit (.p8) con su Key ID y el Team ID.
#
# Dos saltos, como manda Apple:
#   1. Se firma un JWT ES256 con la .p8  ->  `GET /v1/token`  ->  accessToken.
#   2. Con ese accessToken  ->  `GET /v1/geocode?q=...`.
# El accessToken dura ~30 min y se cachea en memoria: sin cache seria un salto
# de mas en CADA direccion, y esto se llama en bucle sobre listas largas.
#
# SIN LAS TRES VARIABLES DE ENTORNO NO HACE NADA (devuelve None) y el rescate se
# comporta exactamente igual que antes. Es decir: mientras no se configure la
# clave, este bloque es inerte y no puede cambiar ni una coordenada.
_APPLE_TOKEN: dict = {"valor": "", "expira": 0.0}


def _apple_maps_configurado() -> bool:
    return all(os.environ.get(k, "").strip() for k in
               ("APPLE_MAPS_KEY_ID", "APPLE_MAPS_TEAM_ID", "APPLE_MAPS_PRIVATE_KEY"))


async def _apple_maps_token(c) -> str:
    """El accessToken de Apple, cacheado hasta un minuto antes de caducar."""
    ahora = time.time()
    if _APPLE_TOKEN["valor"] and _APPLE_TOKEN["expira"] > ahora:
        return _APPLE_TOKEN["valor"]
    kid = os.environ["APPLE_MAPS_KEY_ID"].strip()
    iss = os.environ["APPLE_MAPS_TEAM_ID"].strip()
    # La .p8 se guarda en el secreto con saltos de linea reales o con "\n"
    # escapados (Fly hace lo segundo si se pega en una sola linea).
    clave = os.environ["APPLE_MAPS_PRIVATE_KEY"].strip().replace("\\n", "\n")
    firmado = jwt.encode({"iss": iss, "iat": int(ahora), "exp": int(ahora) + 1800},
                         clave, algorithm="ES256", headers={"kid": kid, "typ": "JWT"})
    r = await c.get("https://maps-api.apple.com/v1/token",
                    headers={"Authorization": "Bearer %s" % firmado})
    r.raise_for_status()
    j = r.json()
    tok = j.get("accessToken") or ""
    if not tok:
        raise RuntimeError("Apple no devolvio accessToken")
    _APPLE_TOKEN["valor"] = tok
    _APPLE_TOKEN["expira"] = ahora + max(60, int(j.get("expiresInSeconds") or 1800)) - 60
    return tok


def _apple_geo_parse(j: dict) -> Optional[dict]:
    """De la respuesta de Apple al mismo formato que las demas fuentes. PURO.

    Apple no declara `location_type` como Google, asi que la precision se deduce
    de lo que ha entendido: con numero de portal es `portal`; con via pero sin
    numero, `calle`; sin via, `zona`. No se inventa nada: si no hay coordenada,
    no hay resultado.
    """
    res = (j or {}).get("results") or []
    if not res:
        return None
    r0 = res[0] or {}
    coord = r0.get("coordinate") or {}
    lat, lng = coord.get("latitude"), coord.get("longitude")
    if lat is None or lng is None:
        return None
    sa = r0.get("structuredAddress") or {}
    numero = (sa.get("subThoroughfare") or "").strip()
    calle = (sa.get("thoroughfare") or "").strip()
    if numero and calle:
        precision = "portal"
    elif calle:
        precision = "calle"
    else:
        precision = "zona"
    lineas = r0.get("formattedAddressLines") or []
    return {
        # `familia` es OBLIGATORIA: el acuerdo se cuenta por familias, no por
        # servicios, y una fuente sin ella rompe el agrupado. Apple es familia
        # propia de verdad —su cartografia no es OSM ni el IGN—, asi que
        # ademas puede corroborar a las otras en lugar de repetirlas.
        "fuente": "apple", "familia": "apple",
        "lat": float(lat), "lng": float(lng),
        "display": ", ".join(x for x in lineas if x) or (r0.get("name") or ""),
        "calle": calle, "numero": numero,
        "cp": (sa.get("postCode") or "").strip(),
        "municipio": (sa.get("locality") or sa.get("administrativeArea") or "").strip(),
        "precision": precision,
    }


async def _geo_apple(c, via: str, municipio: str = "", cp: str = "") -> Optional[dict]:
    """Apple Maps como una fuente mas del rescate. None si no esta configurada."""
    if not _apple_maps_configurado():
        return None
    consulta = ", ".join(x for x in (via, cp, municipio, "España") if x)
    try:
        tok = await _apple_maps_token(c)
        r = await c.get("https://maps-api.apple.com/v1/geocode",
                        params={"q": consulta[:300], "lang": "es-ES", "limit": 1},
                        headers={"Authorization": "Bearer %s" % tok})
        if r.status_code == 401:                      # token caducado antes de tiempo
            _APPLE_TOKEN["valor"] = ""
            tok = await _apple_maps_token(c)
            r = await c.get("https://maps-api.apple.com/v1/geocode",
                            params={"q": consulta[:300], "lang": "es-ES", "limit": 1},
                            headers={"Authorization": "Bearer %s" % tok})
        r.raise_for_status()
        return _apple_geo_parse(r.json())
    except Exception as e:
        # Que Apple falle no puede tumbar el rescate: las otras fuentes siguen.
        logger.warning("geo apple: %s: %s", type(e).__name__, str(e)[:150])
        return None


@api_router.get("/cortex/geo/rescate")
async def cortex_geo_rescate(via: str, municipio: str = "", cp: str = "",
                             _=Depends(require_admin)):
    """Las dos fuentes que sólo se pueden preguntar desde el servidor.

    Devuelve una LISTA de resultados con la misma forma que los buscadores del
    navegador, para que se sumen a la votación sin ningún trato especial. Puede
    venir vacía: no encontrar nada es una respuesta y hay que poder darla.

    Se cachea en `geo_rescate` porque el Catastro es lento (tres saltos, varios
    segundos) y porque la misma dirección se consulta una y otra vez: el mismo
    portal falla muchos días seguidos, que es justo por lo que está en esta
    pantalla.
    """
    via = (via or "").strip()[:200]
    municipio = (municipio or "").strip()[:120]
    cp = re.sub(r"\D", "", cp or "")[:5]
    if len(via) < 3:
        raise HTTPException(400, "via demasiado corta")

    # ── EL CONCELLO, ANTES DE PREGUNTAR A NADIE ──────────────────────────────
    # El Catastro busca dentro de un municipio, no "en Galicia". Con el campo
    # vacio o con basura la consulta sale mal formada y devuelve cero, que es
    # lo que pasaba en el 90% de los casos. Esto no adivina: si no puede
    # afirmar el concello devuelve None y se sigue como antes.
    nomen = {"concello": None, "motivo": "sin_modulo"}
    if _nomen is not None:
        try:
            nomen = _nomen.situar(via, municipio, cp)
        except Exception as e:
            logger.warning(f"Nomenclator: {type(e).__name__}: {str(e)[:100]}")
    municipio_busqueda = nomen.get("concello") or municipio

    # La clave lleva version: sin ella, las 149 busquedas ya guardadas como
    # "cero resultados" seguirian devolviendo cero y esto no se notaria.
    clave = (f"v2|{_geo_sin_acentos(via).upper()}|"
             f"{_geo_sin_acentos(municipio).upper()}|{cp}")
    guardado = await db.geo_rescate.find_one({"_id": clave}, {"_id": 0, "res": 1, "nomen": 1})
    if guardado is not None:
        return {"resultados": guardado.get("res") or [], "cache": True,
                "nomenclator": guardado.get("nomen") or nomen}

    # ── TAMBIEN CON EL TOPONIMO LIMPIO ───────────────────────────────────────
    # Medido contra el Catastro real: 'LUGAR DE AGUIEIRA | Porto do Son'
    # devuelve cero y 'TEAIO | Dodro' devuelve el punto. Lo que rompe la
    # consulta es el prefijo y el numero de portal pegados al nombre, no el
    # municipio. Se pregunta por las dos formas: van en el mismo gather, asi
    # que no cuesta ni un segundo mas, y los resultados se suman a la misma
    # votacion sin trato especial.
    via_limpia = ""
    if _nomen is not None:
        try:
            via_limpia = _nomen.limpiar(via)
        except Exception:
            via_limpia = ""
    formas = [via]
    if via_limpia and via_limpia.upper() != via.upper() and len(via_limpia) >= 3:
        formas.append(via_limpia)

    import httpx as _httpx
    resultados = []
    async with _httpx.AsyncClient(timeout=25, headers=_UA_GEO,
                                  follow_redirects=True) as c:
        tareas = []
        for f in formas:
            tareas.append(_geo_catastro(c, f, municipio_busqueda, cp))
            tareas.append(_geo_overpass(c, f, municipio_busqueda))
        # Apple, una sola vez y con la via tal cual: es la que encuentra el rural
        # que las demas no. Si no esta configurada devuelve None y no suma nada.
        tareas.append(_geo_apple(c, via, municipio_busqueda, cp))
        salidas = await asyncio.gather(*tareas, return_exceptions=True)
    _vistos = set()
    for s in salidas:
        if isinstance(s, dict):
            # Preguntar por dos formas puede traer el MISMO punto dos veces, y
            # eso inflaria la votacion: dos votos de la misma fuente parecerian
            # dos fuentes de acuerdo. Se deduplica por fuente y coordenada.
            k = (s.get("fuente"), round(float(s.get("lat") or 0), 6),
                 round(float(s.get("lng") or 0), 6))
            if k in _vistos:
                continue
            _vistos.add(k)
            resultados.append(s)
        elif isinstance(s, Exception):
            logger.warning(f"rescate geo: {type(s).__name__}: {str(s)[:120]}")

    await db.geo_rescate.update_one(
        {"_id": clave},
        {"$set": {"res": resultados, "en": datetime.now(timezone.utc),
                  "nomen": nomen}},
        upsert=True)
    # El Nomenclator viaja en la respuesta aunque no haya resultados: saber
    # que la direccion esta en Ribeira ya es util para quien la mira, incluso
    # si ninguna fuente da el punto exacto.
    return {"resultados": resultados, "cache": False, "nomenclator": nomen}


# ─── QUÉ HAY EN LA COORDENADA (GEOCODIFICACIÓN INVERSA) ───────────────────────
#
# Para el caso en que Cortex manda el punto pero NO el texto de la dirección.
# Sin texto no hay nada que buscar y la pantalla se quedaba en "sin dirección
# que buscar", que es rendirse teniendo un dato en la mano.
#
# ── ESTO NO ES LA DIRECCIÓN DEL CLIENTE, Y ES IMPORTANTE ─────────────────────
# Es lo que hay DONDE MANDARON AL CONDUCTOR. La razón por la que el paquete está
# en esta pantalla es justamente que ese punto puede estar mal. Así que esto
# responde "¿a dónde te mandaron?", nunca "¿dónde vive el cliente?". Presentarlo
# como lo segundo sería el falso positivo más caro de esta pantalla, porque
# mandaría a alguien a llamar a una puerta que no es. Los textos de la UI dicen
# exactamente eso y no otra cosa.
#
# ── POR QUÉ EL ACUERDO SE MIDE DISTINTO QUE EN LA BÚSQUEDA NORMAL ────────────
# Buscando una dirección, el acuerdo se mide por CERCANÍA: dos fuentes que caen
# a 40 m hablan del mismo portal. Aquí eso no vale para nada — todas las fuentes
# devuelven aproximadamente el punto que les diste, así que "coinciden" siempre.
# Lo que hay que contrastar es el NOMBRE de lo que dicen que hay.
#
# Medido sobre el paquete real del 20-08-2026 (42.6168, -8.8840):
#     Catastro     LG PESQUEIRA 77, BOIRO
#     CartoCiudad  LUGAR PESQUEIRA, Boiro
#     Nominatim    Estrada Xeral, 15939 O Cabo da Cruz
#     Photon       (sin calle), 15939 O Cabo da Cruz
#     Overpass     Estrada Xeral
# Las dos familias dicen cosas distintas y las dos tienen razón: la DIRECCIÓN
# es Lugar Pesqueira y la CARRETERA por la que se llega es la Estrada Xeral.
# Dar una de las dos por buena a la brava sería inventar. Se afirma la calle
# sólo cuando dos familias independientes coinciden en el nombre; si no, se
# afirma el municipio y el código postal —que es lo que sí está claro— y se
# enseña lo que dice cada fuente para que lo juzgue una persona.



# ─── NORMALIZADOR DE DIRECCIONES + GENERADOR DE CONSULTAS ─────────────────────
#
# De las 173 direcciones distintas que han dado "no puedo encontrar la
# dirección", el callejero oficial no contestaba NADA a 103. Mirando esas 103 el
# patrón salta a la vista: no faltan callejeros, se les manda basura. Literales
# de la base:
#
#   'Calle Real 40, 2°, https://maps.app.goo.gl/YJU8NQYcr...'   ← una URL dentro
#   'ALIMENTACION VILLA S.L B15269889, Calle canle numero 20'   ← empresa y CIF
#   'C\ Brion - Leiro (Rianxo) C.P.15928, Nº 43, 15928 Rianxo'  ← 'C' y 'C.P.'
#   'Os Bolos. Lagartones . Rua D . Número 14, 36687 A Estrada' ← puntos por comas
#   'Calle arcay, N30-32, 15873 Bembibre (val do dubra)'        ← rango de números
#   'Bao 2, 15880 Santa Cruz  de  Ribadulla--Vedra'             ← guiones dobles
#
# Aquí se limpia todo eso y se generan VARIAS consultas por dirección, de la más
# específica a la más general. No es tirar consultas a lo loco: en el rural
# gallego la que acaba acertando suele ser 'lugar + concello', no 'calle +
# número', porque la jerarquía real es casa → lugar → parroquia → concello.
#
# MEDIDO sobre esas 173 direcciones, con el callejero oficial como única fuente:
#   antes                          40% situadas
#   con normalizador y variantes   82% situadas... pero con basura dentro
#   + cerrojo de credibilidad      68% situadas Y COMPROBADAS
#
# El cerrojo (_dir_creible) tumbó 110 respuestas, y son justo las que habrían
# mandado a alguien a otra provincia: 'Calle Pombais 1, 15939 Boiro' devolvía un
# CP de Ourense, y 'OUTEIRO Nº 1, OCA, 36685 A ESTRADA' uno de Álava. Ese 82%
# era mentira en catorce puntos.


# ── Cosas que no son parte de una dirección y estorban a cualquier callejero ──
_DIR_URL = re.compile(r"\b(?:https?://|www\.)\S+", re.I)
_DIR_CIF = re.compile(r"\b[A-Z]\d{7,8}[A-Z0-9]?\b")
_DIR_EMPRESA = re.compile(r"\b(s\.?l\.?u?|s\.?a\.?|c\.?b\.?|s\.?c\.?)\b\.?", re.I)
_DIR_CP_INLINE = re.compile(r"\bc\.?\s*p\.?\s*:?\s*(\d{5})\b", re.I)
_DIR_TEL = re.compile(r"\b[6-9]\d{8}\b")

# Piso, puerta, escalera. Todo esto sobra para localizar el portal.
_DIR_PISO = re.compile(
    r"(?:^|[\s,])(?:"
    r"bajo|bj|baixo|entlo|entresuelo|[áa]tico|s[óo]tano|"
    r"(?:piso|pso|planta|pta|puerta|esc|escalera|bloque|blq|port(?:al)?)\.?\s*[\w\-]{0,4}|"
    r"\d{1,2}\s*[ºª°]\s*[a-zA-Z]?|"
    r"[-–]\s*\d{1,2}\s*[a-zA-Z]\b|"
    r"(?:izq|izda|izquierda|dcha|derecha|centro|ctro)\w*"
    r")(?=$|[\s,])", re.I)

# 'nº 5', 'n°56', 'numero 4', 'num. 43', 'N30-32'  → el número, y el PRIMERO
# si es un rango: mandar '30-32' no lo entiende nadie.
_DIR_NUM = re.compile(r"\b(?:n[ºo°ª]?|num|n[úu]m(?:ero)?)\.?\s*(\d{1,4})", re.I)
_DIR_RANGO = re.compile(r"\b(\d{1,4})\s*[-–/]\s*\d{1,4}\b")


def _dir_limpia(txt: str) -> str:
    """Quita de la cadena todo lo que no es dirección."""
    t = " " + str(txt or "") + " "
    t = _DIR_URL.sub(" ", t)
    t = _DIR_TEL.sub(" ", t)
    t = _DIR_CIF.sub(" ", t)
    t = _DIR_EMPRESA.sub(" ", t)
    t = re.sub(r"[\\/]", " ", t)          # 'C\\ Brion' → 'C Brion'
    t = t.replace("--", ", ").replace("–", "-")
    t = _DIR_RANGO.sub(r"\1", t)            # 'N30-32' → 'N30'
    t = _DIR_NUM.sub(r" \1", t)             # 'nº 5' → ' 5'
    # Los puntos que separan tramos se vuelven comas; los de abreviatura no.
    t = re.sub(r"\.\s+(?=[A-ZÁÉÍÓÚÑ])", ", ", t)
    t = re.sub(r"\s*\.\s*$", "", t)
    t = _DIR_PISO.sub(" ", t)
    t = re.sub(r"[;]+", ",", t)
    t = re.sub(r"\s+", " ", t)
    t = re.sub(r"\s*,\s*", ", ", t)
    t = re.sub(r"(,\s*)+", ", ", t).strip(" ,")
    return t


def _dir_despieza(txt: str):
    """Saca vía, número, lugar, municipio, CP y provincia.

    En Galicia la jerarquía real es casa → lugar → parroquia → concello, y el
    texto la trae mezclada. Se guardan los tramos intermedios por separado
    porque son los que localizan una casa en el rural, donde no hay calle.
    """
    bruto = _dir_limpia(txt)
    if not bruto:
        return None

    cp = ""
    m = _DIR_CP_INLINE.search(bruto)
    if m:
        cp = m.group(1)
        bruto = _DIR_CP_INLINE.sub(" ", bruto)

    # Municipio entre paréntesis: '(val do dubra)', '(Porto do Son)'.
    entre_par = re.findall(r"\(([^)]{3,40})\)", bruto)
    bruto = re.sub(r"\([^)]*\)", " ", bruto)
    bruto = re.sub(r"\s+", " ", bruto).strip(" ,")

    tramos = [x.strip() for x in bruto.split(",") if x.strip()]
    if not tramos:
        return None

    ciudad = ""
    if len(tramos) > 1:
        ult = tramos[-1]
        m1 = re.match(r"^(\d{5})\s*(.*)$", ult)
        m2 = re.match(r"^(.*?)\s+(\d{5})$", ult)
        if m1:
            cp = cp or m1.group(1); ciudad = m1.group(2).strip(); tramos.pop()
        elif m2:
            ciudad = m2.group(1).strip(); cp = cp or m2.group(2); tramos.pop()
        elif re.fullmatch(r"\d{5}", ult):
            cp = cp or ult; tramos.pop()

    via = tramos.pop(0) if tramos else ""
    # El número puede haber quedado pegado a la vía.
    numero = ""
    mn = re.search(r"\s(\d{1,4})\s*[A-Za-z]?$", via)
    if mn:
        numero = mn.group(1)
        via = via[:mn.start()].strip(" ,.-")

    intermedios = [x for x in tramos if x and not re.fullmatch(r"\d{1,4}\s*[A-Za-z]?", x)]
    # Provincias: no son municipio, y colarlas como tal manda a otro sitio.
    PROV = {"a coruña", "la coruña", "coruña", "pontevedra", "lugo", "ourense",
            "orense", "galicia", "españa", "espana"}
    intermedios = [x for x in intermedios if x.strip().lower() not in PROV]

    candidatos_muni = [x for x in (entre_par + intermedios[::-1] + [ciudad]) if x]
    municipio = candidatos_muni[0] if candidatos_muni else ""
    lugar = intermedios[0] if intermedios else ""

    return {"via": via, "numero": numero, "lugar": lugar,
            "municipio": municipio, "cp": cp, "ciudad": ciudad,
            "otros_muni": candidatos_muni, "limpio": bruto}


def _dir_variantes(d) -> list:
    """Las consultas a probar, de la más específica a la más general.

    No es tirar consultas a lo loco: cada una responde a una pregunta distinta
    y se para en cuanto una contesta. En el rural la que acaba acertando suele
    ser 'lugar + concello', no 'calle + número'.
    """
    if not d:
        return []
    v, n, lg, cp = d["via"], d["numero"], d["lugar"], d["cp"]
    munis = [m for m in d["otros_muni"] if m][:3]
    fuera = []
    for mu in munis or [""]:
        if v and n and mu: fuera.append(f"{v} {n}, {mu}")
        if v and mu:       fuera.append(f"{v}, {mu}")
        if v and lg and mu and lg.lower() != mu.lower():
            fuera.append(f"{v}, {lg}, {mu}")
        if lg and mu and lg.lower() != mu.lower(): fuera.append(f"{lg}, {mu}")
    if v and n and cp: fuera.append(f"{v} {n}, {cp}")
    if v and cp:       fuera.append(f"{v}, {cp}")
    if v and n:        fuera.append(f"{v} {n}")
    if v:              fuera.append(v)
    # Sin duplicados y sin perder el orden.
    vistas, limpio = set(), []
    for q in fuera:
        k = re.sub(r"\s+", " ", q).strip().lower()
        if k and k not in vistas:
            vistas.add(k); limpio.append(q)
    return limpio[:8]


def _dir_creible(j: dict, d: dict, original: str) -> bool:
    """¿Es compatible esta respuesta con la dirección que se pidió?

    Dos comprobaciones INDEPENDIENTES del nombre de la calle: el código postal
    (mismos tres primeros dígitos = misma comarca) y el municipio. Basta una.

    Sin esto, el generador de variantes es un peligro: al preguntar por trozos
    sueltos, un callejero encuentra 'Pombais' o 'Outeiro' en cualquier punto de
    España y contesta tan tranquilo. Medido: 110 respuestas de este tipo, con
    códigos postales de Ourense, Álava, Málaga y Las Palmas para direcciones de
    A Coruña.
    """
    if not isinstance(j, dict):
        return False
    cp_j = re.sub(r"\D", "", str(j.get("postalCode") or j.get("cp") or ""))
    if d.get("cp") and cp_j:
        return cp_j[:3] == d["cp"][:3]
    mun_j = _geo_sin_acentos(str(j.get("muni") or j.get("municipio") or "")).lower().strip()
    if not mun_j:
        return False
    texto = _geo_sin_acentos(original or "").lower()
    for cand in (d.get("otros_muni") or []):
        c = _geo_sin_acentos(str(cand)).lower().strip()
        if c and (c in mun_j or mun_j in c):
            return True
    return mun_j in texto


@api_router.get("/cortex/geo/parse")
async def cortex_geo_parse(q: str, _=Depends(require_admin)):
    """Despieza una dirección de Cortex y devuelve las consultas a probar.

    Existe para que el navegador pregunte con texto limpio en vez de con la
    cadena tal cual la escribió el cliente. Las variantes van ordenadas de la
    más específica a la más general: se prueban en orden y se para en la primera
    que conteste algo creíble.
    """
    d = _dir_despieza(q or "")
    if not d:
        return {"ok": False, "variantes": []}
    return {"ok": True, **d, "variantes": _dir_variantes(d)}


_CAT_COORD = "https://ovc.catastro.meh.es/OVCServWeb/OVCSWLocalizacionRC/OVCCoordenadas.asmx"

# Prefijos de tipo de vía que sobran al comparar nombres: 'LG PESQUEIRA' y
# 'LUGAR PESQUEIRA' son lo mismo, y compararlos en crudo daría desacuerdo.
_RE_SIGLA_VIA = re.compile(
    r"^(?:lg|lugar|cl|calle|ru|rua|av|avda|avenida|pz|plaza|praza|cr|carretera|"
    r"ctra|cm|camino|camino|tr|travesia|pq|parroquia|ba|barrio|ur|urbanizacion|"
    r"po|paseo|gl|glorieta|sd|senda|estrada|aldea)\b\.?\s*", re.I)


def _nucleo_via(s: str) -> str:
    """El nombre de una vía reducido a lo que se puede comparar.

    Quita acentos, la sigla del tipo de vía, los números y las palabras de
    relleno. 'LG PESQUEIRA 77' y 'LUGAR PESQUEIRA' acaban los dos en
    'pesqueira'.
    """
    t = _geo_sin_acentos(str(s or "")).lower().strip()
    t = _RE_SIGLA_VIA.sub("", t)
    t = re.sub(r"\b\d+\b", " ", t)
    t = re.sub(r"\b(de|del|da|do|la|el|los|las|os|as|a|o|y|e)\b", " ", t)
    return " ".join(re.sub(r"[^a-z0-9 ]+", " ", t).split())


def _mismo_nombre(a: str, b: str) -> bool:
    """¿Hablan las dos de la misma vía?

    Basta con que compartan una palabra significativa: los callejeros escriben
    lo mismo de mil maneras ('RUA SANTAS MARIÑAS (DAS)' / 'Rua das Santas
    Mariñas'). Palabras de tres letras o menos no cuentan, que si no 'San'
    emparejaría media Galicia.
    """
    ta = {w for w in _nucleo_via(a).split() if len(w) > 3}
    tb = {w for w in _nucleo_via(b).split() if len(w) > 3}
    return bool(ta and tb and (ta & tb))


async def _inv_catastro(c, lat: float, lng: float) -> list:
    """Catastro: qué hay en el punto y, si ahí no hay nada, qué hay a 50 m.

    El `_Distancia` es el que salva el rural: un punto caído en la carretera no
    tiene referencia catastral propia, pero las casas de al lado sí. Devuelve
    hasta una docena de direcciones OFICIALES de alrededor, que es justo lo que
    necesita quien está intentando averiguar a qué puerta iba el paquete.
    """
    salidas = []
    try:
        r = await _geo_pide(c, f"{_CAT_COORD}/Consulta_RCCOOR",
                            {"SRS": "EPSG:4326", "Coordenada_X": str(lng),
                             "Coordenada_Y": str(lat)})
        exacta = (_xml_tag(r.text, "ldt") or [""])[0].strip()
        # Dos cosas que NO son una dirección: la frase que devuelve cuando no
        # encuentra nada, y una parcela rústica ('Polígono 7 Parcela 9023'), que
        # es un trozo de monte y no una puerta a la que llamar.
        if (exacta and "NO HAY REFERENCIA" not in exacta.upper()
                and not re.match(r"^pol[ií]gono\s", exacta, re.I)):
            salidas.append({"fuente": "catastro", "familia": "ign",
                            "texto": exacta[:200], "metros": 0})
    except Exception:
        pass

    try:
        r = await _geo_pide(c, f"{_CAT_COORD}/Consulta_RCCOOR_Distancia",
                            {"SRS": "EPSG:4326", "Coordenada_X": str(lng),
                             "Coordenada_Y": str(lat)})
        for d in _xml_tag(r.text, "ldt")[:12]:
            d = d.strip()
            # Las parcelas rústicas ('Polígono 7 Parcela 9023') no son una
            # dirección a la que se pueda llamar: se descartan.
            if d and not re.match(r"^pol[ií]gono\s", d, re.I):
                salidas.append({"fuente": "catastro_50m", "familia": "ign",
                                "texto": d[:200], "metros": 50})
    except Exception:
        pass
    return salidas


async def _inv_cartociudad(c, lat: float, lng: float) -> Optional[dict]:
    """CartoCiudad (IGN). Pide EPSG:4258, que para este uso es igual que 4326."""
    try:
        r = await _geo_pide(c, "https://www.cartociudad.es/geocoder/api/geocoder/reverseGeocode",
                            {"lon": str(lng), "lat": str(lat)})
        j = r.json()
    except Exception:
        return None
    if not isinstance(j, dict):
        return None
    via = " ".join(str(x).strip() for x in (j.get("tip_via"), j.get("address")) if x)
    if not via.strip():
        return None
    return {"fuente": "cartociudad", "familia": "ign", "texto": via[:200],
            "calle": str(j.get("address") or "")[:160],
            "cp": str(j.get("postalCode") or "")[:12],
            "municipio": str(j.get("muni") or "")[:120], "metros": 0}


async def _inv_osm(c, lat: float, lng: float) -> list:
    """Las tres voces de OpenStreetMap. Cuentan como UNA sola familia.

    Se preguntan las tres porque cada una falla en sitios distintos —en el punto
    de Boiro, Photon no dio calle y Nominatim sí— pero coincidir entre ellas no
    confirma nada: leen la misma base.
    """
    out = []
    try:
        r = await _geo_pide(c, "https://nominatim.openstreetmap.org/reverse",
                            {"lat": str(lat), "lon": str(lng), "format": "jsonv2"}, 2)
        a = (r.json() or {}).get("address") or {}
        via = a.get("road") or a.get("pedestrian") or a.get("residential") or ""
        if via or a.get("postcode"):
            out.append({"fuente": "nominatim", "familia": "osm",
                        "texto": str(via)[:200], "calle": str(via)[:160],
                        "cp": str(a.get("postcode") or "")[:12],
                        "municipio": str(a.get("city") or a.get("town")
                                         or a.get("village") or "")[:120],
                        "metros": 0})
    except Exception:
        pass

    try:
        r = await _geo_pide(c, "https://photon.komoot.io/reverse",
                            {"lat": str(lat), "lon": str(lng), "limit": "1"}, 2)
        p = ((r.json().get("features") or [{}])[0] or {}).get("properties") or {}
        via = p.get("street") or ""
        if via or p.get("postcode"):
            out.append({"fuente": "photon", "familia": "osm",
                        "texto": str(via)[:200], "calle": str(via)[:160],
                        "cp": str(p.get("postcode") or "")[:12],
                        "municipio": str(p.get("city") or p.get("county") or "")[:120],
                        "metros": 0})
    except Exception:
        pass

    try:
        q = (f'[out:json][timeout:20];way(around:120,{lat},{lng})["highway"]["name"];'
             f'out center 6;')
        r = await _geo_pide(c, _OVERPASS, cuerpo=q, intentos=2)
        vistos = []
        for e in (r.json().get("elements") or []):
            n = (e.get("tags") or {}).get("name")
            if n and n not in vistos:
                vistos.append(n)
        if vistos:
            out.append({"fuente": "overpass", "familia": "osm",
                        "texto": vistos[0][:200], "calle": vistos[0][:160],
                        "cp": "", "municipio": "", "metros": 120,
                        "cerca": vistos[:5]})
    except Exception:
        pass
    return out


@api_router.get("/cortex/geo/inverso")
async def cortex_geo_inverso(lat: float, lng: float, _=Depends(require_admin)):
    """Qué hay en el punto al que mandaron al conductor.

    Devuelve lo que dice CADA fuente y, aparte, lo único que se puede AFIRMAR:
    la calle sólo si dos familias independientes coinciden en el nombre, y el
    municipio y el código postal cuando eso es todo lo que está claro.

    Nunca devuelve un número de portal. La geocodificación inversa da el portal
    del edificio más cercano al punto, que no tiene por qué ser el del cliente
    —de hecho, si el punto estuviera bien, el conductor habría encontrado la
    dirección—. Decir un número aquí sería inventarlo.
    """
    if not (-90 <= lat <= 90) or not (-180 <= lng <= 180):
        raise HTTPException(400, "coordenada fuera de rango")

    # Caché por coordenada redondeada a ~1 m. El mismo portal falla muchos días
    # seguidos y estas consultas son lentas (el Catastro, sobre todo).
    clave = f"inv:{lat:.5f},{lng:.5f}"
    guardado = await db.geo_rescate.find_one({"_id": clave}, {"_id": 0, "res": 1})
    if guardado is not None:
        return {**(guardado.get("res") or {}), "cache": True}

    import httpx as _httpx
    async with _httpx.AsyncClient(timeout=25, headers=_UA_GEO,
                                  follow_redirects=True) as c:
        cat, carto, osm = await asyncio.gather(
            _inv_catastro(c, lat, lng), _inv_cartociudad(c, lat, lng),
            _inv_osm(c, lat, lng), return_exceptions=True)

    fuentes = []
    for s in (cat, osm):
        if isinstance(s, list):
            fuentes.extend(s)
    if isinstance(carto, dict):
        fuentes.append(carto)

    # ── QUÉ SE PUEDE AFIRMAR, Y CON CUÁNTA FUERZA ──────────────────────────
    #
    # Aquí no vale el "o dos familias o no digo nada" de la búsqueda normal, y
    # se vio en cuanto se probó: en el punto real de Boiro OCHO respuestas del
    # Catastro decían 'LG PESQUEIRA' y la regla dura no afirmaba nada, porque
    # todas eran de la misma familia. Callar eso no es prudencia, es tirar la
    # única respuesta que había.
    #
    # Se dice lo que se sabe Y de quién se sabe, en tres niveles:
    #   dos_fuentes    OpenStreetMap y el callejero oficial coinciden. Lo mejor.
    #   solo_oficial   sólo el callejero oficial, pero de acuerdo consigo mismo.
    #                  Se afirma diciendo que viene de ahí y de ningún sitio más.
    #   (nada)         las fuentes se contradicen. Entonces sólo municipio y CP.
    #
    # La discrepancia NO se esconde: se devuelve aparte. En Boiro el Catastro
    # dice 'Lugar Pesqueira' (la dirección) y OpenStreetMap 'Estrada Xeral' (la
    # carretera por la que se llega). Las dos son verdad y quien mira la
    # pantalla tiene que ver las dos.
    def _nom(f):
        return f.get("calle") or f.get("texto") or ""

    con_nombre = [f for f in fuentes if _nom(f).strip()]
    osm = [f for f in con_nombre if f["familia"] == "osm"]
    exactas = [f for f in con_nombre if f["fuente"] in ("catastro", "cartociudad")]
    vecinas = [f for f in con_nombre if f["fuente"] == "catastro_50m"]

    calle, familias_calle, confianza = "", [], None

    # Nivel 1: acuerdo entre familias distintas.
    for a in con_nombre:
        fams = {a["familia"]} | {b["familia"] for b in con_nombre
                                 if b is not a and _mismo_nombre(_nom(a), _nom(b))}
        if len(fams) >= 2 and len(fams) > len(familias_calle):
            calle, familias_calle, confianza = _nom(a), sorted(fams), "dos_fuentes"

    # Nivel 2: sólo el callejero oficial, y coherente consigo mismo. El acierto
    # EXACTO sobre el punto pesa doble: es la parcela que contiene la coordenada,
    # no una de al lado.
    if not calle:
        from collections import Counter
        # Se cuentan RESPUESTAS DISTINTAS, no votos inflados. Duplicar el peso
        # de las respuestas "exactas" ya se probó y salió mal: en la Praza do
        # Obradoiro, CartoCiudad contesta 'AVENIDA RAXOI' —la plaza de al lado—
        # y con el voto doble ganaba él solo a un Catastro que decía
        # 'PZ OBRADOIRO'. Una fuente sola no puede ganarle a otra fuente sola.
        respuestas, texto_de = Counter(), {}
        for f in exactas + vecinas:
            n = _nucleo_via(_nom(f))
            if n:
                respuestas[n] += 1
                texto_de.setdefault(n, _nom(f))
        # El acierto EXACTO del Catastro (la parcela que contiene el punto, no
        # una de al lado) desempata, pero no vale por dos: suma medio punto.
        exacta_cat = next((f for f in exactas if f["fuente"] == "catastro"), None)
        bonus = _nucleo_via(_nom(exacta_cat)) if exacta_cat else None

        if respuestas:
            def peso(n):
                return respuestas[n] + (0.5 if n == bonus else 0)
            top = max(respuestas, key=peso)
            total = sum(respuestas.values())
            # Dos condiciones, y las dos hacen falta:
            #  · al menos DOS respuestas distintas dicen lo mismo — una sola
            #    fuente no afirma nada, por oficial que sea;
            #  · y son mayoría — en una esquina el Catastro devuelve tres calles
            #    de alrededor y ninguna es "la" dirección.
            if respuestas[top] >= 2 and peso(top) >= max(2, (total + 1) / 2):
                calle, familias_calle, confianza = texto_de[top], ["ign"], "solo_oficial"

    # El municipio y el CP son el suelo: casi siempre se sabe, y es lo que pide
    # quien está mirando la pantalla cuando no hay nada más.
    def _mas_repetido(campo):
        # collections no es global en este fichero: se importa donde se usa,
        # como el resto de importaciones puntuales.
        from collections import Counter
        vals = [str(f.get(campo) or "").strip() for f in fuentes if f.get(campo)]
        return Counter(vals).most_common(1)[0][0] if vals else ""

    municipio, cp = _mas_repetido("municipio"), _mas_repetido("cp")
    alrededor = [f["texto"] for f in fuentes if f["fuente"] == "catastro_50m"]

    # SIN NÚMERO DE PORTAL. El Catastro devuelve 'LG PESQUEIRA 77', y ese 77 es
    # la casa más cercana al punto, no la del cliente — si el punto estuviera
    # bien, el conductor habría encontrado la dirección. Enseñar el número aquí
    # sería mandar a alguien a llamar a una puerta al azar. Los números siguen
    # estando en la lista de "alrededor", que es lo que son.
    if calle:
        calle = re.sub(r"\s*\([^)]*\)\s*$", " ", calle)      # ' (A CORUÑA)'
        calle = re.sub(r"\b\d+\s*(?:\([A-Za-z]\))?", " ", calle)  # '77', '2(D)'
        calle = " ".join(calle.split()).strip(" ,.-")
        if municipio:
            calle = re.sub(r"[\s,]*" + re.escape(municipio) + r"\s*$", "",
                           calle, flags=re.I).strip(" ,.-")

    # Lo que dicen los demás y no encaja. Se enseña, no se descarta.
    discrepancia = sorted({_nom(f) for f in con_nombre
                           if calle and not _mismo_nombre(calle, _nom(f))})

    if calle:
        precision = "calle"
    elif municipio or cp:
        precision = "zona"
    else:
        precision = None

    res = {
        "precision": precision,
        "calle": calle, "familias": familias_calle,
        # Con cuánta fuerza se afirma la calle. La pantalla escribe una frase
        # distinta para cada valor: no es lo mismo "coinciden dos callejeros
        # independientes" que "lo dice el oficial y nadie más".
        "confianza": confianza,
        "discrepancia": discrepancia[:4],
        "municipio": municipio, "cp": cp,
        # Direcciones oficiales de alrededor. Se enseñan como lo que son —lo que
        # hay cerca— y jamás como la dirección del paquete.
        "alrededor": alrededor[:8],
        "fuentes": [{k: v for k, v in f.items() if k != "metros"} for f in fuentes],
    }
    await db.geo_rescate.update_one(
        {"_id": clave}, {"$set": {"res": res, "en": datetime.now(timezone.utc)}},
        upsert=True)
    return {**res, "cache": False}


# ─────────────────────────────────────────────────────────────────────────────
# EL CUADRE DEL DEBRIEF
# ─────────────────────────────────────────────────────────────────────────────
# Ver la explicacion larga arriba de _cx_debrief_reparto. En corto: separar
# "no se entrego, tiene que volver" de "no lo hemos visto", porque en pantalla
# son iguales y confundirlos significa acusar a alguien sin pruebas.

# LAS CUATRO CATEGORIAS QUE SE MIRAN DE PRIMERAS.
# Son las mismas que Cortex enseña en su propia pantalla, con sus nombres:
# separarlas importa porque cada una se atiende distinto. Un "se puede volver
# a intentar" vuelve a salir mañana; un "falta" es una llamada AHORA.
CX_REINTENTO = ("ATTEMPTED",)
# NOT_DELIVERED entra aqui: Cortex dice que no se entrego, luego vuelve.
CX_NO_ENTREGA = ("NOT_DELIVERED", "NO_ITEMS_DELIVERED",
                 "BACK_TO_ORIGIN", "CUSTOMER_UNAVAILABLE", "ADDRESS_NOT_FOUND",
                 "DAMAGED", "LOCKER_ISSUE")
CX_NO_RECOGIDO = ("UNCOLLECTED", "NOT_READY")
CX_FALTA = ("MISSING",)

# Cortex lo ha dicho: no se entrego. El conductor lo trae en la furgoneta.
CX_DEVUELVE = CX_REINTENTO + CX_NO_ENTREGA + CX_NO_RECOGIDO
# Cancelado por Amazon: sale en Cortex y NO en la cuenta del conductor.
CX_CANCELADO = ("TR_CANCELLED",)

# ── EL CONTEXTO MANDA SOBRE EL ESTADO ────────────────────────────────────────
# Medido: la cancelacion casi nunca esta en `state`. Vive en el contexto del
# ultimo evento, y el estado se queda en NOT_READY o BACK_TO_ORIGIN. Mirando
# solo el estado salian 6 cancelados en 30 dias; mirando el contexto son 50.
CX_CTX_CANCELADO = ("TR_CANCELLED", "CANCELLED", "ORDER_CANCELLED")
# Lo movio el cliente. Vuelve a la nave, pero NO es un fallo del conductor y
# no debe pintarse como tal.
CX_CTX_REPROGRAMADO = ("RESCHEDULED_BY_CUSTOMER", "RESCHEDULED")
# El cliente lo recogio el mismo. NO viene en la furgoneta: pedirselo al
# conductor es reclamarle algo que nunca llevo.
CX_CTX_CLIENTE = ("COLLECTED_BY_CUSTOMER", "PICKED_BY_CUSTOMER",
                  "PICKED_UP_BY_CUSTOMER")
# Cortex ya dice que el paquete no aparece. No es "devuelvemelo", es un aviso.
CX_CTX_PERDIDO = ("OBJECT_MISSING", "PACKAGE_MISSING")
# ── EL CICLO NORMAL DE UN PAQUETE, MEDIDO ────────────────────────────────────
# El 28-08-2026 me equivoque con esto y la pantalla enseño barbaridades: 2.288
# "recogidas que trae" y 2.867 "no salieron" en un dia con 45 rutas en la calle.
# Vi que todos los PICKED_UP venian de un PENDING_PICKUP y conclui que eran
# recogidas de cliente. Es al reves: es el ciclo de TODOS los paquetes.
#
# Contado sobre los entregados de ese dia:
#     PENDING_PICKUP -> PICKED_UP -> DELIVERED                    1.680
#     PENDING_PICKUP -> DELIVERED                                   709
#     PENDING_PICKUP -> PICKED_UP -> YOU_ARE_NEXT -> DELIVERED       304
#     PENDING_PICKUP -> YOU_ARE_NEXT -> DELIVERED                    170
#
# Y el esquema de Cortex lo confirma: cada tarea lleva `taskType`, y el
# `PENDING_PICKUP` es el estado de la tarea PICK_UP — el conductor recogiendo el
# paquete EN LA NAVE, no un cliente devolviendo nada:
#     "taskType":"PICK_UP","taskState":"PENDING_PICKUP","executionStatus":"NOT_STARTED"
#
# Asi que los tres significan lo mismo para quien hace el debrief: TODAVIA NO
# ESTA ENTREGADO. No hay forma de distinguir una recogida de verdad por el
# estado, y por eso no se intenta: Cortex las cuenta aparte ("Recogidas en
# carretera", 16 ese dia) y hasta que la extension capture `taskType` no se
# puede afirmar cual es cual. Afirmarlo a ojo es lo que rompio la pantalla.
CX_AMBIGUO = ("PENDING_PICKUP", "PICKED_UP", "LOADED",
              "YOU_ARE_NEXT", "ARRIVED", "OBSERVED", "NONE")

# Minutos de margen. Por debajo, se entiende que la captura murio ahi.
# 45 min no es un numero redondo elegido a ojo: con captura viva, un paquete
# cambia de estado varias veces por hora (100-131 capturas por paquete y dia).
# Se puede ajustar sin tocar codigo por si cambia el ritmo de la extension.
CX_HUECO_MIN = int(os.environ.get("CORTEX_HUECO_MIN") or 45)


def _cx_minutos(a: str, b: str):
    """Minutos entre dos marcas ISO. None si alguna no se puede leer.

    Devuelve None en vez de 0 a proposito: un 0 por no saber leer la fecha
    haria que un paquete sin fecha pareciera recien capturado, que es
    justo la conclusion peligrosa.
    """
    da, dbb = _cortex_parse_dt(a), _cortex_parse_dt(b)
    if not da or not dbb:
        return None
    return (da - dbb).total_seconds() / 60.0


def _cx_debrief_reparto(paquetes: list, ultima_por_ruta: dict, en_curso: bool = False,
                        dia: str = "") -> dict:
    """Reparte los paquetes de UN conductor en los cinco cajones.

    `ultima_por_ruta` es la ultima captura vista en CADA ruta. El hueco se
    mide siempre contra la ruta del propio paquete, nunca contra la persona:
    un support que ayuda en dos rutas tiene dos relojes distintos, y usar el
    mas tardio convertiria sus paquetes de la otra ruta en una acusacion.

    Tampoco vale el final del dia: las rutas no terminan a la vez, y usarlo
    haria que toda ruta que cierra pronto pareciera llena de paquetes sin
    cerrar.
    """
    cajones = {"entregados": [], "cancelados": [], "no_observado": [],
               "perdidos": [], "sin_cerrar": [], "reprogramados": [],
               "cliente": [], "arrastrados": [],
               # Los cuatro que se miran de primeras
               "reintento": [], "no_entrega": [], "no_recogido": []}
    for p in paquetes:
        # EL ESTADO SE LEE DEL TIMELINE, NO DEL CAMPO `state`.
        # El campo guardado era el del ultimo evento que LLEGO, y Cortex manda
        # eventos historicos con su propia hora: uno de las 10:51 podia pisar
        # un DELIVERED de las 11:36. La ingesta ya no lo permite, pero los
        # paquetes que se guardaron mal antes siguen mal en la base, y esta
        # pantalla es la que le reclama cosas a una persona: aqui se recalcula
        # para que este bien HOY, sin esperar a que se vuelvan a capturar ni
        # tocar datos historicos.
        vigente, vigente_at = _cx_estado_vigente(p.get("timeline") or [])
        st = (vigente or p.get("state") or "").upper()
        ctx = _cx_contexto(p)
        # ¿ARRASTRA DE OTRO DIA?
        # El informe de faltas devuelve los paquetes que siguen pendientes de
        # reintento, y esos vienen de dias anteriores aunque se pidan con la
        # fecha de hoy. Medido: de 145 en los cajones de reclamar, 141 eran del
        # mismo dia; los otros 4 tenian su ultimo evento de hace 1 a 21 dias.
        # Un paquete cuyo ultimo movimiento fue hace tres semanas NO lo lleva
        # hoy nadie en la furgoneta, y reclamarselo a quien llega es el peor
        # tipo de falso positivo: el que hace que dejen de mirar la pantalla.
        arrastra = bool(dia and vigente_at and vigente_at.strftime("%Y-%m-%d") < dia)
        fila = {
            "tba": p.get("tba"),
            "stop_id": p.get("stop_id"),
            # De que ruta viene. Es lo que permite separar lo suyo de lo que
            # trae por haber ido a ayudar a otra.
            "ruta": (p.get("route_code") or "").strip() or None,
            "estado": st,
            "contexto": ctx or None,
            "motivo": _cx_motivo_legible(p),
            "direccion": _cortex_addr_str(p.get("stop_address")),
            "visto": p.get("updated_at"),
        }
        if st == "DELIVERED":
            cajones["entregados"].append(fila)
        elif arrastra:
            # Aparte y sin reclamar. Se enseña para que se vea que existe: si
            # desapareciera sin mas, alguien lo echaria en falta y desconfiaria
            # del resto de la cuenta.
            fila["visto_el"] = vigente_at.strftime("%Y-%m-%d")
            cajones["arrastrados"].append(fila)
        # ── El contexto se mira ANTES que el estado ──────────────────────────
        # Un NOT_READY cuyo contexto es TR_CANCELLED es un cancelado, no un
        # paquete que reclamar. El estado se queda corto y el contexto es el
        # que dice la verdad.
        elif ctx in CX_CTX_CANCELADO:
            cajones["cancelados"].append(fila)
        elif ctx in CX_CTX_CLIENTE:
            cajones["cliente"].append(fila)
        elif ctx in CX_CTX_PERDIDO or st == "MISSING":
            cajones["perdidos"].append(fila)
        elif ctx in CX_CTX_REPROGRAMADO:
            cajones["reprogramados"].append(fila)
        elif st in CX_CANCELADO:
            cajones["cancelados"].append(fila)
        elif st in CX_REINTENTO:
            cajones["reintento"].append(fila)
        elif st in CX_NO_ENTREGA:
            cajones["no_entrega"].append(fila)
        elif st in CX_NO_RECOGIDO:
            cajones["no_recogido"].append(fila)
        elif st in CX_AMBIGUO:
            hueco = _cx_minutos(
                ultima_por_ruta.get((p.get("route_code") or "").strip(), ""),
                p.get("updated_at"))
            fila["hueco_min"] = None if hueco is None else round(hueco)
            if en_curso:
                # EL DIA NO HA TERMINADO. Un paquete cargado a las 09h en una
                # ruta que sigue capturando a las 18:34 no esta "sin cerrar":
                # esta en reparto, o el conductor todavia no ha vuelto. Llamar
                # a eso un problema pinta 40 lineas rojas por ruta y hace que
                # la pantalla no se mire. Se cuenta como inventario y ya.
                cajones["sin_cerrar"].append(fila)
            elif hueco is None or hueco <= CX_HUECO_MIN:
                # La captura se paro con este paquete a medias. No sabemos nada.
                cajones["no_observado"].append(fila)
            else:
                # La captura siguio y este no se movio: eso si es raro.
                cajones["sin_cerrar"].append(fila)
        else:
            cajones["no_observado"].append(fila)
    return cajones


def _cx_contexto(p: dict) -> str:
    """El contexto del ultimo evento que lo traiga, en mayusculas y normalizado.

    Se recorre el timeline hacia atras porque el contexto no siempre viene en
    el ultimo evento: la fuente que trae el motivo (el informe de faltas) y la
    que trae el estado (route-details) son distintas y no llegan a la vez.
    'NONE' se trata como ausencia: Cortex lo usa como relleno, no como motivo.
    """
    for ev in reversed(p.get("timeline") or []):
        c = str(ev.get("context") or "").strip().upper().replace(" ", "_").replace("-", "_")
        if c and c != "NONE":
            return c
    return ""


def _cx_motivo_legible(p: dict) -> str:
    """El porque, en cristiano, sacado del ultimo evento con contexto.

    El estado dice QUE paso; el contexto dice POR QUE. Un 'ATTEMPTED' a secas
    no le sirve a quien esta en la puerta con el conductor delante.
    """
    ctx = _cx_contexto(p)
    legible_ctx = {
        "CUSTOMER_UNAVAILABLE": "no estaba el cliente",
        "BUSINESS_CLOSED": "negocio cerrado",
        "ADDRESS_NOT_FOUND": "no encontro la direccion",
        "OBJECT_MISSING": "el paquete no aparece",
        "COLLECTED_BY_CUSTOMER": "lo recogio el cliente",
        "RESCHEDULED_BY_CUSTOMER": "el cliente lo aplazo",
        "TR_CANCELLED": "cancelado",
        "NO_ITEMS_DELIVERED": "no se entrego nada en la parada",
        "INACCESSIBLE_DELIVERY_LOCATION": "no se puede llegar",
        "INACCESSIBLE_PICKUP_LOCATION": "no se puede llegar a recogerlo",
        "LOCKER_ISSUE": "problema con el locker",
        "SHIPMENT_NOT_READY": "el envio no estaba listo",
        "NO_SECURE_LOCATION": "sin sitio seguro donde dejarlo",
        "DAMAGED": "dañado",
    }.get(ctx, ctx.lower().replace("_", " ") if ctx else "")
    base = {
        "ATTEMPTED": "Se intento y no se pudo",
        "CUSTOMER_UNAVAILABLE": "El cliente no estaba",
        "ADDRESS_NOT_FOUND": "No encontro la direccion",
        "DAMAGED": "Llego dañado",
        "LOCKER_ISSUE": "Problema con el locker",
        "UNCOLLECTED": "Sin recoger",
        "BACK_TO_ORIGIN": "Marcado para devolver",
        "NOT_READY": "No estaba listo",
        "TR_CANCELLED": "Cancelado por Amazon",
        "MISSING": "Amazon lo da por perdido",
        "LOADED": "Cargado en la furgoneta",
        "PENDING_PICKUP": "Pendiente de recoger",
        "YOU_ARE_NEXT": "En reparto",
    }.get((p.get("state") or "").upper(), (p.get("state") or ""))
    return f"{base} · {legible_ctx}" if legible_ctx else base


@api_router.get("/cortex/debrief")
async def cortex_debrief(day: str = "", center: str = "", _=Depends(require_admin)):
    """Que tiene que devolver cada conductor, antes de que se vaya a casa.

    Devuelve una fila por conductor con los TBA exactos que trae en la
    furgoneta, el motivo de cada uno, y —en un cajon aparte y bien separado—
    lo que no podemos afirmar porque dejamos de mirar.

    El cajon `no_observado` NO es un fallo de nadie y no debe pintarse como
    tal: es nuestra ceguera, no su descuido.
    """
    dia = day or datetime.now(timezone.utc).strftime("%Y-%m-%d")
    en_curso = dia >= datetime.now(timezone.utc).strftime("%Y-%m-%d")
    match = {"service_day": dia}
    if center and center not in ("Todos", "todos"):
        match["center"] = {"$regex": re.escape(center.strip()), "$options": "i"}

    cur = db.cortex_packages.find(
        match,
        {"_id": 0, "tba": 1, "state": 1, "stop_id": 1, "stop_address": 1,
         "updated_at": 1, "driver_id": 1, "driver_name": 1, "route_code": 1,
         "center": 1, "timeline": 1, "seen_at": 1})
    paquetes = await cur.to_list(20000)
    if not paquetes:
        return {"dia": dia, "conductores": [], "total": 0, "resumen": {}}

    # Ultima captura POR RUTA: la referencia del hueco.
    ultima_por_ruta: dict = {}
    for p in paquetes:
        r = (p.get("route_code") or "").strip()
        u = p.get("updated_at") or ""
        if u > ultima_por_ruta.get(r, ""):
            ultima_por_ruta[r] = u

    # ── CUANDO BAJAMOS ESTA RUTA POR ULTIMA VEZ ──────────────────────────────
    # Esto NO es `updated_at`. `updated_at` es la hora del ultimo EVENTO en
    # Cortex, y una ruta que termino a las 19:00 no vuelve a moverla aunque la
    # pidamos cincuenta veces mas. La pantalla lo llamaba "ultima captura" y por
    # eso parecia que los datos estaban viejos cuando no lo estaban: con ese
    # numero me equivoque yo mismo al diagnosticar esto.
    # `seen_at` lo escribe la ingesta en cada captura, asi que responde a la
    # unica pregunta que importa antes de reclamarle nada a nadie: ¿esto esta al
    # dia? Los paquetes guardados antes de existir el campo no lo traen y salen
    # como desconocido, que es la verdad, no como cero.
    _ahora_iso = datetime.now(timezone.utc).isoformat()
    visto_por_ruta: dict = {}
    for p in paquetes:
        r = (p.get("route_code") or "").strip()
        v = p.get("seen_at") or ""
        if v > visto_por_ruta.get(r, ""):
            visto_por_ruta[r] = v

    # El conductor no viene en todos los paquetes (el informe de faltas no lo
    # trae). Se completa por ruta, igual que hace /cortex/missing-hoy.
    did_por_ruta: dict = {}
    for p in paquetes:
        r = (p.get("route_code") or "").strip()
        if p.get("driver_id") and r and r not in did_por_ruta:
            did_por_ruta[r] = p["driver_id"]

    # UNA FILA POR PERSONA. Es quien esta delante con los paquetes.
    # Agrupar por (conductor, ruta) partia en dos a quien ayuda en otra ruta,
    # y ninguna de las dos mitades era "lo que lleva en la furgoneta".
    porconductor: dict = {}
    rutas_de: dict = {}
    for p in paquetes:
        r = (p.get("route_code") or "").strip()
        did = p.get("driver_id") or did_por_ruta.get(r) or "sin-asignar"
        porconductor.setdefault(did, []).append(p)
        if r:
            rutas_de.setdefault(did, set()).add(r)

    nombres = await _cx_nombres({d for d in porconductor if d and d != "sin-asignar"})

    # Lo ya marcado a mano en el debrief de ese dia.
    marcas = {m["_id"]: m async for m in db.cortex_debrief.find({"service_day": dia})}

    filas = []
    for did, pk in porconductor.items():
        rutas = sorted(rutas_de.get(did) or [])

        # ── ¿CUAL ES SU RUTA? ────────────────────────────────────────────────
        # La que mas paquetes le pone, pero SOLO si dobla a la siguiente.
        # Medido sobre 37 casos de apoyo en dos dias: 34 tienen un reparto
        # clarisimo (227 vs 27, 225 vs 1) y 3 quedan parejos. En esos tres no
        # se afirma nada: etiquetar como "de apoyo" la ruta propia de alguien
        # es peor que no etiquetar.
        _cuenta: dict = {}
        for _p in pk:
            _r = (_p.get("route_code") or "").strip()
            if _r:
                _cuenta[_r] = _cuenta.get(_r, 0) + 1
        _orden = sorted(_cuenta.items(), key=lambda x: -x[1])
        ruta_propia = None
        if len(_orden) == 1:
            ruta_propia = _orden[0][0]
        elif len(_orden) > 1 and _orden[0][1] >= _orden[1][1] * 2:
            ruta_propia = _orden[0][0]
        caj = _cx_debrief_reparto(pk, ultima_por_ruta, en_curso, dia)
        for grupo in ("reintento", "no_entrega", "no_recogido", "perdidos", "sin_cerrar"):
            for f in caj[grupo]:
                m = marcas.get(f"{dia}:{f['tba']}")
                f["marca"] = (m or {}).get("marca")
                f["marca_nota"] = (m or {}).get("nota")
        # LO PENDIENTE SON LOS CUATRO, NO EL INVENTARIO.
        # Contar aqui lo que sigue cargado en la furgoneta ponia rutas con "42
        # pendientes" que en realidad tenian dos problemas y cuarenta paquetes
        # todavia en reparto.
        # Los cuatro cajones, juntos, son "lo que hay que comprobar con el
        # conductor delante". El inventario no entra: si entrara, ninguna ruta
        # se daria por comprobada sin escanear 140 paquetes.
        comprobar = (caj["reintento"] + caj["no_entrega"] +
                     caj["no_recogido"] + caj["perdidos"])
        pendientes = [f for f in comprobar if not f.get("marca")]
        recogidos = sum(1 for f in comprobar if f.get("marca") == "devuelto")
        no_aparecen = sum(1 for f in comprobar if f.get("marca") == "no_aparece")
        filas.append({
            "driver_id": did,
            # SIN FICHA NO ES "SIN IDENTIFICAR".
            # Cortex NO manda nombres (medido: 0 de 7.171 paquetes de hoy), asi
            # que lo unico que pone cara a un conductor es su Transporter ID en
            # la ficha. Hoy 13 de los 53 que salieron a ruta no lo tienen puesto.
            # Poner "Sin identificar" no dice que hacer; poner el ID y avisar de
            # que le falta la ficha, si: se arregla en Conductores en 20 s.
            "conductor": ((nombres.get(did) or {}).get("nombre")
                          or (did if did and did != "sin-asignar" else "Sin asignar")),
            "sin_ficha": not (nombres.get(did) or {}).get("nombre"),
            "transporter_id": did if did != "sin-asignar" else None,
            # `ruta` sigue existiendo para pintar y buscar; `rutas` es la
            # verdad cuando alguien ha tocado mas de una.
            # `ruta` es lo que se pinta de cabecera: la suya si se sabe, y si
            # no, todas juntas (que es lo unico honesto cuando no esta claro).
            "ruta": ruta_propia or (" + ".join(rutas) if rutas else "Sin ruta"),
            "rutas": rutas,
            "ruta_propia": ruta_propia,
            # Las de apoyo, con cuantos paquetes trae de cada una. Sirve para
            # pintar "fue a ayudar en XA_C20 · 3 paquetes" sin tener que
            # contarlos en la pantalla.
            "rutas_apoyo": [{"ruta": r, "paquetes": n} for r, n in _orden
                            if ruta_propia and r != ruta_propia],
            # Cuando no se puede afirmar cual es la suya, se dice: la pantalla
            # enseña las dos sin etiquetarlas y quien mira decide.
            "reparto_dudoso": bool(len(_orden) > 1 and not ruta_propia),
            "paquetes_por_ruta": dict(_orden),
            "es_apoyo": len(rutas) > 1,
            "center": (pk[0].get("center") or "").strip(),
            "total": len(pk),
            "entregados": len(caj["entregados"]),
            # Los cuatro que se miran de primeras
            "reintento": caj["reintento"],
            "no_entrega": caj["no_entrega"],
            "no_recogido": caj["no_recogido"],
            "perdidos": caj["perdidos"],
            # El inventario: lo que sigue en la furgoneta. Util para cuadrar
            # del todo, pero no es lo primero que se mira.
            "sin_cerrar": caj["sin_cerrar"],
            # Lo que NO cuenta, y se enseña aparte para que se vea que no cuenta
            "cancelados": caj["cancelados"],
            "reprogramados": caj["reprogramados"],
            "cliente": caj["cliente"],
            "arrastrados": len(caj["arrastrados"]),
            "no_observado": len(caj["no_observado"]),
            # El contador: de N que hay que comprobar, cuantos van
            "a_comprobar": len(comprobar),
            "recogidos": recogidos,
            "no_aparecen": no_aparecen,
            "pendientes": len(pendientes),
            # "cuadra" NO es "no queda nada por mirar": es "esta todo mirado Y
            # ademas aparecio todo". Un paquete confirmado como perdido deja la
            # ruta comprobada, pero no cuadrada.
            "comprobada": len(pendientes) == 0,
            "cuadra": len(pendientes) == 0 and no_aparecen == 0,
            # La ultima captura que le afecta: la mas tardia de SUS rutas.
            # Aqui si vale la mas tardia, porque es informativa y no decide
            # nada — la regla del hueco ya se aplico paquete a paquete.
            # El ultimo MOVIMIENTO en Cortex (lo que paso), y aparte los
            # minutos desde que bajamos sus rutas (si lo que vemos vale).
            "ultima_captura": max((ultima_por_ruta.get(r) or "" for r in rutas),
                                  default=None) or None,
            "capturado_hace_min": (lambda m: None if m is None else round(m))(
                _cx_minutos(_ahora_iso,
                            max((visto_por_ruta.get(r) or "" for r in rutas), default="") or None)),
        })

    # ORDEN NATURAL POR RUTA, no por numero de pendientes.
    # Ordenar por pendientes hacia que la lista se reordenara sola segun se iba
    # marcando, y quien busca "la C21" tenia que rastrearla. Ahora salen en el
    # mismo orden que en Cortex, que es como las lee quien esta en la nave. Y
    # natural, no alfabetico: sin esto XA_C10 iria antes que XA_C2.
    def _orden_ruta(f):
        import re as _re
        r = f.get("ruta_propia") or f.get("ruta") or ""
        partes = _re.split(r"(\d+)", r)
        return [int(p) if p.isdigit() else p.lower() for p in partes]
    filas.sort(key=_orden_ruta)
    # RUTAS son route_code distintos, no filas. Contando filas salian 61 con
    # 45 rutas y 2 supports en la nave: el numero mas facil de mirar de la
    # pantalla y estaba mal.
    todas_rutas = {(p.get("route_code") or "").strip()
                   for p in paquetes if (p.get("route_code") or "").strip()}
    resumen = {
        "rutas": len(todas_rutas),
        "conductores": len(filas),
        "apoyos": sum(1 for f in filas if f["es_apoyo"]),
        "paquetes": sum(f["total"] for f in filas),
        "entregados": sum(f["entregados"] for f in filas),
        "reintento": sum(len(f["reintento"]) for f in filas),
        "no_entrega": sum(len(f["no_entrega"]) for f in filas),
        "no_recogido": sum(len(f["no_recogido"]) for f in filas),
        "a_devolver": sum(len(f["reintento"]) + len(f["no_entrega"]) +
                          len(f["no_recogido"]) for f in filas),
        "sin_cerrar": sum(len(f["sin_cerrar"]) for f in filas),
        "cancelados": sum(len(f["cancelados"]) for f in filas),
        "reprogramados": sum(len(f["reprogramados"]) for f in filas),
        "cliente": sum(len(f["cliente"]) for f in filas),
        "arrastrados": sum(f["arrastrados"] for f in filas),
        "no_observado": sum(f["no_observado"] for f in filas),
        "perdidos": sum(len(f["perdidos"]) for f in filas),
        "cuadran": sum(1 for f in filas if f["cuadra"]),
        # ── EL CONTADOR DEL DIA ──────────────────────────────────────────────
        "a_comprobar": sum(f["a_comprobar"] for f in filas),
        "recogidos": sum(f["recogidos"] for f in filas),
        "no_aparecen": sum(f["no_aparecen"] for f in filas),
        "sin_comprobar": sum(f["pendientes"] for f in filas),
        "rutas_comprobadas": sum(1 for f in filas if f["comprobada"]),
    }
    # "cuadran" se contaba sobre filas y se comparaba contra "rutas": dos
    # unidades distintas en la misma fraccion. Ahora las dos son conductores.
    resumen["cuadran_de"] = len(filas)
    # Aviso de captura muerta: si casi todo el dia esta sin observar, el cuadre
    # de hoy no vale y hay que decirlo ARRIBA, no dejar que se deduzca.
    tot = max(1, resumen["paquetes"])
    resumen["ciego_pct"] = round(100.0 * resumen["no_observado"] / tot, 1)
    resumen["fiable"] = resumen["ciego_pct"] < 5.0
    resumen["en_curso"] = en_curso
    # EL VEREDICTO. Se calcula aqui y no en la pantalla para que no haya dos
    # versiones de la misma regla. Y solo hay un camino a "todo_recogido":
    # que este TODO mirado y que ademas apareciera todo.
    if resumen["a_comprobar"] == 0:
        resumen["veredicto"] = "nada_que_comprobar"
    elif resumen["sin_comprobar"] > 0:
        resumen["veredicto"] = "a_medias"
    elif resumen["no_aparecen"] > 0:
        resumen["veredicto"] = "faltan"
    else:
        resumen["veredicto"] = "todo_recogido"
    return {"dia": dia, "conductores": filas, "total": len(filas),
            "resumen": resumen, "en_curso": en_curso}


class DebriefMarca(BaseModel):
    marca: str          # 'devuelto' | 'no_aparece'
    nota: str = ""


@api_router.post("/cortex/debrief/{tba}")
async def cortex_debrief_marcar(tba: str, body: DebriefMarca,
                                day: str = "", user=Depends(require_admin)):
    """Marcar un paquete como devuelto en mano, o como que no aparece.

    Se guarda en coleccion APARTE y no sobre el paquete: `cortex_packages` lo
    reescribe la extension en cada captura, asi que una marca puesta ahi se
    perderia sola y sin avisar.
    """
    marca = (body.marca or "").strip().lower()
    if marca not in ("devuelto", "no_aparece", ""):
        raise HTTPException(status_code=400, detail="Marca no valida")
    dia = day or datetime.now(timezone.utc).strftime("%Y-%m-%d")
    tba = (tba or "").strip().upper()
    if not tba:
        raise HTTPException(status_code=400, detail="Falta el paquete")
    if not marca:
        await db.cortex_debrief.delete_one({"_id": f"{dia}:{tba}"})
        return {"ok": True, "marca": None}
    # ── ¿SE HA ENTREGADO MIENTRAS MIRABAS? ───────────────────────────────────
    # Medido el 26-08: cinco marcas de "lo trae" puestas entre 1 y 5 minutos
    # DESPUES de que Cortex registrara la entrega al cliente. No es que nadie
    # marcara sin mirar: la captura tarda 65-90 s y la pantalla refresca cada
    # 45, asi que durante el debrief se puede estar viendo una lista de hace
    # dos minutos — justo cuando el conductor cierra las ultimas paradas.
    #
    # La marca se guarda igual (quien esta delante puede tener razon y Cortex
    # equivocarse), pero se avisa en el momento. Guardar en silencio que un
    # paquete "volvio a la nave" cuando esta entregado es meter un dato falso
    # en el unico sitio donde no se puede.
    aviso = None
    try:
        pk = await db.cortex_packages.find_one(
            {"tba": tba}, {"_id": 0, "timeline": 1, "state": 1})
        if pk:
            vig, vig_at = _cx_estado_vigente(pk.get("timeline") or [])
            if (vig or pk.get("state")) == "DELIVERED":
                cuando = vig_at.strftime("%H:%M") if vig_at else None
                aviso = ("Cortex dice que este paquete se entregó"
                         + (f" a las {cuando}" if cuando else "")
                         + ". Se ha guardado igual, pero comprueba antes de reclamarlo.")
    except Exception as e:
        logger.debug(f"debrief aviso: {e}")

    await db.cortex_debrief.update_one(
        {"_id": f"{dia}:{tba}"},
        {"$set": {"tba": tba, "service_day": dia, "marca": marca,
                  "nota": (body.nota or "")[:300],
                  "quien": (user or {}).get("name") or (user or {}).get("sub"),
                  "en": datetime.now(timezone.utc).isoformat(),
                  # Queda escrito que se marco sobre un paquete ya entregado:
                  # sirve para saber despues si la lista iba retrasada.
                  **({"entregado_ya": True} if aviso else {})}},
        upsert=True)
    return {"ok": True, "marca": marca, "aviso": aviso}


@api_router.get("/cortex/missing-hoy")
async def cortex_missing_hoy(day: str = "", center: str = "", _=Depends(require_admin)):
    """Los paquetes que HOY están en MISSING, con quién los lleva.

    Pestaña propia, aparte de los "no puedo encontrar la dirección": son dos
    problemas distintos y se atienden distinto. Un MISSING es un paquete que no
    aparece —hay que llamar al conductor y que mire la furgoneta— y una
    dirección que no se encuentra es un problema de mapa. Mezclarlos en una
    lista obliga a leer cada línea para saber de qué va.

    Se resuelve el nombre del conductor igual que en /cortex/routes: en
    cortex_packages sólo hay `driver_id`, y sin nombre esta pantalla no sirve
    para lo único que hace falta hacer con un missing, que es llamar a alguien.

    Se adjunta también la dirección REAL si ya se conoce de esa celda: un
    paquete perdido en un portal que además está mal geolocalizado explica
    bastante de por qué se perdió.
    """
    dia = day or datetime.now(timezone.utc).strftime("%Y-%m-%d")
    match = {"service_day": dia, "state": "MISSING"}
    if center and center not in ("Todos", "todos"):
        match["center"] = {"$regex": re.escape(center.strip()), "$options": "i"}

    cur = db.cortex_packages.aggregate(
        [{"$match": match}] + _stage_celda() + [
            {"$project": {"_id": 0, "tba": 1, "stop_address": 1, "stop_id": 1,
                          "driver_name": 1, "driver_id": 1, "route_code": 1, "center": 1,
                          "priority": 1, "reason": 1, "timeline": 1, "first_seen": 1,
                          "updated_at": 1, "_la": 1, "_ln": 1, "_celda": 1}},
            {"$limit": 300},
        ], allowDiskUse=True)
    pkgs = await cur.to_list(300)
    if not pkgs:
        return {"dia": dia, "paquetes": [], "total": 0}

    rutas = sorted({(p.get("route_code") or "").strip() for p in pkgs if p.get("route_code")})
    did_por_ruta: dict = {}
    if rutas:
        cur_c = db.cortex_packages.aggregate([
            {"$match": {"service_day": dia, "route_code": {"$in": rutas},
                        "driver_id": {"$nin": [None, ""]}}},
            {"$group": {"_id": "$route_code", "d": {"$first": "$driver_id"}}},
        ], allowDiskUse=True)
        async for r in cur_c:
            if r.get("_id"):
                did_por_ruta[r["_id"]] = r.get("d")

    def _did(p):
        return p.get("driver_id") or did_por_ruta.get((p.get("route_code") or "").strip())

    nombres = await _cx_nombres({d for d in (_did(p) for p in pkgs) if d})
    celdas = sorted({p["_celda"] for p in pkgs})
    notas = {n["celda"]: n async for n in db.portales.find(
        {"celda": {"$in": celdas}}, {"_id": 0, "celda": 1, "geodir": 1, "nota": 1})}

    out = []
    for p in pkgs:
        n = notas.get(p["_celda"], {})
        # Cuándo se marcó MISSING: es la antigüedad, y con un paquete perdido
        # el tiempo que lleva perdido es la mitad de la información.
        hora = None
        for ev in (p.get("timeline") or []):
            if ev.get("state") == "MISSING" and ev.get("at"):
                hora = ev["at"]
        out.append({
            "tba": p.get("tba"),
            "stop_id": p.get("stop_id"),
            "direccion": _cortex_addr_str(p.get("stop_address")),
            "conductor": (nombres.get(_did(p)) or {}).get("nombre") or p.get("driver_name"),
            "ruta": p.get("route_code"),
            "center": (p.get("center") or "").strip(),
            "lat": p.get("_la"), "lng": p.get("_ln"),
            "celda": p.get("_celda"),
            "hora": hora or p.get("updated_at"),
            "prioridad": p.get("priority"),
            "motivo": p.get("reason"),
            "nota": n.get("nota"),
            "real": (n.get("geodir") or None),
        })
    out.sort(key=lambda x: (x["hora"] or ""), reverse=True)
    return {"dia": dia, "paquetes": out, "total": len(out),
            "criticos": sum(1 for p in out if p.get("prioridad") == "critical")}


@api_router.get("/cortex/direcciones-hoy")
async def cortex_direcciones_hoy(day: str = "", center: str = "", _=Depends(require_admin)):
    """Los paquetes de HOY que el conductor marcó "no puedo encontrar la dirección".

    Esto NO es la Libreta de portales. La Libreta mira 60 días hacia atrás y
    agrupa por zona: sirve para decidir qué portales arreglar, y se lee una vez
    a la semana. Aquí se quiere lo contrario y para otro momento: los paquetes
    de HOY, uno a uno, con su TBA, su conductor y su hora, mientras la ruta
    todavía está en marcha y aún se puede hacer algo con ellos.

    DÓNDE VIVE "no puedo encontrar la dirección": NO en `state`. El estado que
    guarda Cortex es el genérico `ATTEMPTED` (raw `DELIVERY_ATTEMPTED`), y el
    motivo va en el `context` del evento del timeline:

        {"state": "ATTEMPTED", "raw": "DELIVERY_ATTEMPTED",
         "context": "ADDRESS_NOT_FOUND", "at": "..."}

    Filtrar por `state == "ADDRESS_NOT_FOUND"` devuelve CERO siempre, aunque en
    la pantalla de Cortex se estén viendo. Comprobado el 2026-08-15: 71
    ATTEMPTED ese día y ni un solo paquete con ese estado.

    Y el evento se busca POR FECHA, no vale con que el paquete sea de hoy: un
    mismo paquete arrastra intentos de días anteriores en su timeline (este
    mismo tenía uno del día 13 y otro del 15). Sin filtrar por día saldrían
    todos los del historial, que es justo lo que no se quiere aquí.

    La dirección real NO se resuelve aquí: la calcula el navegador (Nominatim
    responde 403 al servidor) y la guarda por celda con /cortex/portales/geodir.
    Este endpoint sólo junta el paquete con lo que ya se sepa de su celda, para
    que al recargar no haya que volver a buscar nada.
    """
    dia = day or datetime.now(timezone.utc).strftime("%Y-%m-%d")
    # Cortex escribe el mismo motivo de dos formas según de dónde salga:
    # 'ADDRESS_NOT_FOUND' en el timeline de route-details y 'ADDRESS NOT FOUND'
    # (con espacios) en el informe de faltas — se ve en su propia URL:
    # `&reasonCode=ADDRESS%20NOT%20FOUND`. Se aceptan las dos, y también lo ya
    # guardado antes de normalizarlo en la extensión.
    _RE_SIN_DIR = r"^ADDRESS[ _-]?NOT[ _-]?FOUND$"
    match = {"service_day": dia,
             "timeline.context": {"$regex": _RE_SIN_DIR, "$options": "i"}}
    if center and center not in ("Todos", "todos"):
        match["center"] = {"$regex": re.escape(center.strip()), "$options": "i"}

    cur = db.cortex_packages.aggregate(
        [{"$match": match}] + _stage_celda() + [
            {"$project": {"_id": 0, "tba": 1, "stop_address": 1, "stop_id": 1,
                          "driver_name": 1, "driver_id": 1, "route_code": 1, "center": 1,
                          "state": 1, "timeline": 1, "_la": 1, "_ln": 1, "_celda": 1}},
            {"$limit": 400},
        ], allowDiskUse=True)
    pkgs = await cur.to_list(400)
    if not pkgs:
        return {"dia": dia, "paquetes": [], "total": 0}


    # QUIÉN LLEVA EL PAQUETE — lo primero que hace falta para poder llamarle.
    #
    # Dos trampas juntas:
    #  · `cortex_packages` NO tiene driver_name, tiene driver_id (el ID de
    #    Amazon). El nombre se resuelve aparte con _cx_nombres, igual que hace
    #    /cortex/routes. Buscar driver_name aquí devolvía siempre vacío.
    #  · El informe de faltas —de donde sale la dirección— tampoco trae
    #    conductor, así que estos paquetes ni siquiera tienen driver_id. Se
    #    coge el de la RUTA: cualquier otro paquete del mismo route_code ese día
    #    sí lo trae, porque viene de route-details.
    rutas = sorted({(p.get("route_code") or "").strip() for p in pkgs if p.get("route_code")})
    did_por_ruta: dict = {}
    if rutas:
        cur_c = db.cortex_packages.aggregate([
            {"$match": {"service_day": dia, "route_code": {"$in": rutas},
                        "driver_id": {"$nin": [None, ""]}}},
            {"$group": {"_id": "$route_code", "d": {"$first": "$driver_id"}}},
        ], allowDiskUse=True)
        async for r in cur_c:
            if r.get("_id"):
                did_por_ruta[r["_id"]] = r.get("d")

    def _did(p):
        return (p.get("driver_id")
                or did_por_ruta.get((p.get("route_code") or "").strip()))

    nombres = await _cx_nombres({d for d in (_did(p) for p in pkgs) if d})

    # Lo que ya se sabe de esas celdas: si otro paquete de la misma puerta ya se
    # resolvió, este sale resuelto de entrada y el navegador no repite la busqueda.
    celdas = sorted({p["_celda"] for p in pkgs})
    notas = {n["celda"]: n async for n in db.portales.find(
        {"celda": {"$in": celdas}}, {"_id": 0, "celda": 1, "geodir": 1, "nota": 1})}

    out = []
    for p in pkgs:
        n = notas.get(p["_celda"], {})
        # La hora del intento de HOY. `at` puede llegar como fecha o como
        # cadena, asi que se compara por los 10 primeros caracteres de su texto.
        # Un paquete con un ADDRESS_NOT_FOUND de otro dia y ninguno de hoy no
        # entra: hoy no ha fallado.
        hora, intentos_hoy = None, 0
        for ev in (p.get("timeline") or []):
            if not ev.get("at") or not re.match(
                    _RE_SIN_DIR, str(ev.get("context") or ""), re.I):
                continue
            if str(ev["at"])[:10] != dia:
                continue
            intentos_hoy += 1
            hora = ev["at"]
        if not intentos_hoy:
            continue
        out.append({
            "intentos_hoy": intentos_hoy,
            "tba": p.get("tba"),
            "stop_id": p.get("stop_id"),
            "direccion": _cortex_addr_str(p.get("stop_address")),
            "conductor": (nombres.get(_did(p)) or {}).get("nombre") or p.get("driver_name"),
            "ruta": p.get("route_code"),
            "center": (p.get("center") or "").strip(),
            "lat": p.get("_la"), "lng": p.get("_ln"),
            "celda": p.get("_celda"),
            "hora": hora,
            "nota": n.get("nota"),
            "real": n.get("geodir"),
        })
    # Lo mas reciente arriba: es el que todavia da tiempo a rescatar.
    out.sort(key=lambda x: (x["hora"] or ""), reverse=True)
    return {"dia": dia, "paquetes": out, "total": len(out),
            "sin_resolver": sum(1 for p in out if not p["real"])}


@api_router.get("/cortex/portales/mi-ruta")
async def cortex_portales_mi_ruta(user: dict = Depends(require_any_auth)):
    """Los avisos de portal de los paquetes que este conductor lleva HOY.

    Esta es la parte que convierte la libreta en dinero: en cuanto la furgoneta
    carga, los paquetes traen driver_id y coordenadas, asi que se sabe a que
    portales va antes de que salga. El conductor abre la app y ve el codigo del
    portal ANTES de plantarse delante, en vez de descubrirlo fallando.
    """
    # El JWT del conductor lleva su ficha en 'id' (create_token(driver_id, ...)
    # en /auth/driver-token), no el ID de Amazon: hay que resolverlo contra la
    # ficha. Un admin que llame a esto no tiene ficha y no recibe avisos, que es
    # lo correcto: esta ruta es la vista personal del conductor.
    ficha = await db.drivers.find_one({"id": user.get("id")}, {"_id": 0, "driver_id": 1})
    did = ((ficha or {}).get("driver_id") or "").strip()
    if not did:
        return {"avisos": [], "motivo": "sin_id_amazon"}

    hoy = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    cur = db.cortex_packages.aggregate(
        [{"$match": {"driver_id": did, "service_day": hoy}}] + _stage_celda() +
        [{"$group": {"_id": "$_celda", "paquetes": {"$sum": 1},
                     "stop": {"$first": "$stop_id"}}}], allowDiskUse=True)
    celdas = await cur.to_list(500)
    if not celdas:
        return {"avisos": [], "motivo": "sin_paquetes_hoy"}

    claves = [c["_id"] for c in celdas]
    porc = {c["_id"]: c for c in celdas}
    avisos = []
    async for n in db.portales.find({"celda": {"$in": claves}, "resuelto": {"$ne": True}}, {"_id": 0}):
        geo = n.get("geo") or {}
        gd = n.get("geodir") or {}
        # Un aviso sin nota y sin dirección resuelta no dice nada. Pintarlo
        # entrenaría al conductor a ignorar este bloque, y el día que sí haya
        # algo tampoco lo leería.
        if not (n.get("nota") or geo.get("display") or gd.get("display")):
            continue
        c = porc.get(n["celda"], {})
        avisos.append({"nota": n.get("nota"), "lat": n.get("lat"), "lng": n.get("lng"),
                       "stop": c.get("stop"), "paquetes": c.get("paquetes", 0),
                       "autor": n.get("autor"),
                       # La dirección del mapa se manda tal cual, con su
                       # precisión: el conductor tiene que poder ver que es
                       # "la calle", no "el portal exacto".
                       "direccion": geo.get("display") or None,
                       "precision": geo.get("precision") or None,
                       # DÓNDE ESTÁ DE VERDAD la dirección, cuando dos fuentes
                       # independientes lo confirmaron. `metros_amazon` es lo
                       # accionable: a cuánto está del punto al que le mandan.
                       # Sólo viaja lo confirmado — al conductor no se le
                       # enseñan hipótesis, que es lo que le haría perder viajes.
                       "real": ({"display": gd.get("display"),
                                 "lat": gd.get("lat"), "lng": gd.get("lng"),
                                 "metros": gd.get("metros_amazon"),
                                 "precision_acuerdo": gd.get("precision_acuerdo"),
                                 "veredicto": gd.get("veredicto"),
                                 "fuentes": gd.get("fuentes") or []}
                                if gd.get("display") and gd.get("lat") is not None else None)})
    avisos.sort(key=lambda a: a["paquetes"], reverse=True)
    return {"avisos": avisos, "stops_con_aviso": len(avisos), "dia": hoy}


@api_router.get("/cortex/ingest-token")
async def cortex_ingest_token(user: dict = Depends(require_admin)):
    """La llave de la extensión. UNA POR EMPRESA, y nunca compartida.

    El `db_name` es lo que separa los datos de una empresa de los de otra: va
    dentro del token y la ingesta lo aplica antes de escribir nada. Si faltara,
    `set_current_org_db(None)` caería en la base por defecto y los paquetes de
    un DSP acabarían mezclados con los de otro — en silencio, con HTTP 200 y
    sin un solo error en los logs (gotcha 26).
    """
    db_name = user.get("db_name")
    if not db_name:
        # Preferimos no dar token a dar uno que mezcle datos. Un token que no
        # funciona se nota en cinco minutos; datos de dos empresas mezclados se
        # notan semanas después y ya no se pueden separar.
        raise HTTPException(
            500, "Tu cuenta no tiene empresa asignada, así que no se puede generar "
                 "una llave que aísle tus datos. Avísanos antes de instalar la extensión.")
    payload = {
        "scope": "cortex_ingest", "org_id": user.get("org_id", ""),
        "db_name": db_name, "name": user.get("name", ""),
        "exp": datetime.now(timezone.utc) + timedelta(days=365),
    }
    return {"token": jwt.encode(payload, SECRET_KEY, algorithm=JWT_ALGORITHM),
            "ingest_url": f"{PUBLIC_BASE_URL}/api/cortex/ingest",
            "empresa": user.get("org_id") or "",
            "caduca": (datetime.now(timezone.utc) + timedelta(days=365)).strftime("%Y-%m-%d")}


@api_router.post("/cortex/ingest")
async def cortex_ingest(request: Request):
    """Recibe observaciones canónicas de la extensión (JSON real de Cortex ya
    normalizado). No requiere JWT de usuario: se autentica por token de ingesta."""
    _cortex_ingest_org(request)
    body = await request.json()

    # QUE VERSION DE LA EXTENSION HABLA. Repartida a varias naves, sin esto no
    # hay forma de saber quien tiene cual, y un fallo arreglado hace tres
    # versiones se investiga otra vez desde cero. Es una sola linea por
    # estacion y se ve en /cortex/diagnostico.
    _ver = str(request.headers.get("x-ext-version") or "")[:16]
    if _ver:
        # UNA FILA POR INSTALACION, no una por empresa. Antes se guardaba en un
        # unico `version:extension` y el ultimo equipo que hablara pisaba a los
        # demas: con cuatro PCs en la oficina, la version que se veia era la del
        # que acababa de refrescar. Asi no se puede probar una version nueva en
        # un equipo sin perder de vista a los otros, que es justo lo que hacia
        # falta el 04-09-2026. El id lo genera la extension al instalarse y no
        # dice quien es nadie: solo distingue una instalacion de otra.
        _inst = re.sub(r"[^A-Za-z0-9_-]", "", str(request.headers.get("x-ext-install") or ""))[:40]
        try:
            ahora = datetime.now(timezone.utc)
            await db.cortex_diagnostico.update_one(
                {"_id": "version:%s" % (_inst or "extension")},
                {"$set": {"kind": "version", "which": "extension", "url": _ver,
                          "instalacion": _inst or None,
                          "visto_en": ahora.isoformat(),
                          "expira_en": ahora + timedelta(days=30)}},
                upsert=True)
        except Exception:
            pass

    # ── DIAGNÓSTICO DE ESQUEMA ────────────────────────────────────────────────
    # La extensión lleva tiempo mandando el ESQUEMA REAL de route-details y del
    # informe de faltas (kind='schema'), y esto lo tiraba a la basura: solo
    # miraba body['packages']. Sin ese esquema no hay forma de saber qué campos
    # da Cortex de verdad, y las reglas se acaban escribiendo a ojo — que es
    # justo lo que no queremos para tocar el DCR.
    #
    # `schemaOf` del interceptor conserva los valores de cadena cortos, así que
    # aquí llegan los códigos literales: taskType, taskState, taskStateContext,
    # tipos de parada. Con eso se puede decidir con pruebas si una anulación en
    # nave se distingue sola, en vez de inventar un umbral de hora y dirección.
    kind = str(body.get("kind") or "").strip()

    # ── LOS CONTADORES DEL PROPIO CORTEX ─────────────────────────────────────
    # `route-summaries` trae lo que Amazon cuenta por ruta y por conductor. Es la
    # unica forma de saber si vamos por detras, y hace falta: el 28-08-2026 a las
    # 14:37 Cortex decia 3.251 restantes y nosotros teniamos 1.039 entregados de
    # 6.775 — unas 2.500 entregas sin capturar y en pantalla no se notaba nada.
    #
    # Se guarda TAL CUAL y sin interpretarlo. El esquema que teniamos se capturo
    # con los arrays vacios, asi que los nombres de dentro no se conocen; leerlos
    # cuando haya datos de verdad es mas lento y es lo unico que no se inventa
    # nada. Una foto por dia y estacion, siempre la ultima.
    if kind == "resumen_cortex":
        try:
            dia = str(body.get("dia") or "")[:10] or datetime.now(timezone.utc).strftime("%Y-%m-%d")
            sa = str(body.get("sa") or "")[:64]
            datos = body.get("datos") or {}

            # ── SE ACEPTAN LAS DOS FORMAS ────────────────────────────────────
            # Las versiones viejas de la extension mandan las rutas EN CRUDO
            # (43 campos por ruta) y bajo la clave `conductores`; las nuevas las
            # mandan ya recortadas y en `gente`/`cuentas`. Con varias naves, en
            # cualquier momento hay dos versiones a la vez, y una de ellas
            # guardaria el resumen a medias — que es peor que no guardarlo,
            # porque parece que esta y no lo esta.
            # Se normaliza aqui: el crudo se recorta al llegar.
            def _ruta_norm(r):
                if not isinstance(r, dict):
                    return None
                if "paquetes" in r or "routeCode" not in r:
                    return r                      # ya viene recortada
                prog = r.get("routeDeliveryProgress") or {}
                return {
                    "routeId": r.get("routeId"), "routeCode": r.get("routeCode"),
                    "transporterId": r.get("transporterIdFromRms"),
                    "status": r.get("routeStatus"), "progreso": r.get("progressStatus"),
                    "paquetes": prog.get("routePackageSummary") or {},
                    "totalTasks": prog.get("totalTasks"),
                    "completedTasks": prog.get("completedTasks"),
                    "totalStops": prog.get("totalStops"),
                    "completedStops": prog.get("completedStops"),
                }

            _rutas = [x for x in (_ruta_norm(r) for r in (datos.get("rutas") or [])) if x]
            _gente = datos.get("gente") or []
            # `conductores` es como lo llamaban las versiones viejas.
            _cuentas = datos.get("cuentas") or datos.get("conductores") or []
            datos = {"rutas": _rutas, "gente": _gente, "cuentas": _cuentas}

            await db.cortex_resumen.update_one(
                {"_id": f"{dia}:{sa}"},
                {"$set": {"dia": dia, "service_area_id": sa,
                          "rutas": (datos.get("rutas") or [])[:200],
                          # Nombre y telefono de cada conductor, publicados por
                          # el propio Cortex. Es lo que hace que el debrief pueda
                          # poner cara a un id en vez de enseñar el codigo.
                          "gente": (datos.get("gente") or [])[:400],
                          "cuentas": (datos.get("cuentas") or [])[:400],
                          "visto_en": datetime.now(timezone.utc).isoformat(),
                          "expira_en": datetime.now(timezone.utc) + timedelta(days=60)}},
                upsert=True)
            # Con la gente recien capturada, completa los telefonos que falten.
            await _telefonos_desde_cortex()
        except Exception as e:
            logger.warning(f"Resumen de Cortex: {e}")
        return {"ok": True, "guardado": "resumen_cortex"}

    if kind in ("schema", "debug"):
        try:
            cual = str(body.get("which") or kind)[:40]
            await db.cortex_diagnostico.update_one(
                {"_id": f"{kind}:{cual}"},
                {"$set": {
                    "kind": kind, "which": cual,
                    "url": str(body.get("url") or "")[:200],
                    # El esquema, no los datos: llega ya recortado por la extensión.
                    "schema": str(body.get("schema") or "")[:8000],
                    "count": body.get("count"), "bytes": body.get("bytes"),
                    "visto_en": datetime.now(timezone.utc).isoformat(),
                    # TTL: es diagnóstico, no histórico. No debe crecer sin fin
                    # (la colección hermana ya se desbocó una vez).
                    "expira_en": datetime.now(timezone.utc) + timedelta(days=30),
                }}, upsert=True)
        except Exception as e:
            logger.debug(f"Cortex diagnostico: {e}")
        return {"ok": True, "guardado": kind}

    packages = body.get("packages") or []
    if not isinstance(packages, list):
        raise HTTPException(status_code=400, detail="Formato inválido: se espera 'packages': [...]")
    captured_at = body.get("captured_at")
    stats = {"new": 0, "changed": 0, "same": 0}
    for obs in packages[:6000]:
        try:
            stats[await _cortex_apply_observation(obs, captured_at)] += 1
        except Exception as e:
            logger.warning(f"Cortex ingest obs: {e}")
    logger.info(f"Cortex ingest: {stats['new']} nuevos, {stats['changed']} cambios de {len(packages)} obs")
    return {"ok": True, **stats, "received": len(packages)}


@api_router.get("/cortex/diagnostico")
async def cortex_diagnostico(_=Depends(require_admin)):
    """Lo que Cortex manda de verdad: esquema de route-details, del sumario y
    del informe de faltas, tal y como los ve la extensión.

    Existe para dejar de escribir reglas a ojo. Mientras no se sepa qué campo
    marca una anulación en nave —un taskType, un taskStateContext, un tipo de
    parada— cualquier exclusión del DCR es una suposición, y una suposición que
    mueve el DCR es peor que no tocarlo.
    """
    docs = await db.cortex_diagnostico.find({}, {"_id": 0, "expira_en": 0}).to_list(200)
    docs.sort(key=lambda d: str(d.get("visto_en") or ""), reverse=True)
    # Las versiones, agrupadas: cuantos equipos llevan cada una y cuando hablo
    # el ultimo. Es lo que permite instalar una version nueva en UN equipo y
    # comprobar que efectivamente es ese el que la lleva.
    vers: dict = {}
    for d in docs:
        if d.get("kind") != "version":
            continue
        v = vers.setdefault(d.get("url") or "?", {"version": d.get("url") or "?",
                                                  "equipos": 0, "ultima": ""})
        v["equipos"] += 1
        v["ultima"] = max(v["ultima"], str(d.get("visto_en") or ""))
    return {"diagnostico": docs,
            "versiones": sorted(vers.values(), key=lambda v: v["ultima"], reverse=True),
            "hay_esquema": any(d.get("kind") == "schema" for d in docs)}


def _cortex_day_query(day: str) -> dict:
    """Filtro Mongo por día de servicio. Los paquetes nuevos traen service_day;
    los antiguos (sin él) se ubican por la fecha de updated_at como fallback."""
    if not day:
        return {}
    return {"$or": [
        {"service_day": day},
        {"$and": [{"service_day": {"$in": [None, ""]}},
                  {"updated_at": {"$regex": f"^{re.escape(day)}"}}]},
    ]}


async def _cortex_scope(day: str, center: str) -> dict:
    """Query Mongo combinando día + centro. El centro se resuelve por el MAPEO
    estación→centro (serviceAreaId), que es el identificador duro y siempre
    correcto; así reasignar una estación re-filtra al instante sin re-etiquetar."""
    conds = []
    dq = _cortex_day_query(day)
    if dq:
        conds.append(dq)
    if center and center not in ("Todos", "todos", ""):
        c = center.upper()
        stations = [s async for s in db.cortex_stations.find(
            {}, {"_id": 0, "service_area_id": 1, "center": 1})]
        saids = [s["service_area_id"] for s in stations
                 if s.get("service_area_id") and s.get("center") == c]
        mapped_ids = [s["service_area_id"] for s in stations
                      if s.get("service_area_id") and s.get("center")]
        # Un paquete es de este centro si su estación está mapeada a él, o si ya
        # trae la etiqueta center (captura reciente que la leyó bien).
        or_c = [{"center": c}]
        if saids:
            or_c.append({"service_area_id": {"$in": saids}})
        # HUÉRFANOS: sin etiqueta de centro Y sin estación mapeada a ningún
        # centro. Antes desaparecían al filtrar por centro (parecía que "no
        # había nada"); ahora se ven en TODOS los centros hasta que se asigna
        # su estación — datos invisibles es peor que datos sin repartir.
        if mapped_ids:
            or_c.append({"$and": [{"center": {"$in": [None, ""]}},
                                  {"service_area_id": {"$nin": mapped_ids}}]})
        else:
            or_c.append({"center": {"$in": [None, ""]}})
        conds.append({"$or": or_c})
    if not conds:
        return {}
    return conds[0] if len(conds) == 1 else {"$and": conds}


"""Reparto automático de estaciones Cortex por GEOGRAFÍA.

El problema real: con dos pestañas de Cortex abiertas, la etiqueta de centro que
la extensión saca del selector de la página se mezcla, y acaban dos estaciones
distintas marcadas con el mismo centro. Pedirle al usuario que lo asigne a mano
no es una solución: ya hay un botón para eso y no debería hacer falta.

El discriminante bueno es dónde se entrega. El prefijo de ruta separa OGA5
(XA_C) de la zona de A Coruña/Vigo (CA_A), pero NO separa DGA1 de DGA2 — las dos
usan CA_A. Las coordenadas sí: Santiago, Cambre y Vigo están a 60-100 km unas de
otras, así que no hay forma de confundirlas.

Las referencias de cada centro no se inventan: salen de los talleres ya
sembrados en este mismo fichero (_SEED_WORKSHOPS), que llevan `center` y
coordenadas verificadas. Se toma la MEDIANA de cada centro, no la media, para
que un taller aislado no arrastre el punto de referencia.
"""
_CENTRO_KM_MAX = 70.0       # más lejos que esto, no es de ese centro
_CENTRO_MARGEN = 1.8        # el mejor debe estar 1,8× más cerca que el segundo


def _mediana(xs: list) -> float:
    ys = sorted(xs)
    n = len(ys)
    return ys[n // 2] if n % 2 else (ys[n // 2 - 1] + ys[n // 2]) / 2


@functools.lru_cache(maxsize=1)
def _centros_referencia() -> dict:
    """centro → (lat, lng) mediano de sus talleres verificados."""
    acc: dict = {}
    for w in _SEED_WORKSHOPS:
        c = (w.get("center") or "").strip().upper()
        la, ln = w.get("latitude"), w.get("longitude")
        if c and isinstance(la, (int, float)) and isinstance(ln, (int, float)):
            acc.setdefault(c, []).append((float(la), float(ln)))
    return {c: (_mediana([p[0] for p in ps]), _mediana([p[1] for p in ps]))
            for c, ps in acc.items() if len(ps) >= 3}


def _centro_por_coordenada(lat: float, lng: float) -> tuple:
    """(centro, km) del centro más cercano, o (None, motivo) si no está claro.

    Devolver None es una respuesta legítima: un punto a mitad de camino entre
    dos centros no se asigna a ojo. Sin certeza, no se etiqueta.
    """
    refs = _centros_referencia()
    if not refs:
        return None, "sin_referencias"
    dists = sorted(((_haversine_km((lat, lng), p) or 9e9, c) for c, p in refs.items()))
    mejor_km, mejor = dists[0]
    if mejor_km > _CENTRO_KM_MAX:
        return None, f"lejos_de_todo_{round(mejor_km)}km"
    if len(dists) > 1 and dists[1][0] < mejor_km * _CENTRO_MARGEN:
        return None, f"ambiguo_{mejor}_vs_{dists[1][1]}"
    return mejor, round(mejor_km, 1)


async def _centro_de_estacion(sid: str) -> dict:
    """Resuelve el centro de una estación por la mediana de sus entregas.

    La mediana, no la media: una entrega mal geocodificada en mitad del Atlántico
    movería la media y no mueve la mediana.
    """
    cur = db.cortex_packages.aggregate([
        {"$match": {"service_area_id": sid, "lat": {"$nin": [None, ""]}}},
        {"$sample": {"size": 400}},
        {"$project": {"_id": 0, "lat": 1, "lng": 1, "route_code": 1}},
    ], allowDiskUse=True)
    lats, lngs, prefijos = [], [], set()
    async for p in cur:
        try:
            lats.append(float(p["lat"])); lngs.append(float(p["lng"]))
        except (TypeError, ValueError, KeyError):
            continue
        m = re.match(r"^(.*?)(\d+)\s*$", str(p.get("route_code") or ""))
        if m:
            prefijos.add(m.group(1))
    if len(lats) < 20:
        return {"centro": None, "motivo": "pocas_coordenadas", "muestra": len(lats)}
    centro, det = _centro_por_coordenada(_mediana(lats), _mediana(lngs))
    return {"centro": centro, "motivo": None if centro else det,
            "km": det if centro else None, "muestra": len(lats),
            "prefijos": sorted(prefijos)[:6],
            "lat": round(_mediana(lats), 5), "lng": round(_mediana(lngs), 5)}


@api_router.post("/cortex/stations/auto")
async def cortex_stations_auto(aplicar: bool = False, _=Depends(require_admin)):
    """Propone (o aplica) el centro de cada estación por geografía.

    Con `aplicar=false` solo dice qué haría: se puede mirar antes de tocar nada.
    Con `aplicar=true` escribe el mapeo y re-etiqueta los paquetes, igual que el
    botón manual — pero solo las estaciones que ha podido resolver SIN duda.
    Una estación ambigua se queda como está: prefiero dejarla sin resolver a
    repartir mal el DCR de un centro.
    """
    sids = await db.cortex_packages.distinct("service_area_id")
    propuestas, aplicadas = [], 0
    for sid in [s for s in sids if s]:
        r = await _centro_de_estacion(sid)
        actual = await db.cortex_stations.find_one({"service_area_id": sid}, {"_id": 0, "center": 1, "manual": 1})
        r["service_area_id"] = sid
        r["actual"] = (actual or {}).get("center")
        r["cambia"] = bool(r["centro"] and r["centro"] != r["actual"])
        propuestas.append(r)
        if aplicar and r["centro"]:
            await db.cortex_stations.update_one(
                {"service_area_id": sid},
                {"$set": {"center": r["centro"], "manual": True, "origen": "geografia",
                          "resuelto_en": datetime.now(timezone.utc).isoformat()}},
                upsert=True)
            res = await db.cortex_packages.update_many(
                {"service_area_id": sid, "center": {"$ne": r["centro"]}},
                {"$set": {"center": r["centro"]}})
            r["paquetes_reetiquetados"] = res.modified_count
            aplicadas += 1
    propuestas.sort(key=lambda x: -(x.get("muestra") or 0))
    return {"propuestas": propuestas, "aplicadas": aplicadas,
            "sin_resolver": [p["service_area_id"] for p in propuestas if not p["centro"]],
            "referencias": {c: {"lat": round(p[0], 4), "lng": round(p[1], 4)}
                            for c, p in _centros_referencia().items()}}


@api_router.get("/cortex/stations")
async def cortex_stations(_=Depends(require_admin)):
    """Estaciones Cortex detectadas y su centro, con las MEZCLAS a la vista.

    Antes esto tenía dos fallos que hacían inservible el reparto por centro:

    1. La etiqueta que se enseñaba salía del PRIMER paquete que Mongo devolviera
       (un `setdefault` que nunca se corregía). Bastaba un paquete despistado
       para que una estación entera apareciera con un centro que no era — que es
       exactamente lo que pasaba con la que salía como 'DGP1'.
    2. Se traía los ~90.000 documentos a Python para contarlos. En una máquina
       de 1 GB eso no falla: se muere en silencio.

    Ahora agrupa en Mongo y devuelve el REPARTO real de centros de cada
    estación. Si una estación tiene paquetes bajo dos centros distintos se dice
    (`mezclado`), porque eso es justo lo que hay que arreglar y hasta ahora no
    se veía. El mapeo manual sigue mandando sobre todo lo demás.
    """
    stations = await db.cortex_stations.find({}, {"_id": 0}).to_list(200)
    # Si por lo que sea quedan dos documentos con el mismo service_area_id,
    # MANDA EL MANUAL. Un `{s["service_area_id"]: s for s in ...}` se quedaba
    # con el último que devolviera Mongo, que podía ser el que escribió la
    # extensión: por eso una asignación hecha a mano parecía no guardarse.
    smap: dict = {}
    for s in stations:
        sid = s.get("service_area_id")
        if not sid:
            continue
        previo = smap.get(sid)
        if previo is None or (s.get("manual") and not previo.get("manual")):
            smap[sid] = s

    cur = db.cortex_packages.aggregate([
        {"$match": {"service_area_id": {"$nin": [None, ""]}}},
        {"$group": {
            "_id": {"sid": "$service_area_id", "center": "$center"},
            "n": {"$sum": 1},
            "rutas": {"$addToSet": "$route_code"},
            "ultimo": {"$max": "$service_day"},
        }},
    ], allowDiskUse=True)

    porEstacion: dict = {}
    async for row in cur:
        # $group OMITE la clave del _id cuando el campo no existe (gotcha 9)
        sid = (row.get("_id") or {}).get("sid")
        if not sid:
            continue
        centro = ((row.get("_id") or {}).get("center") or "").strip()
        e = porEstacion.setdefault(sid, {"n": 0, "centros": {}, "rutas": set(), "ultimo": None})
        e["n"] += row["n"]
        if centro:
            e["centros"][centro] = e["centros"].get(centro, 0) + row["n"]
        for r in (row.get("rutas") or []):
            if r and len(e["rutas"]) < 400:
                e["rutas"].add(r)
        if row.get("ultimo") and (not e["ultimo"] or row["ultimo"] > e["ultimo"]):
            e["ultimo"] = row["ultimo"]

    def prefijo(rc):
        m = re.match(r"^(.*?)(\d+)\s*$", str(rc or ""))
        return m.group(1) if m else None

    out = []
    for sid, e in porEstacion.items():
        manual = smap.get(sid) or {}
        # El más frecuente, no el primero que salga. Y solo como SUGERENCIA:
        # el mapeo manual, si existe, manda.
        mayoritario = max(e["centros"].items(), key=lambda kv: kv[1])[0] if e["centros"] else None
        prefijos = sorted({p for p in (prefijo(r) for r in e["rutas"]) if p})
        out.append({
            "service_area_id": sid,
            "center": manual.get("center") or mayoritario,
            "manual": bool(manual.get("manual")),
            "station_code": manual.get("station_code"),
            "sample_routes": sorted(e["rutas"])[:4],
            # Los prefijos delatan la mezcla mejor que cuatro códigos sueltos:
            # dos estaciones con el mismo prefijo no pueden ser centros distintos.
            "prefijos": prefijos[:6],
            "centros": dict(sorted(e["centros"].items(), key=lambda kv: -kv[1])),
            "mezclado": len(e["centros"]) > 1,
            "ultimo_dia": e["ultimo"],
            "n": e["n"],
        })

    out.sort(key=lambda x: -x["n"])
    # Un prefijo de ruta que aparece en dos estaciones con centros distintos es
    # una contradicción: o el mapeo está mal, o Cortex reutiliza el prefijo.
    porPrefijo: dict = {}
    for s in out:
        for p in s["prefijos"]:
            porPrefijo.setdefault(p, set()).add(s["center"] or "—")
    conflictos = sorted(p for p, cs in porPrefijo.items() if len(cs) > 1)
    return {"stations": out,
            "mezcladas": sum(1 for s in out if s["mezclado"]),
            "prefijos_en_conflicto": conflictos}


@api_router.post("/cortex/stations")
async def cortex_assign_station(body: dict = Body(...), _=Depends(require_admin)):
    """Asigna manualmente un serviceAreaId a un centro y re-etiqueta sus paquetes."""
    sid = str(body.get("service_area_id") or "").strip()
    center = str(body.get("center") or "").strip().upper()
    if not sid or not center:
        raise HTTPException(400, "Falta service_area_id o center")
    # manual=True: este mapeo lo decidió una persona y las capturas de la
    # extensión ya no pueden pisarlo (antes se sobrescribía cada 2 minutos).
    #
    # update_MANY, no update_one: si quedara algún duplicado de service_area_id
    # (los creaba una carrera de upserts de la ingesta), update_one tocaba sólo
    # uno y la lectura podía quedarse con el otro. El botón devolvía 200 y no
    # cambiaba nada en pantalla. Con update_many, si hay dos documentos se
    # quedan los dos diciendo lo mismo y la ambigüedad desaparece.
    r_map = await db.cortex_stations.update_many(
        {"service_area_id": sid}, {"$set": {"center": center, "manual": True}})
    if r_map.matched_count == 0:
        await db.cortex_stations.update_one(
            {"service_area_id": sid}, {"$set": {"center": center, "manual": True}}, upsert=True)

    # SOLO esta estación, y se responde. Antes aquí se hacía una
    # re-sincronización GLOBAL —un update_many por CADA estación, sobre ~165.000
    # paquetes— dentro de la misma petición: tardaba tanto que al usuario le
    # parecía que el botón no hacía nada. El mapeo, que es lo que se ve al
    # instante en la pantalla, ya está escrito arriba.
    r = await db.cortex_packages.update_many(
        {"service_area_id": sid, "center": {"$ne": center}}, {"$set": {"center": center}})

    # El repaso del resto (cura mezclas viejas de cuando el mapeo se pisaba
    # cada 2 minutos) se hace después, sin que nadie espere por él.
    _org = _current_db_name.get()

    async def _resincronizar():
        try:
            set_current_org_db(_org)
            n = 0
            async for s in db.cortex_stations.find(
                    {"center": {"$nin": [None, ""]}}, {"_id": 0, "service_area_id": 1, "center": 1}):
                if s.get("service_area_id") and s["service_area_id"] != sid:
                    rr = await db.cortex_packages.update_many(
                        {"service_area_id": s["service_area_id"], "center": {"$ne": s["center"]}},
                        {"$set": {"center": s["center"]}})
                    n += rr.modified_count
            if n:
                logger.info(f"Cortex: resincronización de fondo, {n} paquetes re-etiquetados")
        except Exception as e:
            logger.warning(f"Cortex resincronización de fondo: {e}")

    asyncio.create_task(_resincronizar())
    return {"ok": True, "updated": r.modified_count, "resto_en_curso": True}


@api_router.get("/cortex/days")
async def cortex_days(center: str = "", _=Depends(require_admin)):
    """Días con datos, para el selector del panel (más reciente primero).

    Se agrupa EN MONGO. Antes se bajaban los paquetes a Python con
    `.to_list(20000)` y se contaban aquí, y eso tenía un fallo que se notaba
    justo cuando más duele: con ~167.000 paquetes en la colección, el corte de
    20.000 se quedaba con los documentos MÁS VIEJOS en orden natural, así que
    **el día de hoy no aparecía nunca en el selector**. El panel, al no
    encontrar hoy en la lista, saltaba solo a la fecha más reciente que sí
    salía y enseñaba "Ayer". Los contadores por día también eran falsos (1 ó 2
    paquetes en días de 3.000).

    Es el mismo antipatrón que ya se corrigió en /cortex/stations: contar en
    Python lo que Mongo cuenta solo. Sin límite de documentos y sin traerse
    nada, no vuelve a degradarse según crezca la colección.
    """
    q = await _cortex_scope("", center)
    cur = db.cortex_packages.aggregate([
        {"$match": q},
        # El día bueno es `service_day`; si falta, la fecha de captura. Se
        # normaliza aquí para que el $group no tenga que decidir nada.
        {"$project": {"d": {"$cond": [
            {"$and": [{"$ne": ["$service_day", None]}, {"$ne": ["$service_day", ""]}]},
            "$service_day",
            {"$substr": [{"$ifNull": [{"$toString": "$updated_at"}, ""]}, 0, 10]},
        ]}}},
        {"$match": {"d": {"$nin": [None, ""]}}},
        {"$group": {"_id": "$d", "n": {"$sum": 1}}},
        {"$sort": {"_id": -1}},
        # Un selector de días no necesita más de medio año; el resto sería
        # peso muerto en cada carga del panel.
        {"$limit": 180},
    ], allowDiskUse=True)
    # `.get()` siempre: $group omite la clave _id cuando el campo no existe
    # (gotcha 9), y un KeyError aquí tumbaría el selector entero.
    days = [{"day": r.get("_id"), "n": r.get("n", 0)} async for r in cur if r.get("_id")]
    return {"days": days, "today": datetime.now(timezone.utc).strftime("%Y-%m-%d")}


@api_router.get("/cortex/overview")
async def cortex_overview(day: str = "", center: str = "", _=Depends(require_admin)):
    today = (day or datetime.now(timezone.utc).strftime("%Y-%m-%d"))
    # Proyección MÍNIMA: con miles de paquetes reales, bajar los documentos
    # completos (timelines enteros, direcciones…) pesaba megas y ahogaba al
    # panel. Solo los campos que usa el cálculo.
    pkgs = await db.cortex_packages.find(
        await _cortex_scope(today, center),
        {"_id": 0, "state": 1, "driver_name": 1, "route_code": 1,
         "timeline.state": 1, "timeline.at": 1}).to_list(20000)
    # Frescura de la captura (org completa, cualquier día): la señal de
    # confianza del panel — "¿la extensión sigue viva?"
    _last = await db.cortex_packages.find({}, {"_id": 0, "updated_at": 1}).sort("updated_at", -1).to_list(1)
    last_capture_at = _last[0].get("updated_at") if _last else None
    n = len(pkgs)
    missing = [p for p in pkgs if p.get("state") == "MISSING"]
    recovered_today, lost, missing_today, rec_times, attempts_pre = [], [], [], [], []
    by_driver, by_route = {}, {}
    for p in pkgs:
        tl = p.get("timeline") or []
        states = [e.get("state") for e in tl]
        if p.get("state") == "LOST":
            lost.append(p)
        # Missing hoy
        m_ev = next((e for e in tl if e.get("state") == "MISSING"), None)
        if m_ev and str(m_ev.get("at", ""))[:10] == today:
            missing_today.append(p)
            if p.get("driver_name"):
                by_driver[p["driver_name"]] = by_driver.get(p["driver_name"], 0) + 1
            if p.get("route_code"):
                by_route[p["route_code"]] = by_route.get(p["route_code"], 0) + 1
            attempts_pre.append(sum(1 for s in states[:states.index("MISSING")] if s == "ATTEMPTED") if "MISSING" in states else 0)
        # Recuperación hoy + tiempo medio
        if "RECOVERED" in states or (p.get("state") == "DELIVERED" and "MISSING" in states):
            i_m = states.index("MISSING") if "MISSING" in states else None
            i_r = next((i for i in range(len(states)) if states[i] in ("RECOVERED", "DELIVERED") and (i_m is None or i > i_m)), None)
            if i_m is not None and i_r is not None:
                t0, t1 = _cortex_parse_dt(tl[i_m].get("at")), _cortex_parse_dt(tl[i_r].get("at"))
                if t0 and t1 and str(tl[i_r].get("at", ""))[:10] == today:
                    recovered_today.append(p)
                    rec_times.append((t1 - t0).total_seconds() / 60)
    resolved = len(recovered_today) + len(lost)
    recovery_pct = round(100 * len(recovered_today) / resolved) if resolved else None
    health = 100 - min(60, len(missing) * 6) - min(20, len(lost) * 10)
    return {
        "tracked": n, "missing_now": len(missing),
        "missing_today": len(missing_today), "recovered_today": len(recovered_today),
        "lost": len(lost), "recovery_pct": recovery_pct,
        "avg_recovery_min": round(sum(rec_times) / len(rec_times)) if rec_times else None,
        "avg_attempts_before_missing": round(sum(attempts_pre) / len(attempts_pre), 1) if attempts_pre else None,
        "health": max(0, health),
        "last_capture_at": last_capture_at,
        "by_driver": sorted([{"name": k, "n": v} for k, v in by_driver.items()], key=lambda x: -x["n"])[:8],
        "by_route": sorted([{"route": k, "n": v} for k, v in by_route.items()], key=lambda x: -x["n"])[:8],
    }


def _cx_ruta_cajon(state) -> str:
    """En que cajon de la tarjeta de ruta cae un paquete por su estado.

    Con las listas canonicas (`_CX_OK`, `_CX_EN_VUELO`…), no con nombres
    escritos a mano: hasta el 02-09-2026 `loaded` solo contaba LOADED y
    ARRIVED, dos estados que dejaron de existir con el gotcha 28, asi que con
    1.209 paquetes PICKED_UP en la calle todas las rutas salian "terminadas",
    el dashboard decia "0 rutas en curso" y la alarma de minutos sin entregar
    no se calculaba nunca. Un filtro por un valor que no existe no da error:
    da cero (gotcha 33). Probado en `test_cajones_ruta.py`.
    """
    if state in _CX_OK:
        return "delivered"
    if state in ("MISSING", "LOST"):
        return "missing"
    if state in _CX_EN_VUELO:
        return "loaded"
    if state in _CX_REINTENTABLE:
        return "attempted"
    if state in ("BACK_TO_ORIGIN", "RETURNED", "RECOVERED"):
        return "returned"
    return "other"


@api_router.get("/cortex/routes")
async def cortex_routes(day: str = "", center: str = "", _=Depends(require_admin)):
    """Resumen agregado por ruta: la vista principal cuando hay miles de paquetes."""
    today = (day or datetime.now(timezone.utc).strftime("%Y-%m-%d"))
    # OJO: el campo es driver_id, NO driver_name. cortex_packages nunca ha
    # tenido driver_name, asi que la pantalla mostraba "Sin conductor" en TODAS
    # las rutas teniendo el dato delante. El nombre se resuelve despues.
    pkgs = await db.cortex_packages.find(
        await _cortex_scope(today, center),
        {"_id": 0, "route_code": 1, "driver_id": 1, "state": 1, "priority": 1, "updated_at": 1, "center": 1}).to_list(20000)
    routes = {}
    for p in pkgs:
        rc = p.get("route_code") or "—"
        r = routes.setdefault(rc, {"route_code": rc, "driver_name": None, "driver_id": None,
                                   "total": 0, "delivered": 0,
                                   "missing": 0, "attempted": 0, "loaded": 0, "returned": 0, "other": 0,
                                   "critical": 0, "updated_at": None, "ultima_entrega": None})
        r["total"] += 1
        st = p.get("state")
        r[_cx_ruta_cajon(st)] += 1
        if p.get("priority") == "critical":
            r["critical"] += 1
        if p.get("driver_id") and not r["driver_id"]:
            r["driver_id"] = p["driver_id"]
        u = p.get("updated_at")
        if u and (not r["updated_at"] or u > r["updated_at"]):
            r["updated_at"] = u
        # Hora de la ultima ENTREGA (no de la ultima actualizacion): es lo que
        # dice si la furgoneta sigue moviendose. updated_at de un paquete
        # entregado es su hora de entrega — comprobado contra cortex_events
        # sobre 400 paquetes: desviacion mediana 0 s.
        if st == "DELIVERED" and u and (not r["ultima_entrega"] or u > r["ultima_entrega"]):
            r["ultima_entrega"] = u

    nombres = await _cx_nombres({r["driver_id"] for r in routes.values() if r.get("driver_id")})
    ahora = datetime.now(timezone.utc)
    for r in routes.values():
        n = nombres.get(r.get("driver_id") or "")
        if n:
            r["driver_name"] = n.get("nombre")
            r["ficha_id"] = n.get("ficha_id")
        r["pendientes"] = r["total"] - r["delivered"]

        # ¿SIGUE ESTA RUTA EN LA CALLE? Sólo si le quedan paquetes DENTRO DE LA
        # FURGONETA (LOADED/ARRIVED).
        #
        # `pendientes` no sirve para esto: cuenta también los intentados, los
        # devueltos y los no recogidos, que son fallos del día y no van a
        # entregarse ya porque el conductor volvió a nave hace horas. Usarlo
        # hacía que una ruta terminada a las 17:00 apareciera a la 1:00 de la
        # madrugada como "parada hace 480 minutos" — una alarma que sonaba toda
        # la noche en rutas que estaban perfectas. Lo cazó Dani mirando la
        # pantalla a la 1 AM: "está claro que ya terminaron hace horas".
        r["en_reparto"] = r["loaded"] > 0
        # Minutos desde la ultima entrega. Es un HECHO, no una prediccion: un
        # predictor de hora de fin no se sostiene con estos datos (ver
        # docs/PREDICTOR_RESCATES.md). Se muestra para que decida el gestor.
        r["min_sin_entregar"] = None
        if r["ultima_entrega"] and r["en_reparto"]:
            ue = r["ultima_entrega"]
            if not isinstance(ue, datetime):
                ue = _cortex_parse_dt(ue)
            if ue:
                if ue.tzinfo is None:
                    ue = ue.replace(tzinfo=timezone.utc)
                r["min_sin_entregar"] = max(0, int((ahora - ue).total_seconds() // 60))

    out = sorted(routes.values(), key=lambda r: str(r["route_code"] or ""))
    return {"routes": out, "total_packages": len(pkgs)}


@api_router.get("/cortex/packages")
async def cortex_packages(q: str = "", state: str = "", priority: str = "", day: str = "", route: str = "",
                          center: str = "", limit: int = 200, _=Depends(require_admin)):
    limit = max(1, min(int(limit or 200), 6000))
    ands = []
    dq = await _cortex_scope(day, center)
    if dq:
        ands.append(dq)
    if q:
        rx = {"$regex": re.escape(q), "$options": "i"}
        ands.append({"$or": [{"tba": rx}, {"reference_id": rx}, {"route_code": rx},
                             {"driver_name": rx}, {"stop_address": rx}, {"stop_id": rx}]})
    query = {}
    if state:
        query["state"] = state.upper()
    if priority:
        query["priority"] = priority.lower()
    if route:
        query["route_code"] = route
    if ands:
        query["$and"] = ands
    pkgs = await db.cortex_packages.find(query, {"_id": 0, "timeline": 0}).sort("updated_at", -1).to_list(limit)
    for _p in pkgs:                      # defensa: nunca devolver un objeto aqui
        _p["stop_address"] = _cortex_addr_str(_p.get("stop_address"))
    if route:
        # Dentro de una ruta se lee mejor por orden de parada.
        def _stop_key(p):
            s = str(p.get("stop_id") or "")
            return (0, int(s)) if s.isdigit() else (1, 0)
        pkgs.sort(key=_stop_key)
    return {"packages": pkgs}


def _cortex_clean_timeline(tl: list) -> list:
    """Sanea el timeline: ordena por hora, quita el ruido OBSERVED (capturas sin
    estado, legacy) cuando hay eventos reales, y colapsa repetidos consecutivos."""
    tl = sorted(tl or [], key=lambda e: str(e.get("at", "")))
    has_real = any(e.get("state") not in (None, "", "OBSERVED") for e in tl)
    if has_real:
        tl = [e for e in tl if e.get("state") not in (None, "", "OBSERVED")]
    out = []
    for e in tl:
        if out and out[-1].get("state") == e.get("state"):
            continue  # mismo estado seguido: el primero (más antiguo) es el que vale
        out.append(e)
    return out


@api_router.get("/cortex/package/{tba}")
async def cortex_package_detail(tba: str, _=Depends(require_admin)):
    pkg = await db.cortex_packages.find_one({"tba": tba.upper()}, {"_id": 0})
    if not pkg:
        raise HTTPException(status_code=404, detail="Paquete no encontrado")
    clean = _cortex_clean_timeline(pkg.get("timeline") or [])
    if clean != (pkg.get("timeline") or []):
        # Cura permanente del registro (elimina el ruido legacy de una vez)
        await db.cortex_packages.update_one({"tba": pkg["tba"]}, {"$set": {"timeline": clean}})
    pkg["timeline"] = clean
    # Cura permanente de direcciones guardadas como objeto (bug historico)
    fixed_addr = _cortex_addr_str(pkg.get("stop_address"))
    if fixed_addr != pkg.get("stop_address"):
        pkg["stop_address"] = fixed_addr
        await db.cortex_packages.update_one({"tba": pkg["tba"]}, {"$set": {"stop_address": fixed_addr}})
    evalr = _cortex_evaluate(pkg)
    # Paquetes del mismo stop (para la pista "otros del stop se entregaron")
    same_stop = []
    if pkg.get("stop_id") and pkg.get("route_code"):
        same_stop = await db.cortex_packages.find(
            {"stop_id": pkg["stop_id"], "route_code": pkg["route_code"], "tba": {"$ne": pkg["tba"]}},
            {"_id": 0, "tba": 1, "state": 1}).to_list(20)
    return {"package": pkg, "evaluation": evalr, "same_stop": same_stop}


@api_router.get("/cortex/alerts")
async def cortex_alerts(day: str = "", center: str = "", _=Depends(require_admin)):
    q = {"state": {"$in": ["MISSING", "LOST"]}}
    dq = await _cortex_scope(day, center)
    if dq:
        q = {"$and": [q, dq]}
    pkgs = await db.cortex_packages.find(q, {"_id": 0}).sort("updated_at", -1).to_list(500)
    alerts = []
    rank = {"critical": 0, "high": 1, "medium": 2, "low": 3}
    for p in pkgs:
        ev = _cortex_evaluate(p)
        if ev["priority"] in ("critical", "high"):
            alerts.append({
                "tba": p["tba"], "priority": ev["priority"], "reason": ev["reason"],
                "route_code": p.get("route_code"), "driver_name": p.get("driver_name"),
                "stop_id": p.get("stop_id"), "state": p.get("state"),
                "confidence": (ev.get("investigator") or {}).get("confidence"),
                "recommendation": (ev.get("investigator") or {}).get("text"),
            })
    alerts.sort(key=lambda a: rank.get(a["priority"], 9))
    return {"alerts": alerts}


@api_router.get("/cortex/heatmap")
async def cortex_heatmap(day: str = "", center: str = "", _=Depends(require_admin)):
    q = {"lat": {"$ne": None}, "state": {"$in": ["MISSING", "LOST", "ATTEMPTED"]}}
    dq = await _cortex_scope(day, center)
    if dq:
        q = {"$and": [q, dq]}
    pkgs = await db.cortex_packages.find(
        q, {"_id": 0, "lat": 1, "lng": 1, "state": 1, "tba": 1}).to_list(2000)
    return {"points": [p for p in pkgs if p.get("lat") and p.get("lng")]}


