@api_router.get("/admin/actividad")
async def admin_actividad(path: str = "", sub: str = "", horas: int = 24, limite: int = 200,
                          _=Depends(require_superadmin)):
    """Quien ha escrito que en las ultimas horas, en toda la plataforma.

    Es la pregunta que no se pudo contestar el 01-09-2026 («¿quien borro
    esto?»). Lee `audit_requests`, que llena el middleware de escrituras.
    """
    q: dict = {"at": {"$gte": datetime.now(timezone.utc) - timedelta(hours=max(1, min(horas, 24 * 30)))}}
    if path:
        q["path"] = {"$regex": re.escape(path)}
    if sub:
        q["sub"] = sub
    filas = await global_db.audit_requests.find(q, {"_id": 0}).sort("at", -1).to_list(max(1, min(limite, 2000)))
    for f in filas:
        if isinstance(f.get("at"), datetime):
            f["at"] = f["at"].isoformat()
    return {"total": len(filas), "filas": filas}


@api_router.post("/cortex/reset")
async def cortex_reset(data: dict = Body(default={}), user: dict = Depends(require_superadmin)):
    """Borra TODOS los paquetes y eventos de Cortex de ESTA empresa.

    Solo el super-admin, solo con `{"confirmar": "BORRAR"}` en el cuerpo, y
    queda en `audit_log`. Hasta el 02-09-2026 pedia `require_admin` y un
    `window.confirm`: el boton «Borrar todo y empezar limpio» vivia en la
    tarjeta de arranque de Paquetes IA, al alcance de los 14 usuarios del
    panel, y un clic borro 265.986 paquetes y 555.730 eventos —dos meses de
    historico—, y con ellos la scorecard en vivo, las direcciones que fallan y
    el DCR de cada dia. Se recuperaron de la copia diaria de R2 (gotcha 45).
    Nada que borre un historico entero puede depender de un solo clic ni estar
    al alcance de quien no es el dueno. Lo vigila `scripts/check_borrado.py`.
    """
    if (data or {}).get("confirmar") != "BORRAR":
        raise HTTPException(400, "Escribe BORRAR en `confirmar` para borrar todo el historico de Cortex")
    p = await db.cortex_packages.delete_many({})
    e = await db.cortex_events.delete_many({})
    await _audit(user, "cortex_reset", {"db": _current_db_name.get(),
                                        "packages_deleted": p.deleted_count,
                                        "events_deleted": e.deleted_count})
    return {"ok": True, "packages_deleted": p.deleted_count, "events_deleted": e.deleted_count}


# ===================================================================
# APARCAMIENTO - plano de plazas por centro + trazabilidad diaria
# ===================================================================
# Flujo real: la plantilla asigna plaza -> el conductor la ve al hacer su
# auditoria y reporta donde aparco -> el coordinador confirma / deniega /
# corrige. Al dia siguiente la plantilla sabe donde esta cada furgoneta.
#
# Sin falsos positivos: "spot" (lo que MANDAMOS) y "reported_spot" (lo que
# DICE el conductor) son campos DISTINTOS. Solo confirmar los une. Si no
# coinciden, se marca discrepancia en vez de elegir uno a ciegas.


def _pk_bay(code, x, y, w, h, rot=0.0):
    return {"code": str(code), "x": round(x, 2), "y": round(y, 2),
            "w": round(w, 2), "h": round(h, 2), "rot": rot}


# Version del plano generado. Si sube, los planos AUTO-GENERADOS se regeneran;
# los que el coordinador ya ha editado a mano (seeded=False) NUNCA se tocan.
_PK_LAYOUT_V = 3


def _pk_default_layout(center):
    """Plano inicial con la GEOMETRIA REAL de cada centro.

    Coordenadas en % dentro del lienzo de su zona (0-100), con "ratio" =
    ancho/alto de la zona para que las proporciones sean creibles. "rot" son
    grados: una plaza ancha (w>h) sin rotar dibuja el coche en horizontal.
    """
    c = (center or "").upper()

    if c == "OGA5":
        # ── Nave: 17 plazas en horizontal contra las paredes, morro a pared.
        #    11 pegadas a la pared derecha y 6 a la izquierda, pasillo central.
        nave = []
        for i in range(11):                       # pared derecha
            nave.append(_pk_bay(i + 1, 54, 3.0 + i * 8.6, 42, 7.2))
        for i in range(6):                        # pared izquierda
            nave.append(_pk_bay(12 + i, 4, 3.0 + i * 8.6, 42, 7.2))

        # ── Exterior junto a la nave: 8 + 8 en DIAGONAL, culo a la pared y
        #    morro hacia el carril central (ambas filas "apuntan" hacia arriba).
        ext = []
        for i in range(8):                        # fila izquierda
            ext.append(_pk_bay(18 + i, 4, 5.0 + i * 11.4, 37, 8.4, -40))
        for i in range(8):                        # fila derecha (espejo)
            ext.append(_pk_bay(26 + i, 59, 5.0 + i * 11.4, 37, 8.4, 40))

        # ── Parking de tierra: 4 hileras de 6 en bateria, coches en vertical
        #    y carriles entre hileras (disposicion estandar de parcela).
        tierra = []
        n = 34
        for row in range(4):
            for col in range(6):
                tierra.append(_pk_bay(n, 4 + col * 15.8, 6 + row * 24, 13, 17))
                n += 1

        return {
            "center": c, "name": "OGA5 - Santiago", "v": _PK_LAYOUT_V,
            "zones": [
                {"id": "nave", "name": "Dentro de la nave", "color": "violet",
                 "note": "17 plazas en horizontal contra las paredes (11 derecha + 6 izquierda)",
                 "ratio": 0.62, "aisle": "vertical", "spots": nave},
                {"id": "exterior", "name": "Exterior junto a la nave", "color": "sky",
                 "note": "16 plazas en diagonal, culo a la pared y morro al carril central",
                 "ratio": 0.58, "aisle": "vertical", "spots": ext},
                {"id": "tierra", "name": "Parking de tierra", "color": "emerald",
                 "note": "24 plazas en bateria, 4 hileras de 6",
                 "ratio": 1.15, "aisle": "horizontal", "spots": tierra},
            ],
        }

    if c == "DGA1":
        # Recinto exterior completo: 6 hileras de 6 en bateria con carriles.
        spots, n = [], 1
        for row in range(6):
            for col in range(6):
                spots.append(_pk_bay(n, 3 + col * 16, 4 + row * 16, 13.5, 12))
                n += 1
        return {
            "center": c, "name": "DGA1", "v": _PK_LAYOUT_V,
            "zones": [
                {"id": "exterior", "name": "Parking exterior", "color": "sky",
                 "note": "Todo el recinto es aparcamiento exterior en bateria",
                 "ratio": 1.0, "aisle": "horizontal", "spots": spots},
            ],
        }

    # Centro sin plano propio: PLANTILLA de partida (nave + exterior), marcada
    # como borrador para que el coordinador la ajuste. No es un dato inventado:
    # es un punto de partida editable, y la UI lo advierte en amarillo.
    nave, ext = [], []
    for i in range(8):
        nave.append(_pk_bay(i + 1, 54, 4 + i * 11.8, 42, 9.5))
    for i in range(6):
        nave.append(_pk_bay(9 + i, 4, 4 + i * 11.8, 42, 9.5))
    for i in range(6):
        ext.append(_pk_bay(15 + i, 4, 6 + i * 15.2, 37, 11, -40))
    for i in range(6):
        ext.append(_pk_bay(21 + i, 59, 6 + i * 15.2, 37, 11, 40))
    return {"center": c, "name": c, "v": _PK_LAYOUT_V, "zones": [
        {"id": "nave", "name": "Dentro de la nave", "color": "violet",
         "note": "Plantilla de partida - ajusta el numero de plazas",
         "ratio": 0.7, "aisle": "vertical", "spots": nave},
        {"id": "exterior", "name": "Exterior", "color": "sky",
         "note": "Plantilla de partida - plazas en diagonal hacia el carril",
         "ratio": 0.62, "aisle": "vertical", "spots": ext},
    ]}


async def _pk_get_layout(center):
    c = (center or "").upper()
    doc = await db.parking_layouts.find_one({"center": c}, {"_id": 0})
    # Un plano editado por una persona (seeded=False) es sagrado: no se toca.
    # Uno auto-generado de version anterior se regenera con la geometria nueva.
    if doc and not (doc.get("seeded") and doc.get("v", 1) < _PK_LAYOUT_V):
        return doc
    doc = _pk_default_layout(c)
    doc["seeded"] = True          # plano por defecto, aun sin revisar por humano
    await db.parking_layouts.update_one({"center": c}, {"$set": doc}, upsert=True)
    return doc


def _pk_valid_codes(layout):
    return {s.get("code") for z in layout.get("zones", []) for s in (z.get("spots") or [])}


@api_router.get("/parking/layout")
async def parking_layout(center: str = "", _=Depends(require_admin)):
    if not center or center.upper() == "TODOS":
        raise HTTPException(400, "Indica un centro concreto para ver su plano")
    return await _pk_get_layout(center)


@api_router.put("/parking/layout")
async def parking_layout_save(body: dict = Body(...), _=Depends(require_admin)):
    """Guarda el plano editado (zonas, nombres y posiciones de plazas)."""
    c = str(body.get("center") or "").strip().upper()
    zones = body.get("zones")
    if not c or not isinstance(zones, list):
        raise HTTPException(400, "Falta center o zones")
    codes = [str(s.get("code")) for z in zones for s in (z.get("spots") or [])]
    if len(codes) != len(set(codes)):
        raise HTTPException(400, "Hay codigos de plaza repetidos: cada plaza debe ser unica")
    doc = {"center": c, "name": str(body.get("name") or c), "zones": zones, "seeded": False,
           "updated_at": datetime.now(timezone.utc).isoformat()}
    await db.parking_layouts.update_one({"center": c}, {"$set": doc}, upsert=True)
    return {"ok": True, "spots": len(codes)}


# ══════════════════════════════════════════════════════════════════════════
# ACTIVACION (onboarding). El estado se DEDUCE de los datos reales, nunca de
# una marca de "ya lo hice": si el DSP borra su flota, la guia vuelve a
# aparecer honestamente. Un flag guardado mentiria.
# ══════════════════════════════════════════════════════════════════════════

@api_router.get("/onboarding")
async def onboarding_status(user: dict = Depends(require_any_auth)):
    """Que le falta a este DSP para sacarle partido al producto.

    Cuenta barata (count_documents con filtro indexado). Una sola peticion
    para toda la guia: no queremos 4 llamadas en el primer render del panel.
    """
    vehiculos = await db.vehicles.count_documents({"status": {"$nin": ["deleted", "baja"]}})
    conductores = await db.drivers.count_documents({"active": {"$ne": False}})
    inspecciones = await db.inspections.count_documents({"deleted": {"$ne": True}})
    # "Equipo": mas de un usuario admin en la organizacion (opcional pero
    # es la senal de que el DSP ya no lo lleva una sola persona).
    equipo = 0
    try:
        org_id = user.get("org_id")
        if org_id:
            equipo = await global_db.admin_users.count_documents({"org_id": org_id})
    except Exception:
        equipo = 0

    pasos = [
        {"id": "vehiculos", "hecho": vehiculos > 0, "n": vehiculos},
        {"id": "conductores", "hecho": conductores > 0, "n": conductores},
        {"id": "inspeccion", "hecho": inspecciones > 0, "n": inspecciones},
        {"id": "equipo", "hecho": equipo > 1, "n": equipo, "opcional": True},
    ]
    obligatorios = [x for x in pasos if not x.get("opcional")]
    hechos = sum(1 for x in obligatorios if x["hecho"])
    return {
        "pasos": pasos,
        "hechos": hechos,
        "total": len(obligatorios),
        "completo": hechos == len(obligatorios),
    }


@api_router.post("/parking/zone-image")
async def parking_zone_image(
    center: str = Form(...),
    zone_id: str = Form(...),
    ratio: str = Form(""),
    file: UploadFile = File(...),
    _=Depends(require_admin),
):
    """Foto aerea de fondo para una zona (la captura de satelite del propio DSP).

    No descargamos imagenes de terceros: la sube el cliente, es suya y queda en
    su bucket. Asi el plano se ve sobre el terreno real de SU nave, y funciona
    igual para cualquier centro futuro.
    """
    c = (center or "").strip().upper()
    zid = (zone_id or "").strip()
    if not c or not zid:
        raise HTTPException(400, "Falta center o zone_id")

    content = await file.read()
    if not content:
        raise HTTPException(400, "Archivo vacio")
    if len(content) > 8 * 1024 * 1024:
        raise HTTPException(413, "Imagen demasiado grande (max 8 MB)")
    ctype = (file.content_type or "").lower()
    if not ctype.startswith("image/"):
        raise HTTPException(400, "El archivo debe ser una imagen")

    ext = (file.filename or "foto.jpg").rsplit(".", 1)[-1].lower()
    if ext not in ("jpg", "jpeg", "png", "webp"):
        ext = "jpg"
    key = "parking/" + c + "/" + re.sub(r"[^a-zA-Z0-9_-]", "_", zid) + "_" + uuid.uuid4().hex[:8] + "." + ext

    s3 = get_r2()
    if not s3:
        raise HTTPException(502, "Almacenamiento R2 no configurado")
    try:
        await asyncio.get_running_loop().run_in_executor(
            _executor,
            lambda: s3.put_object(Bucket=R2_BUCKET, Key=key, Body=content, ContentType=ctype))
    except Exception as e:
        raise HTTPException(500, "Error subiendo la imagen: " + str(e))

    r2_public = os.environ.get("R2_PUBLIC_URL", "").rstrip("/")
    url = (r2_public + "/" + key) if r2_public else key

    # La FOTO manda sobre la forma de la zona: guardamos su proporcion real
    # (ancho/alto) para que el lienzo la muestre entera, sin recortes ni
    # deformacion. Si no, las plazas caen donde no toca sobre el terreno.
    try:
        r = float(ratio)
        if not (0.15 <= r <= 8):
            r = None
    except (TypeError, ValueError):
        r = None

    layout = await _pk_get_layout(c)
    found = False
    for z in layout.get("zones", []):
        if z.get("id") == zid:
            z["bg"] = url
            if r:
                z["ratio"] = round(r, 3)
            found = True
    if not found:
        raise HTTPException(404, "Zona " + zid + " no existe en el plano de " + c)
    # Guardar el plano deja de considerarse auto-generado: es trabajo humano.
    await db.parking_layouts.update_one(
        {"center": c}, {"$set": {"zones": layout["zones"], "seeded": False}}, upsert=True)
    return {"ok": True, "url": url}


@api_router.get("/parking/state")
async def parking_state(center: str = "", day: str = "", _=Depends(require_admin)):
    """Plano + ocupacion del dia + datos reales de vehiculo/conductor."""
    c = (center or "").upper()
    if not c or c == "TODOS":
        raise HTTPException(400, "Indica un centro concreto")
    d = (day or datetime.now(timezone.utc).strftime("%Y-%m-%d"))[:10]
    layout = await _pk_get_layout(c)
    rows = await db.parking_assignments.find({"center": c, "day": d}, {"_id": 0}).to_list(500)
    vids = [r["vehicle_id"] for r in rows if r.get("vehicle_id")]
    dids = [r["driver_id"] for r in rows if r.get("driver_id")]
    vmap, dmap = {}, {}
    if vids:
        async for v in db.vehicles.find({"id": {"$in": vids}},
                                        {"_id": 0, "id": 1, "license_plate": 1, "brand": 1, "model": 1}):
            vmap[v["id"]] = v
    if dids:
        async for dr in db.drivers.find({"id": {"$in": dids}}, {"_id": 0, "id": 1, "name": 1}):
            dmap[dr["id"]] = dr
    for r in rows:
        r["vehicle"] = vmap.get(r.get("vehicle_id"))
        r["driver"] = dmap.get(r.get("driver_id"))
        # Discrepancia EXPLICITA: lo asignado no coincide con lo reportado
        r["mismatch"] = bool(r.get("reported_spot") and r.get("spot")
                             and r["reported_spot"] != r["spot"])
    return {"layout": layout, "day": d, "assignments": rows}


@api_router.post("/parking/assign")
async def parking_assign(body: dict = Body(...), user: dict = Depends(require_admin)):
    """Asigna una plaza a un vehiculo para un dia (lo que MANDAMOS)."""
    c = str(body.get("center") or "").strip().upper()
    d = str(body.get("day") or datetime.now(timezone.utc).strftime("%Y-%m-%d"))[:10]
    spot = str(body.get("spot") or "").strip()
    vehicle_id = str(body.get("vehicle_id") or "").strip()
    if not (c and spot and vehicle_id):
        raise HTTPException(400, "Faltan center, spot o vehicle_id")
    layout = await _pk_get_layout(c)
    if spot not in _pk_valid_codes(layout):
        raise HTTPException(400, "La plaza " + spot + " no existe en el plano de " + c)
    # Una plaza, un vehiculo: si esta ocupada por otro se avisa, no se pisa
    clash = await db.parking_assignments.find_one(
        {"center": c, "day": d, "spot": spot, "vehicle_id": {"$ne": vehicle_id}}, {"_id": 0})
    if clash:
        raise HTTPException(409, "La plaza " + spot + " ya esta asignada a otro vehiculo ese dia")
    now = datetime.now(timezone.utc).isoformat()
    await db.parking_assignments.update_one(
        {"center": c, "day": d, "vehicle_id": vehicle_id},
        {"$set": {"center": c, "day": d, "vehicle_id": vehicle_id, "spot": spot,
                  "driver_id": body.get("driver_id"), "status": "asignada",
                  "assigned_by": user.get("name") or user.get("sub"), "assigned_at": now},
         "$setOnInsert": {"id": str(uuid.uuid4())}}, upsert=True)
    return {"ok": True}


@api_router.post("/parking/report")
async def parking_report(body: dict = Body(...), user: dict = Depends(require_any_auth)):
    """El conductor reporta donde ha aparcado (sin pisar lo asignado)."""
    c = str(body.get("center") or "").strip().upper()
    d = str(body.get("day") or datetime.now(timezone.utc).strftime("%Y-%m-%d"))[:10]
    spot = str(body.get("spot") or "").strip()
    vehicle_id = str(body.get("vehicle_id") or "").strip()
    if not (c and spot and vehicle_id):
        raise HTTPException(400, "Faltan center, spot o vehicle_id")
    layout = await _pk_get_layout(c)
    if spot not in _pk_valid_codes(layout):
        raise HTTPException(400, "La plaza " + spot + " no existe en el plano de " + c)
    now = datetime.now(timezone.utc).isoformat()
    await db.parking_assignments.update_one(
        {"center": c, "day": d, "vehicle_id": vehicle_id},
        {"$set": {"center": c, "day": d, "vehicle_id": vehicle_id,
                  "reported_spot": spot, "status": "reportada",
                  "driver_id": body.get("driver_id"), "inspection_id": body.get("inspection_id"),
                  "reported_by": user.get("name") or user.get("sub"), "reported_at": now},
         "$setOnInsert": {"id": str(uuid.uuid4())}}, upsert=True)
    return {"ok": True}


@api_router.post("/parking/resolve")
async def parking_resolve(body: dict = Body(...), user: dict = Depends(require_admin)):
    """Confirmar / denegar / corregir lo reportado, con rastro de quien y cuando."""
    c = str(body.get("center") or "").strip().upper()
    d = str(body.get("day") or datetime.now(timezone.utc).strftime("%Y-%m-%d"))[:10]
    vehicle_id = str(body.get("vehicle_id") or "").strip()
    action = str(body.get("action") or "").strip()
    if not (c and vehicle_id and action in ("confirm", "deny", "edit")):
        raise HTTPException(400, "Faltan datos o la accion no es valida")
    cur = await db.parking_assignments.find_one(
        {"center": c, "day": d, "vehicle_id": vehicle_id}, {"_id": 0})
    if not cur:
        raise HTTPException(404, "No hay registro de aparcamiento para ese vehiculo y dia")
    now = datetime.now(timezone.utc).isoformat()
    who = user.get("name") or user.get("sub")
    if action == "confirm":
        upd = {"spot": cur.get("reported_spot") or cur.get("spot"), "status": "confirmada",
               "resolved_by": who, "resolved_at": now}
    elif action == "deny":
        upd = {"status": "denegada", "resolved_by": who, "resolved_at": now}
    else:
        spot = str(body.get("spot") or "").strip()
        layout = await _pk_get_layout(c)
        if spot not in _pk_valid_codes(layout):
            raise HTTPException(400, "La plaza " + spot + " no existe en el plano de " + c)
        upd = {"spot": spot, "status": "confirmada", "corrected": True,
               "resolved_by": who, "resolved_at": now}
    await db.parking_assignments.update_one(
        {"center": c, "day": d, "vehicle_id": vehicle_id}, {"$set": upd})
    return {"ok": True, **upd}


@api_router.get("/parking/last-known")
async def parking_last_known(center: str = "", _=Depends(require_admin)):
    """Donde quedo cada furgoneta la ultima vez que se CONFIRMO: lo que necesita
    la plantilla del dia siguiente para saber de donde sale cada una."""
    c = (center or "").upper()
    q = {"status": "confirmada"}
    if c and c != "TODOS":
        q["center"] = c
    rows = await db.parking_assignments.find(q, {"_id": 0}).sort("day", -1).to_list(2000)
    last = {}
    for r in rows:
        vid = r.get("vehicle_id")
        if vid and vid not in last:
            last[vid] = {"vehicle_id": vid, "spot": r.get("spot"), "day": r.get("day"),
                         "center": r.get("center")}
    return {"vehicles": list(last.values())}


@api_router.get("/whc/plan")
async def whc_plan_get(center: str, _=Depends(require_admin)):
    """El plan pegado de la semana en curso, para no tener que volver a pegarlo.

    Se guarda por (centro, semana): al cambiar de semana no se arrastra el plan
    de la anterior, que seria el peor error posible — ver horas viejas creyendo
    que son las de esta semana.
    """
    sun, _sat = _sun_sat_week(datetime.now(timezone.utc).strftime("%Y-%m-%d"))
    doc = await db.whc_planes.find_one(
        {"center": (center or "").upper(), "week": sun}, {"_id": 0})
    return {"hay": bool(doc), "semana": sun, **(doc or {})}


@api_router.delete("/whc/plan")
async def whc_plan_delete(center: str, _=Depends(require_admin)):
    """Borra el plan guardado de la semana en curso de ese centro."""
    sun, _sat = _sun_sat_week(datetime.now(timezone.utc).strftime("%Y-%m-%d"))
    r = await db.whc_planes.delete_many({"center": (center or "").upper(), "week": sun})
    return {"ok": True, "borrados": r.deleted_count, "semana": sun}


